-- Merit and Flaw descriptions, the [pt] half (SPEC I102e, I21, V210 / T751).
--
-- One entry per item of PICKER_LIST["merit"] and ["flaw"], keyed in ENGLISH because that is
-- what the sheet saves (SPEC V24). Three blocks, exactly as the eight description modules
-- already do: "<Book>, p. <n>" - blank - blank - <Name> - blank - blank - <text>. The book
-- title does not translate; only p./pag. does (SPEC I100e).
--
-- One module PER LANGUAGE and never both halves in one file (SPEC V210): half of every
-- module was the language the session never opens, and require pulled both in to read one.
-- The renderer builds the name by concatenation - require("descMerit_" .. half .. ".lua")
-- and never a constant name (SPEC V210b).
--
-- Data only: no function, no state, no require of gui/ndb/locale (SPEC I24).
-- Generated by research/gen_merit_data.ps1 from research/merit_flaw.tsv and the bodies
-- research/extract_merit_flaw.ps1 pulls out of the books. Do not hand-edit.

return {
				-- >>> MERIT_DESC_BEGIN (generated - SPEC T751)
				["Ability Deficit"] = {
					pt = [==[Book of Secrets, pág. 53


Ability Deficit


Por alguma razão, você ficou aquém do seu potencial. Talvez seja jovem demais para ter aprendido muito sobre a vida (uma excelente razão para um mago-criança ter este Defeito); ou levou uma existência protegida, afiando seus Conhecimentos mas carecendo de Talentos. Você pode ser um construto que deixou o laboratório há pouco tempo, ou ser fisicamente frágil demais para ter dominado grande coisa em Talentos ou Perícias. Certamente há alguma razão de história por trás dos seus Traços deficientes, e essa causa terá outros efeitos sobre a crônica também.

Em termos de jogo, este Defeito subtrai cinco pontos de uma das suas categorias de Habilidade (Talentos, Perícias ou Conhecimentos) e limita seus Traços iniciais naquela categoria a três pontos ou menos, mesmo que você gaste pontos livres para elevá-los. (Você pode, é claro, elevá-los depois que a crônica começar.) Como dito acima, este é um bom Defeito para crianças Despertas, construtos e outros que ainda não tiveram a chance de "ser tudo o que podem ser".

Para detalhes sobre magos jovens, veja Magos-Crianças no Capítulo Dois, pp. 115-116.]==],
				},
				["Absent-Minded"] = {
					pt = [==[Book of Secrets, pág. 50


Absent-Minded


Hã… o que era mesmo aquilo que você estava tentando lembrar? Droga… Este Defeito reflete uma memória e um senso de conexão dispersos – nada tão perigoso quanto uma Perturbação completa (Mage 20, pp. 648-650), mas ainda assim uma desconexão angustiante e ocasionalmente arriscada.

Em termos de sistema, seu Narrador frequentemente vai pedir rolagens de Inteligência para lembrar coisas como nomes, rostos, detalhes de missões e por aí vai. Em termos de história, você vive dando branco, confundindo pessoas com outras, embaralhando dados, deixando projetos pela metade (ou totalmente abandonados), esquecendo de alimentar seu familiar e cometendo erros de julgamento potencialmente perigosos. Embora você não vá esquecer coisas vitais como seu nome, os elementos do seu foco mágico ou Traços vitais do personagem (Talentos, Perícias e Conhecimentos), o resto escapa da sua cabeça com uma regularidade frustrante. E quando essa cabeça comanda os poderes da Magia Verdadeira, esses lapsos podem ter consequências fatais.]==],
				},
				["Addicted to Vampire Blood"] = {
					pt = [==[The Hunters Hunted II, pág. 42


Addicted to Vampire Blood


Sua personagem precisa constantemente da euforia que só o sangue de vampiro proporciona. Fora isso, ela se sente vazia e apática. Esse hábito é dos mais perigosos e só pode ser vencido por abstinência completa (e, provavelmente, com não pouca terapia). Sempre que sua personagem tiver acesso à vitae de um Cainita e quiser resistir ao impulso de beber, o Narrador pode exigir uma rolagem de Autocontrole. Se ela não provar sangue de vampiro por mais de uma semana, você sofre +1 de dificuldade progressiva nessas rolagens até que ela mate a sede. Defeito Físico]==],
				},
				["Addiction"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 482


Addiction


Você sofre de um vício em alguma substância, que agora precisa estar presente no sangue que você bebe (ou você entra em frenesi automaticamente, como no Defeito Exclusão de Presa). Pode ser álcool, nicotina, drogas pesadas ou simplesmente adrenalina. Essa substância sempre o prejudica de alguma forma (veja "Venenos e Drogas", p. 301, para detalhes).]==],
				},
				["Aging"] = {
					pt = [==[The Hunters Hunted II, pág. 141


Aging


Você não é mais tão ágil quanto era. Reduza em um ponto um Atributo Físico à sua escolha. Um Atributo não pode cair abaixo de um por causa deste Defeito. Você pode adquiri-lo aos 40 anos e mais uma vez a cada década depois disso. Mental]==],
				},
				["Albino"] = {
					pt = [==[Ghouls & Revenants, pág. 134


Albino


O albinismo ocorre quando um grupo de genes normalmente recessivos se torna dominante, levando à falta de pigmentação da pele. Embora em geral inofensiva, a aparência de um indivíduo albino pode ser assustadora, sobretudo para quem não conhece a condição. Ela se caracteriza por uma pele extremamente pálida e íris vermelhas.

O albinismo era visto com grande desconfiança na maioria das culturas antigas, a ponto de ainda hoje pessoas com a condição serem evitadas e postas de lado, e consideradas mau presságio em muitas partes do mundo. Embora seja inofensiva do ponto de vista fisiológico, ela faz o indivíduo se destacar. Isso pode reduzir a capacidade de um carniçal de se misturar à multidão sem a ajuda de um disfarce. Por outro lado, quem carrega o Defeito Albino também pode transformar o medo alheio em fonte de intimidação, principalmente se o seu carniçal ou revenante tiver uma reputação que não possa ser ignorada.

Ao escolher o Defeito Albino, tenha em mente que sua pele é altamente suscetível a queimaduras solares, por ter pouca ou nenhuma pigmentação para refletir os raios UV nocivos do sol.

Usado por: todos os carniçais e revenantes Modificações de Vicissitude]==],
				},
				["Amnesia"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 486


Amnesia


Você é incapaz de lembrar qualquer coisa sobre seu passado, sobre si mesmo ou sobre sua família (seja ela mortal ou vampírica), embora esse passado possa muito bem voltar para assombrá-lo. Suas origens e as circunstâncias por trás da amnésia cabem ao Narrador determinar, e ele é encorajado a torná-las o mais interessantes possível.]==],
				},
				["Anachronism (1)"] = {
					pt = [==[Book of Secrets, pág. 81


Anachronism (1)


O tempo passou por você… ou talvez ainda não tenha alcançado você. Suas crenças, personalidade, maneirismos, moda e expectativas estão radicalmente fora de compasso com o mundo ao seu redor. Isso pode ser um afetamento deliberado da sua parte ("Os Velhos Tempos eram melhores que hoje" / "Por que esperar o futuro chegar se você pode se tornar o futuro?"), um soluço temporal ligado à Esfera do Tempo ou um Defeito de Paradoxo, o resultado de uma longevidade paranormal ou de uma viagem no tempo para trás, a manifestação de uma vida passada (ou futura) especialmente insistente… diabos, talvez nem você saiba direito por que é assim, mas é, e o resto do mundo não consegue deixar de notar.

O valor deste Defeito depende do tamanho da encrenca em que seus anacronismos o metem:

(1 ponto) Você parece um pouco esquisito e potencialmente ofensivo ("Por que eles não estão sentados no fundo do ônibus? Não existe lei sobre isso?"), exibindo manias de um passado ou futuro reconhecivelmente diferente, mas não radicalmente atrás ou à frente da época atual. Some +1 à dificuldade para entender a tecnologia e os modos de comportamento atuais.

(2 pontos) Você é uma relíquia de uma era claramente anterior, ou o arauto de uma seriamente avançada. O que você diz, veste, espera e acredita está perturbadoramente fora de sintonia com o que o cerca e pode criar problemas consideráveis… especialmente quando você discursa sobre bobagens como política, costumes sociais, sexualidade e lei. A tecnologia atual o confunde, seja por ser inexplicavelmente avançada, seja por ser assombrosamente primitiva. Some +2 à dificuldade de todo esforço para compreender sua época atual, incluindo rolagens sociais que dependam de se dar bem com as pessoas desta era.

(3 pontos) Você vem de um tempo tão distante que a era atual lhe parece tão alienígena quanto você parece às pessoas dela. Diabos, você pode nem falar inglês (traço comum de quem existiu antes da expansão da influência britânica e americana nos anos 1800), ou falar sua língua com um sotaque e expressões que essencialmente a transformam em outro idioma (pense em Shakespeare, ou no romance Laranja Mecânica, de Anthony Burgess). Suas expectativas quanto a tecnologia e costumes sociais divergem de forma selvagem, e você pode facilmente se meter em apuros sérios. Some +3 às rolagens apropriadas, e você pode ser incapaz de processar certas coisas (dirigir, política, informática atual etc.) por completo.

Supondo que você tenha a chance de se aclimatar ao que o cerca, este Defeito pode ser reduzido com pontos de experiência. Até lá, seus companheiros terão muita coisa a explicar em seu nome!]==],
