				},
				["Ancestral Soil Dependence"] = {
					pt = [==[Lore of the Clans, pág. 239


Ancestral Soil Dependence


Sua carne anseia por uma terra natal que você nunca viu. A voz de Kupala castiga seu sono diurno se esse anseio não for atendido. A terra de um lugar importante para você como mortal não basta; além dela, você precisa de dois punhados do solo maculado do leste europeu, da terra ancestral dos Tzimisce. Este Traço se manifesta com mais frequência nos filhos dos koldun e no ramo do Clã que se acredita descender de Yorak. Pode até se manifestar em filhos gerados gerações depois de seus ancestrais terem se mudado. Personagens Abraçados no leste europeu não podem escolher este Defeito (já dependem do solo local).]==],
				},
				["Animate Shadow"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 427


Animate Shadow


Sua sombra não é meramente a ausência de luz no formato do seu corpo; é uma entidade viva e maldosa, com vontade própria. Ela ataca amigos e inimigos por igual, rasgando o cenário e rosnando para quem passa. Além de ser um problema assustador, você perde dois dados em todas as rolagens Sociais com Lasombra que saibam da sua condição.]==],
				},
				["Anosmia"] = {
					pt = [==[Lore of the Clans, pág. 162


Anosmia


Sua vida no esgoto tirou seus sentidos de olfato e paladar. Isso significa que você não se abala nem com o pior fedor ou o sabor mais repugnante. Significa também, porém, que você jamais consegue ter sucesso em qualquer rolagem de Percepção que dependa de gosto ou cheiro. E isso não o torna imune de forma alguma a ataques de gás ou venenos; você só não vai perceber que eles estão ali.]==],
				},
				["Apostate (Dark Ages)"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 425


Apostate (Dark Ages)


Não há pecado em mudar de Estrada. Contudo, a maneira como você mudou foi espetacular e ofensiva. Você denunciou publicamente sua antiga Estrada e discursou contra as falhas dos preceitos dela. Como era de se esperar, isso lhe rendeu a ira dos que seguem sua antiga Estrada, mas também deixou desconfiados os membros da nova. Você precisa trabalhar o dobro para ganhar o respeito dos seus pares. Fique atento, também, aos que possam buscar vingança.]==],
				},
				["Apprentice (1)"] = {
					pt = [==[Book of Secrets, pág. 81


Apprentice (1)


A maioria das sociedades metafísicas, a Tecnocracia inclusive, adota um sistema de mentor/aprendiz. Nos primeiros anos de um membro, um mais velho é designado para ensinar — ou escolhe ensinar — um recém-chegado inexperiente. Já nos últimos tempos de filiação, espera-se que o mais velho transmita sua experiência à geração seguinte. Além dos programas de treinamento habituais de cada grupo, um novo recruta muitas vezes acaba sob os cuidados de um membro experiente. E, no caso deste Defeito, você tirou a sorte grande.

Quando você toma um aprendiz, passa a ser responsável por alguém (qualquer que seja o título formal dele) que torna sua vida difícil. Você não pode simplesmente pôr essa pessoa na rua: precisa oferecer disciplina, orientação, treinamento e, muitas vezes, uma estrutura de apoio (teto, comida, espaço de pesquisa e assim por diante) para que o novato se torne um membro bem-sucedido da sua seita. Um aprendiz, porém, não é um vaso de planta; mesmo os mais cooperativos exigem tempo e atenção, e os atos deles – bons e nem tanto – se refletem no seu próprio status social. Os mais problemáticos, por extensão, podem empurrar um mentor rumo à solidão rabugenta.

Como Defeito, este Traço reflete a variedade de aprendizes possíveis e o efeito que eles têm sobre a sua vida:

(1 ponto) Um aluno ideal, cooperativo e dedicado, que ocupa muito pouco do seu espaço e do seu tempo, faz boa figura por você e parece ansioso por aprender, sem discutir muito.

(2 pontos) Um aluno típico, que precisa de um bom tanto de acompanhamento; comete deslizes ocasionais de protocolo e disciplina; e consome uma quantidade razoável de tempo, espaço e paciência. Ainda assim, é atento e mais ou menos respeitoso, e lhe dá motivos de sobra para se orgulhar.

(3 pontos) Um aluno bastante desnorteado, cuja presença consome tempo e atenção consideráveis. Este aprendiz pode ser desastrado, inconveniente, lerdo e vez ou outra problemático em situações sociais e exercícios de treinamento. Ele tem futuro, mas vai dar muito trabalho fazê-lo realizar seu potencial.

(4 pontos) Um aluno seriamente desafiador, cujo comportamento e dedicação deixam muito a desejar. Este aprendiz pode ter talento, mas o fardo começa a pesar mais que os benefícios de instruí-lo.

(5 pontos) Um imbecil obstinado, arrogante e desrespeitoso, cuja presença dá mais trabalho do que vale. Perigoso para si mesmo e para todos ao redor (você inclusive), ele é uma vergonha para a sociedade que vocês dividem. Por que mesmo você está treinando essa pessoa? Talvez um dia haja luz no fim do túnel, mas vai custar muito trabalho e sacrifício até que esse aprendiz seja algo além de uma perda do seu tempo.

De novo: esta é uma pessoa pela qual você é responsável. A menos que dedique bastante tempo, atenção e frequentemente recursos financeiros a melhorar a condição dele, seu aprendiz pode piorar com o tempo. Por outro lado, você pode conseguir moldar um aprendiz problemático até virar um exemplo para a sua sociedade. Do ponto de vista de regras, você pode reduzir o valor deste Defeito com trabalho dedicado – o encrenqueiro obstinado de cinco pontos pode acabar virando o aluno ideal de um ponto se você investir tempo, esforço e interpretação nisso. Narradores: permitam que o jogador compre a redução deste Defeito com experiência quando ele se esforçar para endireitar um aprendiz problemático, mas sintam-se à vontade também para agravar os inconvenientes do Defeito se o jogador deixar as coisas se arrastarem demais.

Apesar das preconcepções usuais sobre idade e experiência, um aprendiz pode ser mais velho que seu mentor. Ele pode ter pertencido originalmente a outra seita (digamos, um Verbena que desertou para a Nova Ordem Mundial ou para os Bata'a) e ter a cabeça cheia de ideias sobre como as coisas "deveriam" ser feitas – ideias que vão contra os seus ensinamentos. Ou pode ser um mago novo que Despertou na meia-idade e, por isso, tem dificuldade em receber ordens de um mago experiente que ele considera um garoto. Até os melhores alunos erram, e por isso nenhum nível deste Defeito vem sem dor de cabeça – afinal, é por isso que ele é um Defeito!

Mais uma vez, este Traço baseado em personagem representa um personagem de Narrador completo, cuja personalidade, necessidades, problemas e agendas fazem dele muito mais que uma lista de pontos numa ficha. Num grupo de interpretação experiente, você pode deixar outro jogador conduzir esse aprendiz, como personagem de apoio ou como o mago principal dele. Nesses casos, é claro, o aluno será menos poderoso e experiente que o professor, a menos que tenha começado sua vida Desperta como mago de outro grupo. De todo modo, o aprendiz deve ser parte importante da crônica, e pode até acabar virando o centro da história (como na saga Harry Potter) se o aprendizado der certo. Um aprendizado podre, por outro lado, ainda pode render a esse personagem um papel de destaque na crônica: o de antagonista cuja história próxima com o mago só torna a briga mais feia para todos os envolvidos.]==],
				},
				["Apprentice (2)"] = {
					pt = [==[Book of Secrets, pág. 81


Apprentice (2)


A maioria das sociedades metafísicas, a Tecnocracia inclusive, adota um sistema de mentor/aprendiz. Nos primeiros anos de um membro, um mais velho é designado para ensinar — ou escolhe ensinar — um recém-chegado inexperiente. Já nos últimos tempos de filiação, espera-se que o mais velho transmita sua experiência à geração seguinte. Além dos programas de treinamento habituais de cada grupo, um novo recruta muitas vezes acaba sob os cuidados de um membro experiente. E, no caso deste Defeito, você tirou a sorte grande.

Quando você toma um aprendiz, passa a ser responsável por alguém (qualquer que seja o título formal dele) que torna sua vida difícil. Você não pode simplesmente pôr essa pessoa na rua: precisa oferecer disciplina, orientação, treinamento e, muitas vezes, uma estrutura de apoio (teto, comida, espaço de pesquisa e assim por diante) para que o novato se torne um membro bem-sucedido da sua seita. Um aprendiz, porém, não é um vaso de planta; mesmo os mais cooperativos exigem tempo e atenção, e os atos deles – bons e nem tanto – se refletem no seu próprio status social. Os mais problemáticos, por extensão, podem empurrar um mentor rumo à solidão rabugenta.

Como Defeito, este Traço reflete a variedade de aprendizes possíveis e o efeito que eles têm sobre a sua vida:

(1 ponto) Um aluno ideal, cooperativo e dedicado, que ocupa muito pouco do seu espaço e do seu tempo, faz boa figura por você e parece ansioso por aprender, sem discutir muito.

(2 pontos) Um aluno típico, que precisa de um bom tanto de acompanhamento; comete deslizes ocasionais de protocolo e disciplina; e consome uma quantidade razoável de tempo, espaço e paciência. Ainda assim, é atento e mais ou menos respeitoso, e lhe dá motivos de sobra para se orgulhar.

(3 pontos) Um aluno bastante desnorteado, cuja presença consome tempo e atenção consideráveis. Este aprendiz pode ser desastrado, inconveniente, lerdo e vez ou outra problemático em situações sociais e exercícios de treinamento. Ele tem futuro, mas vai dar muito trabalho fazê-lo realizar seu potencial.

(4 pontos) Um aluno seriamente desafiador, cujo comportamento e dedicação deixam muito a desejar. Este aprendiz pode ter talento, mas o fardo começa a pesar mais que os benefícios de instruí-lo.

(5 pontos) Um imbecil obstinado, arrogante e desrespeitoso, cuja presença dá mais trabalho do que vale. Perigoso para si mesmo e para todos ao redor (você inclusive), ele é uma vergonha para a sociedade que vocês dividem. Por que mesmo você está treinando essa pessoa? Talvez um dia haja luz no fim do túnel, mas vai custar muito trabalho e sacrifício até que esse aprendiz seja algo além de uma perda do seu tempo.

De novo: esta é uma pessoa pela qual você é responsável. A menos que dedique bastante tempo, atenção e frequentemente recursos financeiros a melhorar a condição dele, seu aprendiz pode piorar com o tempo. Por outro lado, você pode conseguir moldar um aprendiz problemático até virar um exemplo para a sua sociedade. Do ponto de vista de regras, você pode reduzir o valor deste Defeito com trabalho dedicado – o encrenqueiro obstinado de cinco pontos pode acabar virando o aluno ideal de um ponto se você investir tempo, esforço e interpretação nisso. Narradores: permitam que o jogador compre a redução deste Defeito com experiência quando ele se esforçar para endireitar um aprendiz problemático, mas sintam-se à vontade também para agravar os inconvenientes do Defeito se o jogador deixar as coisas se arrastarem demais.

Apesar das preconcepções usuais sobre idade e experiência, um aprendiz pode ser mais velho que seu mentor. Ele pode ter pertencido originalmente a outra seita (digamos, um Verbena que desertou para a Nova Ordem Mundial ou para os Bata'a) e ter a cabeça cheia de ideias sobre como as coisas "deveriam" ser feitas – ideias que vão contra os seus ensinamentos. Ou pode ser um mago novo que Despertou na meia-idade e, por isso, tem dificuldade em receber ordens de um mago experiente que ele considera um garoto. Até os melhores alunos erram, e por isso nenhum nível deste Defeito vem sem dor de cabeça – afinal, é por isso que ele é um Defeito!

Mais uma vez, este Traço baseado em personagem representa um personagem de Narrador completo, cuja personalidade, necessidades, problemas e agendas fazem dele muito mais que uma lista de pontos numa ficha. Num grupo de interpretação experiente, você pode deixar outro jogador conduzir esse aprendiz, como personagem de apoio ou como o mago principal dele. Nesses casos, é claro, o aluno será menos poderoso e experiente que o professor, a menos que tenha começado sua vida Desperta como mago de outro grupo. De todo modo, o aprendiz deve ser parte importante da crônica, e pode até acabar virando o centro da história (como na saga Harry Potter) se o aprendizado der certo. Um aprendizado podre, por outro lado, ainda pode render a esse personagem um papel de destaque na crônica: o de antagonista cuja história próxima com o mago só torna a briga mais feia para todos os envolvidos.]==],
				},
				["Apprentice (3)"] = {
					pt = [==[Book of Secrets, pág. 81


Apprentice (3)


A maioria das sociedades metafísicas, a Tecnocracia inclusive, adota um sistema de mentor/aprendiz. Nos primeiros anos de um membro, um mais velho é designado para ensinar — ou escolhe ensinar — um recém-chegado inexperiente. Já nos últimos tempos de filiação, espera-se que o mais velho transmita sua experiência à geração seguinte. Além dos programas de treinamento habituais de cada grupo, um novo recruta muitas vezes acaba sob os cuidados de um membro experiente. E, no caso deste Defeito, você tirou a sorte grande.

Quando você toma um aprendiz, passa a ser responsável por alguém (qualquer que seja o título formal dele) que torna sua vida difícil. Você não pode simplesmente pôr essa pessoa na rua: precisa oferecer disciplina, orientação, treinamento e, muitas vezes, uma estrutura de apoio (teto, comida, espaço de pesquisa e assim por diante) para que o novato se torne um membro bem-sucedido da sua seita. Um aprendiz, porém, não é um vaso de planta; mesmo os mais cooperativos exigem tempo e atenção, e os atos deles – bons e nem tanto – se refletem no seu próprio status social. Os mais problemáticos, por extensão, podem empurrar um mentor rumo à solidão rabugenta.

Como Defeito, este Traço reflete a variedade de aprendizes possíveis e o efeito que eles têm sobre a sua vida:

(1 ponto) Um aluno ideal, cooperativo e dedicado, que ocupa muito pouco do seu espaço e do seu tempo, faz boa figura por você e parece ansioso por aprender, sem discutir muito.

(2 pontos) Um aluno típico, que precisa de um bom tanto de acompanhamento; comete deslizes ocasionais de protocolo e disciplina; e consome uma quantidade razoável de tempo, espaço e paciência. Ainda assim, é atento e mais ou menos respeitoso, e lhe dá motivos de sobra para se orgulhar.

(3 pontos) Um aluno bastante desnorteado, cuja presença consome tempo e atenção consideráveis. Este aprendiz pode ser desastrado, inconveniente, lerdo e vez ou outra problemático em situações sociais e exercícios de treinamento. Ele tem futuro, mas vai dar muito trabalho fazê-lo realizar seu potencial.

(4 pontos) Um aluno seriamente desafiador, cujo comportamento e dedicação deixam muito a desejar. Este aprendiz pode ter talento, mas o fardo começa a pesar mais que os benefícios de instruí-lo.

(5 pontos) Um imbecil obstinado, arrogante e desrespeitoso, cuja presença dá mais trabalho do que vale. Perigoso para si mesmo e para todos ao redor (você inclusive), ele é uma vergonha para a sociedade que vocês dividem. Por que mesmo você está treinando essa pessoa? Talvez um dia haja luz no fim do túnel, mas vai custar muito trabalho e sacrifício até que esse aprendiz seja algo além de uma perda do seu tempo.

De novo: esta é uma pessoa pela qual você é responsável. A menos que dedique bastante tempo, atenção e frequentemente recursos financeiros a melhorar a condição dele, seu aprendiz pode piorar com o tempo. Por outro lado, você pode conseguir moldar um aprendiz problemático até virar um exemplo para a sua sociedade. Do ponto de vista de regras, você pode reduzir o valor deste Defeito com trabalho dedicado – o encrenqueiro obstinado de cinco pontos pode acabar virando o aluno ideal de um ponto se você investir tempo, esforço e interpretação nisso. Narradores: permitam que o jogador compre a redução deste Defeito com experiência quando ele se esforçar para endireitar um aprendiz problemático, mas sintam-se à vontade também para agravar os inconvenientes do Defeito se o jogador deixar as coisas se arrastarem demais.

Apesar das preconcepções usuais sobre idade e experiência, um aprendiz pode ser mais velho que seu mentor. Ele pode ter pertencido originalmente a outra seita (digamos, um Verbena que desertou para a Nova Ordem Mundial ou para os Bata'a) e ter a cabeça cheia de ideias sobre como as coisas "deveriam" ser feitas – ideias que vão contra os seus ensinamentos. Ou pode ser um mago novo que Despertou na meia-idade e, por isso, tem dificuldade em receber ordens de um mago experiente que ele considera um garoto. Até os melhores alunos erram, e por isso nenhum nível deste Defeito vem sem dor de cabeça – afinal, é por isso que ele é um Defeito!

Mais uma vez, este Traço baseado em personagem representa um personagem de Narrador completo, cuja personalidade, necessidades, problemas e agendas fazem dele muito mais que uma lista de pontos numa ficha. Num grupo de interpretação experiente, você pode deixar outro jogador conduzir esse aprendiz, como personagem de apoio ou como o mago principal dele. Nesses casos, é claro, o aluno será menos poderoso e experiente que o professor, a menos que tenha começado sua vida Desperta como mago de outro grupo. De todo modo, o aprendiz deve ser parte importante da crônica, e pode até acabar virando o centro da história (como na saga Harry Potter) se o aprendizado der certo. Um aprendizado podre, por outro lado, ainda pode render a esse personagem um papel de destaque na crônica: o de antagonista cuja história próxima com o mago só torna a briga mais feia para todos os envolvidos.]==],
