				["Arcane Curse (1)"] = {
					pt = [==[Lore of the Clans, pág. 219


Arcane Curse (1)


Por causa dos seus estudos ou dos de outra pessoa, você sofre de uma maldição mágica. Pode ser uma aversão ou alergia, ou mesmo um efeito mágico estranho. O nível do defeito depende de quanto a maldição o debilita. Curar a aflição pode ser impossível, ou exigir algum tipo de missão ou pesquisa avançada.

1 ponto: uma esquisitice pequena, como um traço animal ou uma cor de olhos estranha.

2 pontos: um problema perceptível, como sua magia carregar uma mácula ou padrão que a torna imediatamente reconhecível, ou plantas murcharem na sua presença.

3 pontos: algo problemático, como pessoas adoecerem na sua presença ou animais atacarem você.

4 pontos: um empecilho preocupante, como desenvolver a fraqueza de outro Clã.

5 pontos: potencialmente mortal, como o luar ser tão perigoso para você quanto a luz do sol.]==],
