				},
				["Artificially Aged"] = {
					pt = [==[Ghouls & Revenants, pág. 138


Artificially Aged


Você é um carniçal ou revenante menor de idade que foi moldado pela carne para parecer um adulto mais velho e maduro. Sua verdadeira maturidade ainda está longe, no futuro, mas você aparenta uma ou duas décadas a mais que sua idade real. Enquanto permanecer carniçal, seu corpo não envelhecerá.

Por causa dos horrores infligidos ao seu corpo e à sua mente jovens, sua personagem talvez nunca se reconcilie com o que lhe aconteceu. Fisicamente, você pode passar por alguém bem mais velho, mas mental e emocionalmente ainda é uma criança. Assim, você provavelmente encontrará dificuldades na maioria das situações sociais, e seu Narrador pode exigir que você subtraia um ou mais dados das paradas de dados Sociais.

Usado por: como a Qualidade Modificação de Vicissitude, este Defeito só pode ser adquirido a critério do seu Narrador.]==],
				},
				["Aura of the Typhon"] = {
					pt = [==[Lore of the Clans, pág. 67


Aura of the Typhon


Alguma coisa rasteja sob a sua pele, enrodilhada na sua própria essência — algo que faz os Lupinos o espreitarem por algum propósito medonho que você não compreende. Os uivos deles seguem seus passos. Você capta vislumbres de movimento borrado e o brilho de olhos e dentes no escuro. Eles chegam mais perto a cada noite. O que querem de você?]==],
				},
				["Bad Sight (1)"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 481


Bad Sight (1)


Sua visão é defeituosa. As dificuldades de qualquer rolagem que envolva enxergar aumentam em dois. Como Defeito de um ponto, a condição pode ser corrigida com óculos ou lentes de contato; como Defeito de três pontos, ela é severa demais para ser corrigida.]==],
				},
				["Bad Sight (3)"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 481


Bad Sight (3)


Sua visão é defeituosa. As dificuldades de qualquer rolagem que envolva enxergar aumentam em dois. Como Defeito de um ponto, a condição pode ser corrigida com óculos ou lentes de contato; como Defeito de três pontos, ela é severa demais para ser corrigida.]==],
				},
				["Banshee-in-Waiting"] = {
					pt = [==[Lore of the Bloodlines, pág. 3


Banshee-in-Waiting


A Fuga está aos poucos empurrando você para a loucura. Se sua Força de Vontade temporária chegar a 0, você automaticamente ganha uma perturbação que jamais poderá ser removida. Outras perturbações adquiridas por outros meios podem ser removidas normalmente. Você pode acumular no máximo três dessas perturbações permanentes por perder sua Força de Vontade antes de ser consumido por ela. Se acontecer uma quarta vez, você se perde imediatamente na Fuga e vira um personagem sob controle do Narrador, caminhando na direção que a música mandar e matando tudo o que cruzar seu caminho.]==],
				},
				["Beacon of the Unholy"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 494


Beacon of the Unholy


Você irradia uma maldade palpável. Membros do clero e mortais devotos sabem por instinto que há algo terrivelmente errado com você, e reagem de acordo.]==],
				},
				["Beast Within"] = {
					pt = [==[Book of Secrets, pág. 92


Beast Within


Você tem um temperamento verdadeiramente infernal: tão violento que parece um vulcão dentro da alma. Como um lobisomem ou um vampiro, você está sujeito ao temido frenesi, que o transforma numa máquina de fúria incandescente. Sob estresse intenso, você arrisca perder cada fiapo de iluminação que possui. Levado a esse extremo, você desencadeia os poderes mais imediatamente destrutivos ao seu alcance — e que se dane a "vulgaridade"! Todos ao seu redor viram alvo, e as consequências só importam para você depois que a tempestade interior passa.

Em termos de sistema, este Defeito o lança em fúrias letais como o Traço Furioso/Atavismo de Estresse apresentado em Mage 20, p. 644. Em vez de rolar sua Força de Vontade para evitar o frenesi, porém, você rola seu valor de Avatar mais um dado, usando sua Força de Vontade como dificuldade. Se, por exemplo, o jovem Vyper Trabia sofre do Defeito Besta Interior, com Avatar 4 e Força de Vontade 5, o jogador de Vyper rola cinco dados contra dificuldade 5 quando aquele estabanado Akáshico está sob estresse feroz. Uma falha nessa rolagem manda Vyper para uma fúria berserk. Pois é, isso provavelmente acontece com bastante frequência. Os amigos de Vyper não ficam por perto quando as coisas desandam.

(Se você usar o Traço opcional de Ressonância descrito no Capítulo Dois, pode substituir a parada de dados da fúria pela sua Ressonância mais alta, mais um dado. A dificuldade continua sendo seu Traço de Força de Vontade, e sua Ressonância mais o dado extra deve ao menos igualar, se não superar, seu Traço de Avatar. Nesse caso, a Ressonância em questão precisa ser algo caprichosamente instável – Selvagem, Primal, Feroz e assim por diante – e não uma energia calma e centrada. Para detalhes, veja Quatro Sabores de Ressonância, pp. 136-138.)

Como o Avatar pode ser visto como sua Besta interior, um personagem com Essência de Padrão não pode adquirir este Defeito. Ele serve melhor a Essências Dinâmicas, embora um Avatar Questionador ou Primordial também possa alcançar fúrias assustadoras. Um mago em fúria não consegue usar rituais nem ferramentas complicadas; só os métodos de ataque mais diretos – mágicos ou não – funcionam. Embora magos raramente sofram lapsos tão grotescos de autocontrole, um Carniçal Desperto (como na Qualidade), um ciborgue, um Vitorioso, um Parente de Metamorfo (de novo, como na Qualidade) ou um metamorfo animalesco podem carregar essa monstruosidade desumana.

Para traços de personagem igualmente bestiais, veja o Defeito Mental: Mente Feral (p. 52) e a Prática Expandida de Animalismo no Capítulo Três, pp. 197-199.]==],
				},
				["Bedeviled"] = {
					pt = [==[Book of Secrets, pág. 94


Bedeviled


Ah, seu pobre coitado! Um poder misterioso decidiu sacanear você, e é perfeitamente capaz de transformar sua vida numa crônica de desgraças. Miséria e reveses são seu pão de cada dia; se as coisas começam a melhorar, você começa a olhar para cima, procurando a bigorna inevitável descendo em direção à sua cabeça. Isso vai muito além de simples azar ou de uma maldiçãozinha qualquer. Seu inimigo enigmático é um desgraçado dedicado, e seja lá o que for (não é necessariamente um diabo de verdade, embora certamente pareça um para você!), essa força tem recursos aparentemente ilimitados e um senso de humor bem doentio; em resumo, é o seu Narrador típico.

Defeito baseado em história, este Traço miserável basicamente dá ao Narrador licença para escalar sua personagem como protagonista de um Livro de Jó do século XXI. (E, de novo, dê uma olhada em Tragédia.) Deve haver alguma lógica por trás dessa sacanagem metafísica, é claro, mas a origem das suas agonias, e o modo como você poderia acabar com elas, é assunto que o Narrador sabe e você tem de descobrir… se tiver a sorte de viver o bastante.]==],
				},
				["Bestial"] = {
					pt = [==[Lore of the Clans, pág. 163


Bestial


Você é mais próximo dos animais que dos humanos, e isso aparece. Além da fraqueza do Clã Nosferatu, você tem outra: sempre que entra em frenesi, ganha uma característica animal, como na fraqueza do Clã Gangrel (V20, p. 55).

Com permissão do Narrador, características animais adquiridas em definitivo podem justificar a compra de certas Qualidades depois da criação do personagem, como Membros de Lagarto (p. 160) ou Fauces Monstruosas (pp. 160-161). Nesse caso, o Narrador pode simplesmente concedê-las ou exigir gasto de pontos de experiência (por exemplo, o dobro do valor em pontos da Qualidade). Defeitos semelhantes também podem ser adquiridos, mas não rendem pontos livres nem de experiência adicionais.]==],
				},
				["Betrayer's Mark"] = {
					pt = [==[Lore of the Clans, pág. 219


Betrayer's Mark


Embora você seja leal à Casa e ao Clã Tremere, por algum motivo carrega a marca dos antitribu (veja o quadro na p. 216). Pode ser que tenha voltado ao Clã depois de deixar a Sabá, ou que tenha participado da Vaulderie sem saber ou como parte de uma operação disfarçada. Seja qual for a razão, a marca deixa os outros Tremere desconfiados de você. Você terá de se esforçar muito mais para provar seu valor, e poucos no Clã lhe confiarão posições de poder e responsabilidade.]==],
				},
				["Bigot"] = {
					pt = [==[Book of Secrets, pág. 50


Bigot


Você odeia pra caramba aquela gente, seja lá quem "aquela gente" for. Aquela gente provavelmente também não gosta de você. Certo, talvez você não deixe seus sentimentos evidentes, mas sua convicção de que aquela gente é feita de encrenqueiros inferiores que são Tudo o Que Há de Errado com o Mundo, Caramba, transparece nas suas ações e decisões mesmo que você não diga nada disso em voz alta. Esses preconceitos determinam sua escolha de amigos e inimigos, guiam suas crenças, influenciam sua política e tendem a vazar em momentos inconvenientes se você perder a cabeça. (Veja Pavio Curto, acima.) Você pode até mudar de ideia algum dia, mas por ora o fanatismo é a lente pela qual você vê o mundo… e, especialmente para magos, esse tipo de coisa significa muito para o mundo em geral.

Apesar da visão convencional (e não incorreta) do fanático como racista, machista e homofóbico raivoso, gente supostamente liberal também pode ser fanática; os piores fanáticos, aliás, costumam ser os cheios de razão, cujas alegações de mente aberta são desmentidas por um preconceito silencioso e implacável contra aquela gente. Versões mais antigas deste Defeito o avaliavam em apenas dois pontos; no século XXI, porém, o fanatismo tem mais chance de lhe render encrenca quando é revelado, sobretudo na internet ou na mídia de massa… a menos, claro, que você esteja concorrendo à presidência ou falando em nome de gente que compartilha suas opiniões, caso em que você vira santo para uns e demônio para outros.

Vale notar que fanáticos costumam ter razões compreensíveis para seus preconceitos. Elas podem nascer de mágoas pessoais, viés cultural, ansiedades raciais, proclamações das escrituras, traumas psíquicos, choques de gênero, paradigmas filosóficos e – especialmente no mundo de Mage – distinções físicas e metafísicas entre "nós" e "eles". Essas razões provavelmente soam como besteira para a maioria das pessoas, mas continuam perfeitamente justificadas para o fanático em questão.

Vale notar também que este Defeito não deve de forma alguma ser tomado como licença para maltratar seus colegas de mesa. Como em outros temas para público adulto, os preconceitos de um personagem podem virar gatilho de tensões reais dentro do grupo e, por isso, devem ser tratados com cuidado, como descrito nas seções Problemas e Gatilhos de Mage 20, pp. 344-345.]==],
				},
				["Bizarre Hunger (2)"] = {
					pt = [==[Book of Secrets, pág. 87


Bizarre Hunger (2)


Você prefere – talvez até precise – comer merda esquisita… possivelmente no sentido literal da expressão. Talvez tenha feito um voto, sofrido uma maldição, sido tratado (ou criado) com rituais profanos ou hiperciência arcana, ou sido iniciado numa irmandade oculta com… exigências interessantes de admissão. Em todo caso, você precisa consumir substâncias que podem ser degradantes, desagradáveis, caras ou francamente ilegais.

Quanto mais inconveniente a substância, mais este Defeito vale:

(2 pontos) Fácil de conseguir, ainda que não tão fácil de engolir (papel, ovos crus, fezes etc.).

(3 pontos) Desagradável, arriscada e talvez ilegal de consumir (carne podre, água de pântano, cannabis crua e afins).

(4 pontos) Rango especializado, imundo, criminoso e/ou caro (sangue humano, poções ou refeições feitas sob encomenda e coisas do tipo).

(5 pontos) Você realmente não deveria comer essas coisas… mas precisa (humanos vivos, lodo tóxico, pó de ouro, concocções altamente especializadas com aparência de comida e outras formas semelhantes de sustento).

Para cada ponto no seu Traço de Vigor, você aguenta um dia sem satisfazer sua exigência alimentar especial. Depois disso, perde um nível de vitalidade por dia até consumir sua substância particular ou então morrer de fome ou sede, sofrer a punição de um voto não cumprido, ou suportar quaisquer outras consequências que resultem de negar sua fome bizarra.

Para um Traço companheiro relacionado (e provavelmente essencial), veja a Qualidade física: Estômago de Ferro, p. 36. E, para um instrumento de foco possivelmente relacionado, veja a entrada Canibalismo dos Instrumentos Expandidos do Capítulo Três, pp. 206-207.]==],
				},
