				},
				["Black and White"] = {
					pt = [==[The Hunters Hunted II, pág. 42


Black and White


O mundo é, na verdade, uma coleção de tons de cinza, mas sua personagem não o vê assim. Para ela, tudo é claro como preto no branco. Ela pensa em termos de pessoas a favor ou contra, quente ou frio, bom ou mau, fácil ou impossível, burro ou genial. Essa mentalidade fechada pode custar caro à sua personagem em oportunidades perdidas, mal-entendidos e sub ou superestimação dos outros. Em situações sociais em que a perspectiva sentenciosa da sua personagem entra em jogo, as dificuldades das rolagens correspondentes aumentam em um.]==],
				},
				["Black Sheep"] = {
					pt = [==[Anarchs Unbound, pág. 102


Black Sheep


Você pertence a uma linhagem prestigiosa, tida como exemplo por outra seita — ou ao menos era assim antes de você aderir ao Movimento Anarquista. Você envergonhou seu senhor, seu avô e talvez ainda mais acima na linha; agora chegou a hora de pagar. Seus antigos irmãos de ninhada querem trazê-lo de volta ao rebanho, nem que seja para limpar a mancha da reputação deles, e se recusam a reconhecer sua independência. Seu senhor e seu avô não poupam esforços para tornar a vida difícil para você e para qualquer Anarquista que lhe dê abrigo. Este defeito combina os efeitos de Ressentimento do Senhor e Caçado como um Cão, de modo que esses defeitos não podem ser adquiridos junto com Ovelha Negra. (Para mais informações sobre eles, veja as pp. 490 e 492 de V20, respectivamente.)

Além disso, muitos membros do Movimento Anarquista desconfiam ativamente de você só pela sua linhagem, acreditando que seja um agente duplo. Todas as rolagens sociais envolvendo seus companheiros Anarquistas sofrem +2 de dificuldade.]==],
				},
				["Blacklisted (1)"] = {
					pt = [==[Book of Secrets, pág. 59


Blacklisted (1)


Por ter se indisposto com algum Poder Constituído, você virou pária junto a algum segmento das Massas. O resultado afeta suas chances de emprego, sua posição social, sua situação legal, seu crédito, checagens de antecedentes, possibilidades de aluguel e outros elementos importantes de existir no mundo cotidiano.

Apresentado originalmente como Antecedente Adverso de Certificação, este Defeito afeta sua situação oficial regional, nacional e talvez internacional. O grau em que você foi banido profissionalmente depende do valor do Defeito:

(1 ponto) Trivial – ficha de motorista ruim, suspeito de furto em lojas, banido de um sindicato local.

(2 pontos) Menor – ficha criminal por contravenção, carteira suspensa.

(3 pontos) Significativo – advogado cassado, clérigo destituído, filiação política impopular, baixa desonrosa das forças armadas.

(4 pontos) Grave – condenado por crime, agressor sexual fichado, lista de vigilância do governo, registro médico revogado.

(5 pontos) Pária – lista dos mais procurados do FBI, suspeito de terrorismo, pedófilo condenado, declarado legalmente incapaz ou insano.

Uma inclusão na lista negra de quatro ou cinco pontos também acaba no banco de dados de vigilância da Tecnocracia – um lugar bem perigoso para um mago estar! E, embora os Despertos normalmente não consultem as autoridades mundanas antes de recrutar ou fazer alianças com os seus, um mago que teve problemas graves com essas autoridades provavelmente terá problemas com magos também… especialmente se esses problemas incluírem crimes como terrorismo ou pedofilia, que certos magos levam muito, muito a mal.]==],
				},
