(4 pontos) Grave – condenado por crime, agressor sexual fichado, lista de vigilância do governo, registro médico revogado.

(5 pontos) Pária – lista dos mais procurados do FBI, suspeito de terrorismo, pedófilo condenado, declarado legalmente incapaz ou insano.

Uma inclusão na lista negra de quatro ou cinco pontos também acaba no banco de dados de vigilância da Tecnocracia – um lugar bem perigoso para um mago estar! E, embora os Despertos normalmente não consultem as autoridades mundanas antes de recrutar ou fazer alianças com os seus, um mago que teve problemas graves com essas autoridades provavelmente terá problemas com magos também… especialmente se esses problemas incluírem crimes como terrorismo ou pedofilia, que certos magos levam muito, muito a mal.]==],
				},
				["Blacklisted (5)"] = {
					pt = [==[Book of Secrets, pág. 59


Blacklisted (5)


Por ter se indisposto com algum Poder Constituído, você virou pária junto a algum segmento das Massas. O resultado afeta suas chances de emprego, sua posição social, sua situação legal, seu crédito, checagens de antecedentes, possibilidades de aluguel e outros elementos importantes de existir no mundo cotidiano.

Apresentado originalmente como Antecedente Adverso de Certificação, este Defeito afeta sua situação oficial regional, nacional e talvez internacional. O grau em que você foi banido profissionalmente depende do valor do Defeito:

(1 ponto) Trivial – ficha de motorista ruim, suspeito de furto em lojas, banido de um sindicato local.

(2 pontos) Menor – ficha criminal por contravenção, carteira suspensa.

(3 pontos) Significativo – advogado cassado, clérigo destituído, filiação política impopular, baixa desonrosa das forças armadas.

(4 pontos) Grave – condenado por crime, agressor sexual fichado, lista de vigilância do governo, registro médico revogado.

(5 pontos) Pária – lista dos mais procurados do FBI, suspeito de terrorismo, pedófilo condenado, declarado legalmente incapaz ou insano.

Uma inclusão na lista negra de quatro ou cinco pontos também acaba no banco de dados de vigilância da Tecnocracia – um lugar bem perigoso para um mago estar! E, embora os Despertos normalmente não consultem as autoridades mundanas antes de recrutar ou fazer alianças com os seus, um mago que teve problemas graves com essas autoridades provavelmente terá problemas com magos também… especialmente se esses problemas incluírem crimes como terrorismo ou pedofilia, que certos magos levam muito, muito a mal.]==],
				},
				["Blind"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 484


Blind


Você não enxerga. Personagens podem compensar a perda da visão ficando mais atentos aos outros sentidos, mas pistas e imagens visuais estão perdidas para eles. As dificuldades de todas as rolagens baseadas em Destreza aumentam em dois. Curiosamente, vampiros com Percepção da Aura (Auspícios 2) ainda conseguem usar essa habilidade, embora a informação seja interpretada pelos outros sentidos. Por outro lado, vampiros que precisam de contato visual para usar poderes como Dominação contra você sofrem apenas uma penalidade para fazê-lo (veja o quadro na p. 152). Mental]==],
				},
				["Blood Feud"] = {
					pt = [==[Ghouls & Revenants, pág. 132


Blood Feud


A hostilidade entre famílias revenantes como os Grimaldi e os Zantosa é bem conhecida em toda a Sabá. As rivalidades entre Brujah e Ventrue vez ou outra transbordam para o comportamento de seus carniçais nas cidades da Camarilla. Brigas entre famílias revenantes são comuns demais, e essas rixas se arrastam há tanto tempo que alguns membros talvez já tenham esquecido como a discussão começou. Uma Rixa de Sangue pode ser recente, mas o mais provável é que uma rivalidade mortal venha fervendo há décadas, se não séculos.

Nem toda desavença ou rivalidade entre famílias ou facções, porém, é considerada Rixa de Sangue. Uma Rixa de Sangue é o que acontece depois que uma ofensa ou um dano escalam a alturas impossíveis, e a causa inicial da discussão só pode ser reparada quando as duas dívidas forem quitadas, muitas vezes com violência. Membros da família chegam a jurar vinganças para ferir a família rival na primeira oportunidade. Como a própria natureza da rixa, a violência que as duas famílias causam pode ir de cortar pneus a cortar gargantas.

Embora a Rixa de Sangue se aplique especialmente a membros de certas famílias revenantes, este Defeito também pode valer para Clãs rivais numa cidade. Carniçais leais podem se ofender com um deslize ou buscar vingança por uma afronta ao seu Domitor, e esse sentimento pode escalar até o ódio e o desejo de matar. Um carniçal Gangrel pode se envolver numa disputa amarga por território ou domínio com os servos de um Primogênito Toreador. Traições e insultos suficientes podem ser trocados ao longo do conflito para que discussões tensas explodam em brigas ferozes. Em geral, porém, para existir uma Rixa de Sangue é preciso mais que uma simples rivalidade entre as duas partes. Numa Rixa de Sangue, vários membros de cada lado devem estar dispostos a lutar pelo insulto ou pela afronta. O ódio entre os dois lados cresceu com o tempo, e os chamados por vingança têm peso.

Quando confrontado com a possibilidade de que seu rival esteja por perto, sua personagem precisa fazer um teste de Frenesi com -2 de dificuldade. Se tiver sucesso, ela consegue controlar a fúria cega causada pela sede de vingança.

Se falhar no teste, você se sentirá compelido a agir de acordo com sua obsessão por vingança. Pode procurar e confrontar seu rival. Pode atacar alguém parecido com ele, sabotar seu carro ou atacar sua namorada. Pode até incitar as pessoas ao redor a entrar na briga junto. Como você age a partir desse ódio é escolha sua, mas uma falha garante que a Rixa de Sangue será renovada.

Você pode gastar um ponto de Força de Vontade para adiar o momento do frenesi por um turno. Contudo, quanto mais adiar a sua sede de vingança, maiores as chances de que o rival aja de acordo com a dele.

Usado por: revenantes com rivalidade clara com outra família, ou carniçais de Clãs, linhagens ou Seitas em guerra.

Para adquirir este Defeito, você precisa acertar com o Narrador com qual família (ou Clã) é a Rixa de Sangue e quanto o personagem sabe sobre a causa dela. Você também precisa escolher um rival específico do lado oposto, profundamente envolvido na rixa ou na sua origem.]==],
				},
				["Blood Hunted (4)"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 493


Blood Hunted (4)


Você virou alvo de uma caçada de sangue, e voltar à sua cidade natal significa morte. Por quatro pontos, este Defeito significa que apenas sua cidade natal está proibida para você. Por seis, significa que a Camarilla inteira uiva pela sua vitae. Este Defeito só pode ser adquirido por vampiros da Camarilla.]==],
				},
				["Blood Hunted (6)"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 493


Blood Hunted (6)


Você virou alvo de uma caçada de sangue, e voltar à sua cidade natal significa morte. Por quatro pontos, este Defeito significa que apenas sua cidade natal está proibida para você. Por seis, significa que a Camarilla inteira uiva pela sua vitae. Este Defeito só pode ser adquirido por vampiros da Camarilla.]==],
				},
				["Blood Magick"] = {
					pt = [==[Book of Secrets, pág. 92


Blood Magick


Suas Artes exigem sangue… especificamente, o seu próprio sangue. E, embora muitas práticas empreguem pequenos cortes rituais ou sangrias, este grau de sacrifício exige uma quantidade lesiva de fluido vital a cada vez que você lança uma magia.

Com este Defeito (rotulado por engano como Qualidade no suplemento Sorcerer, Revised Edition), você sofre um nível de vitalidade de dano contundente inabsorvível sempre que emprega um Efeito. Em termos de história, você se corta, rasga desenhos na própria pele ou se fere de outro modo o bastante para verter o sangue exigido. Isso pode se acumular rápido se você estiver lançando muita magia sem se dar chance de curar, já que o dano contundente logo vira dano letal (veja Tipos de Ferimento em Mage 20, p. 406). Enquanto isso, sua sangria parece bem nojenta e evidente (muitas vezes de forma vulgar) e tende a sujar tudo. Seus companheiros podem apreciar o resultado da sua magia, mas talvez tenham objeções aos métodos que você usa… ainda mais porque a magia de sangue tem uma fama bastante ruim entre todas as práticas, exceto as mais primais.]==],
				},
				["Blood Weakness (4)"] = {
					pt = [==[Lore of the Bloodlines, pág. 4


Blood Weakness (4)


A linhagem começou como um experimento para fabricar um Cainita a partir de linhagens diversas. Eles aperfeiçoaram o processo alquímico, mas em algum ponto do caminho uma fraqueza de um ancestral pegou. Ela se manifestou no seu Abraço. Além das fraquezas que você já possui, você também possui a fraqueza dos Gangrel (V20, p. 55) ou a dos Tzimisce (V20, p. 71). Por quatro pontos, escolha uma das duas. Por sete, você tem as duas. Gárgulas Guerreiras com a versão Gangrel da Fraqueza de Sangue podem ganhar características animais e características de pedra num mesmo frenesi.

Além disso, escolha uma das quatro Disciplinas disponíveis para as Gárgulas. Para você, essa Disciplina é considerada fora de Clã e custa a quantia mais alta de pontos de experiência para ser elevada.]==],
				},
				["Blood Weakness (7)"] = {
					pt = [==[Lore of the Bloodlines, pág. 4


Blood Weakness (7)


A linhagem começou como um experimento para fabricar um Cainita a partir de linhagens diversas. Eles aperfeiçoaram o processo alquímico, mas em algum ponto do caminho uma fraqueza de um ancestral pegou. Ela se manifestou no seu Abraço. Além das fraquezas que você já possui, você também possui a fraqueza dos Gangrel (V20, p. 55) ou a dos Tzimisce (V20, p. 71). Por quatro pontos, escolha uma das duas. Por sete, você tem as duas. Gárgulas Guerreiras com a versão Gangrel da Fraqueza de Sangue podem ganhar características animais e características de pedra num mesmo frenesi.

Além disso, escolha uma das quatro Disciplinas disponíveis para as Gárgulas. Para você, essa Disciplina é considerada fora de Clã e custa a quantia mais alta de pontos de experiência para ser elevada.]==],
				},
				["Blood-Hungry Soul (2)"] = {
					pt = [==[Book of Secrets, pág. 87


Blood-Hungry Soul (2)


Numa encarnação anterior, você foi um carniçal escravizado por um vício profano em sangue vampírico. Agora precisa resistir ao chamado daquela vida passada voraz e à fixação dela na vitae inebriante dos Cainitas.

Quanto mais funda a sua sede por essa satisfação maldita, mais este Defeito vale:

(2 pontos) Você recorda as tentações gloriosas do sangue, mas lembra delas como uma escolha ruim de muito tempo atrás. Se a oportunidade surgir, porém, precisará de uma rolagem de Força de Vontade (dificuldade 5) para resistir ao impulso de perseguir de novo aquele vício. Se sucumbir mais uma vez nesta vida, a dificuldade para resistir às tentações seguintes sobe para 6 toda vez que a chance de consumir esse sangue reaparecer.

(3 pontos) A tentação é mais forte. Agora a rolagem para resistir ao primeiro gole é 6, e a para resistir aos petiscos carmesins seguintes vira 8.

(5 pontos) Você está mal. Muito mal! Obcecado pelas lembranças do glorioso sangue místico, você precisa vencer dificuldade 8 para resistir aos velhos hábitos, e dificuldade 10 a cada tentativa de negar essa sede depois de ter recaído no vício maldito.

Isso não vai acabar bem… Veja o quadro Magos, o Laço de Sangue e os Efeitos da Vitae, p. 76, para os efeitos de longo prazo desses vícios fatais.]==],
				},
				["Blood-Hungry Soul (3)"] = {
