				},
				["Body Trail"] = {
					pt = [==[Lore of the Bloodlines, pág. 5


Body Trail


Seja porque o Nagaraja é desleixado demais e propenso a ignorar detalhes durante suas mortes, seja porque gosta especialmente de deixar uma assinatura em cada uma delas para mandar um recado, os outros podem usar isso para rastreá-lo. Toda vez, há objetos na cena do crime que podem levar direto até ele, obrigando-o a viver olhando por cima do ombro. A polícia está sempre a um passo de prendê-lo, ou os assassinos da Camarilla o têm na mira. Em todo caso, deixar um rastro é uma coisa terrível. Para cada pessoa que ele mata durante uma mesma história, a dificuldade dos testes de Sobrevivência para rastreá-lo cai em 1. Essa penalidade é zerada no começo de uma nova história… se ele sobreviver até a próxima, claro.]==],
				},
				["Botched Presentation"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 489


Botched Presentation


Quando seu senhor o apresentou ao Príncipe da cidade, você fez feio. Agora está convencido de que Sua Majestade o odeia (odiando ou não). Você precisa ter sucesso numa rolagem de Força de Vontade (dificuldade 7) só para ficar diante do Príncipe ou de um de seus representantes devidamente autorizados sem sair correndo, gaguejar ou fazer papel de bobo de outro jeito. Este Defeito só pode ser adquirido por vampiros da Camarilla.]==],
				},
				["Bound (Mage)"] = {
					pt = [==[Book of Secrets, pág. 92


Bound (Mage)


O Mentor sempre disse para você não fazer barganhas com entidades estranhas. Mas você escutou? Nada. Agora está enterrado até o pescoço em dívida com alguém cujo poder faz o seu parecer minúsculo, e suas chances de escapar da servidão são risíveis, na melhor das hipóteses. Assombrado pela ideia do pagamento por vir, você vive de tempo emprestado e sabe que o pior ainda está por vir…

Às vezes conhecido, com pequenas variações, como a Barganha de Fausto, Vinculado põe sua personagem na posição faustiana de receber algo interessante em troca de algo considerável – a vida dela, a alma dela, mil anos de servidão ou destino igualmente horrível que ninguém em sã consciência arriscaria. Ainda assim, ocultistas são famosos por pensar no curto prazo, e pactos literalmente diabólicos são moeda corrente no mundo mágico. Os detalhes desse acordo cabem a você e ao seu Narrador; talvez você tenha recebido Qualidades e/ou Habilidades em troca da dívida (compradas com os pontos deste Defeito), escapado de uma situação terrível ("Você quer sair desta armadilha mortal, caro feiticeiro? Muito bem – o que tem a me oferecer?"), salvado alguém importante para você ("Claro, trago sua mãe de volta da beira da morte – vamos discutir os termos deste favor…") ou perdido de outro modo um impasse com uma entidade de Outro Mundo (veja a seção Convocação, Vínculo, Barganha e Proteção em How Do You DO That?, pp. 91-95).

Como o Defeito Destino Sombrio (abaixo), esta dívida lança um ar de mau agouro sobre a parte da crônica que cabe à sua personagem. Neste caso, porém, sua ruína pode ser evitada se você der um jeito de escapar do pacto. Enquanto isso, seu credor cobrará favores ocasionais – nada grande o bastante para quitar a dívida (a menos que a entidade precise de um serviço considerável e concorde em perdoar a obrigação maior), mas feitos que podem acender novas histórias ou complicar as que já existem. Apesar da tradição, essa dívida não precisa ser um pacto de alma com um diabo – uma promessa ao seu deus (ou aos emissários diretos dele) pode ser tão terrível quanto uma feita ao Coisa-Ruim!]==],
				},
				["Bound (Vampire)"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 490


Bound (Vampire)


Você está preso pelo laço de sangue a outro vampiro. Seu regente pode não tratá-lo mal, mas o fato é que sua vontade não é inteiramente sua. Saber disso o corrói, ainda que você se veja perdido em devoção ao seu mestre vampírico. Vampiros da Sabá não podem adquirir este Defeito.]==],
				},
				["Bound to the Clan"] = {
					pt = [==[Lore of the Clans, pág. 219


Bound to the Clan


Você fez mais do que apenas beber do sangue dos anciões. Seja como punição, seja por escolha, você ficou completamente preso pelo laço de sangue ao Clã Tremere. Não consegue agir contra o Clã, e tudo o que faz acaba servindo aos Tremere. Você pode não gostar, mas não consegue evitar. Claro que, vinculado ao Clã, você não pode ser vinculado a nenhum indivíduo. Muitos Tremere mais velhos têm este Defeito, já que no passado era comum vincular por completo os novos Tremere.]==],
				},
				["Branded (3)"] = {
					pt = [==[Book of Secrets, pág. 89


Branded (3)


Você foi julgado culpado por um Tribunal das Tradições, que Marcou seu Avatar com um sigilo indicando seu crime. Quem consegue ver esse sigilo reconhece que você é um criminoso de algum tipo, e quanto pior a Marca, mais grave o crime e mais dura a reação. Nem toda reação será negativa; mas, considerando o tipo de gente que se simpatizaria com um criminoso conhecido, você realmente quer a boa vontade dessas pessoas?

(3 pontos) Marca temporária por um Crime Menor (veja abaixo), que desaparece em um a três meses. Ao fim desse período, o Defeito some. Esta Marca aumenta a dificuldade das suas rolagens sociais em +1 com magos das Tradições "médios" e +2 com os especialmente cumpridores da lei.

(4 pontos) Marca duradoura por um Crime Menor. Ela dura um ano ou mais e o marca como um infrator bastante notório. A dificuldade das suas rolagens sociais sobe +2 entre a maioria dos magos que reconhecem o significado da Marca, e +3 entre os que levam a sério essas ofensas e punições.

(5 pontos) Marca duradoura por um Crime Grave, que não desaparecerá por pelo menos nove anos e pode ser essencialmente permanente. Ela aumenta a dificuldade das suas rolagens sociais em +3 para qualquer personagem que se importe minimamente com a justiça das Tradições e com quem sofre suas punições. Certos grupos vão persegui-lo para puni-lo ainda mais, e outros o considerarão carne de primeira para seus esforços de recrutamento.

Para detalhes sobre crimes e punições das Tradições, veja as entradas sobre Crimes e Punições do Capítulo Quatro, na seção Entre as Tradições, pp. 213-219.]==],
				},
				["Branded (4)"] = {
					pt = [==[Book of Secrets, pág. 89


