				},
				["Brittle Body (2)"] = {
					pt = [==[Lore of the Bloodlines, pág. 91


Brittle Body (2)


Seu cadáver já desfigurado não lida tão bem quanto deveria com as exigências físicas de ser um Cainita. Seus ossos quebram em horas inoportunas, sua pele rasga se você se move rápido demais, e você precisa ter cuidado toda noite. A versão de 2 pontos deste defeito lhe dá +2 de dificuldade em todas as rolagens Físicas, por causa da natureza delicada do seu corpo. A versão de 4 pontos significa que você também carrega o dano físico por mais tempo que os outros Cainitas. Você ainda cura níveis de vitalidade normalmente, mas qualquer penalidade em dados permanece até a noite seguinte, quando você desperta. Isso vem somado à penalidade nas rolagens Físicas.]==],
				},
				["Brittle Body (4)"] = {
					pt = [==[Lore of the Bloodlines, pág. 91


Brittle Body (4)


Seu cadáver já desfigurado não lida tão bem quanto deveria com as exigências físicas de ser um Cainita. Seus ossos quebram em horas inoportunas, sua pele rasga se você se move rápido demais, e você precisa ter cuidado toda noite. A versão de 2 pontos deste defeito lhe dá +2 de dificuldade em todas as rolagens Físicas, por causa da natureza delicada do seu corpo. A versão de 4 pontos significa que você também carrega o dano físico por mais tempo que os outros Cainitas. Você ainda cura níveis de vitalidade normalmente, mas qualquer penalidade em dados permanece até a noite seguinte, quando você desperta. Isso vem somado à penalidade nas rolagens Físicas.]==],
				},
				["Broken Antitribu"] = {
					pt = [==[Lore of the Clans, pág. 26


Broken Antitribu


Você é uma das coisas mais lastimáveis que existem — um Assamita antitribu que ainda padece sob a Maldição Tremere. Você se juramentou à Sabá, mas não pode cometer diablerie e só consegue tomar vitae de Cainita já transubstanciada pela Vaulderie. Por isso, a dificuldade de todas as rolagens Sociais contra outros membros da Sabá é +2.]==],
				},
				["Bulimia"] = {
					pt = [==[Lore of the Clans, pág. 270


Bulimia


Você tem fome de sangue e, como todo vampiro, acaba se alimentando, mas a ideia ainda o deixa enjoado. Talvez você simplesmente não tenha nascido para uma eternidade sugando sangue, ou tivesse em vida um distúrbio alimentar que o seguiu para o outro lado da mortalidade. Seja qual for a razão, você não segura o sangue. Sempre que se alimentar, faça uma rolagem de Vigor com dificuldade 8. Se falhar, você vomita o sangue fresco antes que ele seja absorvido pelo corpo, espalhando-o por toda parte (constrangedor na melhor das hipóteses, uma quebra da Máscara na pior). Note que o sangue tomado em frenesi é absorvido normalmente, embora isso traga seus próprios riscos.]==],
				},
				["flaw|Cannibal"] = {
					pt = [==[Ghouls & Revenants, pág. 136


Cannibal


Embora a família revenante Bratovich seja conhecida pela depravação, o desejo de consumir carne humana não se limita a ela. Historicamente, mortais recorreram ao canibalismo em tempos de guerra ou fome, mas também comeram a carne dos mortos como parte de cerimônias religiosas para honrar os caídos. A imensa maioria das culturas, porém, considera a prática bárbara e antinatural.

Tornar-se Canibal é pôr sua personagem em risco de ostracismo e morte. Há vários distúrbios físicos que podem ser transmitidos pelo consumo de carne ou órgãos infectados. Na maior parte das vezes, essa infecção é indetectável por meios normais, não médicos. Se você comer carne humana como carniçal, a vitae já ingerida provavelmente é forte o bastante para anular os efeitos na maioria dos casos. Se, porém, seu carniçal for privado de alimentações futuras, a infecção se instalará à medida que o corpo voltar ao seu estado e idade naturais.

Uma personagem com o Defeito Canibal em geral só se alimenta da carne dos vivos ou dos mortos em particular. A maioria dos canibais não é feita de animais raivosos: são astutos e muito inteligentes. Sabem que a sociedade moderna condena o canibalismo, mas se sentem compelidos a praticá-lo mesmo assim. Por isso costumam ter o cuidado de agir em lugares e horários em que eles e suas vítimas não sejam descobertos com facilidade. Cadáveres sumidos ou pessoas muito queridas, por exemplo, tendem a ser procurados. Se houver testemunhas que viram o canibal e a vítima juntos, isso pode gerar complicações que ele não está preparado para enfrentar. Uma rolagem de Força de Vontade pode ser exigida para determinar se o canibal consegue exercer controle e discrição suficientes para não deixar pistas.

O Defeito Canibal pode ser escolhido por qualquer carniçal, ou concedido a uma personagem pelo Narrador como resultado de uma Perturbação. Embora seja muito mais comum entre famílias revenantes, não é exclusivo delas. Por causa do impacto dramático que ele tem sobre carniçais na sociedade moderna, carniçais da Camarilla são desencorajados de adquiri-lo.

Usado por: revenantes, alguns carniçais da Sabá e independentes]==],
				},
				["Cannot Embrace"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 427


Cannot Embrace


Por alguma maldição, fraqueza ou defeito no seu vampirismo, você é incapaz de gerar prole. Talvez você nem saiba disso até que seja tarde demais e uma vítima esteja sangrando até a morte nos seus braços.]==],
				},
				["Can't Cross Running Water"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 495


Can't Cross Running Water


Você acredita no velho folclore e não consegue atravessar água corrente a menos que esteja ao menos 15 metros acima dela. Considera-se água corrente qualquer corpo d'água com pelo menos meio metro de largura em qualquer direção e que não esteja completamente parado.]==],
				},
				["Carrion Presence"] = {
					pt = [==[Lore of the Bloodlines, pág. 16


Carrion Presence


Esta aflição representa a verdadeira ligação dos Baali com a decrepitude que sua linhagem comanda. A pestilência é atraída pelos Baali; moscas abandonam suas deliciosas carcaças para circular ao redor do vampiro, ratos sobem por seus membros e guincham louvores, e urubus podem ser vistos girando sobre ele quase o tempo todo. O grau da aflição varia de personagem para personagem, mas não há como se livrar do enxame. Espantar as moscas apenas chama outras para o lugar delas. Embora bastante repugnantes para a maioria, esses vampiros carregam isso com orgulho. A coisa, porém, torna bem difícil lidar com círculos que não sejam Baali.]==],
				},
				["Cast No Reflection"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 494


Cast No Reflection


Você de fato não tem reflexo, como os vampiros das lendas. Isso pode atrapalhar bastante quando você tenta se passar por humano. Vampiros do Clã Lasombra têm este Defeito automaticamente (e você pode ser confundido com um deles se o possuir).]==],
				},
				["Cast No Shadow or Reflection (1)"] = {
					pt = [==[Book of Secrets, pág. 82


Cast No Shadow or Reflection (1)


Segundo certas lendas, bruxas não projetam sombra. E, embora isso não seja verdade para a maioria dos magos, de algum modo é verdade para você. Talvez você sofra de um Defeito de Paradoxo persistente, manifeste os próprios medos culturais ou tenha feito uma barganha que lhe custou a sombra ou o reflexo. Em todo caso, sua sombra e/ou seu reflexo estão ausentes. Por um ponto, falta uma dessas coisas; por dois, faltam as duas. E, embora a maioria das pessoas não perceba isso conscientemente, elas tendem a se sentir desconfortáveis na sua presença mesmo sem saber por quê. (Máquinas tecnológicas também registram o fenômeno.) Some +1 à dificuldade de todas as suas rolagens de Traços Sociais na maior parte das circunstâncias, e +2 se uma testemunha fizer uma rolagem baseada em percepção (dificuldade 7) e descobrir por que você parece tão estranho.]==],
				},
				["Cast No Shadow or Reflection (2)"] = {
					pt = [==[Book of Secrets, pág. 82


Cast No Shadow or Reflection (2)


Segundo certas lendas, bruxas não projetam sombra. E, embora isso não seja verdade para a maioria dos magos, de algum modo é verdade para você. Talvez você sofra de um Defeito de Paradoxo persistente, manifeste os próprios medos culturais ou tenha feito uma barganha que lhe custou a sombra ou o reflexo. Em todo caso, sua sombra e/ou seu reflexo estão ausentes. Por um ponto, falta uma dessas coisas; por dois, faltam as duas. E, embora a maioria das pessoas não perceba isso conscientemente, elas tendem a se sentir desconfortáveis na sua presença mesmo sem saber por quê. (Máquinas tecnológicas também registram o fenômeno.) Some +1 à dificuldade de todas as suas rolagens de Traços Sociais na maior parte das circunstâncias, e +2 se uma testemunha fizer uma rolagem baseada em percepção (dificuldade 7) e descobrir por que você parece tão estranho.]==],
				},
				["Catspaw"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 490


Catspaw


Você já fez trabalho sujo para alguém do alto escalão da cidade — o Xerife, o Bispo ou até alguém acima deles. Só que, em vez de lhe render prestígio, seus feitos fizeram de você um constrangimento ou um risco. No momento, a preocupação do seu antigo empregador é mantê-lo calado. No longo prazo, é se livrar de você.]==],
				},
				["Chandala"] = {
					pt = [==[Lore of the Clans, pág. 182


Chandala


Ser membro do jati Chandala tem seus dois lados. Você é responsável pelo descarte de cadáveres, além de muitas outras tarefas imundas, mas ao mesmo tempo costuma ser ignorado. Suas rolagens Sociais contra outros Ravnos sofrem +2 de dificuldade.

Você não precisa adquirir este Defeito para ser membro do jati Chandala, mas só membros do jati Chandala podem tê-lo.]==],
				},
				["Child"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 482


Child


Você era uma criança pequena (entre cinco e dez anos) na época do seu Abraço, o que deixou seus Atributos Físicos subdesenvolvidos e torna difícil lidar com certos aspectos da sociedade mortal. Você não pode ter mais de dois pontos em Força ou Vigor na criação do personagem, exceto ao elevar Atributos Físicos com pontos de sangue, e as dificuldades de todas as rolagens para dirigir ou liderar adultos mortais aumentam em dois. Personagens com este Defeito também devem adquirir o Defeito Baixinho.]==],
				},
				["Chronic Depression"] = {
					pt = [==[Book of Secrets, pág. 51


Chronic Depression


Não importa como estejam as circunstâncias externas: você é frequentemente puxado para o desespero. Tudo parece esmagador, sem sentido e, na melhor das hipóteses, uma piada de mau gosto às custas do mundo. Esse sentimento permeia cada aspecto da sua existência: sua atitude, sua saúde física, seus relacionamentos e até – especialmente! – sua relação com a magia e todas as manifestações dela. (Veja as seções de Mage 20 sobre Foco e as Artes, Ressonância, Quietude e as percepções Vidare dos Outros Mundos.) Resumindo: é péssimo ser você.

Muitas vezes vista como questão puramente psicológica ("Está tudo na sua cabecinha…"), a depressão crônica costuma estar ligada a Impedimentos fisiológicos, como no Defeito Físico de mesmo nome. Este Defeito também pode refletir as sequelas psíquicas de contragolpes de Paradoxo, episódios de Quietude, Coisas Que o Homem Não Deveria Saber, ataques da Esfera da Mente e outras formas de trauma (términos, violações, desastres e afins), embora a depressão induzida por trauma seja mais frequentemente uma manifestação do Defeito TEPT, citado acima. Seja qual for a origem, o elemento psicológico da depressão é inescapável. O peso emocional do desespero constante tende a drenar a vitalidade física, o que por sua vez alimenta mais depressão. Não admira que pessoas cronicamente deprimidas tenham dificuldade em "viver a vida ao máximo". Em certos dias, só levantar da cama sem desabar em choro já é um desafio.

Em termos de história, este Defeito orienta a interpretação e a descrição da personagem como sugerido acima. Em termos de sistema, ele costuma exigir uma rolagem de Força de Vontade quando sua personagem deprimida precisa se empurrar para além da depressão. Um sucesso significa que ela age sem estorvo. Uma falha soma +2 à dificuldade da tarefa principal em questão, que pode envolver Atributos Físicos (a depressão drena a vitalidade), Sociais (mina as relações com os outros) ou Mentais (névoa mental), conforme a situação. Uma falha crítica significa que a depressão toma conta e a derruba num poço negro e fundo de desespero, no qual ela ficará presa por horas ou até dias.

Você pode gastar um ponto de Força de Vontade para empurrar a depressão de lado, evitando a rolagem por completo. Só que, como sabe quem entende a analogia das colheres, mais cedo ou mais tarde os pontos de Força de Vontade acabam. (Para quem não conhece a analogia: é a ideia de que você tem um número limitado de colheres por dia; cada tarefa exige que você entregue uma colher, e logo você fica sem colheres.) O fato de as pessoas se irritarem com a sua Nuvem Negra da Perdição também não ajuda; diabos, você está mais irritado com essa porcaria do que qualquer um! Então, falando sério – em todos os aspectos da vida, a Cidade da Depressão Crônica não é um lugar divertido… nem mesmo para fãs do Mundo das Trevas.]==],
				},
				["Clan Enmity"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 492


Clan Enmity


Um Clã em particular quer você morto. Você ofendeu o Clã inteiro, de anciões a neonatos, e por isso todo membro daquela linhagem quer sua cabeça numa bandeja. Os efeitos deste Defeito podem ir de desfeitas e insultos bem públicos a atentados de verdade contra sua não-vida. Você também sofre +2 de dificuldade em todas as rolagens Sociais envolvendo membros do Clã em questão.]==],
				},
				["Clan Weakness"] = {
					pt = [==[Lore of the Clans, pág. 270


Clan Weakness


Apesar de não ter herdado as outras capacidades do seu Clã de origem, você herdou a fraqueza dele. Embora isso possa ser mortal para um vampiro despreparado, um Caitiff esperto pode virar a coisa a seu favor para se misturar melhor ao Clã de origem. Alguns Nosferatu, por exemplo, provavelmente jamais notariam, e poderiam até sair em defesa do Caitiff diante de acusações de fora.]==],
				},
				["Cloaked in Shadow"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 427


Cloaked in Shadow


Sombras grudam em você o tempo todo. Não são as sombras comuns que qualquer corpo projeta; a escuridão ao seu redor é espessa e pesada, tornando impossível você passar por outra coisa que não algo sobrenatural. Além dessa complicação, a dificuldade das rolagens Sociais com outros vampiros (especialmente os Lasombra) aumenta em um.]==],
				},
				["Cloistered"] = {
					pt = [==[Lore of the Clans, pág. 219


Cloistered


Você passou quase toda a sua existência morta-viva nos salões da capela, o que torna a sociedade Cainita algo novo e confuso para você. Você sofre penalidade de -2 dados em qualquer interação social com quem não seja Tremere.]==],
				},
				["Cold Breeze"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 494


Cold Breeze


Um vento gelado o segue aonde quer que você vá. Ele pode render entradas dramáticas, mas também incomoda os mortais (+1 de dificuldade em todas as rolagens Sociais cabíveis) e o marca como obviamente sobrenatural. Ventos frios varrendo escritórios executivos ou boates lotadas levantam todo tipo de pergunta.]==],
				},
				["Combat Novice"] = {
					pt = [==[The Hunters Hunted II, pág. 42


Combat Novice


Sua personagem pode até falar bonito, mas nunca esteve perto de violência de verdade e, quando ela acontece, dificilmente reage bem. Diante de tiroteio; combate óbvio e brutal (sangue derramado, facadas, ossos quebrando); ou qualquer tipo de violência sobrenatural, role Força de Vontade (dificuldade 7). Se a rolagem falhar, a personagem congela no lugar (se a Coragem dela for maior que o Autocontrole) ou foge do local (se o Autocontrole for maior que a Coragem).

Você precisa fazer essa rolagem em toda cena em que ela testemunhe algo violento, mas, se acumular cinco sucessos, não são mais necessárias rolagens naquela noite de jogo. Uma demonstração de violência especialmente sangrenta pode zerar esse total, a critério do Narrador.]==],
				},
				["Compulsion"] = {
					pt = [==[Book of Secrets, pág. 46


Compulsion


Um tique mental quase reflexo o empurra para comportamentos compulsivos, muitas vezes inconscientes. Em alguns casos, sobretudo entre magos, esses comportamentos se manifestam como atividades ritualizadas: lavar as mãos, arrumar-se de forma obsessiva, fazer uma tarefa exatamente do mesmo jeito toda vez e assim por diante. Outras compulsões geram manias irritantes (cantarolar, fazer barulhos com a boca, falar em voz alta sem querer etc.) ou atividades potencialmente danosas, como furto em lojas, jogatina ou dar em cima de tudo que se move, que aparecem quando você está sob estresse. (Uma compulsão gravemente prejudicial pode ser tratada como o Defeito Perturbação, citado adiante.)

Compulsões pequenas costumam ser justificadas com o velho "ela é assim mesmo". Se quiser que sua personagem evite uma compulsão séria, porém, você precisa gastar um ponto de Força de Vontade para adiar o comportamento por um tempinho. Passado esse tempinho (a critério do Narrador), ela se sente compelida de novo a fazer aquilo… a menos que você gaste outro ponto de Força de Vontade… para adiar mais um tempinho…]==],
				},
				["Compulsive Speech (1)"] = {
					pt = [==[Book of Secrets, pág. 59


Compulsive Speech (1)


Cara, cala a boca, por favor! Mas não: você continua falando… e falando… e falando mais um pouco. Essa compulsão pode vir de um hábito social nervoso, de uma personalidade sabe-tudo, de um desconforto com o silêncio ou de algum outro impulso (possivelmente metafísico) de encher o espaço com palavras. Pior ainda: essas palavras muitas vezes trazem observações grosseiras, informações delicadas e outras coisas que seria melhor não dizer. Puxa – você disse mesmo o que eu acho que você disse? Disse, sim. Ai…

No que toca a este Defeito, a versão de um ponto significa que você fala demais, enquanto a de dois pontos (também conhecida como Boca Grande) significa que você diz as coisas erradas para as pessoas erradas com certa regularidade, muitas vezes para gente acima de você na hierarquia ou que não tem exatamente os seus interesses no coração. Você pode gastar um ponto de Força de Vontade para manter a boca fechada por uma cena ou duas; mais cedo ou mais tarde, porém, as palavras voltam a jorrar…]==],
				},
				["Compulsive Speech (2)"] = {
					pt = [==[Book of Secrets, pág. 59


Compulsive Speech (2)


Cara, cala a boca, por favor! Mas não: você continua falando… e falando… e falando mais um pouco. Essa compulsão pode vir de um hábito social nervoso, de uma personalidade sabe-tudo, de um desconforto com o silêncio ou de algum outro impulso (possivelmente metafísico) de encher o espaço com palavras. Pior ainda: essas palavras muitas vezes trazem observações grosseiras, informações delicadas e outras coisas que seria melhor não dizer. Puxa – você disse mesmo o que eu acho que você disse? Disse, sim. Ai…

No que toca a este Defeito, a versão de um ponto significa que você fala demais, enquanto a de dois pontos (também conhecida como Boca Grande) significa que você diz as coisas erradas para as pessoas erradas com certa regularidade, muitas vezes para gente acima de você na hierarquia ou que não tem exatamente os seus interesses no coração. Você pode gastar um ponto de Força de Vontade para manter a boca fechada por uma cena ou duas; mais cedo ou mais tarde, porém, as palavras voltam a jorrar…]==],
				},
				["Conflicting Loyalties (1)"] = {
					pt = [==[Book of Secrets, pág. 59


Conflicting Loyalties (1)


Embora profundamente leal (provavelmente a ponto de ter a Qualidade Lealdade – veja p. 53), você enfrenta uma crise de compromissos: duas ou mais das partes a quem você é leal estão em conflito, e você fica no meio tentando apoiar todas. Seu melhor amigo pode estar em apuros com a corporação policial em que seu pai trabalhava; seu amante pode ter traído a confiança da sua Convenção; seus Aliados podem ter decidido que seu Mentor precisa cair. E lá está você – encurralado numa situação impossível, tentando fazer o que é certo para todos os envolvidos.

O valor deste Defeito, como sempre, depende da intensidade do conflito:

(1 ponto) Uma crise pequena o obriga a se equilibrar entre as lealdades sem trair nenhuma das partes.

(2 pontos) Um choque considerável faz você mediar situações insustentáveis com uma frequência frustrante.

(3 pontos) Diferenças irreconciliáveis acabarão por obrigá-lo a escolher entre lealdades, e essa é uma escolha que você não sabe se consegue fazer. Até lá, você trava uma campanha aparentemente perdida para apoiar todos os lados sem trair ninguém.

A natureza das suas lealdades, relações e disputas deve, é claro, ser definida quando você adquire este Defeito. Seu Narrador vai trazê-las à mesa com frequência suficiente para manter você correndo atrás da melhor solução para um dilema aparentemente impossível.]==],
				},
				["Conflicting Loyalties (2)"] = {
					pt = [==[Book of Secrets, pág. 59


