				},
				["Conniver"] = {
					pt = [==[Book of Secrets, pág. 60


Conniver


Para a maioria de quem o conhece, você é uma faca permanentemente cravada nas costas de alguém. Essa fama pode não corresponder à verdade (veja os Defeitos Estrangeiro Cultural, Infâmia, Encrenqueiro e Aparência Fichada), mas as pessoas esperam traição da sua parte mesmo quando estão erradas. Subtraia um dado de qualquer parada de dados não mágica que você use ao tentar fazer outros personagens confiarem em você. A penalidade não se estende às paradas de Arete quando você conjura magia da Esfera da Mente (ou de qualquer outra Esfera), mas, se você precisa lançar magia para ser acreditado, então acabou de confirmar aquela reputação.]==],
				},
				["Conspicuous Consumption"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 486


Conspicuous Consumption


Não basta você se nutrir do sangue dos mortais — você acredita que precisa consumir também o coração, o fígado e outros tecidos ricos em sangue da vítima. Isso, é claro, exige a morte de todas as suas vítimas (a menos que você seja extremamente criativo), o que pode gerar inúmeros problemas para manter a Humanidade (e a discrição). Personagens com este Defeito também devem comprar a Qualidade Comer Alimentos.]==],
				},
				["Construct"] = {
					pt = [==[M20 Victorian Age, pág. 122


Construct


Como a Ordem da Razão ainda não avançou a tecnologia até a engenharia genética ou a clonagem, jogadores que escolherem este Defeito para criar "pessoas" artificiais, como autômatos de relojoaria ou outras criações tecnológicas, devem discutir as implicações com o Narrador. Um envolvimento permanente com os Estreitos provavelmente acompanha este Defeito. Golens Despertos, cadáveres reanimados e outras criações místicas correm o mesmo risco.]==],
				},
				["Consumption"] = {
					pt = [==[Lore of the Clans, pág. 239


Consumption


Há algo faminto dentro de você. Mas o que é? Pedaços do Antediluviano? Sua Vicissitude que deu terrivelmente errado? Seja o que for, está ativo, agindo como um câncer, devorando você de dentro para fora. Seu próprio sangue está tomado por bactérias corrosivas que comem a carne. No começo de cada noite, você sofre um nível de vitalidade de dano letal que não pode ser absorvido nem curado com sangue. A única forma de conter o efeito é ingerir um décimo do seu peso corporal em carne para repor sua carcaça esgotada. Seja matando e devorando a pele de humanos, seja saqueando os recipientes de lixo biológico de clínicas de lipoaspiração atrás da gordura sugada, você precisa da sua ração de carne humana para sobreviver. Se tentar ingerir essa refeição macabra antes que o dano ocorra, você simplesmente a vomita como qualquer outro alimento — isto não concede os benefícios da Qualidade Comer Alimentos.]==],
				},
				["Contagious"] = {
					pt = [==[Lore of the Clans, pág. 163


Contagious


Seu corpo continua morrendo por dentro, e suas entranhas apodrecidas alimentam bactérias nocivas, esporos e até fungos. Mortais que o tocarem ou dos quais você se alimentar precisam fazer uma rolagem de Vigor (dificuldade 9) para não adoecer. A doença os deixa de cama com febre e mal-estar, e a cada semana eles podem repetir a rolagem de Vigor. O Narrador pode reduzir a dificuldade se o alvo estiver recebendo atendimento médico adequado. Com um sucesso, eles se recuperam; se falharem, seguem febris. Ao fim de cada mês em que a vítima continua doente, ela perde um ponto de Vigor; se chegar a zero de Vigor, morre. Se o Nosferatu souber do próprio contágio e infectar alguém por maldade, o Narrador pode pedir uma rolagem de degeneração de Humanidade (ou do Caminho de Iluminação cabível) caso a vítima morra. Criaturas sobrenaturais em geral têm como curar ou sarar esse tipo de doença em si mesmas, e vampiros são imunes a esses germes dos mortos.]==],
				},
				["Credulous (3)"] = {
					pt = [==[The Hunters Hunted II, pág. 133


Credulous (3)


Você acredita em monstros e conspirações, e seus colegas agentes sabem disso. Essa fama de crédulo faz de você um risco — não importa quanta verdade você de fato conheça. Com a versão de três pontos deste Defeito, você ainda é agente de campo, mas seus colegas ou o ignoram ou zombam abertamente de você. Subtraia um dado de todas as rolagens de Empatia, Investigação ou Liderança ao lidar com a comunidade de inteligência. Se uma criatura sobrenatural estiver procurando um bode expiatório, seu nome está no topo da lista.

Com a versão de cinco pontos, você está de saída. Recebeu uma tarefa inventada — talvez um estudo de viabilidade para construir um muro na fronteira canadense, ou monitorar a inteligência que sai do escritório da Nova Zelândia. Você não terá apoio nenhum e, se continuar dando trabalho (investigando criaturas sobrenaturais, digamos), gente do alto escalão da sua agência vai arranjar um acidente para calá-lo de vez. Recurso]==],
				},
				["Credulous (5)"] = {
					pt = [==[The Hunters Hunted II, pág. 133


Credulous (5)


Você acredita em monstros e conspirações, e seus colegas agentes sabem disso. Essa fama de crédulo faz de você um risco — não importa quanta verdade você de fato conheça. Com a versão de três pontos deste Defeito, você ainda é agente de campo, mas seus colegas ou o ignoram ou zombam abertamente de você. Subtraia um dado de todas as rolagens de Empatia, Investigação ou Liderança ao lidar com a comunidade de inteligência. Se uma criatura sobrenatural estiver procurando um bode expiatório, seu nome está no topo da lista.

Com a versão de cinco pontos, você está de saída. Recebeu uma tarefa inventada — talvez um estudo de viabilidade para construir um muro na fronteira canadense, ou monitorar a inteligência que sai do escritório da Nova Zelândia. Você não terá apoio nenhum e, se continuar dando trabalho (investigando criaturas sobrenaturais, digamos), gente do alto escalão da sua agência vai arranjar um acidente para calá-lo de vez. Recurso]==],
				},
				["Crucial Component (2)"] = {
					pt = [==[Book of Secrets, pág. 87


Crucial Component (2)


Sua prática metafísica exige instrumentos especializados. Não basta você precisar de combustível para o seu Porsche 911 Turbo S turbinado – você precisa da sua própria mistura de combustíveis, preparada de forma especial, ou o carro não anda. Uma simples varinha de sorveira não serve – suas magias exigem um galho entalhado à mão, cortado de uma sorveira sem cicatrizes na alta meia-noite da véspera de Samhain. Em termos de jogo, ao menos um dos instrumentos do seu foco mágico precisa ser criado, colhido ou modificado especificamente para funcionar com suas magias. Nenhuma ferramenta inferior serve.

Quão difícil é obter ou usar esse componente especializado? Depende do valor do Defeito:

(2 pontos) Fácil de obter e/ou usar (luz do sol, posturas de ioga, óleo de motor, emoções fortes, um livro fácil de achar na seção de esoterismo da livraria etc.).

(3 pontos) Difícil de obter, usar ou repor (chamas abertas, a postura Kurmasana, óleo profissional de competição, tristeza genuína, um texto oculto fora de catálogo e assim por diante).

(4 pontos) Bem difícil de obter, usar e repor (fogo líquido, a pose Vrschikasana, óleo formulado alquimicamente, luto profundo, um exemplar romano legítimo de De Daemonum Socrates, de Apuleio, e outros instrumentos raros e preciosos).

(5 pontos) Único, obscuro, proibido, incômodo, ou alguma combinação dos quatro (um frasco de fogo solar destilado alquimicamente, uma postura de ioga impossivelmente complexa inventada pelo próprio praticante, óleo lubrificante de hipertecnologia formulado e destilado pessoalmente, o grito sentido de uma mãe enlutada, um Grimório de Honório renascentista ilustrado com xilogravuras e inscrito em pele humana esfolada, e instrumentos igualmente raros).

Quando usado, o instrumento escolhido funciona como Instrumento Personalizado (Mage 20, pp. 503 e 587) – possivelmente um Personalizado Único, no caso de um componente de cinco pontos. No seu caso, porém, você não consegue empregar de forma alguma a magia ligada àquele instrumento a menos que também possa empregar aquele instrumento específico. Se Lee Ann Milner depende de uma postura de ioga única, a da centopeia vingativa, para empregar certos Efeitos de Forças por meio da sua prática, então Lee Ann está perdida a menos que consiga assumir a postura a tempo de lançar os Efeitos necessários.

Na versão original deste Defeito, o material estava preso a um Efeito de Esfera específico. Esta versão revisada amarra o Componente Crucial a uma ferramenta que você usa. A mudança torna mais fácil acompanhar o componente e seus usos, empregando as novas regras de foco apresentadas em Mage 20, Capítulo Dez, de modo que o Defeito vire parte integral do jeito como seu mago realiza Efeitos mágicos. Para detalhes sobre Atribuir Práticas e Instrumentos a Efeitos, veja a seção de mesmo nome no Capítulo Três, p. 169.]==],
