(4 pontos) As autoridades também discriminam você. Sua casa pode ser revistada, seu emprego pode ser encerrado, você pode ser despejado, roubado ou agredido, e pouquíssima gente vai se importar.

(5 pontos) Só viver nesta sociedade já é física, social, emocional e legalmente perigoso para a sua segurança, sua sanidade e possivelmente sua vida. Você pode ser preso, escravizado, torturado ou morto com pouca ou nenhuma reação das autoridades.

Ao contrário do Defeito físico Aparência Fichada, esta discriminação não se baseia no corpo. Uma personagem com este Defeito não pode também adquirir Aparência Fichada; se ela se destaca fisicamente e ainda é discriminada socialmente, basta comprar mais pontos neste Defeito.

Ele também não está preso a nenhuma crença, gênero ou etnia; enquanto uma wiccana pode ser Estrangeira Cultural numa cidade cheia de batistas fundamentalistas, um batista fundamentalista pode ser Estrangeiro Cultural num Reino Horizonte de base wiccana. Você pode seguir um credo "herético", pertencer a uma subcultura "de má fama", se identificar como "minoria" sexual/de gênero/étnica/religiosa, ter uma opinião política impopular… qualquer coisa que leve os outros a tratá-lo mal e a saírem impunes pode servir de base para este Defeito.

Dito isso, uma personagem com este Defeito precisa de fato ser maltratada; ser confrontada por uma opinião impopular, ou ter o comportamento criticado, faz parte da experiência humana, enquanto ser revistada pela polícia só por existir é um problema de verdade. Para adquirir este Defeito, sua personagem precisa enfrentar discriminação e ataques reais numa base razoavelmente regular e perigosa. Não: ser xingado na internet não conta, embora um episódio intenso de linchamento virtual – ou seja, exposição de dados pessoais, trotes policiais, destruição de carreira e ameaças sérias à vida e à sanidade – possa contar, a critério do Narrador.

Como o Estrangeiro Cultural está ligado ao entorno social da personagem, uma mudança radical desse entorno pode atenuar ou eliminar o Defeito. Uma pessoa poliamorosa pode ser discriminada numa cidade e recebida de braços (e pernas) abertos em outra; se essa personagem permanecer num ambiente favorável ao poliamor, o jogador precisa comprar a saída do Defeito ou substituí-lo. Da mesma forma, sua "alteridade" precisa ser algo que as pessoas saibam, ou que possam descobrir com facilidade suficiente para que aquilo vire um grande problema na sua vida. Uma "alteridade" profundamente escondida é um Segredo Sombrio (veja abaixo) até que seja revelada.

Para ficar claro: este Defeito não representa de forma alguma um julgamento por parte deste jogo, de seus criadores ou – espera-se! – do seu grupo de jogo. Ele existe para refletir os modos como a sociedade mortal (e, muitas vezes, a Desperta) costuma tratar quem foge de suas normas culturais. Sendo quem são e fazendo o que fazem, magos frequentemente se destacam de maneiras que podem ser perigosas para sua saúde social e às vezes física – olá, Tempos da Fogueira! Contudo, se este Defeito parecer redundante no seu grupo, criar tensões reais indesejadas entre os jogadores ou for abusado por personagens (ou jogadores) que estão apanhando por agirem como babacas, sinta-se livre para ignorá-lo ou descartá-lo.]==],
