					pt = [==[Book of Secrets, pág. 60


Cultural Other (3)


Aos olhos da sua sociedade, você é claramente divergente. De má fama. O Outro. As pessoas suspeitam que você tenha comportamento criminoso, ou ao menos duvidoso; as autoridades o importunam ou detêm por pouco ou nenhum motivo, e seus entes queridos provavelmente "queriam que você fosse igual às pessoas normais". Reconheça-se: todo mago é "o outro" em algum grau. No seu caso, porém, essa alteridade ameaça sua vida, sua liberdade e sua felicidade.

Também conhecido como Minoria Maltratada, este Defeito reflete o preconceito dentro da sua sociedade. O tamanho e a frequência do problema que ele causa determinam seu valor:

(1 ponto) As pessoas ao seu redor tendem a importuná-lo de formas pequenas mas perceptíveis (sendo bruscas fora do normal, usando ofensas na sua presença, tomando liberdades desconfortáveis com sua privacidade, seus bens ou seu corpo etc.) e parecem achar que não há nada de errado nisso. Outros podem sair em sua defesa, mas na maioria das vezes não saem.

(2 pontos) Como acima, mas agora sua família e outros companheiros íntimos acham que você merece ser evitado, envergonhado, insultado e por aí vai, por ser quem ou o que é.

(3 pontos) Estranhos se sentem à vontade para envergonhá-lo, insultá-lo, evitá-lo e talvez agredi-lo fisicamente por princípio. As autoridades podem intervir, mas provavelmente só o farão se leis importantes forem quebradas… e talvez nem então.

(4 pontos) As autoridades também discriminam você. Sua casa pode ser revistada, seu emprego pode ser encerrado, você pode ser despejado, roubado ou agredido, e pouquíssima gente vai se importar.

