				["Curiosity"] = {
					pt = [==[Book of Secrets, pág. 48


Curiosity


Você simplesmente não resiste a um bom mistério! Uma curiosidade incômoda o arrasta para todo tipo de situação complicada. Com as suas capacidades, você tem uma boa chance de descobrir as coisas, também… o que, especialmente no Mundo das Trevas, não é lá muito saudável. Coisa bem de mago, aliás.

Diante de uma pista atraente ou de uma circunstância enigmática, faça uma rolagem de Raciocínio para não ceder à tentação. A dificuldade depende da situação: um mistério casual (digamos, a identidade daquela garota intrigante atrás do balcão do Starbucks) seria dificuldade 5, enquanto resistir a um mistério mais convidativo (a identidade de quem deixou uma dúzia de rosas na sua Capela) seria dificuldade 9. Uma vez na trilha, pouca coisa aquém de uma ameaça mortal o faz parar… e essa ameaça mortal pode muito bem incentivá-lo a cavar ainda mais fundo.]==],
