Cursed (1)


Você é alvo de uma maldição sobrenatural. A força e o alcance dela dependem de quantos pontos você quiser tomar. Exemplos:

Se você repassar um segredo que lhe foi confiado, a traição voltará para prejudicá-lo de algum modo. (1 pt.)

Você gagueja sem controle ao tentar descrever o que viu ou ouviu. (2 pts.)

Ferramentas quebram ou falham quando você tenta usá-las. (3 pts.)

Você está condenado a fazer inimigos daqueles que mais ama ou admira. (4 pts.)

Cada uma das suas conquistas ou triunfos acabará manchada ou fracassará de alguma forma. (5 pts.)]==],
