					pt = [==[Lore of the Clans, pág. 161


Dangerous Secret (4)


Você acabou sabendo de algo que preferia nunca ter descoberto. Pior ainda: as pessoas sobre quem você tem o podre sabem que você sabe. Pode ser que tenha descoberto o refúgio do Príncipe, ou que há infernalistas escondidos na diocese. Seja o que for, você não tem certeza de a quem contar e, se contar, só deixará os envolvidos no segredo mais empolgados em se livrar de você. Você pode até acabar implicado no segredo e correr o risco de cair junto com eles. Quanto mais potente o Defeito, mais poderosas são as pessoas em questão e mais elas querem aquilo calado.]==],
				},
				["Dangerous Secret (5)"] = {
					pt = [==[Lore of the Clans, pág. 161


Dangerous Secret (5)


Você acabou sabendo de algo que preferia nunca ter descoberto. Pior ainda: as pessoas sobre quem você tem o podre sabem que você sabe. Pode ser que tenha descoberto o refúgio do Príncipe, ou que há infernalistas escondidos na diocese. Seja o que for, você não tem certeza de a quem contar e, se contar, só deixará os envolvidos no segredo mais empolgados em se livrar de você. Você pode até acabar implicado no segredo e correr o risco de cair junto com eles. Quanto mais potente o Defeito, mais poderosas são as pessoas em questão e mais elas querem aquilo calado.]==],
				},
				["Dark Aura"] = {
					pt = [==[Lore of the Bloodlines, pág. 3


Dark Aura


Mesmo sem o uso de Auspícios, o Baali parece de algum modo errado para quem interage com ele, emitindo uma aura aterrorizante de doença e poder. A personagem está sempre em ligeira desvantagem ao lidar com outros vampiros ou com os tocados pelo divino, pois eles sentem a depravação da alma dela. Baali com este Defeito sofrem +2 de dificuldade em todas as rolagens Sociais, a menos que estejam usando Intimidação. Para quem usa Auspícios para ver a aura do Baali, ela aparece como uma névoa vermelha e rala em volta da personagem, com olhos vigilantes surgindo aqui e ali dentro dela.]==],
				},
				["Dark Fate"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 495


Dark Fate


Você está condenado à Morte Final ou, pior, a sofrer agonia eterna. Não importa o que faça, você não consegue escapar desse destino terrível. Em algum momento da crônica, seu Destino Sombrio o alcançará. Mais medonho ainda é o fato de você ocasionalmente ter visões desse destino, e o mal-estar que essas imagens provocam exige o gasto de um ponto temporário de Força de Vontade para ser evitado; caso contrário, você perde um dado em todas as suas ações pelo resto da noite. Cabe ao Narrador determinar a natureza exata desse destino e quando ele ocorrerá. É um Defeito difícil de interpretar; ironicamente, embora pareça eliminar todo o livre-arbítrio, saber da própria morte pode ser bastante libertador.]==],
				},
				["Dark Secret"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 489


Dark Secret


Você guarda algum tipo de segredo que, se viesse à tona, seria motivo de imensa vergonha e faria de você um pária na comunidade Cainita local. Pode ser qualquer coisa, de ter assassinado um ancião a ser membro dos Anarquistas.]==],
				},
				["Dead Inside"] = {
					pt = [==[Lore of the Clans, pág. 142


Dead Inside


Você não sente nada além de dor e dormência. Enquanto os outros acham motivos para tornar suas vidas dignas de serem vividas, às vezes você simplesmente não sente essa faísca. Uma vez por sessão, o Narrador pode cancelar qualquer ganho de pontos de Força de Vontade.]==],
				},
				["Deaf"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 483


Deaf


Você não ouve. Embora possa ser mais resistente a algumas aplicações de Dominação, você também não consegue acompanhar mídia eletrônica ou falada, e as dificuldades de muitas rolagens de Percepção aumentam em três.]==],
				},
				["Deathsight"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 494


Deathsight


Tudo parece podre e apodrecido para você. O mundo se apresenta como um cadáver; mortais parecem doentes ou esqueléticos, prédios parecem decrépitos, e seus companheiros Cainitas parecem cadáveres ambulantes em decomposição. Você tem -2 de dificuldade para resistir a todas as rolagens baseadas em Aparência, mas, pelo mesmo motivo, tem +2 de dificuldade em todas as rolagens baseadas em Percepção. Além disso, você acha a interação social difícil e sofre +1 de dificuldade em todas as rolagens baseadas em Social.]==],
				},
				["Debts (1)"] = {
					pt = [==[Book of Secrets, pág. 61


Debts (1)


Magos também precisam de dinheiro para funcionar no reino humano. E, no seu caso, você está ferrado financeiramente. Empréstimos estudantis, dívidas de cartão de crédito, pensão alimentícia, perdas no jogo, condenações judiciais, contas médicas, prestações do carro e/ou da casa… as formas de um mago moderno se enterrar em dívidas são tão numerosas quanto os que lucram com elas. E há ainda a possibilidade de manipulação financeira de fontes Despertas – magos ou Gente da Noite que, de propósito ou não, mantêm você quebrado para firmar o domínio que têm sobre você (veja Technocracy: Syndicate, p. 28). Ou talvez você seja simplesmente péssimo nessa coisa de pagar contas. Seja qual for a razão, sua renda vai embora assim que entra. Você pode até ter o Antecedente Recursos, mas o dinheiro não fica muito tempo na sua conta.

Como Defeito, estas Dívidas representam um valor mínimo que você deve aos credores. Quanto mais você deve, mais o Defeito vale:

(1 ponto) Dívida mínima (menos de US$ 10.000).

(2 pontos) Dívida moderada (menos de US$ 50.000).

(3 pontos) Dívida considerável (mais de US$ 50.000).

(4 pontos) Dívida esmagadora (mais de US$ 100.000).

(5 pontos) Dívida avassaladora (mais de US$ 500.000).

Do nível de três pontos em diante, seus credores empenharão um bom esforço (talvez enorme) para arrancar esse dinheiro de você. Certos credores, como agiotas, começam bem antes disso. As táticas vão de ligações a qualquer hora e cartas de cobrança a processos, retomadas de bens, ameaças, despejo e violência física. Para quem tem renda pequena e/ou irregular, a pressão da dívida e do assédio da cobrança pode causar sofrimento emocional e psicológico intenso… que, por sua vez, afeta a capacidade de ganhar dinheiro… que aprofunda a dívida… que aprofunda o estresse… num ciclo desesperado que pode levar a atos desesperados.]==],
				},
				["Debts (2)"] = {
					pt = [==[Book of Secrets, pág. 61


