				},
				["Deep Sleeper"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 485


Deep Sleeper


Quando você dorme, é muito difícil despertar. A dificuldade de qualquer rolagem para acordar durante o dia aumenta em dois.]==],
				},
				["Deformity"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 482


Deformity


Você tem algum tipo de deformidade — um membro malformado, corcunda ou pé torto, por exemplo — que afeta suas capacidades físicas e sua interação com os outros. Uma corcunda, por exemplo, reduziria a Destreza da personagem em dois pontos e aumentaria em um a dificuldade das rolagens ligadas a perícias sociais. Cabe ao Narrador determinar os efeitos específicos da deformidade escolhida.]==],
				},
				["Degeneration (3)"] = {
					pt = [==[Book of Secrets, pág. 41


Degeneration (3)


Seu corpo está se desfazendo. Uma maldição, uma doença, biotecnologia defeituosa, magias corruptoras ou alguma outra aflição apodrece sua forma física e, embora a magia da Vida possa reparar o dano até certo ponto, essa degeneração é permanente enquanto o Defeito não for removido de algum modo.

Na variação de três pontos, este Defeito representa a incapacidade de curar ferimentos sem a ajuda de magia ou de tecnologia médica. Até ser tratada por Efeitos da Esfera da Vida ou por intervenção médica, a personagem não recupera níveis de vitalidade perdidos por ferimento, doença ou outros fatores.

No nível de seis pontos, a personagem sofre um fluxo constante de ferimentos mesmo sem trauma externo. Sempre que estiver com a Vitalidade cheia, ela perde um nível de vitalidade a cada duas semanas até ser curada ou morrer. Como descrito acima, ela não se cura sozinha.

No nível de nove pontos, essa perda de Vitalidade é essencialmente dano agravado e só pode ser curada por Efeitos vulgares da Esfera da Vida.

Obviamente, este Defeito não significa nada em aventuras únicas ou campanhas curtas. Ele só deve ser adquirido por personagens (e jogadores) envolvidos em crônicas de longa duração.]==],
				},
				["Degeneration (6)"] = {
					pt = [==[Book of Secrets, pág. 41


