				},
				["Demented Eidolon"] = {
					pt = [==[Book of Secrets, pág. 89


Demented Eidolon


Tem alguém dentro da sua cabeça, e não é você. Apesar do seu compromisso com a lógica e a razão, um herege enlouquecido esbraveja dentro do seu crânio, insistindo que o que você faz é magia, não ciência. Essa voz áspera o empurra rumo ao Supersticionismo e ao Desvio da Realidade. Não que você fosse sequer considerar tamanha insanidade. Não mesmo – sério, jamais.

Defeito para operativos Tecnocratas e outros tecnomantes que se recusam a ver o que fazem como "magia", este Traço põe seu eu consciente contra um Avatar decidido a retomar a identidade de mago. O Eidolon (o termo tecnocrata para Essência) investido no seu Gênio (Avatar) chicoteia esse paradigma de Iluminação rumo a direções Desviantes. Enquanto a maioria dos Gênios Tecnocratas se comporta razoavelmente, este assume um semblante escancaradamente sobrenatural e martela a fortaleza da Razão (e do Processamento Social) que protege você de pensamentos Desviantes. Pode até ser divertido deixar outro jogador assumir o papel do seu Gênio, especialmente durante uma Busca… quer dizer, durante um daqueles interlúdios meditativos que permitem processar os enigmas da Iluminação. Idealmente, este Defeito acompanha um Traço de Gênio (Avatar) de 3 ou mais, e combina bem (do ponto de vista do "drama de interpretação", pelo menos!) com Antecedentes como Vidas Passadas, Destino e Lenda, Qualidades como Alma Gêmea e Avatar Companheiro, e Defeitos como Atavismo e – como era de se imaginar – Destino Sombrio.]==],
				},
				["Demon-Hounded (1)"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 427


Demon-Hounded (1)


Um demônio se afeiçoou a você. Ele aparece em horas estranhas e inconvenientes e lhe oferece subornos de riqueza e poder. Em certos dias, pede favores; em outros, os oferece. Que planos negros o inferno tem para você, para que um de seus servos se dê ao trabalho de incomodá-lo? Com que poderes sinistros você brincou e não deveria ter brincado? Com 1 ponto, o demônio é pouco mais que um diabrete, pedindo favores pequenos ou furtando objetos miúdos. Com 3 pontos, ele é seu igual em força física ou mágica, ou uma ameaça menor disposta a arrastar também seus amigos próximos para o caso. Com 5 pontos, é significativamente poderoso, capaz de ameaçar sua coterie, ou um demônio menor disposto a atormentar seus amigos, sua família e seus conhecidos.]==],
				},
