					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 427


Demon-Hounded (4)


Um demônio se afeiçoou a você. Ele aparece em horas estranhas e inconvenientes e lhe oferece subornos de riqueza e poder. Em certos dias, pede favores; em outros, os oferece. Que planos negros o inferno tem para você, para que um de seus servos se dê ao trabalho de incomodá-lo? Com que poderes sinistros você brincou e não deveria ter brincado? Com 1 ponto, o demônio é pouco mais que um diabrete, pedindo favores pequenos ou furtando objetos miúdos. Com 3 pontos, ele é seu igual em força física ou mágica, ou uma ameaça menor disposta a arrastar também seus amigos próximos para o caso. Com 5 pontos, é significativamente poderoso, capaz de ameaçar sua coterie, ou um demônio menor disposto a atormentar seus amigos, sua família e seus conhecidos.]==],
				},
				["Demon-Hounded (5)"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 427


Demon-Hounded (5)


Um demônio se afeiçoou a você. Ele aparece em horas estranhas e inconvenientes e lhe oferece subornos de riqueza e poder. Em certos dias, pede favores; em outros, os oferece. Que planos negros o inferno tem para você, para que um de seus servos se dê ao trabalho de incomodá-lo? Com que poderes sinistros você brincou e não deveria ter brincado? Com 1 ponto, o demônio é pouco mais que um diabrete, pedindo favores pequenos ou furtando objetos miúdos. Com 3 pontos, ele é seu igual em força física ou mágica, ou uma ameaça menor disposta a arrastar também seus amigos próximos para o caso. Com 5 pontos, é significativamente poderoso, capaz de ameaçar sua coterie, ou um demônio menor disposto a atormentar seus amigos, sua família e seus conhecidos.]==],
				},
				["Deranged (3)"] = {
					pt = [==[Book of Secrets, pág. 51


Deranged (3)


Veja Mage 20, pp. 648-650.]==],
				},
				["Deranged (5)"] = {
					pt = [==[Book of Secrets, pág. 51


Deranged (5)


Veja Mage 20, pp. 648-650.]==],
				},
				["Devil's Mark"] = {
					pt = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, pág. 179


Devil's Mark


Seja produto do seu Abraço, seja fruto da exposição a poder infernal ou outro poder profano, você foi marcado com a "Marca do Diabo", uma aberração anatômica que manifesta a mácula demoníaca. Deformidades possíveis incluem, mas não se limitam a: olhos bestiais ou desumanos, cascos, chifres, pele escamosa ou de cor antinatural, uma marca de nascença em forma de sigilo, infestação parasitária, garras, dentes disformes ou membros inúteis (talvez adicionais). Você jamais pode remover ou "melhorar" essas desfigurações, embora magia ou Disciplinas possam escondê-las da vista.

A Marca do Diabo confere os seguintes efeitos de regra: reduza em um o valor máximo de um Atributo (se o máximo é 5, passa a ser 4), enquanto o custo para elevar esse Atributo aumenta em um (1 + valor atual x 4). Se a marca ficar visível ou for conhecida por uma mortal, ela concede -1 de dificuldade em rolagens de Intimidação ao lidar com ela, mas em troca aumenta em um as dificuldades de todas as outras rolagens Sociais. Os jogadores devem acertar com o Narrador uma Marca do Diabo apropriada e o Atributo Físico que melhor se encaixa nela.]==],
				},
				["Diabolical Mentor"] = {
					pt = [==[Book of Secrets, pág. 64


Diabolical Mentor


Seu mentor não era apenas ruim no que fazia – ele se revelou ativamente malévolo. Essa pessoa pode ser um Nephandus de verdade, um Marauder demente, um feiticeiro implacável, um Tecnocrata linha-dura do tipo "chapéu preto e óculos espelhados", um infernalista que vendeu a alma… talvez você nem saiba o que seu mentor realmente é, mas é simplesmente ruim. Obviamente, esse sujeito ferrou com você. Além disso, se você descobriu coisas que ele preferia manter em segredo, isso pode gerar outros Defeitos também: Inimigo, Amaldiçoado e coisas piores…]==],
				},
				["Discredited"] = {
					pt = [==[Book of Secrets, pág. 62


Discredited


No seu campo de atuação, seu nome está na lama. Talvez você seja um cientista cujas teorias bizarras lhe custaram o respeito dos pares… ou um acadêmico que acabou do lado errado da política departamental… ou um jornalista que pisou fundo demais na linha da credibilidade. Seja lá o que tenha feito (ou tenham dito que fez), seus colegas de profissão o olham de cima. Some +2 à dificuldade das suas rolagens sociais e baseadas em Antecedentes quando tentar fazer esses colegas o levarem a sério. Embora seja um Defeito comum entre os Eterritas, sempre metidos em rusgas, qualquer um que dependa de reputação profissional pode ser desacreditado assim – Herméticos professorais, operativos do Sindicato subindo na hierarquia corporativa, agentes da Torre Branca e outros magos de campos competitivos também podem cair em desgraça.]==],
				},
				["Disease Carrier"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 483


Disease Carrier


Seu sangue carrega uma doença letal e altamente contagiosa. Ela pode ser qualquer coisa, de raiva a HIV, e Cainitas que bebam do seu sangue têm 10% de chance de também se tornarem portadores. Você precisa gastar um ponto de sangue extra toda noite ao despertar, ou começará a manifestar os sintomas da doença (chance maior de frenesi no caso da raiva, rolagens de absorção reduzidas no caso do HIV etc.).]==],
				},
				["Disfigured"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 481


Disfigured


Uma desfiguração medonha torna sua aparência perturbadora e memorável. As dificuldades de todas as rolagens ligadas a interação social aumentam em dois. Você não pode ter Aparência acima de 2.]==],
				},
				["Disgrace to the Blood"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 492


Disgrace to the Blood


Seu senhor considera tê-lo Abraçado um erro titânico, e fez questão de contar isso a todo mundo. Você é ridicularizado nas reuniões, alvo de deboche dos seus pares e ativamente desprezado por quem deveria lhe dar orientação. Qualquer pedido ou petição que você faça tende a ser menosprezado pelos amigos do seu senhor, e suas conquistas tendem a ser desmerecidas.]==],
				},
				["Dogmatic"] = {
					pt = [==[Book of Secrets, pág. 64


Dogmatic


Olha, é ótimo que você tenha convicções espirituais tão firmes… mas precisa ser tão babaca com elas? Este Defeito representa uma abordagem religiosa, espiritual e/ou filosófica que define suas crenças morais e mágicas. O problema é que suas crenças não se dão bem com as dos outros; em termos de regra, você soma +2 à dificuldade de todas as rolagens sociais que envolvam lidar com gente de crenças diferentes. Mesmo quando você está tentando, droga, se dar bem com aqueles hereges desorientados, as pessoas percebem que você não aprova. Você faz cara feia, discute, tenta converter todo mundo ao seu modo de pensar… não consegue evitar, sério – suas convicções são simplesmente formidáveis! Afinal, você as usa para mudar o mundo, então como poderiam estar erradas?]==],
				},
				["Domitor Pariah"] = {
					pt = [==[Ghouls & Revenants, pág. 130


Domitor Pariah


Seu mestre é um vampiro que, por alguma razão, é malvisto ou até odiado pelos outros membros do seu Clã, linhagem ou Seita. Sem aliados, sua domitora pode ter dificuldade em manter o status e provavelmente vai depender de carniçais como você para suprir suas necessidades básicas. Você pode receber responsabilidades extras, ou ser manipulado para espionar, atacar, defender ou roubar para ela.

Ao escolher Domitor Pária como Defeito, tenha em mente que, se outros vampiros descobrirem a quem você serve, sua vida pode correr perigo. Os fatos que levaram à queda da sua domitora podem ser mantidos em segredo de você, a critério do Narrador, ou você pode tropeçar nos segredos do seu mestre por acidente.

Uma vez que um carniçal entende o quanto a vida pode ser difícil com um Domitor Pária, você pode semear a rebelião apesar da força do seu laço de sangue.

Usado por: carniçais da Camarilla, alguns carniçais da Sabá]==],
				},
				["Double Agent"] = {
					pt = [==[Book of Secrets, pág. 65


Double Agent


Você trabalha dos dois lados de um muro cheio de espetos; um dia desses vai acabar empalado nele. Talvez você seja um espião do Sindicato no Culto do Êxtase, ou um Eterrita trabalhando com a Iteração X. Nos tempos da Aliança Díspar, você pode pertencer a uma Tradição enquanto passa dados ao seu verdadeiro Ofício. Cedo ou tarde, esse jogo perigoso vai cobrar seu preço. Faça planos, deixe planos de contingência prontos e tente não perecer!

Obviamente, este Defeito precisa ser mantido em segredo dos outros personagens do grupo. Para um drama extra, tente mantê-lo escondido também dos outros jogadores…]==],
				},
				["Dreadful Mara"] = {
					pt = [==[Lore of the Bloodlines, pág. 60


Dreadful Mara


Você bebeu algo que ainda vive dentro de você e o odeia, exercendo um controle alarmante sobre seus pensamentos e ações. A cada noite, o Narrador pode converter um único sucesso rolado em 1, o que pode gerar uma falha crítica. A critério do Narrador, a entidade também pode sussurrar conselhos ou insultos, o que pode aumentar a dificuldade nas tentativas de concentração.]==],
				},
				["Driving Goal"] = {
					pt = [==[Book of Secrets, pág. 51


Driving Goal


Mesmo para os padrões dos Despertos, você possui (ou é possuído por) uma causa tão intensa que ela guia cada aspecto da sua vida, até e inclusive suas crenças sobre a magia e a Ascensão, e a forma como as pratica. Essa meta, infelizmente, é quase impossível de alcançar individualmente: o colapso da Tecnocracia, o retorno dos Velhos Costumes, a queda da era industrializada e assim por diante. Como mago, você até poderia reunir influência suficiente para liderar um movimento maior que empurre a Realidade rumo à sua meta. O mais provável, porém, é que você se despedace contra ela, como tantos magos antes de você… mas, ora, se uma causa vale tanto a pena quanto a sua, então vale qualquer preço que você tenha de pagar.

Como Defeito, esta Meta Motivadora orienta as escolhas de interpretação e informa o foco, a lealdade, a magia, o Caminho, a Ressonância, as Buscas, os contragolpes de Paradoxo e praticamente tudo o mais que se possa imaginar sobre a personagem. Você pode dar pausas curtas na sua cruzada (em geral gastando um ponto de Força de Vontade para seguir outro rumo por um tempo), mas cedo ou tarde essa obsessão o traz de volta à meta que precisa perseguir a qualquer custo, até enfim alcançá-la ou se destruir tentando.]==],
				},
				["Dulled Bite"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 481


Dulled Bite


Por alguma razão, suas presas nunca se desenvolveram por completo, ou podem nem ter se manifestado. Ao se alimentar, você precisa achar outro jeito de fazer o sangue fluir. Sem isso, você precisa obter o dobro do número normal de sucessos para que sua mordida penetre direito. Vários Caitiff e vampiros de alta Geração costumam manifestar este Defeito.]==],
				},
				["Duplicitous"] = {
					pt = [==[Ghouls & Revenants, pág. 128


Duplicitous


Carniçais e revenantes com este Defeito têm fama de desleais por causa de suas ações passadas. Você provavelmente já mentiu, trapaceou ou jogou os dois lados um contra o outro num acordo que desandou. A natureza dessas ações torpes, assim como o alvo pretendido, não foi a mesma todas as vezes. Uma carniçal pode, por exemplo, procurar seu domitor e informá-lo de uma transgressão, real ou imaginada, e em seguida sugerir a punição apropriada para o alvo. Essa mesma carniçal pode então inventar histórias mostrando o quanto foi bem-intencionada ao defender o colega carniçal diante do mestre.

Você pode ser dissimulado como personagem, mas, ao adquirir este Defeito, isso passa a afetar suas relações e negociações com os outros. Você provavelmente não busca levar vantagem em toda situação, mas os outros esperam que sim. Seus aliados e inimigos ficam na ponta dos pés perto de você, porque não sabem se e quando você os tratará com justiça. Podem até apunhalá-lo pelas costas ou tentar prejudicá-lo primeiro, justamente porque esperam isso de você.

A influência do laço de sangue afeta a maioria dos carniçais com este Defeito de formas sutis. Embora seu domitor saiba que você é dissimulado, você não agiria de forma direta contra o seu mestre. Em vez disso, pode trair ou passar a perna nos seus aliados para cair nas graças dele e obter recompensas. Seu domitor também pode apontá-lo para um alvo perigoso, usando-o como isca ou para atrair os inimigos dele, aproveitando-se da sua reputação.

Usado por: todos os carniçais e revenantes Social]==],
				},
				["Easily Intoxicated"] = {
					pt = [==[Book of Secrets, pág. 40


Easily Intoxicated


As substâncias derrubam você rapidinho. O avesso de Tolerância a Álcool/Drogas, acima, este Defeito o torna especialmente suscetível à intoxicação. Suas rolagens de Vigor para resistir aos efeitos de drogas ou venenos (mas não de doenças), como descrito na seção Drogas, Venenos e Doenças de Mage 20, sofrem +3 na dificuldade usual. Ao contrário do que se imagina, isso não faz de você um bom candidato ao Culto do Êxtase, porque você não controla as drogas – as drogas controlam você.]==],
				},
				["Echo Chamber"] = {
					pt = [==[Book of Secrets, pág. 66


Echo Chamber


Você se cerca de pensamento de rebanho. Todas as opiniões sobre temas importantes (política, religião, magia e assim por diante) precisam permanecer uniformes. Nenhuma discordância é permitida dentro dessa câmara de eco, e quem contraria o decreto é posto para fora – muitas vezes à força – e depois evitado, provavelmente difamado. A lealdade ao grupo é medida pela devoção que cada membro demonstra à "verdade" tal como o grupo a entende. Como resultado, essa "verdade" logo se distorce. Como um eco reverberando num espaço fechado, ela vai virando uma deformação da fonte original, ficando mais selvagem e mais extrema até que algo tenha de ceder. Será você esse ponto de ruptura? Que os deuses não permitam…

Essencialmente um Traço de história, este Defeito corta sua personagem de qualquer informação que contrarie a "verdade" definida pelo grupo. Personagens e dados que discordem dela precisam ser postos de lado, ignorados, silenciados, possivelmente atacados, talvez até destruídos "pelo bem do grupo". Como o isolamento gera distorção, o Narrador deve, aos poucos, tornar "a verdade" mais extrema do que ela era. Qualquer um – especialmente um personagem jogador – que discorde dela deve ser punido pelo grupo; quanto mais extremas as distorções, mais dura a punição. Cedo ou tarde, a "verdade" distorcida vai exigir atos distorcidos também: agressão, tortura, assassinato, terrorismo. Nesse ponto, qualquer personagem que tente se afastar vira inimigo também (podendo receber o Defeito de mesmo nome) – no mínimo evitado pelos antigos amigos, provavelmente desonrado socialmente e potencialmente até agredido por ser traidor da causa.

Este Defeito reflete um fenômeno social cada vez mais comum no século XXI, ainda que não seja exclusivo da nossa era: um grupo social comprometido com a ortodoxia forçada e com a remoção da dissidência. O grupo em questão pode ser uma ordem religiosa ou militar, uma tribo de ativismo sociopolítico, um escritório corporativo, um centro de estudos, um coletivo artístico, uma subcultura de fãs, um veículo de imprensa, uma seita mística ou um comitê de ação política – qualquer panelinha que tenha "certas verdades como evidentes por si mesmas" e vitais para a própria existência pode virar uma câmara de eco. "Nós" e "eles" é o princípio que governa e, se você não é um de Nós, então é um de Eles.]==],
				},
				["Echoes (1)"] = {
					pt = [==[Book of Secrets, pág. 83


Echoes (1)


Veja Mage 20, pp. 646-647.]==],
