				},
				["Eerie Presence"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 495


Eerie Presence


Os mortais têm uma consciência inconsciente da sua natureza morta-viva, o que os deixa ansiosos e desconfortáveis perto de você. Por isso, as dificuldades de todas as rolagens ligadas a interação social com mortais aumentam em dois.]==],
				},
				["Enemy (1)"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 490


Enemy (1)


Você tem um inimigo, ou talvez um grupo deles, que quer prejudicá-lo. O poder do inimigo depende de quantos pontos o jogador quiser gastar (cinco pontos indicam a ira de um Matusalém ou de outro inimigo sobrenatural poderoso).]==],
				},
				["Enemy (2)"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 490


Enemy (2)


Você tem um inimigo, ou talvez um grupo deles, que quer prejudicá-lo. O poder do inimigo depende de quantos pontos o jogador quiser gastar (cinco pontos indicam a ira de um Matusalém ou de outro inimigo sobrenatural poderoso).]==],
				},
				["Enemy (3)"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 490


Enemy (3)


Você tem um inimigo, ou talvez um grupo deles, que quer prejudicá-lo. O poder do inimigo depende de quantos pontos o jogador quiser gastar (cinco pontos indicam a ira de um Matusalém ou de outro inimigo sobrenatural poderoso).]==],
				},
				["Enemy (4)"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 490


Enemy (4)


Você tem um inimigo, ou talvez um grupo deles, que quer prejudicá-lo. O poder do inimigo depende de quantos pontos o jogador quiser gastar (cinco pontos indicam a ira de um Matusalém ou de outro inimigo sobrenatural poderoso).]==],
				},
				["Enemy (5)"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 490


Enemy (5)


Você tem um inimigo, ou talvez um grupo deles, que quer prejudicá-lo. O poder do inimigo depende de quantos pontos o jogador quiser gastar (cinco pontos indicam a ira de um Matusalém ou de outro inimigo sobrenatural poderoso).]==],
				},
				["Enemy Brood"] = {
					pt = [==[Lore of the Clans, pág. 163


Enemy Brood


Você fez inimizade com outro grupo de Nosferatu. Ao contrário dos seus inimigos comuns, eles conhecem os lugares que você frequenta e não têm o menor escrúpulo em segui-lo até lá. Eles o mantêm em movimento, caçando-o de esconderijo em esconderijo. Nem os esgotos são mais seguros para você. Se você se mudar para outra cidade, eles usam seus contatos para avisar os aliados e continuar a perseguição. Cedo ou tarde, você vai ter de derrubá-los para se livrar deles.]==],
				},
				["Escaped Target"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 491


Escaped Target


Você havia escolhido um mortal para o Abraço, mas alguém chegou antes. Você não suporta a humilhação de ter sido roubado do seu prêmio e explode de raiva (+2 de dificuldade para evitar o frenesi) sempre que vê aquele que lhe escapou. Esse ódio pode levá-lo a outros comportamentos irracionais, como Abraçar inimigos do neonato, criar filhos não autorizados ou até tentar matar seu rival. Além disso, seu comportamento mesquinho e irracional é bem conhecido e bastante perceptível e, por isso, você sofre +1 de dificuldade em todas as rolagens de Carisma até a situação ser resolvida.]==],
				},
				["Esoteric Discourse / Technobabbler"] = {
					pt = [==[Book of Secrets, pág. 62


Esoteric Discourse / Technobabbler


Seu amor obsessivo por um campo especializado o leva a preencher cada hora acordado com jargão obscuro e metafraseologia obtusa. A maioria das pessoas não entende metade do que você diz, e a incompreensão delas quanto a uma terminologia tão elementar o impele a facilitar uma pedagogia obrigatória (ainda que remedial). Ah, pelo amor de Deus – fale normal pelo menos uma vez!

Em termos de jogo, este Defeito impõe modificadores de dificuldade (+1 ou +2) em rolagens sociais, graças à jargonização compulsiva, à nomenclatura hiperiniciada e ao pedantismo condescendente da personagem. A primeira variação do Defeito reflete especialização arcana, a segunda reflete terminologia técnica, e outras variações (Juridiquês Capcioso, Academicismo Obtuso e assim por diante) podem refletir fascínios semelhantes por outros campos. Para quem de fato entende você, porém, a penalidade usual pode virar bônus social… ponto em que todo mundo provavelmente sai da sala e deixa os especialistas conversando entre si.]==],
				},
				["Ethical Prohibition (2)"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 422


Ethical Prohibition (2)


A necessidade de se alimentar bate de frente com sua bússola moral. Você não consegue reconciliar o que se tornou com aquilo em que acredita. Com 2 pontos, você se recusa a se alimentar de humanos e caça o sangue de animais. Com 4 pontos, você não consegue se aceitar de forma alguma e se recusa a se alimentar, exceto quando é absolutamente necessário.]==],
				},
				["Ethical Prohibition (4)"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 422


Ethical Prohibition (4)


A necessidade de se alimentar bate de frente com sua bússola moral. Você não consegue reconciliar o que se tornou com aquilo em que acredita. Com 2 pontos, você se recusa a se alimentar de humanos e caça o sangue de animais. Com 4 pontos, você não consegue se aceitar de forma alguma e se recusa a se alimentar, exceto quando é absolutamente necessário.]==],
				},
				["Expendable"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 489


Expendable


Alguém no poder não quer você por perto. Talvez ela queira um território que é seu, ou tenha inveja da atenção que você recebe de um lacaio mortal valioso — os detalhes são irrelevantes. O que importa é que ela tem poder para manobrá-lo até situações perigosas "pelo bem da Seita", e não tem o menor escrúpulo em fazê-lo.]==],
				},
				["Expiration Date"] = {
					pt = [==[Anarchs Unbound, pág. 102


Expiration Date


Seu lema pessoal é simples: eu faço o que quero. Isso, como era de se esperar, já lhe causou problemas mais de uma vez. Você é procurado em vários domínios por diversos crimes menores, como dessangrar o carniçal favorito do Senescal. Ainda não sofreu uma caçada de sangue, mas o aviso está na parede. Seu tempo está praticamente esgotado, e ninguém quer ser arrastado junto quando tudo desandar. Mais um erro e você assina sua sentença de Morte Final. Todas as rolagens sociais para conseguir ajuda sofrem +2 de dificuldade, exceto as que envolvam Intimidação.]==],
				},
				["Extreme Kink (3)"] = {
					pt = [==[Book of Secrets, pág. 52


Extreme Kink (3)


Todo mundo tem suas esquisitices; as suas necessidades são, digamos, mais exóticas que um fetiche comum. Você pode até seguir a terceira parte do mantra BDSM — seguro, são e consensual —, mas o seu tesão não é nem seguro nem são pela definição da maioria das pessoas. Não estamos falando de amarrações e palmadinhas – é mais para Cinquenta Tons de Mas Que Diabos Há de Errado com Você? Ao contrário do velho Defeito Sadismo/Masoquismo (que ele substitui), este Defeito não trata da natureza e das particularidades do seu fetiche – trata do tamanho da encrenca em que você pode se meter tentando satisfazê-lo. Um fetiche de três pontos pode prejudicar sua saúde, sua reputação e seus parceiros; um de quatro pontos pode feri-lo seriamente (e a quem tiver o azar de se envolver com você); e um de cinco pontos pode lhe render cadeia ou coisa pior. (Que os deuses ajudem quem você escolher para satisfazer esse tesão…)

Certos magos são mais propensos a este Defeito que outros, sobretudo se preferem práticas do tipo Caminho da Mão Esquerda. Por razões que deveriam ser óbvias, este não é um Defeito apropriado para toda crônica ou todo jogador, e pode muito bem provocar palavras de segurança e cortes de cena por parte do seu Narrador ou dos seus companheiros. (Veja Mage 20, p. 345.) Embora este Defeito, como outros do gênero, não carregue julgamento da nossa parte, esse tipo de coisa pode ofender e disparar gatilhos em outros jogadores, então não seja babaca com isso.]==],
				},
				["Extreme Kink (4)"] = {
					pt = [==[Book of Secrets, pág. 52


