				},
				["Faceless"] = {
					pt = [==[Lore of the Clans, pág. 239


Faceless


Você escapou da tirania da identidade física. Nenhum rosto é seu. A cada pôr do sol, você desperta com um semblante novo, um amálgama montado a partir de memória e sonho. Seus traços, sua etnia e até seu gênero viram coisas fluidas enquanto você dorme. Embora este Defeito encarne os ideais extremos de Azi Dahaka (e deva impressionar a maioria dos Metamorfosistas), ele pode complicar a vida de um vampiro preocupado em manter reconhecimento, reputação ou um disfarce mortal.

A cada anoitecer, o jogador rola um dado e fica sujeito ao resultado da tabela a seguir:

1: nenhuma mudança.

2-3: mudanças pequenas, ainda um tanto reconhecível.

4-8: irreconhecível até para os mais próximos da personagem (como os companheiros de matilha ou o senhor). Etnia e gênero podem mudar.

9-10: metamorfose total. Tentáculos, espinhos ósseos ou outros traços desumanos podem surgir.

Este Defeito afeta alguns Antecedentes (V20, p. 110). Sem um rosto estável, Identidade Alternativa e Fama não podem ser mantidos. Antecedentes como Aliados, Contatos, Influência e Status também podem ser complicados pela falta de identidade sólida. A vampira pode usar Semblante Maleável e um espelho para reconstruir seu rosto verdadeiro de memória, mas isso exige ao menos três sucessos com dificuldade 8 para torná-la reconhecível, e cinco sucessos para uma cópia perfeita.

O Defeito Identidade Trocada (V20, p. 450) não pode ser adquirido. Outras Qualidades e Defeitos podem ser afetados, a critério do Narrador. Personagens precisam ter ao menos um ponto de Vicissitude para adquirir este Defeito.]==],
				},
				["Failure"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 491


Failure


Você já ocupou um título na cidade, mas fracassou de forma catastrófica em suas obrigações. Agora está marcado como incompetente, excluído dos círculos de poder e responsabilidade e, em geral, deixado de lado por quem está subindo. Sua exclusão pode fazer de você alvo de recrutamento pelos inimigos da Seita (ou assim dizem os sussurros, o que o torna ainda mais malvisto). Por outro lado, as consequências do seu erro podem voltar para assombrá-lo.]==],
				},
				["Faithless"] = {
					pt = [==[Book of Secrets, pág. 93


Faithless


A magia, segundo suas crenças, não vem de você – vem do seu deus, e você quebrou a fé com ele. Enquanto não superar essa crise de fé, talvez expiando o que considera suas faltas, suas Esferas ficam travadas no Nível 1 – potentes o bastante para perceber a presença da Divindade ao seu redor, limitadas o bastante para lembrá-lo de que você falhou.

Este Defeito (que tem mais chance de lhe ser "concedido" no decorrer do jogo do que de ser comprado na criação, embora você possa, claro, começar uma personagem nova já em crise) representa o poder da fé na vida da personagem – um poder tão forte que interfere nas suas capacidades como mago. Ironicamente, é a força dessa fé que lhe nega o uso da magia quando você sente que ela lhe falta. Do ponto de vista das regras, você mesmo está se negando o acesso à sua magia porque acredita que ela vem de uma fonte que você traiu. Seu mago acredita que o deus dele o está cortando da magia, mas… considerando que o jogador é praticamente o "deus" de um personagem de jogo, de um jeito meta, isso é verdade.

Embora uma personagem com este Defeito possa seguir qualquer tipo de foco espiritual, seu paradigma e sua prática precisam ser voltados à devoção religiosa. Você pode ser xamã ou sacerdote, uma bruxa ligada à Deusa, um cientista espiritual, até um infernalista cujos poderes nascidos no inferno fluem de um pacto de danação. Obviamente, este Defeito não significa nada para um ateu, nem para alguém de crenças vagamente casuais. Só um mago que acredita profundamente em algum poder maior pode acreditar que tem tanto a perder com uma súbita falta de fé.

Para se livrar deste Defeito, o jogador precisa pagar uma "multa" de cinco pontos para comprar a saída do Traço e interpretar uma Busca do tipo "noite escura da alma", na qual encara seus pecados e se rededica ao seu Caminho divino. A personagem, por sua vez, precisa antes passar por uma expiação condizente com seu sistema de crenças e com o "pecado" que provocou o castigo. Talvez ela precise fazer votos rígidos dentro de uma ordem religiosa… ou votos ainda mais rígidos, se já tiver quebrado os anteriores. Violou um tabu? Então precisa passar por purificação ritual, muitas vezes por meio de jejum, maratonas de oração e provações tradicionalmente torturantes. Um mago que jurou nunca matar e mesmo assim matou alguém pode ser obrigado a fazer reparações consideráveis à família do morto. Expiações tradicionais incluem peregrinações, jornadas de visão, votos de pobreza, mortificações medonhas (autotortura, jejum radical, mutilação e afins) e outros caminhos difíceis de volta ao favor do próprio deus. Seja qual for o credo e a expiação específica, porém, o mago precisa passar horas incontáveis em oração intensa. Uma alma sem fé, afinal, precisa achar o caminho de volta à presença do seu deus… normalmente de joelhos.]==],
				},
				["Family Issues (1)"] = {
					pt = [==[Book of Secrets, pág. 62


Family Issues (1)


Muitos magos deixam a família para trás. Você não deixou, embora muitas vezes desejasse poder. Avesso da Qualidade Apoio Familiar (pp. 53-54), este Defeito lhe entrega uma cesta de presentes vinda direto da Encruzilhada da Disfunção, versão família. Você pode ter um tio intrometido, um irmão abusivo, um pai alcoólatra ou "simplesmente" as sobras de conviver com esse tipo de gente. Pode ter tentado escapar deles mas, se tentou, alguém da sua família ainda está atrás de você. (Veja o Defeito Pais Persistentes de Werewolf 20 e o conto "We Are the Shadows Cast by the Memory of Giants", em Truth Beyond Paradox.) A família não precisa continuar fazendo parte da sua realidade física, mas a bagunça que ela deixou, caso você tenha conseguido escapar, continua parte da sua existência hoje.

Como em Apoio Familiar, o clã em questão pode ser de parentes de sangue, uma família adotiva ou uma família escolhida que você meio que gostaria de não ter escolhido. Quanto mais pontos neste Defeito, mais os problemas familiares interferem na sua vida Desperta. Eles podem ser magos, embora isso raramente aconteça. O mais provável é que sejam gente que ainda procura por você mesmo na sua Vida Nova, pendurados que não o deixam em paz, parentes doentes que precisam de cuidados (veja também o Defeito Tutelado, p. 66), filhos ou irmãos (ou até pais) sempre em apuros com a lei… as possibilidades são tão infinitas quanto as complicações reais que uma família problemática traz. E não, você não pode simplesmente largá-los, mesmo já tendo tentado. Se pudesse, eles não seriam mais problema seu, não é mesmo?]==],
				},
				["Family Issues (2)"] = {
					pt = [==[Book of Secrets, pág. 62


