				},
				["Fangless"] = {
					pt = [==[Lore of the Clans, pág. 270


Fangless


Tido como a marca de um verdadeiro vira-lata, você nunca desenvolveu presas, ou já lhe faltavam dentes antes do Abraço. De um jeito ou de outro, você precisa usar uma faca ou beber de ferimentos abertos. Você não tem nenhum meio natural, além das Disciplinas, de causar dano agravado.]==],
				},
				["Faulty Enhancements (2)"] = {
					pt = [==[Book of Secrets, pág. 88


Faulty Enhancements (2)


Ah, que droga. A garantia do seu equipamento cibernético venceu (supondo, claro, que ele algum dia tenha tido alguma), e agora você está preso a um hardware defeituoso que, literalmente, entrou sob a sua pele. Sua interface cerebral vive travando? Suas pernas emperram? Seu biotecido vive tentando expulsar o metal? Seja qual for o problema, este Defeito é medido pela quantidade de sofrimento que causa:

(2 pontos) Você sofre desorientação e dor constantes.

(3 pontos) As falhas o deixam em desconforto tão severo que você precisa tomar medicação especializada, ou recorrer a outras formas de alívio da dor, ao menos uma vez por dia. Não fazê-lo custa um dado de todas as paradas de dados até o problema ser resolvido.

(4 pontos) Seus Aprimoramentos falham em momentos críticos (em geral numa falha crítica), travam ou congelam, e precisam então ser consertados por um técnico que entenda do equipamento que você carrega.

(5 pontos) Essa porcaria de equipamento sempre pifa quando você mais precisa. Role um dado contra dificuldade 7 sempre que usar cibertecnologia de algum modo importante (levantar coisas pesadas com braços biônicos, varrer a área com sensores em busca de inimigos, desviar magias inimigas e assim por diante). Se tiver sucesso, os Aprimoramentos funcionam normalmente; se falhar, eles falham e precisam ser reiniciados; se der uma falha crítica, travam ou desligam até um técnico competente conseguir consertá-los.

Obviamente, este Defeito não significa nada a menos que você tenha o Antecedente Aprimoramentos. Embora essas panes ocorram com o biotecido Tecnocrata, elas são muito mais comuns em ciberimplantes instalados por facções cujo pessoal não manteve uma abordagem sistemática e padronizada de melhoramentos humanos nos últimos séculos. Eterritas malucos e Adeptos Virtuais ambiciosos demais inventam ferro-velho o tempo todo, e por isso este Defeito é especialmente apropriado para ciborgues dessas Tradições zelosamente individualistas, assim como para ex-Tecnocratas que conseguiram desertar e sobreviver à experiência até agora.]==],
				},
