Como no Defeito Aprendiz, acima, você tem certa responsabilidade sobre essa criatura – ela não é simplesmente sua inimiga, nem sequer uma nêmesis, mas um ser com quem você divide um vínculo vital. E, também como no Aprendiz, o tratamento que você dá a este "gremlin" (o ser lendário que sabotava aviões por diversão) pode reduzir ou intensificar o valor do Defeito. Uma entidade antes maligna pode ser domada e virar um Familiar (como no Antecedente), enquanto um familiar maltratado pode virar gremlin, e um gremlin apenas irritante pode ser irritado até virar ameaça séria ao mago e ao que o cerca. Como regra opcional, você pode até – com aprovação do Narrador – comprar o Defeito Gremlin além do Antecedente Familiar, para representar um companheiro prestativo e ao mesmo tempo perpetuamente problemático.

Um gremlin, como todo personagem nascido de um Traço, é uma entidade por direito próprio. É bem provável que a encrenca que ele causa ao seu mago tenha um fundamento compreensível – uma razão que parece inexplicável ao mago mas é perfeitamente razoável para o gremlin. Um mago que investigue os motivos desse mau comportamento pode acalmar seu companheiro temperamental; por outro lado, tentar entender a mágoa do gremlin pode apenas irritá-lo ainda mais…]==],
				},
				["Grip of the Damned"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 495


Grip of the Damned


Não há êxtase no seu Abraço — só terror e dor. Os mortais dos quais você se alimenta se debatem e gritam enquanto você tenta beber, obrigando-o a agarrá-los durante todo o tempo em que quiser tomar seu sangue. Para vampiros de Humanidade alta, essa experiência pode exigir uma rolagem de Humanidade, a critério do Narrador. Giovanni não podem adquirir este Defeito.]==],
				},
				["Guilt-Wracked"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 486


Guilt-Wracked


Você simplesmente não consegue aceitar que precisa beber sangue para sobreviver. Sente uma culpa horrível a cada vez que se alimenta (role Consciência, dificuldade 7, ou entra em frenesi toda vez que se alimentar — personagens com a Virtude Convicção não podem adquirir este Defeito) e tenta evitar ao máximo fazê-lo. Isso significa que você raramente tem muito sangue no organismo, o que o deixa vulnerável tanto a ataques quanto a frenesis causados pela fome.]==],
				},
				["Gullible"] = {
					pt = [==[Book of Secrets, pág. 65


Gullible


Você acredita em tudo o que lhe dizem. Compartilha memes sem checar veracidade ou fonte. Cai em golpes e trotes toda santa vez. Sério? Como pode um mago ser tão ingênuo assim? Vai saber, mas é isso mesmo – subtraia três dados de toda parada de dados que você rolar (até um mínimo de um dado) quando estiver tentando enxergar através de mentiras (mentiras, não furtividade), ou enganar alguém com suas próprias tentativas atrapalhadas de trapaça.]==],
				},
				["Harbinger of the Abyss"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 428


Harbinger of the Abyss


Você se tornou o vazio: o negro sem fim da noite, uma poça vazia de escuridão. Por onde passa, as sombras saltam para se juntar a você e as chamas bruxuleiam e morrem. Na presença de fogo comum, você precisa fazer uma rolagem reflexa de Obtenebração contra a dificuldade de absorção de qualquer chama próxima. Um sucesso apaga o fogo instantaneamente, mergulhando o local na escuridão. Este Defeito inclui também os efeitos de Toque de Gelo (p. 426) e Presença Sinistra (p. 427), sendo portanto mutuamente exclusivo com eles. A escuridão que se agarra a você, porém, traz um benefício (além de ser um jeito incomum de apagar fogos indesejados): reduza a dificuldade de todas as rolagens de Intimidação em dois, até um mínimo de 4. Você precisa ter ao menos um ponto de Obtenebração para comprar este Defeito.]==],
				},
				["Hard of Hearing"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 480


Hard of Hearing


Sua audição é defeituosa. As dificuldades de qualquer rolagem que envolva ouvir aumentam em dois.]==],
				},
				["Hatred"] = {
					pt = [==[Book of Secrets, pág. 52


Hatred


Como em Fanático, acima, você despreza profundamente algum objeto de ódio. Talvez você deteste vampiros, metamorfos, gente rica ou gente em situação de rua, o povo feérico, espíritos, cachorros, caminhões, máquinas, TV, advogados, bruxas, policiais, políticos… seja o que for que você odeie, odeia muito, e aproveitará qualquer oportunidade para atrapalhar ou ferir o alvo da sua hostilidade.

Como um fanático, você tem o que considera uma razão perfeitamente racional para odiar aquilo que despreza. Os outros provavelmente o acham pirado, a menos que compartilhem do seu ponto de vista – caso em que podem virar discípulos. (Veja os Antecedentes Aliados, Reforços, Culto, Influência e Lacaios.) Como numa Meta Motivadora, este Defeito guia as escolhas de interpretação, determina alvos e faz você parecer bastante obsessivo sempre que o objeto da sua aversão entra em cena. Como medo e ódio andam juntos, é bem provável que você também tenha Pavio Curto e/ou uma Fobia ligada a este Defeito. E, se você tiver ainda Furioso/Atavismo de Estresse ou Besta Interior, precisará de uma rolagem de Força de Vontade (dificuldade 8) ao ser confrontado de frente com aquilo que abomina, ou perde a cabeça na direção geral daquilo.

Obviamente, este Defeito precisa ser escolhido com cuidado. Se sua personagem tende a explodir como uma bomba contra, digamos, a polícia de forma recorrente, ela terá uma vida bem dura (e provavelmente curta).]==],
				},
				["Haunted"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 495


Haunted


Você é assombrado por um espírito raivoso e atormentado, muito provavelmente uma das suas primeiras vítimas. Esse espírito tenta ativamente atrapalhá-lo, especialmente quando você se alimenta, e faz o possível para descarregar sua angústia em você e em quem estiver por perto. O Narrador determina a natureza exata do espírito, seus poderes e se ele pode ou não ser enfim posto para descansar.]==],
				},
				["Heartless"] = {
					pt = [==[Lore of the Clans, pág. 67


Heartless


Você perdeu seu coração. Ou o removeu por meio do Coração das Trevas (veja V20, p. 210), ou um ancião fez isso com você; de todo modo, você não tem mais acesso fácil a ele. O coração pode estar em poder de um inimigo, ou simplesmente sumido. Se acontecer de um Cainita possuí-lo (digamos, um ancião Setita ou o seu senhor), você precisa obedecer a cada ordem dele. Se estiver apenas sumido, a ansiedade e a obsessão de achá-lo interferem na sua existência noturna e podem aumentar em +1 a dificuldade das rolagens de Força de Vontade, a critério do Narrador.]==],
				},
				["Hemophiliac"] = {
					pt = [==[The Hunters Hunted II, pág. 43


Hemophiliac


Sua personagem sofre de hemofilia. Se for cortada, não para de sangrar sem ajuda médica. Se sua caçadora sofrer dano letal ou agravado, ela sofre um nível adicional de dano contundente a cada cinco minutos até que o ferimento seja tratado para estancar o sangramento. Qualquer vampiro que a morda pode "tratar" esses ferimentos e encerrar o dano contundente contínuo lambendo a lesão depois de mordê-la.]==],
				},
				["Hero Worship"] = {
					pt = [==[Book of Secrets, pág. 46


Hero Worship


Você adora outro personagem a ponto de, para você, ele não errar nunca. Tentativas de mudar sua opinião só o irritam, o fazem se fechar ou o levam a alturas (ou profundezas) de justificativa absurda diante do que quer que digam sobre ele. Traço comum entre quem vive numa Câmara de Eco (veja o Defeito Social de mesmo nome, pp. 66-67), esse ponto cego psicológico pode virar algo irritante, e até perigoso, se estiver centrado na pessoa errada… como, digamos, um Gerente do Sindicato, um Nephandus ou certos candidatos à presidência!

Se seu herói mandar você fazer algo, você tende a obedecer, e precisa de uma rolagem de Força de Vontade para recusar. A dificuldade depende do extremo do pedido; "Me dá um beijo" seria provavelmente dificuldade 5, enquanto "Vá apunhalar seu melhor amigo pelas costas por mim" seria 9 ou 10. Quando é confrontado com provas das fraquezas do seu herói, você é capaz de acabar enxergando a razão – só não é fácil fazê-lo pensar com essa clareza. Qualquer rolagem social voltada a fazê-lo abandonar essa idolatria soma +2 à dificuldade, a menos que o herói tenha feito algo muito errado recentemente… como, digamos, mandar você apunhalar seu melhor amigo pelas costas!]==],
				},
				["Hit List"] = {
					pt = [==[Book of Secrets, pág. 67


Hit List


Um grupo rival quer você morto. Você pode ser um Templário que fez inimigos entre os Eterritas, um Eterrita que passou dos limites com a Nova Ordem Mundial e assim por diante. Seja lá o que aconteceu, é pessoal e vale para o grupo inteiro. Como no Defeito Inimizade de Clã de Vampiro 20, isto é coisa mortal, bem pior que a Inimizade de Seita de um ponto, acima. Rolagens sociais ao lidar com membros desse grupo somam +2 à dificuldade – se é que você terá a chance de fazer alguma. Atacando você à primeira vista ou não, os membros do grupo farão questão de tornar sua vida solitária, desagradável, mesquinha, brutal e curta.]==],
				},
				["Horrific"] = {
					pt = [==[Book of Secrets, pág. 41


Horrific


Muito além de Monstruoso, você é medonho a ponto de inspirar pesadelos. A menos que mascare sua forma verdadeira com magia pesada, pessoas e animais saem correndo e gritando da sua presença. Fisicamente, você não é apenas disforme, é repulsivo num nível primal – o tipo de terror que levou os heróis de Lovecraft à loucura. Você pode nem ser um Nephandus ou um Marauder, mas quem sabe o que essas palavras significam vai presumir que é. Uma vida normal é, para você, impossível. Seja por desfiguração de Paradoxo, doença maligna, modificações corporais extremas (cibernéticas, artísticas ou de outro tipo), cicatrizes severas ou atos semelhantes de um destino malévolo, você parece alguém em quem John Cobb vomitou antes de sair correndo.

Em termos de sistema, este Defeito impõe +3 de dificuldade a qualquer rolagem social que envolva não apavorar as pessoas, e reduz a dificuldade em -3 se o objetivo for justamente apavorá-las. Seu Traço de Aparência fica travado abaixo de zero, e personagens do Narrador de coração fraco ou vontade fraca podem se ver diante de Coisas Que o Homem Não Deveria Saber (conforme Mage 20, p. 407) se acabarem passando um tempo com você.]==],
				},
				["Hunted"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 491


Hunted


Você é perseguido por um caçador de bruxas fanático que acredita (talvez com razão) que você é um perigo para a humanidade. Todos com quem você se associa, mortais ou Cainitas, também podem ser caçados.]==],
				},
				["Hunted by the Hierophants"] = {
					pt = [==[Dark Ages Tome of Secrets, pág. 4


Hunted by the Hierophants


Os Setitas afirmam que sua religião é de libertação da doutrinação e do condicionamento. Os Hierofantes concordam abertamente — e então esmagam quem tenta subverter a fé de Sutekh. Seja por você ser uma Bruxa de Equidna, um dos postulantes deles, ou simplesmente um Setita que jogou fora o jugo de Sutekh, os Hierofantes estão descontentes com sua decisão e vão atrás de você, enviando guerreiros Setitas para pô-lo na linha. Dependendo da profundidade dos seus pecados, eles tentarão capturá-lo e levá-lo de volta às Cortes do Egito ou destruí-lo no ato. Os Hierofantes não toleram profanação e não o tirarão de suas listas até estarem convencidos do seu arrependimento ou da sua Morte Final. Narradores são encorajados a fazer da existência desse vampiro uma vida de paranoia e ameaça quase constante.]==],
				},
				["Hunted Like a Dog"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 492


Hunted Like a Dog


Outra Seita ou grupo de vampiros decidiu que você é alvo de extermínio, e o persegue sem descanso. Pelo lado bom, os inimigos do seu inimigo podem muito bem querer ajudá-lo, o que pode lhe render aliados.]==],
				},
				["Icy"] = {
					pt = [==[Book of Secrets, pág. 49


Icy


Você é um desgraçado de sangue-frio – um assassino, um bandido, um sociopata ou um sádico capaz de cometer atrocidades sem o menor tremor. Embora não seja necessariamente louco (veja as Perturbações em Mage 20, pp. 649-650), sua insensibilidade o marca como um sujeito assustador. As pessoas o evitam, a menos que tenham alguém para matar… e então dão um passo atrás e deixam você fazer o seu trabalho. A Sala 101 tem vagas para gente como você (e, apesar da fachada de mocinhos, as Tradições e os grupos Díspares também), mas ninguém confia de verdade em você, e sua alma está definitivamente em perigo, com os Caídos a um ou dois passos de serem donos do seu traseiro gelado.]==],
				},
				["Ignorance"] = {
					pt = [==[Lore of the Clans, pág. 270


Ignorance


Muitos senhores abandonam sua prole Caitiff sem uma palavra de instrução ou aviso sobre a nova natureza dela. Para a maioria dos Príncipes, a ignorância não desculpa uma quebra da Máscara, e as matilhas da Sabá são rápidas em notar fraqueza. A personagem começa sem nenhum conhecimento das capacidades, dos costumes ou da política dos mortos-vivos, e precisa aprender com os próprios erros ou achar um mentor. Claro que qualquer vampiro disposto a tomar conta de um Caitiff muito provavelmente vinculará pelo sangue o pobre coitado, o que gera um conjunto inteiramente novo de problemas. A ignorância é mortal para um vampiro, e duplamente mortal para os sem Clã.]==],
				},
				["Illiterate (1)"] = {
					pt = [==[Lore of the Bloodlines, pág. 4


Illiterate (1)


Talvez você se comunique melhor por ilustração, dança ou discurso apaixonado; mas não sabe ler nem escrever. Este é um Defeito temporário (1 pt.), que pode ser corrigido com um professor paciente, ou permanente (2 pts.), por causa de uma deficiência que impede sua compreensão. Ele basta para deixá-lo de fora do convívio dos outros da sua linhagem, se você não o esconder.]==],
