				},
				["Impaired Sense"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 421


Impaired Sense


Seja de nascença, seja por uma circunstância infeliz mais tarde na vida, um dos seus sentidos foi diminuído. Talvez você tenha dificuldade de audição ou seja cego, ou talvez um dos outros sentidos tenha perdido a funcionalidade. Rolagens que envolvam o sentido prejudicado têm a dificuldade aumentada em 3. Isso também pode aumentar a dificuldade de outras rolagens ou impor outras penalidades cabíveis. A critério do Narrador, este Defeito pode ser adquirido mais de uma vez, mas cada sentido adicional é um Defeito de 1 ponto.]==],
				},
				["Impatient"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 485


Impatient


Você não tem a menor paciência para ficar parado esperando. Quer fazer as coisas AGORA — que se danem os lerdos que tentam segurá-lo. Toda vez que for obrigado a esperar em vez de agir, é exigida uma rolagem de Autocontrole para ver se você sai correndo por conta própria.]==],
				},
				["Impediment (1)"] = {
					pt = [==[Book of Secrets, pág. 39


Impediment (1)


Por causa de alguma condição física, você lida pior com certas situações do que a maioria das pessoas parece conseguir. E, se isso soa muito condicional, é porque as particularidades deste Defeito dependem bastante do seguinte: que tipo de condição você tem, o quanto ela atrapalha e se os outros conseguem ou não perceber que ela atrapalha.

Literalmente falando, um impedimento atravessa o seu caminho "travando seus pés". Em termos de sistema, este Defeito representa qualquer tipo de limitação enraizada na situação física da personagem. Isso inclui condições neurológicas e químicas internas como autismo, dislexia, fadiga crônica, alergias importantes e outras enfermidades que podem ser "invisíveis" para os outros mas que têm raiz no corpo físico, e não na psique ou no espírito. Tais condições também podem estar ligadas à saúde psicológica e/ou espiritual; esses elementos são interligados, claro. Para os fins deste Defeito, porém, um Impedimento é algo que limita a capacidade da personagem de funcionar no plano físico.

Em termos de história, um Impedimento pode ser qualquer condição corporal – aparente ou não – que atrapalhe a capacidade da personagem de fazer coisas. Exemplos de Impedimentos aparentes incluem um membro faltando, um manquejar, uma coluna torta, dentes faltando, cicatrizes extensas, traços deformados e afins, enquanto Impedimentos "invisíveis" incluem dor e/ou fadiga crônica, visão ruim, asma, tumores internos, transtornos de processamento sensorial e assim por diante. Quanto mais a condição impede sua personagem, mais o Defeito vale:

(1 ponto) Como dores de cabeça crônicas, visão prejudicada, artrite leve ou alguns dentes faltando, o Impedimento traz inconvenientes ocasionais mas não é um transtorno maior na sua vida, a menos que algo agrave a condição ou lhe tire aquilo (óculos, dentadura, analgésico) que você usa para compensá-la.

(2 pontos) Como dislexia, síndrome de Asperger de alto funcionamento, fadiga ou dor crônica, visão ruim ou em deterioração, ou outros obstáculos internos, seu Impedimento traz problemas constantes mas não intransponíveis. Em certas situações, você pode sofrer +1 nas dificuldades ligadas àquele aspecto da sua vida.

(3 pontos) Seu Impedimento – enxaquecas severas, autismo significativo, alergias ou asma, dedos ou um olho faltando, surdez quase completa, paralisia parcial, síndrome de Tourette, membros em deterioração e assim por diante – limita de forma considerável vários aspectos do seu cotidiano. Em regras, você soma +1 às dificuldades ligadas ao Impedimento.

(4 pontos) Um Impedimento inescapável – membro faltando, surdez ou autismo profundos, cegueira quase total, ossos ou tecidos conjuntivos malformados (como na SED, citada acima), artrite severa, mãos ou pés retorcidos e obstáculos semelhantes – o obriga a contornar aquela condição todos os dias. Na maioria das circunstâncias, você soma +2 às dificuldades ligadas ao Impedimento, e certas situações (como uma reação alérgica feia) podem prejudicar sua saúde e pôr sua vida em risco.

(5 pontos) Por causa de uma condição física profunda – paralisia parcial, dor constante e severa, câncer avançado, incapacidade de ouvir ou falar, deterioração musculoesquelética, grande perda de visão e outras enfermidades –, você é incapaz de funcionar da maioria das formas que as pessoas tomam por garantidas. Some +2 às dificuldades físicas, a menos que tenha um jeito confiável de compensar a limitação, e assuma que certas coisas você simplesmente não consegue fazer.

(6 pontos) Por qualquer razão, sua condição é tão avançada e severa que você precisa de grandes adaptações para funcionar no mundo cotidiano. Muitos feitos físicos estão fora do seu alcance, e você soma +2 ou até +3 às dificuldades daquilo que consegue fazer, mas só com grande esforço.

O Defeito representa a limitação prática na vida da personagem; se seu mago tem um braço cibernético que age como o original, só que melhor, então ele não está limitado enquanto o braço não quebrar. Se alguém curar a condição com magia ou outro tratamento, a personagem perde este Defeito.

Nem todos os Impedimentos são iguais, e por isso uma pessoa "cega" pode funcionar no mundo dos que enxergam melhor (isto é, com menos pontos no Defeito) que outra pessoa com deficiência visual (com mais pontos). O valor do Impedimento também pode refletir várias condições distintas que, somadas, atrapalham a personagem a funcionar "normalmente" mais do que qualquer uma delas isoladamente. Como exemplo, este autor tem dislexia, discalculia, visão ruim e dois joelhos cronicamente lesionados; isso o impede? Não. Isso o atrasa em certos aspectos? Com certeza, e por isso o total do "Defeito" dele refletiria o tamanho da dificuldade que essas condições, somadas, impõem no dia a dia.

Este Defeito serve de guarda-chuva para Defeitos Físicos publicados antes, como Cego, Surdo e, especialmente, o pejorativo Aleijado. Ao contrário de muitos rótulos aplicados a essas "deficiências", o Defeito Impedimento não carrega julgamento algum por parte do jogo; ainda que personagens (e jogadores) possam menosprezar uma pessoa "preguiçosa" com cinco pontos em Impedimento por Síndrome da Fadiga Crônica, o Defeito em si não pretende de forma alguma ser um insulto a quem vive com essas condições.

Aliás, um Impedimento pouco aparente pode trazer desafios sociais consideráveis; uma pessoa com síndrome de Tourette pode parecer perfeitamente saudável mesmo enquanto o cérebro dela falha, com os únicos sintomas visíveis sendo sons ou atos "inapropriados". (Veja o Defeito Mental Inapropriado, p. 46.) Aquela maga com SFC pode ser considerada "preguiçosa demais para sair da cama" por quem não vê o corpo dela sabotando-a de dentro para fora. Assim, o valor do Defeito – com aprovação do Narrador – pode refletir penalidade em rolagens sociais em vez de físicas, em certas situações. ("Por que você faltou ao trabalho de novo?" "Eu não conseguia dar dez passos sem cair." "Sei…")]==],
