				["Inbred (1)"] = {
					pt = [==[Lore of the Clans, pág. 107


Inbred (1)


A consanguinidade, ocorrência comum no incestuoso Clã Giovanni, pode assumir muitas formas. O Defeito Consanguíneo cobre todo tipo de defeito físico, mental e emocional. Uma consanguinidade de um ponto é algo simples e discreto, como olhos próximos demais ou uma mordida cruzada (+1 de dificuldade em rolagens de Aparência). Uma de três pontos é mais séria: uma condição de saúde congênita (para mortais) ou uma deformidade física incapacitante (+2 de dificuldade nas rolagens cabíveis de Força, Destreza ou Vigor). As de cinco pontos são gravemente incapacitantes ou emocionalmente devastadoras — de pernas atrofiadas e inúteis a uma Perturbação permanente —, definidas em conjunto pelo jogador e pelo Narrador. Condições consanguíneas podem ou não ser perceptíveis de imediato, embora seu custo em pontos deva ser proporcional à magnitude, conforme o Narrador decidir.]==],
