					pt = [==[Lore of the Clans, pág. 107


Inbred (4)


A consanguinidade, ocorrência comum no incestuoso Clã Giovanni, pode assumir muitas formas. O Defeito Consanguíneo cobre todo tipo de defeito físico, mental e emocional. Uma consanguinidade de um ponto é algo simples e discreto, como olhos próximos demais ou uma mordida cruzada (+1 de dificuldade em rolagens de Aparência). Uma de três pontos é mais séria: uma condição de saúde congênita (para mortais) ou uma deformidade física incapacitante (+2 de dificuldade nas rolagens cabíveis de Força, Destreza ou Vigor). As de cinco pontos são gravemente incapacitantes ou emocionalmente devastadoras — de pernas atrofiadas e inúteis a uma Perturbação permanente —, definidas em conjunto pelo jogador e pelo Narrador. Condições consanguíneas podem ou não ser perceptíveis de imediato, embora seu custo em pontos deva ser proporcional à magnitude, conforme o Narrador decidir.]==],
				},
				["Inbred (5)"] = {
					pt = [==[Lore of the Clans, pág. 107


Inbred (5)


A consanguinidade, ocorrência comum no incestuoso Clã Giovanni, pode assumir muitas formas. O Defeito Consanguíneo cobre todo tipo de defeito físico, mental e emocional. Uma consanguinidade de um ponto é algo simples e discreto, como olhos próximos demais ou uma mordida cruzada (+1 de dificuldade em rolagens de Aparência). Uma de três pontos é mais séria: uma condição de saúde congênita (para mortais) ou uma deformidade física incapacitante (+2 de dificuldade nas rolagens cabíveis de Força, Destreza ou Vigor). As de cinco pontos são gravemente incapacitantes ou emocionalmente devastadoras — de pernas atrofiadas e inúteis a uma Perturbação permanente —, definidas em conjunto pelo jogador e pelo Narrador. Condições consanguíneas podem ou não ser perceptíveis de imediato, embora seu custo em pontos deva ser proporcional à magnitude, conforme o Narrador decidir.]==],
				},
				["Incoherent"] = {
					pt = [==[Lore of the Clans, pág. 163


Incoherent


A fala humana é impossível para você. Pode ser que sua boca esteja disforme demais depois do Abraço, ou que anos vivendo nos esgotos o tenham feito esquecer como se comunicar. Embora entenda o que lhe dizem, você não consegue responder. A telepatia funciona normalmente com você, e você não tem problema algum em se comunicar com animais, mas a fala humana lhe está vedada.]==],
				},
				["Incomplete Understanding"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 490


Incomplete Understanding


Explicaram tudo para você, mas você ainda não tem certeza de como as coisas funcionam na sua Seita. Sua compreensão imperfeita das regras e dos regulamentos da sua nova existência significa que, cedo ou tarde, você vai cometer um erro. É só questão de tempo…]==],
				},
				["Infamous Sire"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 490


Infamous Sire


Seu senhor era, e talvez ainda seja, malvisto e detestado por muitos Cainitas da cidade. Como resultado, você também é malvisto e detestado.]==],
				},
				["Infamy (1)"] = {
					pt = [==[Book of Secrets, pág. 62


Infamy (1)


Você ganhou má fama entre as Massas. Como o Antecedente Fama, este Defeito representa um grau de reconhecimento; no seu caso, porém, isso não é bom… ainda mais quando você quer manter sua vida de mago em segredo dos Adormecidos.

Mais uma vez, o peso do Defeito determina seu valor:

(1 ponto) Certas pessoas de uma região ou subcultura reconhecem você e não gostam de você. (Exemplos: o bêbado da esquina, Vox Day.)

(2 pontos) Sua notoriedade já foi ampla, mas hoje se resume a reconhecimento e desdém ocasionais (H.R. Clinton, M.C. Hammer).

(3 pontos) Você é famoso, mas muita gente não gosta de você (Kanye West, Nickelback).

(4 pontos) As autoridades também não gostam de você (Roosh V, Jared Fogle).

(5 pontos) Seu nome é conhecido em todo lar, e esse nome é uma merda (O.J. Simpson, Charles Manson).

Especialmente na era das redes sociais e das redes de inteligência, esse tipo de infâmia pode ser péssimo. Obviamente, algumas pessoas o adoram, ainda que seja só porque o resto do mundo o odeia. No conjunto, porém, sua reputação entre as Massas é mais má que boa, e as pessoas fazem questão de complicar sua vida. Como em outras más reputações, pode ser que você não tenha feito nada de errado; por outro lado, pode haver bons motivos para as pessoas o detestarem.]==],
				},
				["Infamy (2)"] = {
