				},
				["Infectious"] = {
					pt = [==[Lore of the Clans, pág. 142


Infectious


A loucura corre no seu sangue, e sua mordida também carrega essa mácula. Mortais adquirem uma perturbação temporária a cada três pontos de sangue que você tomar deles. As perturbações duram até o mortal repor o sangue perdido.]==],
				},
				["Infectious Bite"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 481


Infectious Bite


Você não consegue lamber automaticamente as feridas da sua alimentação para fechá-las. Na verdade, suas mordidas têm uma chance em cinco de infeccionar e deixar as vítimas mortais gravemente doentes. A natureza exata da infecção é determinada pelo Narrador.]==],
				},
				["Infertile Vitae"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 484


Infertile Vitae


Durante seu Abraço, algo deu terrivelmente errado, e seu sangue sofreu uma mutação sob o estresse de morrer e se erguer de novo. Todos os que você tenta Abraçar morrem. Não importa o que faça, você não pode criar filhos. Seu sangue, porém, ainda pode ser usado em rituais de sangue como a Taumaturgia e a Vaulderie, ou para outras necessidades vampíricas, como criar carniçais.]==],
				},
				["Initiate of the Road"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 426


Initiate of the Road


Sua vida na estrada rumo à iluminação mal começou. Embora compreenda plenamente os preceitos e os princípios da Estrada que escolheu, você ainda não os pôs à prova. Isso pode ser porque foi Abraçado há pouco ou porque abandonou uma Estrada anterior (caso em que talvez queira considerar também o Defeito Apóstata, na página 425). Com isso vem +1 de dificuldade para resistir a frenesi e a Rötschreck, e você não tem uma aura ligada à sua Estrada. Por outro lado, tem mais facilidade para mudar de Estrada, se quiser.]==],
				},
				["Insane /Infamous Mentor"] = {
					pt = [==[Book of Secrets, pág. 63


Insane /Infamous Mentor


A maga que lhe ensinou o ofício está perigosamente enrolada nele. Talvez ela tenha perdido a cabeça (embora provavelmente ainda não seja uma Marauder); ou ele tenha uma fama horrível que respingou toda em você. Essa pessoa pode estar com raiva de você por alguma razão (boa ou não), ou viver rio abaixo no Riacho da Merda, com o péssimo hábito de arrastar você junto na correnteza. Este Defeito é um ótimo complemento ao Antecedente Mentor, e tem o dom de estragar suas relações com outros magos, além do seu vínculo com a própria mentora.]==],
				},
				["Insubordinate"] = {
					pt = [==[Lore of the Clans, pág. 123


Insubordinate


Você gosta tanto de mandar que tem dificuldade em seguir ordens de qualquer outra pessoa. Quando recebe um plano ou uma ordem, tende a fazer o oposto por princípio. Sempre que for mandado a fazer algo, você precisa de uma rolagem de Força de Vontade, com dificuldade conforme a importância do superior e o perigo da tarefa (dificuldade 7 é o típico para alguém logo acima do vampiro atribuindo-lhe uma tarefa moderadamente perigosa). Se falhar, você fará qualquer coisa, menos o que mandaram.]==],
				},
				["Intemperate"] = {
					pt = [==[Book of Secrets, pág. 49


Intemperate


Tudo o que você faz, faz em excesso. Ah, claro, você (em geral) consegue resistir ao impulso de ser terminalmente burro, mas moderação não faz parte do seu vocabulário. Tomando um drinque? Por que não seis? Uma mão de cartas? Por que não apostar o próximo salário no resultado? De opinar a arriscar corpo e alma, você joga com a vida esperando que o outro é que desvie. As pessoas esperam esse tipo de coisa de Cultistas do Êxtase, mas a maioria dos Extáticos tem noção melhor dos próprios limites que você.

Sempre que estiver fazendo algo que provavelmente não vai render acusação criminal ou morte imediata, faça uma rolagem de Força de Vontade para resistir ao impulso de ir com tudo. A dificuldade depende das prováveis consequências do excesso; riscos pequenos significam dificuldade 8 ou 9, enquanto riscos com potencial de morte são mais fáceis de resistir (dificuldade 5 ou 6)… ainda que você já tenha ido longe demais nesse departamento também!]==],
				},
				["Isolated Upbringing"] = {
					pt = [==[The Hunters Hunted II, pág. 123


Isolated Upbringing


Você foi criado pela Sociedade de Leopoldo, seja por ser filho de um Inquisidor, seja por ter sido adotado pela Sociedade ainda cedo. A Inquisição é tudo o que você conhece. A santidade da sua obra sagrada foi afiada por uma pureza de treino, sem a névoa das distrações. Infelizmente, sua compreensão do mundo lá fora é limitada. Fora do ambiente da Sociedade, subtraia um dado de todas as paradas de dados Sociais. Quando o trabalho de campo o levar para além dos muros da Inquisição, como você vai reagir a toda essa gente nova, a todos esses estímulos e aos colegas caçadores que não foram criados enclausurados?]==],
				},
				["Jinx /Infernal Contraption (10)"] = {
					pt = [==[Book of Secrets, pág. 88


Jinx /Infernal Contraption (10)


Portador da Tempestade. O Um Anel. A Mão do Macaco. Claro, aquele treco paranormal pode ter poderes incríveis, mas é também um saco de misérias como poucos humanos conseguem imaginar. E você tem um. Sortudo…

Como no Antecedente Maravilha (Traço para o qual este Defeito já foi o Antecedente adverso), este Traço representa um item ou dispositivo sobrenatural. Neste caso, porém, o "tesouro" dá mais trabalho do que vale. Talvez ele seja amaldiçoado com infortúnios, mal construído, assombrado por espíritos malignos, fervilhando de emanações de Paradoxo ou experimental demais para o próprio bem. Pode ser a forma terrena de uma entidade desagradável ("Eu era mil vezes mais malvado que tu…"), um artefato alienígena ou o resto de uma cultura que virou pó há milênios – e bem feito para eles! Ou talvez seja simplesmente um tesouro de fato maravilhoso que não vai com a sua cara, como a Espada de Lutar em JourneyQuest. Seja qual for a razão, você é dono dessa mó mística/hipertecnológica e não consegue se livrar dela com facilidade.

Como em todo Defeito de pontos variáveis, o valor deste Traço depende da capacidade que ele tem de estragar sua vida. Neste caso, porém, o valor do Defeito é descontado do custo do Antecedente Maravilha. Para evitar catástrofes matemáticas, cada dois pontos no Defeito valem um ponto no custo do Antecedente Maravilha. Esse custo, porém, não pode cair abaixo de um ponto (dois pontos de Defeito), e assim quaisquer pontos que "sobrem" entre o valor do Defeito e os dois pontos daquela Maravilha são somados à ficha do dono, representando o proverbial albatroz morto pendurado no pescoço: um fardo poderoso do qual ele não pode simplesmente se livrar.

Para regras ampliadas sobre Maravilhas, veja a seção de mesmo nome no Capítulo Dois, pp. 139-165.

(2 pontos) Seu item Azarado tem um inconveniente irritante que, embora não seja mortal, torna difícil a vida de quem o possui. Exemplos: ele atrai fantasmas, cheira mal, faz sons irritantes em horas inconvenientes ou irradia uma aura persistente de desconforto.

(4 pontos) O item Azarado tem vários inconvenientes irritantes (como acima), ou talvez um ou dois problemáticos. Exemplos: ele precisa derramar sangue toda vez que é usado, tem uma personalidade briguenta e desagradável, atrai espíritos malignos ou tenta a dona a violar o próprio código moral.

(6 pontos) Seu item tem uma penca de inconvenientes irritantes (pelo menos seis), três ou quatro problemáticos e/ou um defeito grave. Exemplos: o item pertence a uma entidade paranormal poderosa que o quer de volta, causa dor constante a quem o usa (três níveis de vitalidade contundentes por turno de operação), irradia uma aura de corrupção e decadência, ou empurra o dono continuamente para atrocidades.

(8 pontos) Além de pelo menos seis inconvenientes irritantes e/ou cinco problemáticos, mais dois ou mais defeitos graves, o item também sai pela culatra se você falhar numa rolagem de Raciocínio + Esotérica (ou Raciocínio + Hipertecnologia, se o item usar tecnologia avançada) contra dificuldade 7. O Narrador é encorajado a ser criativo ao decidir como esse tiro pela culatra se manifesta; para sugestões, veja a tabela Mexendo com Maravilhas, Capítulo Dois, p. 141.

(10 pontos) Além do nível anterior de dificuldade, o Narrador basicamente ganha licença aberta para complicar sua vida de formas inesperadas, criativas e muitas vezes misteriosas. Exemplos: um culto sedento de sangue atrás do tesouro, uma entidade demoníaca aprisionada dentro do item, um vórtice interdimensional de flutuações de probabilidade e caprichos da física que se manifestam nas imediações do objeto, e assim por diante.

Esses defeitos, claro, devem se basear na natureza do item Azarado e na relação dele com o dono. Dito isso, não há razão para um robô não poder ser possuído por espíritos malignos, nem para um artefato primevo não poder ser um perigo tecnológico usando tecnologia desconhecida. Coisas mais estranhas que essas acontecem o tempo todo em Mage.]==],
				},
				["Jinx /Infernal Contraption (2)"] = {
					pt = [==[Book of Secrets, pág. 88


