Jinx /Infernal Contraption (9)


Portador da Tempestade. O Um Anel. A Mão do Macaco. Claro, aquele treco paranormal pode ter poderes incríveis, mas é também um saco de misérias como poucos humanos conseguem imaginar. E você tem um. Sortudo…

Como no Antecedente Maravilha (Traço para o qual este Defeito já foi o Antecedente adverso), este Traço representa um item ou dispositivo sobrenatural. Neste caso, porém, o "tesouro" dá mais trabalho do que vale. Talvez ele seja amaldiçoado com infortúnios, mal construído, assombrado por espíritos malignos, fervilhando de emanações de Paradoxo ou experimental demais para o próprio bem. Pode ser a forma terrena de uma entidade desagradável ("Eu era mil vezes mais malvado que tu…"), um artefato alienígena ou o resto de uma cultura que virou pó há milênios – e bem feito para eles! Ou talvez seja simplesmente um tesouro de fato maravilhoso que não vai com a sua cara, como a Espada de Lutar em JourneyQuest. Seja qual for a razão, você é dono dessa mó mística/hipertecnológica e não consegue se livrar dela com facilidade.

Como em todo Defeito de pontos variáveis, o valor deste Traço depende da capacidade que ele tem de estragar sua vida. Neste caso, porém, o valor do Defeito é descontado do custo do Antecedente Maravilha. Para evitar catástrofes matemáticas, cada dois pontos no Defeito valem um ponto no custo do Antecedente Maravilha. Esse custo, porém, não pode cair abaixo de um ponto (dois pontos de Defeito), e assim quaisquer pontos que "sobrem" entre o valor do Defeito e os dois pontos daquela Maravilha são somados à ficha do dono, representando o proverbial albatroz morto pendurado no pescoço: um fardo poderoso do qual ele não pode simplesmente se livrar.

Para regras ampliadas sobre Maravilhas, veja a seção de mesmo nome no Capítulo Dois, pp. 139-165.

(2 pontos) Seu item Azarado tem um inconveniente irritante que, embora não seja mortal, torna difícil a vida de quem o possui. Exemplos: ele atrai fantasmas, cheira mal, faz sons irritantes em horas inconvenientes ou irradia uma aura persistente de desconforto.

(4 pontos) O item Azarado tem vários inconvenientes irritantes (como acima), ou talvez um ou dois problemáticos. Exemplos: ele precisa derramar sangue toda vez que é usado, tem uma personalidade briguenta e desagradável, atrai espíritos malignos ou tenta a dona a violar o próprio código moral.

(6 pontos) Seu item tem uma penca de inconvenientes irritantes (pelo menos seis), três ou quatro problemáticos e/ou um defeito grave. Exemplos: o item pertence a uma entidade paranormal poderosa que o quer de volta, causa dor constante a quem o usa (três níveis de vitalidade contundentes por turno de operação), irradia uma aura de corrupção e decadência, ou empurra o dono continuamente para atrocidades.

(8 pontos) Além de pelo menos seis inconvenientes irritantes e/ou cinco problemáticos, mais dois ou mais defeitos graves, o item também sai pela culatra se você falhar numa rolagem de Raciocínio + Esotérica (ou Raciocínio + Hipertecnologia, se o item usar tecnologia avançada) contra dificuldade 7. O Narrador é encorajado a ser criativo ao decidir como esse tiro pela culatra se manifesta; para sugestões, veja a tabela Mexendo com Maravilhas, Capítulo Dois, p. 141.

(10 pontos) Além do nível anterior de dificuldade, o Narrador basicamente ganha licença aberta para complicar sua vida de formas inesperadas, criativas e muitas vezes misteriosas. Exemplos: um culto sedento de sangue atrás do tesouro, uma entidade demoníaca aprisionada dentro do item, um vórtice interdimensional de flutuações de probabilidade e caprichos da física que se manifestam nas imediações do objeto, e assim por diante.

Esses defeitos, claro, devem se basear na natureza do item Azarado e na relação dele com o dono. Dito isso, não há razão para um robô não poder ser possuído por espíritos malignos, nem para um artefato primevo não poder ser um perigo tecnológico usando tecnologia desconhecida. Coisas mais estranhas que essas acontecem o tempo todo em Mage.]==],
				},
				["Kiss of Death"] = {
					pt = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, pág. 179


Kiss of Death


Se você drenar todo o sangue de um recipiente mortal minutos depois de o coração dele parar, o cadáver se ergue como zumbi (usando as estatísticas de zumbi da p. 164 de V20). Esses zumbis têm vontade própria, são hostis a você e não podem ser comandados sem algum meio feiticeiro ou necromântico de dirigi-los.]==],
				},
				["Lame"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 482


Lame


Suas pernas estão danificadas, o que o impede de correr ou andar com facilidade. Você é obrigado a andar com bengala ou possivelmente com órteses, e tem um manquejar pronunciado. Sua velocidade de caminhada é um quarto da de um humano normal, e correr é impossível.]==],
				},
				["Laughingstock"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 493


Laughingstock


De algum modo você atraiu o escárnio das Harpias locais, que fizeram de você o alvo favorito delas. Você sofre +2 de dificuldade em todas as rolagens Sociais no Elísio e +1 em qualquer outro lugar da cidade. Além disso, sofre +2 de dificuldade para usar Intimidação ou qualquer poder de Dominação sobre quem tiver ouvido as histórias que zombam de você. Este Defeito só pode ser adquirido por vampiros da Camarilla.]==],
				},
				["Lazy"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 482


Lazy


Você é simplesmente preguiçoso e evita qualquer coisa que exija esforço da sua parte. Preferindo deixar o trabalho duro para os outros, você fica à toa. Em qualquer ação que exija preparação, há uma boa chance de você não ter se preparado direito. As dificuldades de ações Físicas espontâneas (inclusive combate, a menos que faça parte de uma ofensiva planejada) aumentam em um.]==],
				},
				["Lifesaver"] = {
					pt = [==[Book of Secrets, pág. 53


Lifesaver


A vida, para você, é um dom e um milagre que vale a pena salvar. No seu entender, mesmo as pessoas mais desgraçadas merecem outra chance de redenção, e por isso você faz questão de salvar vidas e melhorar a sorte de quem (humano ou não) precisa de uma mão neste mundo. Mais que um simples "código contra matar", este Traço lhe dá um imperativo moral de resgatar vidas, e não apenas uma razão para não tirá-las. Em resumo, faz de você uma pessoa generosa e de coração grande, que acredita profundamente na santidade (use você esse termo religioso ou não) da vida. E isso, no Mundo das Trevas, é um fardo magnífico de carregar.]==],
				},
				["Light-Sensitive"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 495


Light-Sensitive


Você é ainda mais sensível à luz do sol que os outros vampiros. A luz solar causa o dobro do dano normal, e a luz da lua pode causar dano letal de forma parecida com a do sol, embora precise incidir diretamente sobre você. Até luzes fortes machucam seus olhos, exigindo o uso de óculos escuros. Seguidores de Set e linhagens aparentadas não podem adquirir este Defeito, pois já têm uma versão pior dele.]==],
				},
				["Lightweight"] = {
					pt = [==[Lore of the Bloodlines, pág. 60


Lightweight


Vergonhosamente, você não consegue ingerir o sangue de nenhuma criatura que não seja mortal, carniçal ou vampiro. Sempre que tentar beber de outra entidade, você é forçado a expulsar o conteúdo logo em seguida e não obtém sustento algum dele.]==],
				},
				["Loathsome Regnant"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 492


Loathsome Regnant


Você não está apenas preso pelo laço de sangue: está sob o jugo de um vampiro que o maltrata de forma medonha. Talvez você seja abusado ou humilhado em público; talvez seu mestre o obrigue a cometer atos inomináveis por ele. De todo modo, a existência sob o laço é um pesadelo sem fim, com o seu regente regendo a sinfonia da malícia. Vampiros da Sabá não podem adquirir este Defeito.]==],
				},
				["Locked Vidare"] = {
					pt = [==[Book of Secrets, pág. 85


Locked Vidare


Magos veem a Penumbra dos Outros Mundos por uma perspectiva metafísica chamada Vidare. A maioria consegue alterar essa perspectiva mudando o ponto de vista. Você, não. Para você, a Periferia fica "travada" numa única perspectiva: a clareza cintilante do Vidare Astral, a luminosidade primal do Vidare Spiritus ou a paisagem apodrecida do Vidare Mortem. Basicamente, sua perspectiva metafísica está congelada. É literalmente assim que você vê o mundo à sua volta, e essa visão nunca muda de verdade. (Para detalhes sobre os Vidare e as impressões que apresentam, veja Mage 20, pp. 82, 89, 94-95, 98-99 e 474.)

Além de moldar a forma como seu Narrador descreve os Vidare para você, e de guiar sua reação ao que percebe, este Defeito também influencia sua personalidade, seu senso de moda, seus paradigmas filosóficos e metafísicos, seu foco mágico e assim por diante. Afinal, quando alguém percebe as coisas de determinada maneira, essa perspectiva tende a tingir quase todos os aspectos da vida.]==],
				},
				["Loose Lips"] = {
					pt = [==[Ghouls & Revenants, pág. 131


Loose Lips


Carniçais muitas vezes têm acesso a uma enorme quantidade de informação sensível no trato noturno com seus domitores, e alguns não resistem ao impulso de revelar (ou vender) esses segredos. Em geral, carniçais e revenantes que não guardam segredo não vivem muito.

Ao adquirir o Defeito Boca Solta, você pode ser conhecido como fofoqueiro. Aliás, essa fraqueza pode ser a razão de um carniçal ter se tornado independente. É possível que o mestre dele tenha achado que negar-lhe alimentações pelo resto da sua vida miserável seria punição adequada, e talvez ainda o esteja vigiando.

Carniçais com este Defeito costumam não receber tarefas que envolvam segredos, de modo que sua utilidade para vampiros de alta patente é limitada. Por outro lado, eles são ferramentas perfeitas para espalhar informação falsa, o que muitas vezes é bem mais útil. Infelizmente, você pode não saber se está cuspindo fato ou ficção até que seja tarde demais.

Usado por: todos os carniçais e revenantes]==],
				},
				["Lord of the Flies"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 495


Lord of the Flies


Arautos zumbidores da putrefação rodopiam à sua volta em toda parte. A presença constante deles torna difícil sua interação social (+1 de dificuldade quando cabível) e quase impossível se aproximar de alguém sem ser notado ou se esconder direito. O zumbido das moscas inevitavelmente o entrega — todas as rolagens de Furtividade sofrem +2 de dificuldade.]==],
				},
				["Lord of the Night"] = {
					pt = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, pág. 179


Lord of the Night


Na sua presença as luzes se apagam, chamas pequenas se extinguem e as sombras se agarram a você ou se movem languidamente com uma não-vida surreal, tornando impossível você passar por qualquer coisa que não seja desumana. A sombra particular que você projeta é uma entidade maldosa com vontade própria. Ela ataca amigos e inimigos por igual, rasgando o cenário e rosnando para quem passa. Esses efeitos podem ser suprimidos por uma cena com o gasto de um ponto de Força de Vontade.]==],
				},
				["Lost Svadharma"] = {
					pt = [==[Lore of the Clans, pág. 183


Lost Svadharma


Você um dia conheceu seu svadharma mas, quando chegou a hora de cumpri-lo, falhou. Aquele destino passou por você, e talvez nunca haja outra chance de consertar. Os outros Ravnos conhecem a história e cobram de você esse fracasso. Você é desprezado, e sua confiança foi lançada na dúvida. Seu total de Força de Vontade é permanentemente reduzido em um, e você não pode gastar Força de Vontade em ações que envolvam diretamente outros Ravnos.]==],
				},
				["Lunacy"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 486


Lunacy


Você é afetado pelas fases da lua, o que aumenta suas chances de entrar em frenesi. Sob a lua crescente, as dificuldades para evitar o frenesi aumentam em um. Sob a lua meia ou gibosa, aumentam em dois. Quando a lua está cheia, aumentam em três.]==],
				},
				["Mage Blood"] = {
					pt = [==[Lore of the Clans, pág. 219


Mage Blood


Seu sangue está tão ligado à magia que você é incapaz de usar qualquer Disciplina que não seja a Taumaturgia (e, para Cainitas que não sejam Tremere, ela ainda é paga a preço de fora de Clã). Embora nenhum caminho ou ritual lhe seja vedado, você não pode ganhar pontos em nenhuma outra Disciplina.]==],
				},
				["Manchurian Candidate"] = {
					pt = [==[The Hunters Hunted II, pág. 132


Manchurian Candidate


Você é o pior tipo de agente duplo: o que não sabe que está comprometido. Algum poder desconhecido para você lhe deu uma tarefa, e você não consegue evitar cumpri-la. Seu controlador o programou para reagir a um sinal específico — pode ser uma palavra-gatilho, um padrão de luzes piscando ou uma imagem determinada. Ao encontrar o gatilho, você fará o que o seu mestre pediu. Depois, você se lembrará de tudo até o momento em que encontrou o sinal — o resto é um vazio. Tarefas comuns incluem espionar sua própria organização, destruir documentos sensíveis, assassinar um alvo nomeado junto com o gatilho ou roubar equipamento valioso.

Acerte com o Narrador um sinal e uma tarefa. Como alternativa, você pode deixar que o Narrador defina sozinho os detalhes do que você anda aprontando. Em algum momento ele descreverá seu gatilho, e você não terá conhecimento nenhum do que acontece entre aquele ponto e o momento em que você volta a si. O Narrador pode deixar o que acontece sob o gatilho como um mistério — ou fazer os outros personagens cruzarem com você enquanto está programado. Combine com ele como retratar sua personagem nesse estado de lavagem cerebral. A programação é forte o bastante para que nem poderes sobrenaturais consigam desviá-lo da tarefa. Social]==],
				},
				["Marked for Death"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 425


Marked for Death


A Corte de Sangue achou falhas em você e pôs um preço na sua cabeça. Você está marcado para morrer e, um a um, seus pares virão trazer essa morte. Você pode até ser mais que capaz de enfrentar seus iguais numa luta, mas não sabe quando nem onde eles atacarão. A paranoia purulenta arranha as bordas dos seus pensamentos; além de atacantes de capacidades variadas surgirem ao acaso, a critério do Narrador você também pode perder um dado nas rolagens Mentais por distração.]==],
				},
				["Masquerade Breaker"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 491


Masquerade Breaker


Nas suas primeiras noites como vampiro, você quebrou a Máscara sem querer — e foi visto fazendo isso. Outra pessoa acobertou seu erro, mas guarda esse favor sobre a sua cabeça. Agora você vive com medo de que a falha seja revelada. Enquanto isso, seu "salvador" tira proveito de você sem a menor piedade. Este Defeito só pode ser adquirido por vampiros de Seitas ou Clãs que respeitem a Máscara.]==],
				},
				["Mayfly Curse (10)"] = {
					pt = [==[Book of Secrets, pág. 42


Mayfly Curse (10)


Sua vida arde intensa e depressa. Talvez por biotecnologia, clonagem ou alguma outra herança ou modificação desumana, você envelhece muito mais rápido que os seres humanos normais. Isso significa que você atingiu a maturidade em tempo recorde, mas também traz uma decrepitude precoce. Quando se vive tão rápido, garoto, de um jeito ou de outro você morre jovem!

No nível de cinco pontos, sua personagem envelhece um ano a cada dois meses de tempo terreno (seis anos de idade por ano que passa). No nível de 10 pontos, ela envelhece um ano por semana (ou 52 anos de idade num único período de 12 meses). Uma personagem dessas faria bem em tomar cuidado com magos versados em Tempo: o feito Juventude ou Decadência Acelerada descrito em How Do You DO That? (pp. 111-112) tem efeitos horríveis sobre uma efêmera, que sofre de seis a 52 anos de envelhecimento para cada ano de tempo imposto a ela.

Conforme os anos se acumulam, outros Defeitos como Envelhecimento, Impedimento, Distraído e assim por diante podem se empilhar sobre a personagem. A magia da Esfera da Vida não anula este Defeito, que poderia ser interpretado como manifestação da forma Descrença do Paradoxo, a menos que o jogador compre a saída dele… e talvez nem então.]==],
				},
				["Mayfly Curse (5)"] = {
					pt = [==[Book of Secrets, pág. 42


Mayfly Curse (5)


Sua vida arde intensa e depressa. Talvez por biotecnologia, clonagem ou alguma outra herança ou modificação desumana, você envelhece muito mais rápido que os seres humanos normais. Isso significa que você atingiu a maturidade em tempo recorde, mas também traz uma decrepitude precoce. Quando se vive tão rápido, garoto, de um jeito ou de outro você morre jovem!

No nível de cinco pontos, sua personagem envelhece um ano a cada dois meses de tempo terreno (seis anos de idade por ano que passa). No nível de 10 pontos, ela envelhece um ano por semana (ou 52 anos de idade num único período de 12 meses). Uma personagem dessas faria bem em tomar cuidado com magos versados em Tempo: o feito Juventude ou Decadência Acelerada descrito em How Do You DO That? (pp. 111-112) tem efeitos horríveis sobre uma efêmera, que sofre de seis a 52 anos de envelhecimento para cada ano de tempo imposto a ela.

Conforme os anos se acumulam, outros Defeitos como Envelhecimento, Impedimento, Distraído e assim por diante podem se empilhar sobre a personagem. A magia da Esfera da Vida não anula este Defeito, que poderia ser interpretado como manifestação da forma Descrença do Paradoxo, a menos que o jogador compre a saída dele… e talvez nem então.]==],
				},
				["Member of the Pack"] = {
					pt = [==[Lore of the Clans, pág. 87


Member of the Pack


Você só consegue convocar, falar com e comandar um tipo específico de animal — corvos, ratos e assim por diante — com o Animalismo. Seu Narrador é quem melhor julga quais tipos de animal cabem neste Defeito, mas a escolha deve ser bastante limitante. Outros animais simplesmente não respondem ao seu uso de Animalismo.]==],
				},
				["Mental Lock"] = {
					pt = [==[Book of Secrets, pág. 47


Mental Lock


Em algum ponto entre o impulso e a ação, as coisas emperram dentro da sua cabeça. Pensamentos ou imagens ficam presos em laços mentais, e de vez em quando você se vê tropeçando nas palavras, travado em padrões de fala ou repetindo atividades aparentemente incontroláveis (bater as mãos, sacudir a cabeça, esfregar os pulsos e assim por diante) que, na maioria das circunstâncias, seriam fáceis de interromper ou controlar. Às vezes chamados de perseveração ou estereotipia (veja a Qualidade Hiperfoco), esses tiques mentais costumam se manifestar a partir de lesão cerebral, trauma emocional, estresse intenso e/ou autismo e outras condições de processamento sensorial. Convencional e incorretamente chamadas de "manias nervosas", essas esquisitices podem ser tentativas de controlar um ambiente aparentemente caótico, dando ao seu cérebro algo que parece estar sob controle. O problema é que você basicamente precisa se sacudir para fora do padrão travado, se concentrar numa sensação nova para quebrar o laço, invocar uma espécie de palavra ou ato "ritualizado" que dispare essa quebra, ou usar algum outro método para se libertar da trava mental. Até lá, você pode se ver gaguejando mesmo sem ter distúrbio de fala, se sentir "congelado" em palavras ou pensamentos que não consegue articular, travar em ruminações quase obsessivas sobre frases sem sentido ou pensamentos perigosos, ficar preso fazendo a mesma coisa repetidamente ou, de outro modo, acabar preso num ciclo interno de retroalimentação.

Em termos de sistema, o Narrador vai de vez em quando inserir esquisitices pequenas mas irritantes na capacidade de fala da sua personagem, sugerir pequenas ações repetitivas para ela e, de modo geral, atrapalhar sua capacidade de ir além de um único pensamento incômodo. Para quebrar essas travas mentais, você precisará rolar a Força de Vontade da personagem contra dificuldade 7, gastar um ponto temporário de Força de Vontade ou então ficar parado, "travado" no meio de um pensamento ou ato, até conseguir romper o bloqueio pela força de vontade ou (após cinco turnos) pela simples passagem do tempo.]==],
				},
				["Methuselah's Thirst"] = {
					pt = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, pág. 177


Methuselah's Thirst


Você não consegue mais se sustentar com sangue mortal e precisa se alimentar do sangue de Cainitas ou de outras criaturas sobrenaturais de reservas potentes, como lupinos ou fadas.]==],
				},
				["Mistaken Identity"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 490


Mistaken Identity


Você se parece com as descrições de outro Cainita, o que gera casos de identidade trocada. Isso pode provocar inúmeras situações constrangedoras ou até perigosas, especialmente se seu "gêmeo" tiver uma reputação terrível ou for procurado por algum crime.]==],
				},
				["Monstrous"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 482


Monstrous


Sua forma física foi retorcida durante o Abraço e agora reflete a Besta que ruge dentro de você. Personagens com este Defeito parecem monstros selvagens e têm Aparência zero. Nosferatu e outras linhagens cujas fraquezas já as fazem começar com Aparência zero não podem adquirir este Defeito.]==],
				},
				["Mortal Flashbacks"] = {
					pt = [==[Lore of the Bloodlines, pág. 91


Mortal Flashbacks


Seu corpo se lembra da sua morte. Toda noite, ao despertar, você recorda vividamente a dor do ferimento que o matou. A ferida se reabre durante a noite e se fecha pouco antes de você se erguer. Esse lembrete traumático da sua mortalidade começa sua noite do pior jeito. Você perde um ponto de Força de Vontade a cada noite ao despertar, pelo trauma de morrer de novo.]==],
				},
				["Mr. Red Tape"] = {
					pt = [==[Book of Secrets, pág. 67


Mr. Red Tape


A burocracia odeia você. Qualquer complicação oficial que possa dar errado vai dar errado se você for quem está lidando com as autoridades. Basicamente o oposto da Qualidade Mestre da Burocracia (p. 58), este Defeito soma +2 à dificuldade de qualquer rolagem que você faça ao tentar resolver algo por meio de um sistema estabelecido, e joga erros idiotas e atrasos no meio do caminho sempre que você precisa lidar com qualquer tipo de burocracia.]==],
				},
				["Multiple Curses"] = {
					pt = [==[Lore of the Clans, pág. 26


Multiple Curses


Além da maldição normal imposta pela sua casta ou seita, você sofre mais uma, associada ao Clã Assamita. O mais provável é que você seja um raro vizir ou feiticeiro dentro da Sabá que sofre da Maldição Baali além da maldição normal da sua casta, mas, a critério do Narrador, outras combinações são possíveis.]==],
				},
				["Mute"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 483


Mute


Você não consegue falar. Pode se comunicar com o Narrador e descrever suas ações, mas não pode conversar com personagens de jogadores ou do Narrador, a menos que todos os envolvidos comprem uma língua de sinais em comum (pela Qualidade Idioma) ou que você escreva o que quer dizer.]==],
				},
				["Nameless"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 425


Nameless


Você não existe. Certamente ainda caminha sobre a terra, e seus amigos e parentes ainda podem vê-lo e tocá-lo, mas todos os registros da sua existência foram destruídos. Nem a sua prole vampírica pode reivindicar o seu nome. Até onde qualquer um possa provar, você nunca existiu. Se adquirir este Defeito, você não pode adquirir nenhuma Qualidade Social que conceda benefícios baseados em reputação. A critério do Narrador, você também pode ficar impedido de adquirir Antecedentes que exijam presença social. Quem ou o que você irritou tanto a ponto de apagarem sua existência da face da terra?]==],
				},
				["Narc"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 492


Narc


Você é conhecido como delator, um informante firmemente enfiado no bolso dos vampiros no comando. Aqueles sobre quem você ainda poderia informar o detestam por isso, e lhe passam informação falsa quando podem, para desacreditá-lo. Se tiverem oportunidade, podem lhe fazer mal. De todo modo, sua fama de dedo-duro o precede, o que lhe dá +1 de dificuldade em todas as rolagens Sociais contra quem não concorda com a sua política.]==],
				},
				["New Arrival"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 490


New Arrival


Você acabou de chegar à sua nova cidade e não conhece ninguém no lugar. As facções existentes podem tentar recrutá-lo ou eliminá-lo, enquanto os vampiros em posição de autoridade o examinam e o medem. Enquanto isso, sua ignorância dos acontecimentos atuais, da história e da política da cidade (sem falar nas esquisitices de personalidade dos vampiros que já estão lá) pode fazê-lo cometer um erro grave.]==],
				},
				["New Kid"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 490


New Kid


Você é o mais recente Abraçado da cidade, ou ainda não provou seu valor à Seita, e todo mundo sabe disso. Isso o coloca automaticamente na base da hierarquia social. Outros neonatos aproveitam toda oportunidade para demonstrar sua inferioridade, ou matilhas rivais testam constantemente sua dignidade perante a Sabá. Mesmo que outra pessoa entre para as fileiras dos mortos-vivos, você continua sendo visto como meio abestalhado pelos seus pares — distinção que pode ter consequências perigosas se as balas começarem a voar. Todas as rolagens sociais sofrem +1 de dificuldade quando você lida com outros neonatos. (Anciliae e anciões o jogam no mesmo balaio dos demais neonatos, sob o desdém geral que têm por todos.)]==],
				},
				["Nightmares"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 485


Nightmares


Você tem pesadelos horrendos toda vez que dorme, e a lembrança deles o assombra nas horas em que está acordado. Ao despertar, você precisa fazer uma rolagem de Força de Vontade (dificuldade 7) ou perde um dado em todas as ações daquela noite. Uma falha crítica indica que, mesmo acordado, você ainda acredita estar preso num pesadelo.]==],
				},
				["Notoriety"] = {
					pt = [==[Book of Secrets, pág. 65


Notoriety


Graças a este inverso da Qualidade Prestígio, você carrega má fama entre seus colegas magos. Em termos de sistema, este Defeito soma +2 às dificuldades de todas as rolagens sociais dentro da sua facção (Tradições, Ofícios, Tecnocracia etc.) e predispõe praticamente todo mundo, fora seus amigos mais próximos, a pensar o pior de você. Boatos seguem seus passos, e sussurros precedem sua chegada. Sejam as histórias verdadeiras ou não, você foi ligado a alguma desonra e será evitado e provavelmente punido de acordo, se é que já não foi. (Veja o Defeito Sobrenatural Marcado a Ferro, p. 89, para uma punição possível, ou como alternativa a este Defeito para um personagem mago das Tradições.) Você pode até conseguir se livrar dessa má fama algum dia, mas a estrada até lá será bem dura.]==],
				},
				["Oathbreaker"] = {
					pt = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, pág. 178


Oathbreaker


Um dia você jurou lealdade a um senhor ou a uma organização, ou firmou um contrato vinculante. Você quebrou essa promessa e todo mundo sabe. Agora é quase impossível conquistar a confiança dos outros. A dificuldade das rolagens Sociais para convencer alguém de que você é confiável aumenta em três, e até os membros da sua coterie podem ter ressalvas quanto a você.]==],
				},
				["Oathbreaker (Ravnos)"] = {
					pt = [==[Lore of the Clans, pág. 182


Oathbreaker (Ravnos)


Fazer um juramento amarra o svadharma de uma pessoa ao de outra, ligando os dois espíritos até que o juramento possa ser cumprido. Por causa disso, uma Ravnos nunca quebra a palavra dada de boa-fé, desde que tenha sido dada com a cerimônia adequada. Se a Ravnos cospe na própria palma e sela a palavra com um aperto de mão, o juramento não pode ser quebrado sem prejudicar o svadharma da vampira (ou assim manda a superstição Ravnos).

A quebra-juramentos perderá o rumo, caindo no vício e na inutilidade, até que o juramento rompido possa ser redimido. Quem olhar para a sua aura verá um talho vermelho e doentio indicando o juramento quebrado. Você não pode gastar Força de Vontade para ignorar seu vício Ravnos, e não ganha Força de Vontade ao cumprir sua Natureza.]==],
				},
				["Obsession"] = {
					pt = [==[Book of Secrets, pág. 49


Obsession


Um interesse absorvente da sua parte tende a ofuscar aquilo que, na sua cabeça, passa por bom senso. Se você ama Star Wars, então viu todos os filmes inúmeras vezes, tem pilhas de bugigangas e gasta um tempo desmedido discutindo minúcias da saga. Sua obsessão é o Tarô? Então você tem dezenas (se não centenas) de baralhos, pesquisa cada elemento possível de significado nas cartas e enlouquece seus amigos com ofertas constantes de leituras e conselhos. Você não pode ter só um ou dois gatos – você é a Pessoa Louca dos Gatos do bairro, que gasta meio salário em ração, areia e veterinário. Essa obsessão provavelmente não vai matá-lo (a menos que você seja doido o bastante para se obcecar por metamorfos ou temas igualmente fatais), mas consome uma quantidade enorme de tempo, atenção e dinheiro. Diante da oportunidade de perseguir sua obsessão por caminhos ainda não explorados, ou quando ela atrapalha coisas importantes como relacionamentos, trabalho ou ambos, você pode precisar de uma rolagem de Força de Vontade (dificuldade 6) para conter o impulso. E, se a obsessão envolver algo compulsivo por natureza – jogatina, por exemplo –, a rolagem pode ter dificuldade 8 ou mais antes que você consiga se livrar da compulsão e focar em outra coisa.]==],
				},
				["Obvious Predator"] = {
					pt = [==[Lore of the Clans, pág. 48


Obvious Predator


Sua raiva Brujah inata está sempre borbulhando sob a superfície, por mais que você tente projetar uma imagem de calma. Os mortais o acham intrinsecamente ameaçador e temem por instinto a violência que você promete desencadear.

Sistema: a dificuldade de todas as rolagens Sociais feitas contra mortais, exceto as de Intimidação, aumenta em 2.]==],
				},
				["OCPD"] = {
					pt = [==[Book of Secrets, pág. 53


OCPD


Magos tendem a ser meio obsessivos por natureza. Você, porém, se sente compelido a seguir rituais pessoais rigorosos, manter um senso obsessivo de ordem, trabalhar até a exaustão (e além), organizar cada elemento possível da sua vida e do seu espaço, adotar comportamentos compulsivos sem perceber que os está adotando e, de resto, perder a noção do tempo, das coisas e das pessoas que não caiam na órbita do seu transtorno de personalidade obsessivo-compulsiva.

Defeito especialmente comum entre tecnomantes, cientistas, magos ritualistas, devotos religiosos, autistas, militares, artistas, executivos e outros cujas filosofias e ocupações exigem atenção contínua, o TPOC também pode resultar de várias formas de trauma psíquico, lesão cerebral, epifanias espirituais, perfeccionismo cultural ou profissional e dedicação metafísica. Via de regra, os comportamentos de uma pessoa ficam mais compulsivos sob estresse. Afinal, quando parece que o mundo está saindo do controle, fica ainda mais importante estabelecer controle sobre o que ainda se pode controlar.

Ao escolher este Defeito, você precisará definir quais compulsões sua personagem tem e quais gatilhos as tornam mais evidentes. Em termos de sistema, você terá de fazer rolagens de Força de Vontade com frequência para se livrar da necessidade de organizar e se obcecar pelo objeto da sua atenção. A dificuldade, claro, depende da situação e do nível de estresse da personagem naquele momento; quanto mais duras as circunstâncias, mais obsessivas as compulsões.]==],
				},
				["Odd Gait"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 421


Odd Gait


Mover-se depressa não é fácil para você; talvez andar doa, talvez você simplesmente nunca tenha pressa. Seja qual for a razão, você se desloca à metade da sua velocidade normal de movimento. Personagens do Narrador também podem passar a reconhecê-lo pelo seu andar incomum.]==],
				},
				["Offensive to Animals"] = {
					pt = [==[Ghouls & Revenants, pág. 138


Offensive to Animals


Carniçais e revenantes que adquirem o Defeito Ofensivo aos Animais terão dificuldade nos encontros com bichos. Cães, lobos, morcegos, aves e outras criaturas se comportam de forma hostil perto da personagem, e provavelmente a atacarão quanto mais ela se aproximar. Muito parecido com o Defeito vampírico de mesmo nome, um carniçal ou revenante Ofensivo aos Animais pode achar difícil circular livremente por certas áreas.

Os animais latem, uivam, ganem e fazem barulho quando a personagem se aproxima. Podem não atacar o carniçal diretamente, a menos que provocados, mas ficarão claramente agressivos ou, como alternativa, fugirão do local.

Este Defeito não é recomendado para carniçais ou revenantes que pretendam usar a Disciplina Animalismo ou que convivam com personagens que a usem.

Usado por: todos os carniçais e revenantes]==],
				},
				["Offline (1)"] = {
					pt = [==[Book of Secrets, pág. 63


Offline (1)


Você odeia a droga da internet. Para você, ela é uma perda de tempo complicada. Você detesta redes sociais, não tem site, se recusa a usar o Twitter e nem sabe (nem quer saber) direito como buscar coisas no Google. Quem quiser falar com você que escreva uma carta, use o telefone ou simplesmente o deixe em paz! (Malditos moleques, saiam do meu gramado digital…)

Embora este Defeito valha apenas um ponto em culturas onde a internet é uma indulgência ocasional (e muitas vezes privilegiada), ele é um Defeito de três pontos em culturas onde o acesso e a participação on-line são elementos importantes da vida social da maioria. Essas divisões culturais estão mais ligadas a recortes geracionais e econômicos que a recortes étnicos ou geográficos. Uma nova-iorquina pobre, idosa ou simplesmente à moda antiga pode não ligar muito para o acesso à rede, desde que consiga manter contato com amigos e família; já um universitário no Rio ficaria em desvantagem bem significativa se escolhesse evitar a internet. E sim – magos do século XXI também usam a internet, mesmo que não visitem a Teia Digital. Presença on-line não é mais coisa só de Adepto Virtual!]==],
				},
				["Offline (3)"] = {
					pt = [==[Book of Secrets, pág. 63


Offline (3)


Você odeia a droga da internet. Para você, ela é uma perda de tempo complicada. Você detesta redes sociais, não tem site, se recusa a usar o Twitter e nem sabe (nem quer saber) direito como buscar coisas no Google. Quem quiser falar com você que escreva uma carta, use o telefone ou simplesmente o deixe em paz! (Malditos moleques, saiam do meu gramado digital…)

Embora este Defeito valha apenas um ponto em culturas onde a internet é uma indulgência ocasional (e muitas vezes privilegiada), ele é um Defeito de três pontos em culturas onde o acesso e a participação on-line são elementos importantes da vida social da maioria. Essas divisões culturais estão mais ligadas a recortes geracionais e econômicos que a recortes étnicos ou geográficos. Uma nova-iorquina pobre, idosa ou simplesmente à moda antiga pode não ligar muito para o acesso à rede, desde que consiga manter contato com amigos e família; já um universitário no Rio ficaria em desvantagem bem significativa se escolhesse evitar a internet. E sim – magos do século XXI também usam a internet, mesmo que não visitem a Teia Digital. Presença on-line não é mais coisa só de Adepto Virtual!]==],
				},
				["Old Flame"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 491


Old Flame


Alguém por quem você já teve profundo carinho está agora do lado do inimigo. Ele ainda tenta apelar à sua compaixão "pelos velhos tempos" enquanto trabalha contra você. A menos que você tenha sucesso numa rolagem resistida de Manipulação + Expressão contra seu antigo amigo, você não consegue agir contra ele, exceto se a situação virar risco de vida.]==],
				},
				["One Eye"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 481


One Eye


Você tem apenas um olho — qual deles falta fica a seu critério. As dificuldades de todas as rolagens de Percepção que envolvam visão aumentam em dois, e as dificuldades de todas as rolagens que exijam noção de profundidade aumentam em um (isso inclui combate à distância).]==],
				},
				["Open Wound (2)"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 482


Open Wound (2)


Você tem um ou mais ferimentos que se recusam a fechar e que sangram sem parar. Esse vazamento lento lhe custa um ponto de sangue extra por noite (descontado pouco antes do amanhecer), além de atrair atenção. Se o ferimento for visível, você sofre +1 de dificuldade em todas as rolagens Sociais. Por dois pontos, o Defeito é apenas feio e tem o efeito básico descrito acima; por quatro pontos, a ferida que verte é grave ou desfigurante e inclui os efeitos do Defeito Ferimento Permanente (abaixo).]==],
				},
				["Open Wound (4)"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 482


Open Wound (4)


Você tem um ou mais ferimentos que se recusam a fechar e que sangram sem parar. Esse vazamento lento lhe custa um ponto de sangue extra por noite (descontado pouco antes do amanhecer), além de atrair atenção. Se o ferimento for visível, você sofre +1 de dificuldade em todas as rolagens Sociais. Por dois pontos, o Defeito é apenas feio e tem o efeito básico descrito acima; por quatro pontos, a ferida que verte é grave ou desfigurante e inclui os efeitos do Defeito Ferimento Permanente (abaixo).]==],
				},
				["Out of Phase"] = {
					pt = [==[Lore of the Bloodlines, pág. 99


Out of Phase


A personagem tem consciência demais do tempo e das possibilidades ao redor. As pessoas parecem estar sempre em lugares ligeiramente diferentes, e a fala frequentemente ecoa nos ouvidos dela. Ela enxerga camadas de linhas temporais alternativas com detalhe demais. Qualquer rolagem de percepção que ela faça sofre +2 de dificuldade, enquanto tenta enxergar para além do irreal.]==],
				},
				["Outcast"] = {
					pt = [==[Lore of the Clans, pág. 26


Outcast


Você rejeitou o ethos da casta na qual foi Abraçado. Talvez seja um dos poucos vizires ou feiticeiros a apoiar a Teia de Facas ou a seguir o Caminho do Sangue. Talvez seja um guerreiro com pouco estômago para o combate, que prefere ser diplomata ou estudioso do oculto. Talvez tenha dado algum espetáculo público que revelou seu desprezo pelos companheiros de casta. Seu senhor agora o rejeita, assim como os demais membros da sua casta. A dificuldade de todas as rolagens Sociais contra membros da sua casta é +2.]==],
				},
				["Outsider"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 423


Outsider


Esta não é sua terra natal; esta não é sua língua materna. Você não é daqui. Tudo é estranho e diferente, dos costumes à comida. Você tem dificuldade com o idioma local (embora consiga se virar comprando a Qualidade Língua Franca), e a dificuldade das rolagens Sociais cabíveis aumenta em um.]==],
				},
				["Outspoken Heretic"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 425


Outspoken Heretic


Você defende uma crença considerada herética por um grande poder religioso, como a Igreja Católica. Ao contrário de outros que praticam suas heresias em segredo, você é aberto quanto às suas convicções. Precisa encarar constantemente falsas acusações, o assédio de quem se julga verdadeiro crente e a recusa de hospitalidade por parte de estranhos fervorosos ou de quem teme a autoridade religiosa. A critério do Narrador, isso pode impor um aumento de até 3 na dificuldade das rolagens Sociais cabíveis.]==],
				},
				["Overconfident"] = {
					pt = [==[Book of Secrets, pág. 48


Overconfident


Você é o melhor que existe naquilo que faz. Se os outros discordam, o problema é deles, não seu! Nada está fora do seu alcance, e por isso você quase nunca recua diante de um desafio, por mais absurdamente superado que pareça estar no momento. Se as coisas derem errado, claro, você sempre pode culpar outra pessoa. Afinal, a culpa claramente não é sua!]==],
				},
				["Overextended"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 492


Overextended


Você meteu o dedo em pratos demais, e as pessoas começaram a notar. Você tem carniçais demais, lacaios demais ou influência demais, o que significa que muita gente tem interesse direto em podar suas operações. Esses inimigos aproveitam toda oportunidade para reduzir seu poder e sua influência e, se para isso for preciso mentir, trapacear ou matar, que seja. Além disso, eles bloqueiam toda tentativa sua de avançar sobre novas áreas de controle. Você está encurralado, e o cerco está se fechando.]==],
				},
				["Overstimulated"] = {
					pt = [==[Lore of the Clans, pág. 142


Overstimulated


Malkavianos notam coisas que muitos outros não notam. Isso significa manter olhos e ouvidos abertos por muito mais tempo que qualquer um. E isso faz de você alguém que se distrai facilmente ao tentar se concentrar. Sofra penalidade de +2 em todas as rolagens que envolvam Percepção.]==],
				},
				["Pacifist"] = {
					pt = [==[M20 Sorcerer, pág. 107


Pacifist


Você escolheu não causar dano intencional a ninguém, seja por restrição religiosa, seja por decisão moral. Pode se defender com magia, e talvez tenha até se especializado nisso para esse fim. Ao adquirir este Defeito, esteja preparado para jogar com essas restrições de forma sincera.]==],
				},
				["Paper Trail"] = {
					pt = [==[Lore of the Clans, pág. 142


Paper Trail


Você passou um tempo em instituições do Estado, como prisões ou manicômios, provavelmente antes do Abraço. A maioria das pessoas tem algum tipo de registro com data de nascimento e outros dados. Essa informação é difícil de eliminar e pode pôr a Máscara em risco. Inimigos com a influência certa podem rastrear esses dados e usá-los contra você. Eles podem levar a alvos vulneráveis ou dar aos caçadores a pista de onde fica o seu refúgio.]==],
				},
				["Paradise Lost"] = {
					pt = [==[The Hunters Hunted II, pág. 125


Paradise Lost


Você um dia teve a Fé Verdadeira, aquela capaz de iluminar a noite. Ela se apagou. Isso não é a simples perda de uma vantagem, é uma ferida escancarada na alma. Você sabe como era ser visto à luz do divino, mas agora tropeça fora do olhar de Deus e se afoga na penumbra fria e cadavérica das dúvidas, um rio sem fim à vista.

Sempre que for confrontado com essa perda (segurar um símbolo sagrado, ser chamado a realizar um milagre, entrar numa igreja etc.), faça uma rolagem de Força de Vontade (dificuldade 7) ou perca um dado em todas as ações pelo resto da cena, enquanto a tristeza o domina. Uma falha crítica consome um ponto de Força de Vontade e o abre ao desespero. Ceder a um vício (álcool, drogas, pornografia etc.) pode repor os pontos de Força de Vontade perdidos assim.

Este Defeito pode ser adquirido no meio da crônica, com a perda da Fé Verdadeira, ou escolhido na criação do personagem como parte de uma história trágica, possivelmente iniciando um enredo de redenção e fé recuperada.]==],
				},
				["Paranoid"] = {
					pt = [==[The Hunters Hunted II, pág. 132


Paranoid


Anos demais no ramo da inteligência fizeram você saber que só é paranoia se eles não estiverem realmente atrás de você. Você desconfia de tudo e de todos — pediria reforços, mas como ter certeza de que eles também não estão no esquema? Você repara em detalhes inofensivos, e cada um deles é mais uma prova da conspiração contra você. Some um à dificuldade de todas as rolagens de interação social.]==],
				},
				["Paranormal Prohibition or Imperative (2)"] = {
					pt = [==[Book of Secrets, pág. 83


Paranormal Prohibition or Imperative (2)


Também conhecido como Geasa e Proibição ou Imperativo Mágico, este Defeito representa algo que você precisa fazer, ou está proibido de fazer, sob pena de consequências terríveis. Em geral, esse imperativo vem de um juramento que você fez, de uma maldição que lhe foi imposta ou de um legado que segue a linhagem da sua família. Rancores feéricos, pactos infernais, heranças divinas, profecias antigas, caprichos forteanos da física… qualquer um deles pode lhe impor esse fardo. Enquanto você não cruzar a linha, deve ficar tudo bem – e você pode até possuir alguma bênção (uma Qualidade ou um Antecedente) ligada a este Defeito. Ah, mas a vida tem o dom de nos empurrar a fazer o que não queremos, e isso vale ainda mais para quem carrega uma maldição ou um geas sobre a cabeça!

O valor deste Defeito se baseia nas suas chances de violar a proibição e nas consequências que ocorrem quando isso acontece:

(1 ponto) Você só quebra a proibição numa circunstância facilmente evitável (nunca matar um gato, ir a Londres ou transar com alguém casado), ou acha fácil cumprir seu imperativo (raspar todo o cabelo, sair de casa todos os dias ou vestir roupas azuis).

(2 pontos) Sua proibição é fácil de quebrar (nunca mentir, sair da sua cidade natal ou transar com alguém), ou seu imperativo é difícil de cumprir (cobrir sempre a cabeça, caminhar ao menos cinco quilômetros por dia ou andar descalço o tempo todo).

(3 pontos) É muito difícil não quebrar sua proibição (nunca falar, ter uma casa própria ou se apaixonar ou desejar alguém), ou honrar seu imperativo (vendar os olhos todos os dias mesmo enxergando, ir a pé a todos os lugares ou permanecer nu o tempo todo).

(+1 ponto) Consequências inconvenientes – você falha criticamente nas três rolagens seguintes, sofre uma enxaqueca, desenvolve uma erupção na pele por vários dias etc.

(+2 pontos) Consequências irritantes – você perde a voz por um dia, perde um dado de todas as paradas por uma semana por causa de dor constante, soma +2 a todas as rolagens sociais com membros da sua facção até conseguir expiar a quebra do juramento e assim por diante.

(+3 pontos) Consequências dolorosas – até conseguir expiar, você fica cego ou mudo, perde um ponto de um Atributo, perde um Aliado, Mentor ou Familiar, adquire o Defeito Quebra-Juramentos (abaixo) ou sofre destino igualmente terrível.

(+4 pontos) Consequências devastadoras – até expiar, seu Avatar o abandona, você perde um total de três pontos entre vários Atributos, adquire os Defeitos Quebra-Juramentos, Perturbado ou ambos, ou suporta punição semelhante.

(+5 pontos) Consequências fatais – ou você vai morrer em breve, ou será arrastado para um Reino de punição em Outro Mundo, ou as duas coisas. A expiação, se é que existe, será duríssima, então NÃO quebre este juramento nem abandone este imperativo!

Este Defeito combina muito bem com diversos Antecedentes (Familiar, Lenda, Vida Passada, Totem, Maravilha e potencialmente outros, a critério do Narrador) e Qualidades (praticamente qualquer uma, a depender de como você define a origem dela). Embora isso não reduza o custo do Traço (apesar da descrição deste Defeito em Mage Revised, que usava um sistema de regras complexo e potencialmente abusável, inexistente nos outros jogos do Mundo das Trevas), uma Proibição/Imperativo pode representar votos, obrigações e/ou legados associados ao Traço benéfico. Se, por exemplo, Riordan Manseragh tivesse feito um juramento místico para conquistar seu familiar espírito-tigre, esse juramento representaria um Imperativo Paranormal, com consequências dolorosas (a perda do Antecedente Familiar) caso ele quebre a promessa.

Sua Proibição/Imperativo precisa estar amarrada à história da sua personagem, e provavelmente tem ligação com os três elementos do foco mágico dela (paradigma, prática e instrumentos). As condições precisam ser algo que possa concebivelmente representar um obstáculo (nada de proibições, por exemplo, de transar com Voormas, nem de imperativos de levantar da cama de manhã), e seu Narrador, claro, fará questão de jogar esses obstáculos no seu caminho em vários momentos da crônica. Dito isso, também pedimos aos Narradores que não abusem deste Defeito, nem o apliquem de forma desproporcional aos pontos que ele vale.

Embora seja bastante incomum, um tecnomante também pode ter um pacto ou proibição metafísica. Ela pode, por exemplo, precisar trabalhar num Mac, usar apenas tecnologia a vapor ou inventar toda a própria tecnologia para não sofrer algum mal-estar paranormal. Assim, este Defeito nem sempre é "místico" por natureza, ainda que a linha que separa misticismo de fenômeno paranormal seja mais questão de semântica que de princípios metafísicos.]==],
				},
				["Paranormal Prohibition or Imperative (3)"] = {
					pt = [==[Book of Secrets, pág. 83


Paranormal Prohibition or Imperative (3)


Também conhecido como Geasa e Proibição ou Imperativo Mágico, este Defeito representa algo que você precisa fazer, ou está proibido de fazer, sob pena de consequências terríveis. Em geral, esse imperativo vem de um juramento que você fez, de uma maldição que lhe foi imposta ou de um legado que segue a linhagem da sua família. Rancores feéricos, pactos infernais, heranças divinas, profecias antigas, caprichos forteanos da física… qualquer um deles pode lhe impor esse fardo. Enquanto você não cruzar a linha, deve ficar tudo bem – e você pode até possuir alguma bênção (uma Qualidade ou um Antecedente) ligada a este Defeito. Ah, mas a vida tem o dom de nos empurrar a fazer o que não queremos, e isso vale ainda mais para quem carrega uma maldição ou um geas sobre a cabeça!

O valor deste Defeito se baseia nas suas chances de violar a proibição e nas consequências que ocorrem quando isso acontece:

(1 ponto) Você só quebra a proibição numa circunstância facilmente evitável (nunca matar um gato, ir a Londres ou transar com alguém casado), ou acha fácil cumprir seu imperativo (raspar todo o cabelo, sair de casa todos os dias ou vestir roupas azuis).

(2 pontos) Sua proibição é fácil de quebrar (nunca mentir, sair da sua cidade natal ou transar com alguém), ou seu imperativo é difícil de cumprir (cobrir sempre a cabeça, caminhar ao menos cinco quilômetros por dia ou andar descalço o tempo todo).

(3 pontos) É muito difícil não quebrar sua proibição (nunca falar, ter uma casa própria ou se apaixonar ou desejar alguém), ou honrar seu imperativo (vendar os olhos todos os dias mesmo enxergando, ir a pé a todos os lugares ou permanecer nu o tempo todo).

(+1 ponto) Consequências inconvenientes – você falha criticamente nas três rolagens seguintes, sofre uma enxaqueca, desenvolve uma erupção na pele por vários dias etc.

(+2 pontos) Consequências irritantes – você perde a voz por um dia, perde um dado de todas as paradas por uma semana por causa de dor constante, soma +2 a todas as rolagens sociais com membros da sua facção até conseguir expiar a quebra do juramento e assim por diante.

(+3 pontos) Consequências dolorosas – até conseguir expiar, você fica cego ou mudo, perde um ponto de um Atributo, perde um Aliado, Mentor ou Familiar, adquire o Defeito Quebra-Juramentos (abaixo) ou sofre destino igualmente terrível.

(+4 pontos) Consequências devastadoras – até expiar, seu Avatar o abandona, você perde um total de três pontos entre vários Atributos, adquire os Defeitos Quebra-Juramentos, Perturbado ou ambos, ou suporta punição semelhante.

(+5 pontos) Consequências fatais – ou você vai morrer em breve, ou será arrastado para um Reino de punição em Outro Mundo, ou as duas coisas. A expiação, se é que existe, será duríssima, então NÃO quebre este juramento nem abandone este imperativo!

Este Defeito combina muito bem com diversos Antecedentes (Familiar, Lenda, Vida Passada, Totem, Maravilha e potencialmente outros, a critério do Narrador) e Qualidades (praticamente qualquer uma, a depender de como você define a origem dela). Embora isso não reduza o custo do Traço (apesar da descrição deste Defeito em Mage Revised, que usava um sistema de regras complexo e potencialmente abusável, inexistente nos outros jogos do Mundo das Trevas), uma Proibição/Imperativo pode representar votos, obrigações e/ou legados associados ao Traço benéfico. Se, por exemplo, Riordan Manseragh tivesse feito um juramento místico para conquistar seu familiar espírito-tigre, esse juramento representaria um Imperativo Paranormal, com consequências dolorosas (a perda do Antecedente Familiar) caso ele quebre a promessa.

Sua Proibição/Imperativo precisa estar amarrada à história da sua personagem, e provavelmente tem ligação com os três elementos do foco mágico dela (paradigma, prática e instrumentos). As condições precisam ser algo que possa concebivelmente representar um obstáculo (nada de proibições, por exemplo, de transar com Voormas, nem de imperativos de levantar da cama de manhã), e seu Narrador, claro, fará questão de jogar esses obstáculos no seu caminho em vários momentos da crônica. Dito isso, também pedimos aos Narradores que não abusem deste Defeito, nem o apliquem de forma desproporcional aos pontos que ele vale.

Embora seja bastante incomum, um tecnomante também pode ter um pacto ou proibição metafísica. Ela pode, por exemplo, precisar trabalhar num Mac, usar apenas tecnologia a vapor ou inventar toda a própria tecnologia para não sofrer algum mal-estar paranormal. Assim, este Defeito nem sempre é "místico" por natureza, ainda que a linha que separa misticismo de fenômeno paranormal seja mais questão de semântica que de princípios metafísicos.]==],
				},
