(+4 pontos) Consequências devastadoras – até expiar, seu Avatar o abandona, você perde um total de três pontos entre vários Atributos, adquire os Defeitos Quebra-Juramentos, Perturbado ou ambos, ou suporta punição semelhante.

(+5 pontos) Consequências fatais – ou você vai morrer em breve, ou será arrastado para um Reino de punição em Outro Mundo, ou as duas coisas. A expiação, se é que existe, será duríssima, então NÃO quebre este juramento nem abandone este imperativo!

Este Defeito combina muito bem com diversos Antecedentes (Familiar, Lenda, Vida Passada, Totem, Maravilha e potencialmente outros, a critério do Narrador) e Qualidades (praticamente qualquer uma, a depender de como você define a origem dela). Embora isso não reduza o custo do Traço (apesar da descrição deste Defeito em Mage Revised, que usava um sistema de regras complexo e potencialmente abusável, inexistente nos outros jogos do Mundo das Trevas), uma Proibição/Imperativo pode representar votos, obrigações e/ou legados associados ao Traço benéfico. Se, por exemplo, Riordan Manseragh tivesse feito um juramento místico para conquistar seu familiar espírito-tigre, esse juramento representaria um Imperativo Paranormal, com consequências dolorosas (a perda do Antecedente Familiar) caso ele quebre a promessa.

Sua Proibição/Imperativo precisa estar amarrada à história da sua personagem, e provavelmente tem ligação com os três elementos do foco mágico dela (paradigma, prática e instrumentos). As condições precisam ser algo que possa concebivelmente representar um obstáculo (nada de proibições, por exemplo, de transar com Voormas, nem de imperativos de levantar da cama de manhã), e seu Narrador, claro, fará questão de jogar esses obstáculos no seu caminho em vários momentos da crônica. Dito isso, também pedimos aos Narradores que não abusem deste Defeito, nem o apliquem de forma desproporcional aos pontos que ele vale.

Embora seja bastante incomum, um tecnomante também pode ter um pacto ou proibição metafísica. Ela pode, por exemplo, precisar trabalhar num Mac, usar apenas tecnologia a vapor ou inventar toda a própria tecnologia para não sofrer algum mal-estar paranormal. Assim, este Defeito nem sempre é "místico" por natureza, ainda que a linha que separa misticismo de fenômeno paranormal seja mais questão de semântica que de princípios metafísicos.]==],
				},
				["Paranormal Prohibition or Imperative (8)"] = {
					pt = [==[Book of Secrets, pág. 83


Paranormal Prohibition or Imperative (8)


Também conhecido como Geasa e Proibição ou Imperativo Mágico, este Defeito representa algo que você precisa fazer, ou está proibido de fazer, sob pena de consequências terríveis. Em geral, esse imperativo vem de um juramento que você fez, de uma maldição que lhe foi imposta ou de um legado que segue a linhagem da sua família. Rancores feéricos, pactos infernais, heranças divinas, profecias antigas, caprichos forteanos da física… qualquer um deles pode lhe impor esse fardo. Enquanto você não cruzar a linha, deve ficar tudo bem – e você pode até possuir alguma bênção (uma Qualidade ou um Antecedente) ligada a este Defeito. Ah, mas a vida tem o dom de nos empurrar a fazer o que não queremos, e isso vale ainda mais para quem carrega uma maldição ou um geas sobre a cabeça!

O valor deste Defeito se baseia nas suas chances de violar a proibição e nas consequências que ocorrem quando isso acontece:

(1 ponto) Você só quebra a proibição numa circunstância facilmente evitável (nunca matar um gato, ir a Londres ou transar com alguém casado), ou acha fácil cumprir seu imperativo (raspar todo o cabelo, sair de casa todos os dias ou vestir roupas azuis).

(2 pontos) Sua proibição é fácil de quebrar (nunca mentir, sair da sua cidade natal ou transar com alguém), ou seu imperativo é difícil de cumprir (cobrir sempre a cabeça, caminhar ao menos cinco quilômetros por dia ou andar descalço o tempo todo).

(3 pontos) É muito difícil não quebrar sua proibição (nunca falar, ter uma casa própria ou se apaixonar ou desejar alguém), ou honrar seu imperativo (vendar os olhos todos os dias mesmo enxergando, ir a pé a todos os lugares ou permanecer nu o tempo todo).

(+1 ponto) Consequências inconvenientes – você falha criticamente nas três rolagens seguintes, sofre uma enxaqueca, desenvolve uma erupção na pele por vários dias etc.

(+2 pontos) Consequências irritantes – você perde a voz por um dia, perde um dado de todas as paradas por uma semana por causa de dor constante, soma +2 a todas as rolagens sociais com membros da sua facção até conseguir expiar a quebra do juramento e assim por diante.

(+3 pontos) Consequências dolorosas – até conseguir expiar, você fica cego ou mudo, perde um ponto de um Atributo, perde um Aliado, Mentor ou Familiar, adquire o Defeito Quebra-Juramentos (abaixo) ou sofre destino igualmente terrível.

(+4 pontos) Consequências devastadoras – até expiar, seu Avatar o abandona, você perde um total de três pontos entre vários Atributos, adquire os Defeitos Quebra-Juramentos, Perturbado ou ambos, ou suporta punição semelhante.

(+5 pontos) Consequências fatais – ou você vai morrer em breve, ou será arrastado para um Reino de punição em Outro Mundo, ou as duas coisas. A expiação, se é que existe, será duríssima, então NÃO quebre este juramento nem abandone este imperativo!

Este Defeito combina muito bem com diversos Antecedentes (Familiar, Lenda, Vida Passada, Totem, Maravilha e potencialmente outros, a critério do Narrador) e Qualidades (praticamente qualquer uma, a depender de como você define a origem dela). Embora isso não reduza o custo do Traço (apesar da descrição deste Defeito em Mage Revised, que usava um sistema de regras complexo e potencialmente abusável, inexistente nos outros jogos do Mundo das Trevas), uma Proibição/Imperativo pode representar votos, obrigações e/ou legados associados ao Traço benéfico. Se, por exemplo, Riordan Manseragh tivesse feito um juramento místico para conquistar seu familiar espírito-tigre, esse juramento representaria um Imperativo Paranormal, com consequências dolorosas (a perda do Antecedente Familiar) caso ele quebre a promessa.

Sua Proibição/Imperativo precisa estar amarrada à história da sua personagem, e provavelmente tem ligação com os três elementos do foco mágico dela (paradigma, prática e instrumentos). As condições precisam ser algo que possa concebivelmente representar um obstáculo (nada de proibições, por exemplo, de transar com Voormas, nem de imperativos de levantar da cama de manhã), e seu Narrador, claro, fará questão de jogar esses obstáculos no seu caminho em vários momentos da crônica. Dito isso, também pedimos aos Narradores que não abusem deste Defeito, nem o apliquem de forma desproporcional aos pontos que ele vale.

Embora seja bastante incomum, um tecnomante também pode ter um pacto ou proibição metafísica. Ela pode, por exemplo, precisar trabalhar num Mac, usar apenas tecnologia a vapor ou inventar toda a própria tecnologia para não sofrer algum mal-estar paranormal. Assim, este Defeito nem sempre é "místico" por natureza, ainda que a linha que separa misticismo de fenômeno paranormal seja mais questão de semântica que de princípios metafísicos.]==],
				},
				["Parasitic Infestation"] = {
					pt = [==[Lore of the Clans, pág. 162


Parasitic Infestation


Viver no escuro fez de você lar de todo tipo de bicho rastejante e chupador de sangue. Sua pele fervilha de carrapatos, piolhos e sanguessugas das mais variadas espécies. Eles mordem e cavam sem parar e, tendo se alimentado da sua vitae, ficaram muito difíceis de matar. Além de não conseguir comandá-los, você já tentou de tudo para se livrar deles e mesmo assim eles persistem. Seja qual for a razão, acham você tão suculento que reduzem sua reserva de sangue pelo resultado de um dado dividido por 3 (arredondando para baixo) toda vez que você se ergue. A coceira constante também o deixa no limite, aumentando em 1 a dificuldade de qualquer rolagem de Autocontrole ou Instinto.]==],
				},
				["Path Inept"] = {
					pt = [==[M20 Sorcerer, pág. 108


Path Inept


Você tem um Caminho que simplesmente não compreende. Isso pode se dever a uma maldição, à falta de treino ou a um bloqueio mental. Você precisa escolher um Caminho entre os disponíveis para a sua Afiliação. Ao melhorá-lo, você precisa gastar um quarto a mais de pontos de experiência para elevar os níveis do Caminho ou os rituais. Ele precisa ser um Caminho que sua personagem deseja e pretende estudar.]==],
				},
				["Permanent Fangs"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 482


Permanent Fangs


Suas presas não se recolhem, o que torna impossível esconder sua verdadeira natureza. Embora alguns mortais possam achar que você limou os dentes ou usa próteses, cedo ou tarde você vai cruzar com alguém que sabe o que você realmente é. Você também fica limitado a uma Aparência máxima de 3.]==],
				},
				["Permanent Paradox Flaw (2)"] = {
					pt = [==[Book of Secrets, pág. 89


Permanent Paradox Flaw (2)


Depois de um encontro feio com o Paradoxo, você ficou com um Defeito que não vai embora. Em termos de sistema, escolha um Defeito de Paradoxo trivial (dois pontos), menor (quatro pontos) ou significativo (seis pontos), conforme descrito em Mage 20, p. 551. Esse Defeito agora faz parte da vida da sua personagem até que você compre a saída deste Defeito, de preferência com experiência ganha em alguma aventura extraordinária ligada ao Defeito de Paradoxo em questão e ao acidente que o criou.]==],
				},
				["Permanent Paradox Flaw (4)"] = {
					pt = [==[Book of Secrets, pág. 89


Permanent Paradox Flaw (4)


Depois de um encontro feio com o Paradoxo, você ficou com um Defeito que não vai embora. Em termos de sistema, escolha um Defeito de Paradoxo trivial (dois pontos), menor (quatro pontos) ou significativo (seis pontos), conforme descrito em Mage 20, p. 551. Esse Defeito agora faz parte da vida da sua personagem até que você compre a saída deste Defeito, de preferência com experiência ganha em alguma aventura extraordinária ligada ao Defeito de Paradoxo em questão e ao acidente que o criou.]==],
				},
				["Permanent Paradox Flaw (6)"] = {
					pt = [==[Book of Secrets, pág. 89


Permanent Paradox Flaw (6)


Depois de um encontro feio com o Paradoxo, você ficou com um Defeito que não vai embora. Em termos de sistema, escolha um Defeito de Paradoxo trivial (dois pontos), menor (quatro pontos) ou significativo (seis pontos), conforme descrito em Mage 20, p. 551. Esse Defeito agora faz parte da vida da sua personagem até que você compre a saída deste Defeito, de preferência com experiência ganha em alguma aventura extraordinária ligada ao Defeito de Paradoxo em questão e ao acidente que o criou.]==],
				},
				["Permanent Wound"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 482


Permanent Wound


Você sofreu ferimentos durante o Abraço que sua transformação, de algum modo, não conseguiu reparar. No começo de cada noite, você se ergue do sono no nível de vitalidade Ferido, embora isso possa ser curado gastando pontos de sangue.]==],
				},
				["Phobia"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 486


Phobia


Você tem um medo avassalador de alguma coisa. Aranhas, cobras, multidões e altura são exemplos de fobias comuns. Você precisa fazer uma rolagem de Coragem toda vez que encontrar o objeto do seu medo. A dificuldade é determinada pelo Narrador. Se falhar, você precisa recuar diante daquilo.]==],
				},
				["Phylactery"] = {
					pt = [==[Book of Secrets, pág. 94


Phylactery


Sua magia, talvez sua própria alma, reside fora do seu corpo físico. Talvez você tenha posto sua alma dentro de um anel, de um jarro ou de uma boneca de madeira para se proteger de possessão e controle. Ou talvez acredite que sua varinha, e não sua Vontade, é a fonte dos seus poderes místicos. Você pode ter construído um robô como extensão do seu Gênio, ou confeccionado um casaco no qual instilou a essência de quem você é. O receptáculo em si não importa, exceto quanto à sua portabilidade. Este Defeito representa o fato de que você precisa ter o receptáculo antes de poder usar suas Artes. Sem ele, você é só mais um Adormecido.

Linguisticamente, filactério vem de uma raiz grega que significa "guardar". Em muitas formas de magia clássica, praticantes punham a alma ou a força vital dentro de amuletos, seja como proteção da alma, seja como recipiente portátil para trabalhos de magia. Judeus ortodoxos às vezes usam tefilin – muitas vezes chamados de filactérios – como lembretes da aliança com Deus. Como Traço de Mage, seu Filactério serve de recipiente para o "deus interior" que permite ao mago mudar a realidade: o Avatar Desperto.

Como sua personagem enxerga essa relação entre o recipiente, seu eu Desperto e a capacidade de fazer magia depende do paradigma dela. Uma bruxa eslava pode acreditar que tirou o próprio coração e o pôs dentro de um ovo cozido; um cientista louco pode usar teoria de colocação por transposição de consciência para guardar sua genialidade num cérebro dentro de um tanque. A xamã metamorfa investe sua alma numa pele de lobo, enquanto um mago Hermético emprega rituais romanos para trancar sua essência imortal num cajado de ouro. Seu filactério provavelmente é um objeto, mas pode concebivelmente ser um lugar (um bosque, um jardim, uma casa etc.) ou um ser vivo (uma criança, um pássaro, uma árvore, uma inteligência fabricada hospedada num computador central e assim por diante). O ponto central é este: seu mago precisa conseguir acessar fisicamente o filactério para usar a magia das Esferas. E é aí que está o Defeito.

No conjunto, um filactério oferece alguns benefícios poderosos em troca de desvantagens bem consideráveis. Do lado bom: ele permite preservar parte da sua consciência fora do corpo mortal. O corpo pode ser destruído, mas sua alma e sua consciência seguem vivas até que o filactério seja destruído. Com Mente 4, você pode projetar essa consciência para outro corpo ou para uma forma astral, enquanto uma personagem com Mente 5/Espírito 5 pode instalar sua consciência Desperta num corpo novo para você.

Se o filactério lhe for tomado, ou se você for levado para longe dele, pode recuperá-lo, ou voltar a ele, com uma aplicação bem-sucedida da Esfera da Correspondência. A dificuldade desse Efeito de retorno é 4 se ele parecer coincidente a uma testemunha, 5 se for vulgar sem testemunhas e 6 se for vulgar com testemunhas. (Sim, o Paradoxo usual se aplica.)

Um filactério vivo mantém um vínculo psíquico com você, como se estivessem em contato empático e telepático constante. (Nenhuma rolagem é necessária.) Se o filactério for um lugar, você mantém consciência daquele lugar e pode checá-lo usando Percepção + Prontidão, dificuldade 6. (Para áreas muito grandes, a dificuldade pode ir de 7 a 10.)

Com o acréscimo da Qualidade "Imortal" no nível de sete pontos, seu corpo físico pode continuar sobrevivendo até que o filactério seja destruído… o que, se você não se importar de ficar sem sua magia por um tempo, pode torná-lo mais ou menos imune à morte, bastando esconder o filactério num lugar seguro. Tradicionalmente, é por isso que muitos magos fazem filactérios: para preservar a vida mortal indefinidamente.

Enquanto seu filactério estiver seguro e intacto, você permanece imune ao Gilgul e a outros ataques que aprisionam a alma. Seu corpo pode ser possuído, mas sua alma não pode ser roubada nem destruída, a menos que alguém ataque o filactério… caso em que você está ferrado, como descrito abaixo. Para detalhes sobre o Gilgul, veja a entrada correspondente no Capítulo Quatro, pp. 218-220.

E, se você investir sua alma num lugar, carrega literalmente a essência daquele lugar dentro de si, enquanto uma parte de você permanece sempre lá. Para praticantes de certas formas ancestrais de magia (ou simplesmente para os românticos convictos), essa é uma razão poderosíssima para fazê-lo.

Esses são os pontos bons. As desvantagens são as seguintes: se o filactério for destruído, sua capacidade de usar magia nesta vida é destruída junto.

Você não consegue fazer magia nem recarregar seu Avatar sem alguma forma de conexão física com o filactério. Essa conexão pode ser um portal físico para contato virtual, como um computador que acessa um servidor central, mas você ainda precisa desse portal para alcançar um filactério distante. (Sim, você pode usar a Esfera da Correspondência para chegar a ele, e é sempre considerado a um sucesso de distância do seu filactério ao usar Correspondência para alcançá-lo.)

Se o filactério for um lugar, você precisa estar naquele lugar para usar as Esferas. Se for um ser vivo, aquela personagem precisa estar ao alcance do toque antes que você possa usá-las. (Explica muita coisa sobre Blofeld e o gato dele, não é?)

Se você usa o filactério para lançar magia, precisa fazê-lo de forma bem ostensiva – gritando comandos para seu robô hipertecnológico, erguendo sua coroa mística ao alto, abrindo caminho entre inimigos com sua espada demoníaca enquanto brada invocações ao seu deus padroeiro, esse tipo de coisa.

Se o seu Avatar se comunica com você por meio de um filactério encarnado, você precisa comprar a Qualidade Avatar Manifesto (p. 71) para representar a forma física dele.]==],
				},
				["Plague of Demons"] = {
					pt = [==[Lore of the Bloodlines, pág. 16


Plague of Demons


Não importa o que aconteça, demônios são constantemente atraídos pelos Baali. De vez em quando isso é uma vantagem (Baali com este Defeito têm -1 de dificuldade para convocar um demônio específico), mas na maior parte do tempo esses espíritos nefastos são pura distração. Eles gritam no ouvido da Baali, puxam a roupa dela, mexem nos pertences dela… e sempre no pior momento possível. A personagem sofre +1 de dificuldade em qualquer rolagem que envolva Percepção. Além disso, uma vez por sessão, o Narrador pode converter uma das rolagens da Baali numa falha crítica.]==],
				},
				["Prey Exclusion"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 485


Prey Exclusion


Você se recusa a caçar certa classe de presas. Pode se recusar a se alimentar de traficantes, policiais, contadores ou gente rica — e, se acidentalmente se alimentar de alguém assim, entra automaticamente em frenesi e precisa fazer uma rolagem para não perder Humanidade ou Caminho (dificuldade 7). Testemunhar outros Cainitas se alimentando do objeto da sua exclusão também pode provocar frenesi, a critério do Narrador. Ventrue, por causa das limitações que a fraqueza de Clã já impõe à alimentação deles, não podem adquirir este Defeito.]==],
				},
				["Primal Marks"] = {
					pt = [==[Book of Secrets, pág. 90


Primal Marks


Você foi marcado por algum deus, espírito, mito ou outra entidade metafísica… e a marca não é das agradáveis. Talvez você compartilhe a voz anasalada e o humor grosseiro de Papa Ghede, ou o pau grotescamente enorme de Coiote, ou os estigmas sangrentos de Cristo. Basicamente, este Defeito é o avesso da Qualidade Marca do Favor; no seu caso, porém, a marca complica sua vida, torce seu corpo e alerta quem compreende o significado dela. Em certos círculos – digamos, ser marcado por Satã vivendo numa região profundamente religiosa –, uma Marca Primal pode ser questão de vida ou morte. Essas marcas também podem indicar o profundo desagrado da entidade em questão, como a Marca de Caim (em sentido não vampírico) que apartou o Primeiro Assassino enquanto poupava sua vida para uma punição prolongada. Mas, mesmo que a entidade goste de você, essa marca em particular é mais fardo que bênção. Se, por exemplo, você fede a bode e tem os traços pesados e peludos de Pã, isso não vai torná-lo lá muito popular entre as moças… ainda mais se você já for mulher!

Esse legado desconcertante pode se manifestar como traços animalescos que revelam sua ligação com um espírito totêmico, como descrito na entrada do Antecedente Totem e na seção correspondente do Apêndice I de Mage 20. (Veja pp. 326-328 e 633-636.) Ou a "marca" pode envolver alguma manifestação física do seu Avatar interior. Você pode compartilhar a "cara" arquetípica de uma família notória, como os Bórgias ou os Romanov, mesmo sem ter parentesco com aquela linhagem; ou ter uma semelhança inquietante com alguma besta sinistra mesmo sem ser metamorfo ou amigo de totem. Talvez você simplesmente pareça aquilo que as pessoas imaginam quando dizem feiticeiro, xamã ou bruxa – o que, em muitas culturas, pode ser bem pouco saudável para quem é assim identificado. Em resumo, você parece estranho no sentido literal e inquietante da palavra, e as pessoas notam.

Obviamente, você deve definir a aparência dessa característica e decidir que tipo de reação as pessoas têm ao notá-la. Como este é um Defeito, essa reação deve ser negativa de alguma forma – a "marca primal do Clã Jolie-Pitt" não é exatamente um Defeito, a menos que você esteja lidando com paparazzi. A "marca" também pode ser um tom de voz, um jeito distinto de se mover (como pássaro, como gato, como Papa Legba) ou certa vibração que quase qualquer um percebe. Seja qual for a origem e a manifestação, essas Marcas Primais são evidentes e tendem a persistir mesmo quando o mago muda de forma. As pessoas reconhecem você mesmo quando você preferiria não ser reconhecido, e esse tipo de distinção também pode ser bem pouco saudável.

Este Defeito combina bem com Antecedentes como Bênção, Destino, Lenda, Vidas Passadas e, como sugerido antes, Totem. Pode ser adquirido como Defeito genético de Aprimoramentos, ou como reflexo de um Avatar especialmente potente. Para uma diversão extra, você pode nem saber por que foi marcado, quem o marcou ou o que virá como resultado da marca. Como em tantos elementos da vida de um mago, essas Marcas Primais podem ser mistérios cujas respostas estão no fim de um Caminho longo e sinuoso… se é que essas respostas algum dia se revelam.]==],
				},
				["Privacy Obsession"] = {
					pt = [==[Lore of the Clans, pág. 239


Privacy Obsession


Talvez seja um traço que corre no sangue. Talvez seu senhor rigoroso tenha esculpido essa lição na sua mente e na sua carne. De um jeito ou de outro, você leva ao extremo o respeito Tzimisce pela privacidade. Você precisa de uma rolagem de Força de Vontade (dificuldade 6) para entrar na morada de outro ser sem ser convidado, embora possa recorrer a artimanhas diabolicamente engenhosas para arrancar um convite involuntário. Quando é perturbado no seu refúgio por um hóspede não convidado, precisa de uma rolagem de Autocontrole ou Instintos (dificuldade 7) para evitar o frenesi.]==],
				},
				["Private Life"] = {
					pt = [==[Lore of the Clans, pág. 200


Private Life


Você tem uma vida completamente separada que nenhum outro Cainita conhece. Pode ser sua família mortal, que você transformou em carniçais, ou um canal no YouTube em que você fala por metáforas sobre suas frustrações com a sociedade Cainita. Se descoberta, ela pode levar outros vampiros a acusá-lo de quebrar a Máscara (se Camarilla), de confraternizar com a humanidade em vez de ser um vampiro superior (se Sabá), ou simplesmente gerar paranoia e desconfiança geral sobre por que você guarda segredos tão profundos.]==],
				},
				["Probationary Member"] = {
					pt = [==[Book of Secrets, pág. 68


Probationary Member


Tendo desertado há pouco de um grupo ou facção rival, você está em período de experiência no grupo atual. Seus pares esperam que você os traia, e certas pessoas provavelmente já decidiram jogá-lo aos leões por princípio. Sua permanência (possivelmente até sua sobrevivência) depende de fazer tudo certo e nada errado… e com que frequência as coisas realmente saem assim tão bem no mundo real?]==],
				},
				["Probationary Sect Member"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 493


Probationary Sect Member


Você é um desertor. Traiu a Camarilla, a Sabá ou outra Seita, e ainda tem muito a provar antes de ser aceito pelos Cainitas para os quais desertou. Outros vampiros o tratam com desconfiança e até hostilidade, e sua reputação pode até sujar a de quem convive com você regularmente.]==],
				},
				["Problem with Authority"] = {
					pt = [==[Ghouls & Revenants, pág. 133


Problem with Authority


Problema com Autoridade é algo pouco saudável para carniçais ou revenantes de quem se espera serviço sem questionamento. É especialmente problemático para carniçais de mestres violentos ou imprevisíveis, e pode levar um carniçal a abandonar o lado de sua domitora. Muitos carniçais independentes sofrem deste Defeito e continuam sentindo os efeitos da própria desobediência.

Levado ao extremo, seu carniçal fica argumentativo e indisciplinado, e pode implicar até com as instruções mais simples. Discutir com figuras de autoridade menores na vida dele, como a polícia, tem menos chance de matá-lo, mas pode acabar em prisão ou demissão.

Usado por: todos os carniçais e revenantes]==],
				},
				["Profiled Appearance"] = {
					pt = [==[Book of Secrets, pág. 41


Profiled Appearance


Você parece um daqueles… sabe, aqueles de quem os "cidadãos de bem" esperam coisa ruim. Dependendo do cenário da sua crônica, isso pode envolver trejeitos, arte corporal, marcas de gênero, traços individuais, herança étnica, modificações cibernéticas ou outros elementos do seu corpo que você não pode remover e provavelmente nem quer "consertar". O problema é que as pessoas ao seu redor vigiam cada movimento seu, criam problemas para você sempre que podem sair impunes e, de resto, lhe causam sofrimento. As autoridades o revistam por princípio, e a maioria não vai se opor ao que elas resolverem fazer com você.

Embora tenha relação com o Defeito Social Estrangeiro Cultural (abaixo), Aparência Fichada se baseia nos traços físicos da personagem, e não no comportamento social dela. Ainda que possa ser disfarçada até certo ponto, sua Aparência Fichada não é algo que possa ser removido sem magia, e reflete uma parte essencial da sua identidade. Como Impedimento, ela não carrega julgamento de valor dentro do jogo, mesmo representando o modo como os outros personagens verão você. Se isso parece injusto no jogo, imagine como deve ser na vida real.]==],
				},
				["Prone to Quiet (4)"] = {
					pt = [==[Book of Secrets, pág. 91


Prone to Quiet (4)


Num esforço de desviar dos estresses inevitáveis da vida Desperta, você tende a cair em Quietudes metafísicas (conforme Mage 20, pp. 554-561) com mais facilidade que a maioria dos magos. Quanto mais fácil você cai nelas, mais este Defeito vale:

(4 pontos) A Quietude é seu contragolpe padrão de Paradoxo, de modo que um contragolpe de cinco pontos ou mais o manda automaticamente para ela.

(5 pontos) A Quietude é seu contragolpe padrão, e você pode cair nela mesmo sem uma descarga de Paradoxo. Role sua parada de Inteligência + Enigmas quando enfrentar uma situação de estresse fora do comum; se tiver sucesso, consegue raciocinar seu caminho para fora da queda – e, se não, bem-vindo de volta à Quietude… (A dificuldade vai de 6 a 10, conforme a gravidade do estresse e o fato de você já ter ou não lidado com aquele tipo específico de estresse antes.)

Embora seja mais notado em Adeptos Virtuais e outros Cidadãos da Rede, que costumam partir para a Teia Digital a fim de escapar do desagrado físico, qualquer mago pode sofrer deste Defeito.]==],
				},
				["Prone to Quiet (5)"] = {
					pt = [==[Book of Secrets, pág. 91


Prone to Quiet (5)


Num esforço de desviar dos estresses inevitáveis da vida Desperta, você tende a cair em Quietudes metafísicas (conforme Mage 20, pp. 554-561) com mais facilidade que a maioria dos magos. Quanto mais fácil você cai nelas, mais este Defeito vale:

(4 pontos) A Quietude é seu contragolpe padrão de Paradoxo, de modo que um contragolpe de cinco pontos ou mais o manda automaticamente para ela.

(5 pontos) A Quietude é seu contragolpe padrão, e você pode cair nela mesmo sem uma descarga de Paradoxo. Role sua parada de Inteligência + Enigmas quando enfrentar uma situação de estresse fora do comum; se tiver sucesso, consegue raciocinar seu caminho para fora da queda – e, se não, bem-vindo de volta à Quietude… (A dificuldade vai de 6 a 10, conforme a gravidade do estresse e o fato de você já ter ou não lidado com aquele tipo específico de estresse antes.)

Embora seja mais notado em Adeptos Virtuais e outros Cidadãos da Rede, que costumam partir para a Teia Digital a fim de escapar do desagrado físico, qualquer mago pode sofrer deste Defeito.]==],
				},
				["Psi Focus (3)"] = {
					pt = [==[M20 Sorcerer, pág. 108


Psi Focus (3)


Seu poder psíquico exige algo além das suas próprias forças mentais para se manifestar, seja sua pena da sorte, um "por favor" bem pedido, ou mimicar a ação que você quer que aconteça. Como Defeito de 3 pontos, você precisa gesticular ou pronunciar um encantamento para o poder funcionar. Como Defeito de 4 pontos, precisa de um foco físico, como cristais, cartas de tarô ou velas. Como Defeito de 5 pontos, o poder só funciona com um foco específico, semelhante ao instrumento único de um mago (Mage 20, p. 588). A versão de 5 pontos também está disponível para feiticeiros menores.]==],
				},
				["Psi Focus (4)"] = {
					pt = [==[M20 Sorcerer, pág. 108


Psi Focus (4)


Seu poder psíquico exige algo além das suas próprias forças mentais para se manifestar, seja sua pena da sorte, um "por favor" bem pedido, ou mimicar a ação que você quer que aconteça. Como Defeito de 3 pontos, você precisa gesticular ou pronunciar um encantamento para o poder funcionar. Como Defeito de 4 pontos, precisa de um foco físico, como cristais, cartas de tarô ou velas. Como Defeito de 5 pontos, o poder só funciona com um foco específico, semelhante ao instrumento único de um mago (Mage 20, p. 588). A versão de 5 pontos também está disponível para feiticeiros menores.]==],
				},
				["Psi Focus (5)"] = {
					pt = [==[M20 Sorcerer, pág. 108


Psi Focus (5)


Seu poder psíquico exige algo além das suas próprias forças mentais para se manifestar, seja sua pena da sorte, um "por favor" bem pedido, ou mimicar a ação que você quer que aconteça. Como Defeito de 3 pontos, você precisa gesticular ou pronunciar um encantamento para o poder funcionar. Como Defeito de 4 pontos, precisa de um foco físico, como cristais, cartas de tarô ou velas. Como Defeito de 5 pontos, o poder só funciona com um foco específico, semelhante ao instrumento único de um mago (Mage 20, p. 588). A versão de 5 pontos também está disponível para feiticeiros menores.]==],
				},
				["Psychic Vampire"] = {
					pt = [==[Book of Secrets, pág. 93


Psychic Vampire


Também conhecida como Toque do Ceifador, esta maldição medonha faz de você um sifão de força vital. Sua presença consome vitalidade do ambiente e dos seres vivos que chegam perto demais. Se você não fizer isso, porém, sua própria força vital definha. Apesar das suas melhores intenções, você é basicamente um vazio ambulante para dentro do qual a própria vida escorre a fim de sustentar sua existência.

Em termos de história, você é um dreno na energia dos seus companheiros. Insetos e plantas pequenas morrem na sua presença, enquanto crianças e animais menores que um cavalo se sentem mal perto de você. Em termos de sistema, qualquer personagem em contato físico com você por uma hora ou mais perde um nível de vitalidade por hora, em dano contundente. Se você não conseguir absorver a força vital de outra pessoa, porém, é a sua própria vitalidade que se esvai. Em regras, você perde níveis de vitalidade na ordem inversa à da cura de dano letal, caindo para Escoriado após um dia, Machucado após três dias, Ferido após uma semana e assim por diante. (Para detalhes, veja Mage 20, p. 406.)

Se você usa magia da Esfera da Vida, suas dificuldades para Efeitos de cura ou aprimoramento sobem +2, enquanto as dificuldades para Efeitos de corrupção, dano ou doença caem -2. (Nos dois casos, os máximos e mínimos usuais continuam valendo.) Cada nível de vitalidade que você inflige a alguém com magia da Esfera da Vida cura um nível seu, se estiver ferido, ou então adia a perda por "inanição" dos seus próprios níveis em um dia por nível infligido.

Inversão da Qualidade Centelha da Vida (p. 78), este Defeito escurece sua aura, faz seu sangue ter gosto horrível para os vampiros e mantém seus companheiros próximos constantemente adoentados com males leves. Magos que afirmam a vida consideram isso marca de profundo infortúnio ou de maldade escancarada, enquanto quem ama a corrupção (Nephandi e afins) o vê como candidato maduro para recrutamento. A ciência mundana não pode fazer nada quanto a essa doença metafísica e despreza conceitos vagos como "energias de força vital". A União Tecnocrata, por outro lado, leva esse tipo de coisa a sério e tende a ver vampiros psíquicos como Desviantes da Realidade da pior espécie.

Para uma aplicação metafísica possivelmente relacionada, veja a entrada Canibalismo dos Instrumentos Expandidos do Capítulo Três, pp. 206-207.]==],
				},
				["PTSD (2)"] = {
					pt = [==[Book of Secrets, pág. 50


PTSD (2)


Veja Mage 20, pp. 647-648.]==],
				},
