PTSD (5)


Veja Mage 20, pp. 647-648.]==],
				},
				["Putrescent"] = {
					pt = [==[Lore of the Clans, pág. 163


Putrescent


O processo sobrenatural que normalmente impede a forma de um vampiro de apodrecer após a morte não funcionou com você. Seu corpo ficou pútrido e frágil, e vai se decompondo aos poucos. Todas as suas rolagens de absorção têm a parada de dados reduzida em 1. Você pode até perder partes do corpo se sofrer um golpe forte o bastante. Se isso acontecer, faça uma rolagem de Vigor (dificuldade 6) e perca uma parte do corpo (à escolha do Narrador) se falhar. Numa falha crítica, você também recebe um nível de dano agravado. Essas partes perdidas podem crescer de novo, mas seu corpo continua apodrecendo.]==],
				},
				["Ragged Bite"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 421


Ragged Bite


Ao contrário dos seus pares Cainitas, você não consegue selar com limpeza o ferimento causado pela alimentação. Em vez disso, deixa marcas rasgadas e sangrentas que podem infeccionar. Seu alvo precisa fazer uma rolagem de Vigor (dificuldade igual ao dano causado + 5) para resistir à infecção. O impacto de um ferimento tão notável combinado a um alvo doente fica a critério do Narrador. No mínimo, isso complica bastante esconder sua identidade como algo que não seja um monstro.]==],
				},
				["Rat in a Cage"] = {
					pt = [==[Lore of the Clans, pág. 87


Rat in a Cage


Sempre que você é encurralado ou fisicamente contido (por uma jaula ou por algemas, por exemplo), sofre ansiedade aguda. As dificuldades de qualquer rolagem feita nessas circunstâncias aumentam em dois.]==],
				},
				["Rebel (1)"] = {
					pt = [==[The Hunters Hunted II, pág. 123


Rebel (1)


Você ganhou certa infâmia na Sociedade de Leopoldo. Na versão de um ponto deste Defeito, você pode simplesmente ser desprezado pelos superiores, que esperam seu tropeço. Na de dois pontos, você é ativamente detestado e pode esperar pouca ajuda. Na de três pontos, há Inquisidores que odeiam você tanto quanto odeiam os sobrenaturais. Você deve acertar com o Narrador o motivo específico dessa má fama. Tenha em mente que sua reputação é relativa às divisões dentro da Inquisição. Algumas seitas podem acolhê-lo só para irritar as rivais. Por exemplo, embora você possa atrair a ira da Sociedade em geral por estudar as artes feiticeiras de perto demais, pode encontrar aceitação, e até incentivo, entre os Irmãos de Alberto Magno.]==],
				},
				["Rebel (2)"] = {
					pt = [==[The Hunters Hunted II, pág. 123


Rebel (2)


Você ganhou certa infâmia na Sociedade de Leopoldo. Na versão de um ponto deste Defeito, você pode simplesmente ser desprezado pelos superiores, que esperam seu tropeço. Na de dois pontos, você é ativamente detestado e pode esperar pouca ajuda. Na de três pontos, há Inquisidores que odeiam você tanto quanto odeiam os sobrenaturais. Você deve acertar com o Narrador o motivo específico dessa má fama. Tenha em mente que sua reputação é relativa às divisões dentro da Inquisição. Algumas seitas podem acolhê-lo só para irritar as rivais. Por exemplo, embora você possa atrair a ira da Sociedade em geral por estudar as artes feiticeiras de perto demais, pode encontrar aceitação, e até incentivo, entre os Irmãos de Alberto Magno.]==],
				},
				["Rebel (3)"] = {
					pt = [==[The Hunters Hunted II, pág. 123


Rebel (3)


Você ganhou certa infâmia na Sociedade de Leopoldo. Na versão de um ponto deste Defeito, você pode simplesmente ser desprezado pelos superiores, que esperam seu tropeço. Na de dois pontos, você é ativamente detestado e pode esperar pouca ajuda. Na de três pontos, há Inquisidores que odeiam você tanto quanto odeiam os sobrenaturais. Você deve acertar com o Narrador o motivo específico dessa má fama. Tenha em mente que sua reputação é relativa às divisões dentro da Inquisição. Algumas seitas podem acolhê-lo só para irritar as rivais. Por exemplo, embora você possa atrair a ira da Sociedade em geral por estudar as artes feiticeiras de perto demais, pode encontrar aceitação, e até incentivo, entre os Irmãos de Alberto Magno.]==],
				},
				["Recruitment Target"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 490


Recruitment Target


Alguém numa das organizações inimigas da sua Seita quer você, e quer muito. Todo esforço está sendo feito para recrutá-lo, com ou sem seu consentimento, e os recrutadores costumam aparecer no pior momento possível.]==],
				},
				["Red List"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 493


Red List


Você está sendo cogitado para a temida Lista Vermelha, ou já está nela: o registro dos vampiros que a Camarilla mais quer extintos. Qualquer vampiro da Camarilla vai atacá-lo à primeira vista ou, mais provavelmente, chamar um bocado de reforço.]==],
				},
				["Refined Palate (1)"] = {
					pt = [==[Lore of the Bloodlines, pág. 60


Refined Palate (1)


Muitos Kiasyd se impõem restrições alimentares: recusam-se a se alimentar dos pobres e doentes, ou até dos que ainda vestem pele, ou de quem passe de certa idade. Isso se manifesta de forma semelhante à fraqueza do Clã Ventrue (V20, p. 73), já que o condicionamento torna intragável qualquer sangue fora da preferência do Kiasyd. A gravidade do Defeito depende de quão estreita é a restrição.]==],
				},
				["Refined Palate (2)"] = {
					pt = [==[Lore of the Bloodlines, pág. 60


Refined Palate (2)


Muitos Kiasyd se impõem restrições alimentares: recusam-se a se alimentar dos pobres e doentes, ou até dos que ainda vestem pele, ou de quem passe de certa idade. Isso se manifesta de forma semelhante à fraqueza do Clã Ventrue (V20, p. 73), já que o condicionamento torna intragável qualquer sangue fora da preferência do Kiasyd. A gravidade do Defeito depende de quão estreita é a restrição.]==],
				},
				["Refined Palate (3)"] = {
					pt = [==[Lore of the Bloodlines, pág. 60


Refined Palate (3)


Muitos Kiasyd se impõem restrições alimentares: recusam-se a se alimentar dos pobres e doentes, ou até dos que ainda vestem pele, ou de quem passe de certa idade. Isso se manifesta de forma semelhante à fraqueza do Clã Ventrue (V20, p. 73), já que o condicionamento torna intragável qualquer sangue fora da preferência do Kiasyd. A gravidade do Defeito depende de quão estreita é a restrição.]==],
				},
				["Religious Hysteria"] = {
					pt = [==[The Hunters Hunted II, pág. 123


Religious Hysteria


Anjos e demônios estão em toda parte! Você os vê. Nota os sinais do plano Divino em cada nuance da vida. O mundo inteiro é um presságio! O Espírito Santo sussurra no seu ouvido o tempo todo. Por que os outros não entendem? Até seus irmãos e irmãs de fé balançam a cabeça enquanto você, sem fôlego, expõe sua mais recente visão sagrada. A diferença entre este Defeito e a Qualidade Extático (veja abaixo) é que as pessoas não levam você a sério. Suas visões acontecem um pouco frequentes demais, são um pouco insustentáveis demais. Subtraia um dado de todas as paradas de dados Sociais. Social]==],
				},
				["Repelled by Crosses"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 495


Repelled by Crosses


Você é repelido pela visão de cruzes comuns, por acreditar que são símbolos de poder sagrado. Diante de uma cruz, você precisa fazer uma rolagem de Força de Vontade (dificuldade 9) ou foge do símbolo pelo resto da cena. Numa falha crítica, além de ter de fugir, o toque da cruz pode causar dano agravado (um nível de vitalidade por turno em que a cruz encoste na sua pele). Esse dano não pode ser absorvido, mesmo que o vampiro tenha Fortitude.]==],
				},
				["Repulsed by Garlic"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 494


Repulsed by Garlic


Você não suporta alho, e o menor sopro do cheiro dele o expulsa de uma sala, a menos que você tenha sucesso numa rolagem de Força de Vontade (dificuldade conforme a intensidade do odor).]==],
				},
				["Repulsive Feature"] = {
					pt = [==[Book of Secrets, pág. 40


Repulsive Feature


Alguma característica física sua afasta as pessoas. Talvez você cheire mal por mais que cuide da higiene, tenha o proverbial "olho gordo", uma voz especialmente irritante, uma condição de pele generalizada ou outra característica física igualmente repugnante. Talvez a mera presença sua faça a pele das pessoas arrepiar, mesmo sem haver nada perceptivelmente feio em você. De todo modo, essa característica desestimula as pessoas a ficarem por perto.

Basicamente o inverso da Qualidade Traço Encantador, este Defeito representa um elemento ocultável, porém desconcertante, da sua presença física. Ao contrário de Impedimento, este Traço afeta como as pessoas o veem, não como seu corpo funciona. Dito isso, você pode adquirir os dois Defeitos juntos, para representar uma condição fisicamente debilitante que também traga efeitos socialmente constrangedores. A característica em questão não representa feiura geral, como em Monstruoso e Medonho, abaixo; ela se manifesta como uma única distinção física desagradável.

Em termos de sistema, este Defeito soma +2 de dificuldade às rolagens de Traços Sociais sempre que a característica entra em jogo. Em termos de história, ele o torna fisicamente distinto, a menos que você se esforce para esconder o Traço Repulsivo. Se você mudar de forma, a característica acompanha as outras formas, o que atrapalha tentativas de disfarce. Se ela transcender o sentido visual (por exemplo, um odor desagradável ou uma voz irritante), pode denunciar sua presença mesmo quando você não pode ser visto. Nos dois casos, este Defeito penaliza suas rolagens de ocultação física da mesma forma que penaliza suas interações sociais.

Como consolo, a característica pode ser usada para assustar ou irritar as pessoas de propósito; nesse caso, a penalidade usual vira -2 na sua dificuldade. Um Traço Repulsivo integrado ao seu foco mágico (de novo, por exemplo, o "olho gordo") oferece os mesmos benefícios instrumentais descritos em Traço Encantador, com o mesmo potencial de mutilação e um incentivo ainda maior para alguém acabar com a sua raça!]==],
				},
				["Repulsive to Animals"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 427


Repulsive to Animals


Quando você está por perto, os animais naturais se assustam e entram em pânico. Diferentemente da perturbação normal causada pela presença de Cainitas, os animais perto de você fogem apavorados ou ficam agressivos e violentos, conforme o temperamento de cada um. Isso torna quase impossível montar um cavalo (ou qualquer outra montaria), já que você não consegue acalmar criatura alguma com uma rolagem normal de Empatia com Animais. Você precisa usar as capacidades da Disciplina Animalismo ou dar ao animal um pouco do seu sangue, o que o transforma em carniçal.]==],
				},
				["Revenant Weakness"] = {
					pt = [==[Lore of the Clans, pág. 239


Revenant Weakness


Você já fez parte de uma família revenante. Depois do Abraço, passou a sofrer tanto a fraqueza do seu Clã quanto a limitação da sua família revenante (V20, pp. 503-506). O Narrador pode permitir que você manifeste a fraqueza de uma linhagem revenante perdida ou destruída. Isso pode acrescentar mistério ao seu passado e render um pouco de investigação genealógica, o que certamente faria de você uma curiosidade para a Fundação do Legado Romeno.]==],
				},
				["Ritual Sleeper"] = {
					pt = [==[M20 Sorcerer, pág. 108


Ritual Sleeper


A magia não acontece num estalar de dedos. Você é incapaz de manifestar qualquer efeito mágico instantâneo e fica limitado a realizar rituais. Se as regras da sua Afiliação já exigem que a magia venha apenas de rituais, você não pode adquirir este Defeito. Você é considerado um Adormecido se testemunhar um efeito mágico instantâneo.]==],
				},
				["Rival House (1)"] = {
					pt = [==[Book of Secrets, pág. 63


Rival House (1)


Você pertence a uma Capela (ou Construto, ou o que for) que mantém animosidade antiga com outra organização do gênero. Pode ser uma Capela Hermética rival, um templo cujos membros o consideram herege, uma gangue de rua hostil, uma ordem de artes marciais adversária, um coven que declarou guerra de bruxas ao seu grupo, um Construto que marcou todos vocês para morrer e assim por diante. Esse antagonismo é mútuo, e espera-se que você aja de acordo. A mediação segue improvável, e as coisas podem piorar antes de melhorar… se é que melhorar as relações é sequer possível.

Obviamente, essa hostilidade é pessoal, com raízes fundas na história da sua crônica e dos seus personagens. Grupos de magos em geral não cultivam rancores coletivos sem razões sérias!

O valor do Defeito depende do poder daquela outra fortaleza e do grau de ódio que ela nutre pelos membros da sua.

(1 ponto) Rivalidade pequena com uma Capela associada de poder igual ou menor que a sua. Na maior parte, o antagonismo envolve trotes, competição, sabotagem miúda e brigas "amigáveis" ocasionais.

(2 pontos) Rivalidade significativa (brigas sérias e calúnias, sabotagem pesada) com uma Capela de poder parecido, ou rivalidade pequena com uma Capela tão poderosa que não considera a sua uma ameaça real.

(3 pontos) Antagonismo mortal entre Capelas mais ou menos equivalentes.

(4 pontos) Rivalidade significativa entre a sua Capela e uma poderosa o bastante para causar dano sério a ela.

(5 pontos) Ódio mortal de uma Capela que poderia arrasar a sua se realmente quisesse… e ela provavelmente quer.

Da versão de três pontos em diante, é bastante improvável que a rivalidade se resolva sem um inimigo comum ou uma interferência considerável de um terceiro ainda mais poderoso. E pode não se resolver nem assim. Este Defeito exige o Antecedente Capela/Construto, mas qualquer personagem com esse tipo de vínculo pode adquiri-lo – ele não se restringe a magos das Tradições e da Tecnocracia. Sua rivalidade também pode cruzar facções: uma Casa Hermética pode manter inimizade antiga com um laboratório Progenitor. Ela pode existir dentro de um único grupo (dois coletivos Eterritas rivais) ou entre dois grupos aparentados que não pertencem à mesma facção; seitas de alquimistas, por exemplo, discutem pelo nome Solificati há séculos, sem fim à vista!]==],
				},
				["Rival House (2)"] = {
					pt = [==[Book of Secrets, pág. 63


Rival House (2)


Você pertence a uma Capela (ou Construto, ou o que for) que mantém animosidade antiga com outra organização do gênero. Pode ser uma Capela Hermética rival, um templo cujos membros o consideram herege, uma gangue de rua hostil, uma ordem de artes marciais adversária, um coven que declarou guerra de bruxas ao seu grupo, um Construto que marcou todos vocês para morrer e assim por diante. Esse antagonismo é mútuo, e espera-se que você aja de acordo. A mediação segue improvável, e as coisas podem piorar antes de melhorar… se é que melhorar as relações é sequer possível.

