O valor do Defeito depende do poder daquela outra fortaleza e do grau de ódio que ela nutre pelos membros da sua.

(1 ponto) Rivalidade pequena com uma Capela associada de poder igual ou menor que a sua. Na maior parte, o antagonismo envolve trotes, competição, sabotagem miúda e brigas "amigáveis" ocasionais.

(2 pontos) Rivalidade significativa (brigas sérias e calúnias, sabotagem pesada) com uma Capela de poder parecido, ou rivalidade pequena com uma Capela tão poderosa que não considera a sua uma ameaça real.

(3 pontos) Antagonismo mortal entre Capelas mais ou menos equivalentes.

(4 pontos) Rivalidade significativa entre a sua Capela e uma poderosa o bastante para causar dano sério a ela.

(5 pontos) Ódio mortal de uma Capela que poderia arrasar a sua se realmente quisesse… e ela provavelmente quer.

Da versão de três pontos em diante, é bastante improvável que a rivalidade se resolva sem um inimigo comum ou uma interferência considerável de um terceiro ainda mais poderoso. E pode não se resolver nem assim. Este Defeito exige o Antecedente Capela/Construto, mas qualquer personagem com esse tipo de vínculo pode adquiri-lo – ele não se restringe a magos das Tradições e da Tecnocracia. Sua rivalidade também pode cruzar facções: uma Casa Hermética pode manter inimizade antiga com um laboratório Progenitor. Ela pode existir dentro de um único grupo (dois coletivos Eterritas rivais) ou entre dois grupos aparentados que não pertencem à mesma facção; seitas de alquimistas, por exemplo, discutem pelo nome Solificati há séculos, sem fim à vista!]==],
				},
				["Rival House (3)"] = {
					pt = [==[Book of Secrets, pág. 63


Rival House (3)


Você pertence a uma Capela (ou Construto, ou o que for) que mantém animosidade antiga com outra organização do gênero. Pode ser uma Capela Hermética rival, um templo cujos membros o consideram herege, uma gangue de rua hostil, uma ordem de artes marciais adversária, um coven que declarou guerra de bruxas ao seu grupo, um Construto que marcou todos vocês para morrer e assim por diante. Esse antagonismo é mútuo, e espera-se que você aja de acordo. A mediação segue improvável, e as coisas podem piorar antes de melhorar… se é que melhorar as relações é sequer possível.

Obviamente, essa hostilidade é pessoal, com raízes fundas na história da sua crônica e dos seus personagens. Grupos de magos em geral não cultivam rancores coletivos sem razões sérias!

O valor do Defeito depende do poder daquela outra fortaleza e do grau de ódio que ela nutre pelos membros da sua.

