(3 pontos) Antagonismo mortal entre Capelas mais ou menos equivalentes.

(4 pontos) Rivalidade significativa entre a sua Capela e uma poderosa o bastante para causar dano sério a ela.

(5 pontos) Ódio mortal de uma Capela que poderia arrasar a sua se realmente quisesse… e ela provavelmente quer.

Da versão de três pontos em diante, é bastante improvável que a rivalidade se resolva sem um inimigo comum ou uma interferência considerável de um terceiro ainda mais poderoso. E pode não se resolver nem assim. Este Defeito exige o Antecedente Capela/Construto, mas qualquer personagem com esse tipo de vínculo pode adquiri-lo – ele não se restringe a magos das Tradições e da Tecnocracia. Sua rivalidade também pode cruzar facções: uma Casa Hermética pode manter inimizade antiga com um laboratório Progenitor. Ela pode existir dentro de um único grupo (dois coletivos Eterritas rivais) ou entre dois grupos aparentados que não pertencem à mesma facção; seitas de alquimistas, por exemplo, discutem pelo nome Solificati há séculos, sem fim à vista!]==],
