				},
				["Rival Sires"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 491


Rival Sires


O avesso de Alvo Escapado: dois vampiros quiseram lhe dar o Abraço. Um conseguiu, o outro falhou — e ela não está nada feliz com esse fracasso. Você, seu senhor de verdade, ou os dois viraram alvo da ira da pretendente frustrada. De todo modo, sua perseguidora sofre +2 de dificuldade para evitar o frenesi na sua presença. Além disso, ela pode muito bem estar trabalhando ativamente para desacreditá-lo ou destruí-lo.]==],
				},
				["Rivalry (1)"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 424


Rivalry (1)


Alguém odeia você tanto que não suporta deixá-lo em paz. A escala deste Defeito é parecida com a do Defeito Inimigo (veja acima), mas seu Rival não quer vê-lo morto. Ele quer apenas tornar sua não-vida o mais problemática e infernal possível. Em valores baixos, o Rival pode até ser um amigo que aparece exatamente no pior momento para roubar seus créditos ou constrangê-lo. Em valores altos, seu Rival perde o sono planejando como deixar sua vida miserável.]==],
