				},
				["Rogue"] = {
					pt = [==[Book of Secrets, pág. 68


Rogue


O mais solto dos canhões, você vai fazer o que bem entender, e que se danem todas as consequências! Você pode até continuar pertencendo a um grupo, mas sua filiação é mais questão de hábito ou conveniência que de lealdade. Como alternativa, você pode ter seguido seu caminho e agora existir num estado nebuloso entre camarada lembrado com carinho e fora da lei declarado. Certos Antecedentes (Requisições e Arma Secreta) lhe estão vedados agora, e outros (Aliados, Reforços, Capela, Recursos e potencialmente muitos mais) ficam difíceis de acessar – talvez até impossíveis – se a ligação deles com você depender da sua lealdade a um grupo. Antigos pares o consideram um risco, e a principal razão de ninguém ter dado cabo de você ainda é que ninguém conseguiu.

Para operativos Tecnocratas, este Defeito é uma sentença de morte em câmera lenta; para outros magos, pode envolver ameaças parecidas à longevidade, embora muitos Ofícios (fora Templários, Wu Lung e Hippolytoi) e a maioria das Tradições (fora Chakravanti, Akashayana e Ordem de Hermes) adotem uma postura mais liberal com membros renegados. De todo modo, suas relações com antigos aliados estão tensas na melhor das hipóteses (+3 na dificuldade da maioria das rolagens sociais que dependam da boa vontade deles), e você está em termos bastante hostis com os seus supostos (ou antigos) superiores. Alguns magos conseguem viver um bom tempo nesse estado de antagonismo mútuo. A maioria, porém, não.]==],
				},
				["Romantic Notions"] = {
					pt = [==[Ghouls & Revenants, pág. 138


Romantic Notions


Você acredita que sua existência inteira como carniçal é uma melhora notável em relação à vida anterior, e está convencido de que deve tudo isso à sua domitora. Sente que ela precisa de você, que você morreria sem ela e que cada alimentação é um ato de puro amor.

Quando sua domitora tenta usar Dominação ou Presença na sua personagem, sua Força de Vontade conta como 2. Este Defeito vale independentemente de como você reaja ao laço de sangue e, sob a influência dele, você pode sentir um amor artificial ainda mais forte pela sua domitora.

Este Defeito não afeta revenantes, que já nasceram na condição, da mesma forma que afeta carniçais. A critério do Narrador, apenas um revenante que se sinta romanticamente inclinado a um vampiro específico com uso de Dominação e Presença pode adquiri-lo. Carniçais independentes não podem comprá-lo, pois não faz sentido narrativo que se sintam romanticamente ligados a um vampiro específico.

Usado por: todos os carniçais, exceto os independentes, e revenantes em casos raros.]==],
				},
				["Rose-Colored Glasses"] = {
					pt = [==[Book of Secrets, pág. 50


Rose-Colored Glasses


Chamado com sarcasmo de Óculos Espelhados Cor-de-Rosa entre operativos da Tecnocracia, este Defeito representa uma lealdade um tanto delirante à facção que você escolheu. Basicamente, para você, seu time não erra nunca. A causa deles é justa, o paradigma é inabalável, os atos são necessários dadas as circunstâncias, por mais extremos que sejam. Sua personagem vê quase tudo o que o grupo faz sob a luz mais favorável… o que, considerando o quanto grupos Despertos podem ser terríveis, significa que você está escolhendo fechar os olhos para muita coisa. Confrontado com verdades inconvenientes, você pode ficar francamente irracional, agressivo ou até fanático. E, se um dia for confrontado com verdades que não possa negar, evitar ou caluniar, o choque pode devastá-lo por anos – muito possivelmente jogando-o nos braços de uma facção diametralmente oposta, pela qual nutrirá lealdade parecida. (Veja Mudando de Foco e Lealdade em Mage 20, p. 339.)]==],
				},
				["Rotten Liar"] = {
					pt = [==[Book of Secrets, pág. 66


Rotten Liar


Cara, você é péssimo em mentir! Não conseguiria contar uma inverdade crível nem se sua vida dependesse disso… o que pode acontecer, então isso é meio que um problema para você. Talvez você seja honesto demais para o seu próprio bem, ou amaldiçoado a dizer a verdade como a conhece, custe o que custar e sejam quais forem suas intenções; ou talvez você simplesmente gagueje ao longo das tentativas de engano, entregando suas mentiras pela linguagem corporal e pelo tom de voz. Seja qual for a razão, some +2 à dificuldade de qualquer rolagem feita ao tentar enganar outro personagem. Sim, a penalidade vale também para enganos mágicos, como ilusões ou controle mental. A honestidade pode nem sempre ser a melhor política entre os Despertos, mas para você costuma ser a melhor opção.]==],
				},
				["Scales (1)"] = {
					pt = [==[Lore of the Clans, pág. 67


Scales (1)


Set o abençoou no seu Abraço, e você carrega a marca dele. Uma parte da sua pele é coberta de escamas. Como Defeito de um ponto, é uma área pequena e fácil de esconder. Como Defeito de dois pontos, um membro inteiro é coberto, enquanto ter um rosto escamoso e sem lábios é um Defeito de três pontos. Os Rebanhos ficam assustados e perturbados diante das escamas obviamente antinaturais, e os Cainitas têm seus próprios preconceitos contra os Setitas. Todas as rolagens sociais recebem +2 de dificuldade quando as escamas estão visíveis. Essa penalidade não se aplica a interações sociais com outros Setitas.]==],
				},
				["Scales (2)"] = {
					pt = [==[Lore of the Clans, pág. 67


Scales (2)


Set o abençoou no seu Abraço, e você carrega a marca dele. Uma parte da sua pele é coberta de escamas. Como Defeito de um ponto, é uma área pequena e fácil de esconder. Como Defeito de dois pontos, um membro inteiro é coberto, enquanto ter um rosto escamoso e sem lábios é um Defeito de três pontos. Os Rebanhos ficam assustados e perturbados diante das escamas obviamente antinaturais, e os Cainitas têm seus próprios preconceitos contra os Setitas. Todas as rolagens sociais recebem +2 de dificuldade quando as escamas estão visíveis. Essa penalidade não se aplica a interações sociais com outros Setitas.]==],
				},
				["Scales (3)"] = {
					pt = [==[Lore of the Clans, pág. 67


Scales (3)


Set o abençoou no seu Abraço, e você carrega a marca dele. Uma parte da sua pele é coberta de escamas. Como Defeito de um ponto, é uma área pequena e fácil de esconder. Como Defeito de dois pontos, um membro inteiro é coberto, enquanto ter um rosto escamoso e sem lábios é um Defeito de três pontos. Os Rebanhos ficam assustados e perturbados diante das escamas obviamente antinaturais, e os Cainitas têm seus próprios preconceitos contra os Setitas. Todas as rolagens sociais recebem +2 de dificuldade quando as escamas estão visíveis. Essa penalidade não se aplica a interações sociais com outros Setitas.]==],
				},
				["Sect Enmity"] = {
					pt = [==[Book of Secrets, pág. 64


Sect Enmity


Grupos de magos tendem a ter problemas entre si por natureza. Você, porém, conseguiu irritar uma seita inteira de magos dentro do seu grupo maior. Pode ser uma bruxa Verbena que irritou a Casa Hermética Flambeau (eita), um Terno Preto do lado errado dos Amigos da Coragem, ou uma Lança Vermelha que falou mal da Sociedade da Roda Fantasma e viveu para se arrepender. Embora seus inimigos não tentem matá-lo – vocês estão teoricamente do mesmo lado, afinal –, eles realmente não vão com a sua cara, nem com quase nada em você.

Em geral, os membros da seita em questão terão o mínimo de contato possível com você e não serão nada cooperativos se precisarem lidar com você. Rolagens sociais feitas com membros desse grupo somam +2 à dificuldade. Você obviamente não pode pertencer a essa seita ao adquirir o Defeito, embora possa concebivelmente aparar as arestas, comprar a saída dele e entrar para o grupo mais tarde. Um jogador pode comprá-lo várias vezes para representar relações ruins com seitas diferentes. Aconselha-se aos Narradores criar alguns personagens recorrentes da seita rival, para dar dentes a este Defeito. Para uma versão mais severa, veja Lista Negra, abaixo.]==],
				},
				["Seizures"] = {
					pt = [==[Ghouls & Revenants, pág. 136


Seizures


Crises convulsivas tendem a ocorrer em momentos de pressão, e poucos mortais têm existência mais estressante ou aterrorizante que a de um carniçal. A aflição do Defeito Convulsões também pode ser mais pronunciada em famílias revenantes cujos membros sofrem com um caldo genético limitado. Muitos tipos de convulsão podem ser controlados ou atenuados com medicação, depois de exames médicos completos. Contudo, alguns carniçais e revenantes não estão dispostos a arriscar a vida procurando um médico, e essas Convulsões muitas vezes não estão ligadas a uma doença diagnosticada. Este Defeito é efeito colateral dos muitos horrores que carniçais e revenantes testemunham ao longo da vida.

As convulsões podem ser desastrosas, especialmente se ocorrerem na presença de um vampiro ou num momento inoportuno. Em qualquer circunstância estressante ligada a combate, ameaças físicas ou verbais, ou à visão de algo aterrorizante e sangrento, a personagem com este Defeito precisará fazer uma rolagem de Frenesi. Um sucesso significa que a crise não foi disparada e você conseguiu recuperar o controle.

Uma falha indica que seu corpo não deu conta do estresse e algo aconteceu. Numa falha crítica, sua personagem sofre uma crise convulsiva generalizada. Ela cai no chão e se debate sem controle por um número de minutos igual ao número de 1s rolados no teste de Frenesi. Seus atos podem acabar ferindo você ou os outros, já que seu dedo pode puxar o gatilho sem querer, ou você pode escorregar e cair. Uma falha comum provavelmente resulta em um apagão até o turno seguinte. Conforme a necessidade da sua história, seu carniçal pode desmaiar e cair, sua visão pode escurecer por alguns segundos, ou seu braço pode tremer sem que você consiga controlá-lo.

Usado por: todos os carniçais e revenantes]==],
				},
				["Self-Preservation"] = {
					pt = [==[Ghouls & Revenants, pág. 132


Self-Preservation


Por alguma razão, sua personagem se recusa a cumprir ordens que julgue ameaçadoras à própria segurança e que ponham sua vida em risco. Para carniçais, o Defeito Autopreservação anula o propósito de servir a um vampiro. Se você não pode defender sua domitora, seu valor cai consideravelmente. Um carniçal Vinculado capaz de recusar uma ordem, porém, merece ser vigiado de perto. Este Defeito é também uma das razões mais comuns para um carniçal deixar o serviço do seu mestre e passar a agir como independente.

Revenantes com senso de Autopreservação podem sentir os efeitos deste Defeito de outra forma. Sua lealdade à família pode ser questionada, já que você é capaz de sacrificar outro parente ou aliado na hora certa. Se você também estiver sujeito ao laço de sangue, sua incapacidade de se "entregar" por completo às ordens de um vampiro pode gerar consequências imprevistas, da experimentação ao escrutínio ainda maior.

Em regras, toda vez que sua domitora ou seu mestre der uma ordem que ameace sua vida, sua personagem faz um teste de Força de Vontade com +2 de dificuldade. Se tiver sucesso, o carniçal ou revenante pode recusar a ordem. Recusar um comando desses na frente do mestre, porém, costuma render punição severa.

Carniçais e revenantes espertos tentarão manipular este Defeito a seu favor. Podem tentar cumprir uma ordem arriscada garantindo que não sofrerão dano, ainda que isso nem sempre seja possível.

Usado por: todos os carniçais e revenantes]==],
				},
				["Shadow Scarred"] = {
					pt = [==[Lore of the Bloodlines, pág. 48


Shadow Scarred


Desde que escapou das Terras das Sombras, você luta para se readaptar ao mundo dos vivos. Vê Espectros vorazes em cada sombra. Você precisa rolar Coragem (dificuldade 7) ou gastar um ponto de Força de Vontade sempre que usar Necromancia, pois teme as consequências de tocar o Submundo.]==],
				},
				["Shadow Walker"] = {
					pt = [==[Lore of the Clans, pág. 107


Shadow Walker


O Clã Giovanni está, por natureza, inexoravelmente ligado ao reino além do sudário. Os Giovanni que sofrem deste Defeito estão tão presos às Terras das Sombras que, mesmo entre os vivos, precisam interagir com o mundo dos mortos todas as noites. Para os caminhantes de sombra, os objetos do Submundo são tão reais quanto qualquer coisa do mundo físico. Esses vampiros descobrem que os fantasmas de paredes podem barrar seu caminho, que objetos espectrais podem atingi-los e que os poderes dos espectros funcionam como se o Cainita estivesse do outro lado da Mortalha. Este Defeito é parecido com o poder Mão Morta do Caminho das Cinzas (V20, p. 163), exceto que Caminhante de Sombras está sempre ativo e de forma alguma permite à personagem enxergar além da Mortalha.

O Narrador pode determinar que certas formações das Terras das Sombras atrapalhem você. A menos que tenha algum meio de enxergá-las, você não vê o Submundo e por isso precisa tatear seu caminho com cuidado — essencialmente um cego submetido à paisagem do além. A critério do Narrador, paredes imateriais ou efeitos ambientais podem restringir seu movimento.]==],
				},
				["Short"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 481


Short


Você está bem abaixo da altura média — 1,50 m ou menos. Você tem dificuldade em alcançar ou manusear objetos feitos para adultos de tamanho normal, e sua velocidade de corrida é metade da de um humano comum.]==],
				},
				["Short Fuse"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 486


Short Fuse


Você se irrita com facilidade. As dificuldades para evitar o frenesi são dois pontos maiores. Vampiros Brujah não podem adquirir este Defeito, pois já sofrem de uma fraqueza semelhante.]==],
				},
				["Shy"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 485


Shy


Você fica visivelmente desconfortável ao lidar com pessoas e tenta evitar situações sociais sempre que pode. As dificuldades de todas as rolagens que envolvam interação social com estranhos aumentam em dois. Se a personagem virar o centro das atenções num grupo grande, as dificuldades aumentam em três.]==],
				},
				["Siege Mentality"] = {
					pt = [==[The Hunters Hunted II, pág. 132


Siege Mentality


A agência é sua família e são seus únicos amigos. Você não confia em civis nem em amadores para fazer aquilo que considera o seu trabalho, e políticos e legisladores só atrapalham a sua agência. Você até confiaria em outras agências de inteligência se elas provassem, ao menos uma vez, que conseguem achar o próprio traseiro com espelho e lanterna.

Sua postura tem uma série de efeitos em cascata. Primeiro, você é atrevido e mandão com os "civis", seja um agente do FBI falando com a polícia local, seja um operativo da CIA lidando com uma empresa privada de inteligência. Subtraia dois dados de todas as paradas de Empatia e Investigação ao lidar com amadores da sua área. Segundo, você fica na defensiva perto de outros membros da comunidade de inteligência, mesmo estando supostamente do mesmo lado. Some um à dificuldade de todas as rolagens de interação social com eles. Por fim, se a lei atrapalhar seu dever, você não pensa duas vezes antes de quebrá-la. O Narrador é encorajado a fazer seus superiores lhe darem uma bela bronca pelo desprezo escancarado ao procedimento.]==],
				},
				["Sire's Resentment"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 490


Sire's Resentment


Seu senhor não gosta de você e lhe deseja o mal. À menor oportunidade, ela buscará ativamente prejudicá-lo. Os aliados do seu senhor também trabalham contra você, e muitos anciões podem ter ressentimento pela sua figura.]==],
				},
				["Sleeping With the Enemy"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 492


Sleeping With the Enemy


Você tem algum tipo de ligação íntima com um membro de uma Seita oposta ou de um Clã inimigo. Pode ser um amante, um filho, um amigo ou um contato do outro lado da cerca mas, seja qual for a política envolvida, você mantém uma relação amistosa (ou mais que amistosa) com seu suposto inimigo. Seus laços estreitos com alguém do outro lado seriam considerados traição pelos seus superiores na Seita e, se descoberto, a pena certamente será a morte.]==],
				},
				["Slow Healing"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 483


Slow Healing


Você tem dificuldade para curar ferimentos. São necessários dois pontos de sangue para curar um nível de vitalidade de dano contundente ou letal, e você cura um nível de dano agravado a cada cinco dias (além dos cinco pontos de sangue e do gasto de Força de Vontade habituais).]==],
				},
				["Smell of the Grave"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 481


Smell of the Grave


Você exala um odor de umidade e terra recém-revirada, que perfume nenhum consegue disfarçar. Mortais na sua presença imediata ficam desconfortáveis, e por isso as dificuldades de todas as rolagens Sociais para afetar mortais aumentam em um.]==],
				},
				["Soft-Hearted"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 485


Soft-Hearted


Você não suporta ver os outros sofrerem. Evita qualquer situação que envolva causar dor física ou emocional a alguém, a menos que tenha sucesso numa rolagem de Força de Vontade (dificuldade 8). Você precisa ter Humanidade 7 ou mais para adquirir este Defeito — vampiros em Caminhos de Iluminação só podem adquiri-lo com aprovação do Narrador.]==],
				},
				["Special Responsibility"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 490


Special Responsibility


Pouco depois do seu Abraço, você se ofereceu para alguma tarefa a fim de ganhar respeito e aprovação dos vampiros ao seu redor. Agora você queria nunca ter aberto a maldita boca! Embora não receba nenhum crédito especial por cumprir esse dever, você perderia muito respeito se parasse. A natureza e os detalhes da tarefa devem ser acertados com o Narrador de antemão. As ideias vão de emprestar dinheiro a outros Cainitas a atuar como mensageiro ou até reunir vítimas para ritae (como os Banquetes de Sangue).]==],
				},
				["Speech Impediment"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 485


Speech Impediment


Você tem gagueira ou outro distúrbio de fala que atrapalha a comunicação verbal. As dificuldades de todas as rolagens que envolvam comunicação verbal aumentam em dois. Este Defeito deve ser interpretado sempre que possível.]==],
				},
				["Sphere Inept"] = {
					pt = [==[Book of Secrets, pág. 94


Sphere Inept


Um elemento específico da Realidade escapa a você. Por mais dedicado que seja a dominar suas complexidades, esse campo da magia continua sendo um desafio. Basicamente, é o inverso da Qualidade Esfera Natural, descrita acima; uma Esfera custa 130% a mais (arredondando para cima) para ser aprendida que as demais.

Custo (Esfera comum / Esfera de Afinidade): Esfera nova 13 pts · nível 2: 11/9 · nível 3: 21/19 · nível 4: 32/28 · nível 5: 42/37.

De novo, este Defeito só pode ser aplicado a uma Esfera (ainda bem!) e transparece na sua prática e no seu passado. Quem é inapto para compreender, digamos, o Tempo terá uma relação bem torta com horários e pontualidade.]==],
				},
				["Squeamish (1)"] = {
					pt = [==[Ghouls & Revenants, pág. 130


Squeamish (1)


Seu carniçal ou revenante pode até falar bonito, mas nunca esteve perto de violência de verdade. Diante da visão de sangue, você provavelmente não reagirá bem, e pode desmaiar, entrar em pânico ou sair correndo.

Em situações que envolvam tiroteio, combate sangrento ou uso agressivo de Disciplinas, role Força de Vontade (dificuldade 7). Se a rolagem falhar, sua personagem congela no lugar (se a Coragem dela for maior que o Autocontrole) ou foge do local (se o Autocontrole for maior que a Coragem).

A critério do Narrador, você pode ser obrigado a fazer um teste de Força de Vontade uma vez por cena cabível. Sua personagem não precisa estar diretamente envolvida na briga; pode ser apenas testemunha de uma facada. Ao acumular cinco sucessos numa mesma sessão, não são mais necessárias rolagens naquela noite de jogo. Uma demonstração especialmente sangrenta de violência, porém, pode exigir nova rolagem, a critério do Narrador.

Numa falha crítica, seu carniçal fica tão abalado pela cena macabra que não consegue agir pelo resto da cena. Ele fica congelado de choque e pode se sujar ou vomitar em resposta ao medo ou à repulsa.

Usado por: todos os carniçais e revenantes]==],
				},
				["Squeamish (3)"] = {
					pt = [==[Ghouls & Revenants, pág. 130


Squeamish (3)


Seu carniçal ou revenante pode até falar bonito, mas nunca esteve perto de violência de verdade. Diante da visão de sangue, você provavelmente não reagirá bem, e pode desmaiar, entrar em pânico ou sair correndo.

Em situações que envolvam tiroteio, combate sangrento ou uso agressivo de Disciplinas, role Força de Vontade (dificuldade 7). Se a rolagem falhar, sua personagem congela no lugar (se a Coragem dela for maior que o Autocontrole) ou foge do local (se o Autocontrole for maior que a Coragem).

A critério do Narrador, você pode ser obrigado a fazer um teste de Força de Vontade uma vez por cena cabível. Sua personagem não precisa estar diretamente envolvida na briga; pode ser apenas testemunha de uma facada. Ao acumular cinco sucessos numa mesma sessão, não são mais necessárias rolagens naquela noite de jogo. Uma demonstração especialmente sangrenta de violência, porém, pode exigir nova rolagem, a critério do Narrador.

Numa falha crítica, seu carniçal fica tão abalado pela cena macabra que não consegue agir pelo resto da cena. Ele fica congelado de choque e pode se sujar ou vomitar em resposta ao medo ou à repulsa.

Usado por: todos os carniçais e revenantes]==],
				},
				["Stench"] = {
					pt = [==[Lore of the Clans, pág. 161


Stench


A maioria dos Nosferatu adquire certo odor, mas você fede tanto que até seus irmãos de Clã acham difícil ficar por perto. Sua presença é anunciada pelo seu fedor, o que tira dois dados de todas as rolagens de Furtividade.]==],
				},
				["Stereotype"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 486


Stereotype


Você comprou de cabeça todas as histórias de vampiro que leu e ouviu. Usa capa ou purpurina no corpo, fala com sotaque e, de resto, age de forma caricata. Esse comportamento é constrangedor ao extremo para outros Cainitas, que provavelmente vão isolá-lo ou zombar de você (+2 de dificuldade em rolagens Sociais com vampiros que não compartilhem dos seus hábitos). Você também se destaca aos olhos dos caçadores.]==],
				},
				["Stigmata (2)"] = {
					pt = [==[Lore of the Clans, pág. 142


Stigmata (2)


Oráculos costumam ser marcados como mensageiros dos deuses. Suas marcas vêm na forma de ferimentos fantasmas que vertem sangue. O sangramento é leve mas incessante, e lhe custa um ponto de sangue extra todo dia, pouco antes de você despertar ao anoitecer.

A versão de 2 pontos deste Defeito significa ferimentos fáceis de esconder de olhares curiosos, como nas mãos ou no flanco. Você ganha +1 de dificuldade em todas as rolagens Sociais ao lidar com quem saiba da sua condição.

A versão de 4 pontos não pode ser escondida com facilidade, como olhos que sangram. A penalidade Social sobe para +2, e um dos seus Atributos também ganha +1 de dificuldade em todas as rolagens, por causa do sangue que verte sem parar.]==],
				},
				["Stigmata (4)"] = {
					pt = [==[Lore of the Clans, pág. 142


Stigmata (4)


Oráculos costumam ser marcados como mensageiros dos deuses. Suas marcas vêm na forma de ferimentos fantasmas que vertem sangue. O sangramento é leve mas incessante, e lhe custa um ponto de sangue extra todo dia, pouco antes de você despertar ao anoitecer.

A versão de 2 pontos deste Defeito significa ferimentos fáceis de esconder de olhares curiosos, como nas mãos ou no flanco. Você ganha +1 de dificuldade em todas as rolagens Sociais ao lidar com quem saiba da sua condição.

A versão de 4 pontos não pode ser escondida com facilidade, como olhos que sangram. A penalidade Social sobe para +2, e um dos seus Atributos também ganha +1 de dificuldade em todas as rolagens, por causa do sangue que verte sem parar.]==],
				},
				["Stone Tongue"] = {
					pt = [==[Lore of the Bloodlines, pág. 37


Stone Tongue


A transformação do Abraço não afetou só a sua aparência. Ela tornou fisicamente difícil você falar de forma correta e clara. Pode ser por causa de uma língua desajeitada, de presas feias ou de um bico de ave de rapina. Seja qual for a causa, você sofre +2 de dificuldade em qualquer rolagem Social que exija falar.]==],
				},
				["Strangeness"] = {
					pt = [==[Book of Secrets, pág. 85


Strangeness


Sua destreza metafísica de vez em quando distorce a realidade na sua presença, mesmo quando você não quer. Coisas esquisitas acontecem quando você não espera, e essas esquisitices parecem ter raiz no tipo de magia que você pratica. Um especialista em Entropia pode sofrer torções de probabilidade e decadência; um curandeiro afinado com a Vida descobre crescimentos e mutações estranhas nas formas de vida ao redor, enquanto um mago dotado em Forças entorta a física nas suas imediações. Esses fenômenos vêm e vão sem sua orientação ou controle. De forma perversa, quanto mais habilidoso você fica na magia, mais fortes ficam essas marés de estranheza.

Em termos de sistema, o Narrador decide, uma ou duas vezes por sessão, rolar seu Arete contra dificuldade 6. Se tiver sucesso, ele insere alguma ocorrência aleatória baseada numa Esfera que você possui – mais frequentemente, na sua Esfera de Afinidade. A grama pode crescer de repente, espelhos podem rachar, impressões psíquicas podem informá-lo sobre os hábitos sexuais de quem está do seu lado no elevador – esse tipo de coisa.

Se a rolagem falhar, nada de incomum acontece. Numa falha crítica, porém, um contragolpe de Paradoxo expele um ponto de Paradoxo da sua reserva atual para cada ponto que você tenha na Esfera de Afinidade; ou todo o Paradoxo atual, se você tiver menos que isso na reserva. (Se, por exemplo, Jinx tem três pontos em Entropia mas só um ponto de Paradoxo, o contragolpe dispersa esse único ponto.) Esses contragolpes pequenos não causam grande dano, mas, dada a natureza imprevisível deste Defeito, podem chegar em horas bem inconvenientes.]==],
				},
				["Stress Atavism"] = {
					pt = [==[Book of Secrets, pág. 53


Stress Atavism


Veja Mage 20, p. 644, e a Qualidade Furioso.]==],
				},
				["Sympathizer"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 490


Sympathizer


Você expressou publicamente simpatia por alguns dos objetivos e políticas dos inimigos da sua Seita. Suas opiniões abertas sobre o assunto o tornaram suspeito aos olhos da hierarquia da cidade, e você pode ser suspeito (ou preso) por traição.]==],
				},
				["Taint of Corruption"] = {
					pt = [==[Book of Secrets, pág. 96


Taint of Corruption


O mal tem um domínio íntimo sobre você. Seu espírito foi corrompido – possivelmente desde o nascimento, como nos Nephandi renascidos conhecidos como widderslainte – e você é, como dizem os lobisomens, "da Wyrm", queira você ou não. Isso não significa necessariamente que você se comporte de forma maligna.]==],
				},
				["Territorial"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 486


Territorial


Você é extremamente territorial: demarca uma área específica como seu terreno de caça e reage com agressividade a invasores. Se outro vampiro entrar no seu território sem convite, você precisa fazer uma rolagem de frenesi. Se falhar, ataca o intruso imediatamente e continua atacando até que ele esteja morto ou tenha deixado seu terreno de caça. Você reluta em sair do seu território, exceto em circunstâncias desesperadas.]==],
				},
				["Thaumaturgically Inept"] = {
					pt = [==[Lore of the Clans, pág. 219


Thaumaturgically Inept


Alguma coisa em você se recusa a responder à Taumaturgia. A magia simplesmente não funciona para você. Você não pode adquirir nenhuma capacidade na Disciplina Taumaturgia, nem em seus caminhos ou rituais. Para um Tremere, isso é duplamente difícil, já que a habilidade em Taumaturgia costuma ser a chave para uma posição dentro do Clã. Embora alguns escolham de bom grado ignorar os estudos taumatúrgicos e servir de outras formas, a inaptidão nunca é desculpada. Apenas Tremere podem adquirir este Defeito.]==],
				},
				["The Bard's Tongue"] = {
					pt = [==[Book of Secrets, pág. 82


The Bard's Tongue


Uma maldição o tornou incapaz de mentir. Ela pode até compeli-lo a dizer a verdade quando você luta para ficar calado. Pior ainda: você tende a dizer coisas que depois se revelam verdadeiras, mesmo sem nada saber sobre elas na hora. ("Não tente conseguir comida com aquele cara ali – ele está armado e tendo um dia muito ruim.") Você costuma fazer certa "cara" quando o impulso de dizer a verdade chega, e quem o conhece já aprendeu a reconhecer os sinais de uma "explosão de honestidade" antes mesmo de você abrir a boca.

A vida e as crônicas de Mage estão cheias de momentos em que é melhor manter a verdade guardada. Assim, para evitar dizer a proverbial verdade inconveniente (ou pior), você precisa gastar um ponto de Força de Vontade para ficar de boca fechada. Reprimir essa verdade também pode lhe custar um nível de vitalidade em dano contundente, se aquilo que você está segurando for uma daquelas "coisas que realmente precisam ser ditas" mas que não é inteligente dizer naquelas circunstâncias. ("Pois é, Agente Coragem, todo mundo sabe que você joga dos dois lados com todos os grupos – isso não é exatamente um 'segredo', não é mesmo?")]==],
				},
				["The Eighth"] = {
					pt = [==[Lore of the Bloodlines, pág. 5


The Eighth


Seu senhor é um dos Sete, os buscadores de Golconda diablerizadores que tentavam garantir que a riqueza espiritual da salvação não se perdesse com a Morte Final deles. Eles o escolheram como sucessor e o prepararam com orgulho para o seu dever sagrado. Você, por sua vez, sorriu diante das mentiras deles, ouviu a baboseira toda e correu para as montanhas na primeira oportunidade. Você é caçado sem trégua, não apenas pelos Tremere, mas pelo seu senhor, pelos outros Sete e por seus vários puxa-sacos. Você precisa ser no mínimo de Nona Geração para adquirir este Defeito.]==],
				},
				["The Largest Maw"] = {
					pt = [==[Lore of the Bloodlines, pág. 70


The Largest Maw


Por causa do tamanho das fileiras de dentes de tubarão do Nagaraja, ele tem dificuldade em se comunicar verbalmente. Fala por entre poças de saliva e às vezes morde os próprios dentes no processo. Isso o torna mais calado que os demais Nagaraja, mas também atrapalha situações em que a fala clara é obrigatória, como discursar ou recitar rituais delicados. Todas as dificuldades de rolagens em que a fala seja fator sobem +2.]==],
				},
				["Thin Blood"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 483


Thin Blood


Seu sangue é ralo, fraco, e não o sustenta bem. Todos os custos em pontos de sangue são dobrados (por exemplo, usar Disciplinas ligadas ao sangue ou curar dano), embora você perca apenas um ponto de sangue ao se erguer à noite. Além disso, você é incapaz de criar um laço de sangue, e as tentativas de gerar outros vampiros só dão certo uma vez em cinco.]==],
				},
				["Thirst for Innocence"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 486


Thirst for Innocence


A visão da inocência — de qualquer tipo — desperta em você uma sede de sangue terrível. Role Autocontrole ou Instintos, ou entra em frenesi e ataca a fonte da sua fome.]==],
				},
				["Thirteenth Generation"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 427


Thirteenth Generation


Por alguma reviravolta estranha do sobrenatural, você foi Abraçado por um membro da Décima Segunda Geração. Seu senhor pode nem ter esperado que isso desse certo, e a coisa certamente preocupa os poderosos, pois você é algo que decididamente não deveria existir. A dificuldade de qualquer rolagem para ativar suas Disciplinas aumenta em um. A critério do Narrador, você também pode enfrentar outras dificuldades aumentadas ao esbarrar em quem tem medo ou desconfiança do que você é. Considere seriamente adquirir também os Defeitos Não Pode Abraçar ou Sangue Fraco.]==],
				},
				["Throwback (1)"] = {
					pt = [==[Book of Secrets, pág. 85


Throwback (1)


Assombrado por uma vida passada (muitas vezes conforme o Antecedente de mesmo nome, descrito acima), você sofre com memórias terríveis e age de formas que, digamos, não são produtivas para a sua encarnação atual. Talvez você ainda deteste os clérigos que torturaram um "você" anterior por bruxaria 400 anos atrás; o cheiro de carne assando ainda o joga em ataques de pânico. Ou você tem vertigem e surtos de acrofobia por causa daquela vez em que uma encarnação anterior caiu do alto da muralha de um castelo. Você pode escorregar para sotaques arcaicos, línguas estrangeiras ou termos que não são exatamente atuais (nem socialmente aceitáveis) no mundo de hoje. Flashbacks, saltos temporais, comportamento inapropriado – tudo isso faz parte do pacote da vida que você leva agora.

Para cada ponto neste Defeito, até o máximo de cinco pontos (e dados), o Narrador rolará um dado contra dificuldade 8 quando surgir a possibilidade de uma vida passada afetar a sua vida presente. Quanto mais sucessos, mais aquela vida passada o afeta. Os sintomas dessa "síndrome do atavismo" em geral dependem do capricho do Narrador, mas você pode colaborar com ele para montar uma história (ou várias) das encarnações anteriores de que sua personagem se lembra, e então interpretar sintomas condizentes com elas. Em flashbacks especialmente fortes (três sucessos ou mais), você pode precisar rolar sua Força de Vontade (de novo, dificuldade 8) para conter a reação ao que a personagem recorda.

Descrito no Guide to the Traditions como Antecedente adverso de Vida Passada, este Defeito é um bom acompanhante daquele Antecedente, do Antecedente Sonho e de outras Qualidades e Defeitos ligados à reencarnação (Almas Gêmeas, Avatar Estilhaçado e Traços semelhantes descritos nesta seção). Com algumas mudanças cabíveis nos sintomas, você também pode descrever o Defeito Atavismo como manifestação de um Antecedente Lenda, ou como memórias de uma vida que remonta a vários séculos. Você preferiria esquecer as coisas que fez, e as que suportou, durante a Conquista das Américas, mas nunca consegue de verdade.]==],
				},
				["Throwback (2)"] = {
					pt = [==[Book of Secrets, pág. 85


Throwback (2)


Assombrado por uma vida passada (muitas vezes conforme o Antecedente de mesmo nome, descrito acima), você sofre com memórias terríveis e age de formas que, digamos, não são produtivas para a sua encarnação atual. Talvez você ainda deteste os clérigos que torturaram um "você" anterior por bruxaria 400 anos atrás; o cheiro de carne assando ainda o joga em ataques de pânico. Ou você tem vertigem e surtos de acrofobia por causa daquela vez em que uma encarnação anterior caiu do alto da muralha de um castelo. Você pode escorregar para sotaques arcaicos, línguas estrangeiras ou termos que não são exatamente atuais (nem socialmente aceitáveis) no mundo de hoje. Flashbacks, saltos temporais, comportamento inapropriado – tudo isso faz parte do pacote da vida que você leva agora.

Para cada ponto neste Defeito, até o máximo de cinco pontos (e dados), o Narrador rolará um dado contra dificuldade 8 quando surgir a possibilidade de uma vida passada afetar a sua vida presente. Quanto mais sucessos, mais aquela vida passada o afeta. Os sintomas dessa "síndrome do atavismo" em geral dependem do capricho do Narrador, mas você pode colaborar com ele para montar uma história (ou várias) das encarnações anteriores de que sua personagem se lembra, e então interpretar sintomas condizentes com elas. Em flashbacks especialmente fortes (três sucessos ou mais), você pode precisar rolar sua Força de Vontade (de novo, dificuldade 8) para conter a reação ao que a personagem recorda.

Descrito no Guide to the Traditions como Antecedente adverso de Vida Passada, este Defeito é um bom acompanhante daquele Antecedente, do Antecedente Sonho e de outras Qualidades e Defeitos ligados à reencarnação (Almas Gêmeas, Avatar Estilhaçado e Traços semelhantes descritos nesta seção). Com algumas mudanças cabíveis nos sintomas, você também pode descrever o Defeito Atavismo como manifestação de um Antecedente Lenda, ou como memórias de uma vida que remonta a vários séculos. Você preferiria esquecer as coisas que fez, e as que suportou, durante a Conquista das Américas, mas nunca consegue de verdade.]==],
				},
