				},
				["Tic/Twitch"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 481


Tic/Twitch


Você tem algum tipo de movimento repetitivo que faz em momentos de estresse, e ele entrega sua identidade na hora. Exemplos incluem uma tosse nervosa, torcer as mãos sem parar, estalar os dedos e assim por diante. Custa um ponto de Força de Vontade se abster do seu tique.]==],
				},
				["Tortured Artist"] = {
					pt = [==[Lore of the Clans, pág. 200


Tortured Artist


Nada é bom o bastante no seu trabalho. Por mais elogios que receba, você só enxerga as falhas e os erros. Isso leva a longos períodos de tédio, o que torna sua produção artística irregular, na melhor das hipóteses. Além disso, você se joga em acordos comerciais e situações sociais com intensidade, o que muitas vezes acaba em decepção amorosa, que gera a dor e a paixão que alimentam sua obra seguinte. Você sofre +1 de dificuldade em rolagens Sociais nas quais esteja sendo elogiado, cumprimentado ou tratado com respeito.]==],
				},
				["Touch of Frost"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 494


Touch of Frost


Plantas murcham quando você se aproxima e morrem ao seu toque. Seu toque suga o calor dos seres vivos, como se você fosse feito de gelo.]==],
				},
				["Troublemaker"] = {
					pt = [==[Book of Secrets, pág. 65


Troublemaker


Praticamente o inverso da Qualidade Santidade (p. 57): você projeta uma impressão de culpa mesmo quando não fez nada de errado. As pessoas o culpam por quase tudo, e as autoridades pegam mais pesado com você do que pegariam se você não parecesse um pequeno merdinha nocivo! Você passa a impressão de pecador nato, não importa como se comporte. Ora, se você vai ser punido faça o que fizer, talvez devesse ao menos se divertir um pouco antes de o chicote descer.]==],
				},
				["Turncoat"] = {
					pt = [==[Ghouls & Revenants, pág. 132


Turncoat


O Vira-Casaca é mais que um simples traidor. Revenantes que adquirem este Defeito traíram mais que laços de amizade: traíram também os laços de família e de dever. Em geral, um revenante com este Defeito decidiu que tem mais interesse em servir aos inimigos da própria família, e tomou as providências necessárias para isso.

A maioria dos revenantes Vira-Casaca entende as consequências dos próprios atos. Sabe que este Defeito exige que se protejam e se escondam dos antigos colegas; podem até esperar que suas famílias os cacem pela traição. Dependendo da natureza e da profundidade da traição, vampiros aliados podem decidir prestar ajuda na caçada.

Uma revenante Vira-Casaca provavelmente conquistou a confiança dos novos amigos matando um antigo aliado, amigo ou parente, ou entregando informação sensível, como o refúgio de um vampiro (antes) aliado ou as senhas de acesso às finanças e contas da família.

Apesar de estar protegida por um vampiro poderoso, por um Clã, por membros de uma Seita local ou por uma família revenante, personagens com este Defeito sabem que seus problemas estão longe do fim. Os novos aliados provavelmente serão céticos e podem não revelar nada além de detalhes menores. Afinal, se a Vira-Casaca traiu a própria família ou um mestre estando sob influência do laço de sangue, pode fazê-lo de novo.

Em geral, este Defeito rende mais em personagens envolvidos na política de uma organização maior. As consequências da traição de um revenante — digamos, um Grimaldi revelando segredos sobre o desejo da família de deixar a Sabá — costumam ser amplas e significativas. Assim, carniçais independentes também podem escolhê-lo quando fizer sentido. Um carniçal independente, porém, pode ter dificuldade em achar os aliados necessários para garantir sua sobrevivência, já que a maioria dos vampiros vai querer um laço de sangue com o traidor.

Usado por: revenantes, alguns carniçais independentes]==],
				},
				["Twisted Apprenticeship"] = {
					pt = [==[Book of Secrets, pág. 64


Twisted Apprenticeship


Alguém lhe ensinou tudo errado. Por alguma razão, o mentor que o apresentou ao mundo Desperto fez um trabalho péssimo, e agora você colhe os frutos. Ele pode ter lhe contado mentiras sobre outros grupos, enchido sua cabeça de besteira sobre a natureza da magia (embora, sejamos honestos, praticamente todo mundo faça isso) ou simplesmente se comportado como um idiota de marca maior e deixado a conta com você. Agora as pessoas o culpam por coisas que você não fez (ou que fez por ignorância), e a má fama e os ensinamentos piores do mentor grudam em você como um fedor capaz de matar deus. Você provavelmente se recupera algum dia, mas sua carreira Desperta começou de forma lastimável.]==],
				},
				["Unblinking"] = {
					pt = [==[Lore of the Clans, pág. 239


Unblinking


Seus olhos não se fecham. Nunca. Talvez você tenha deixado sua humanidade longe demais para manter esse tipo de hábito, ou talvez tenha moldado pela carne algum tipo de escama ocular transparente ou membrana nictitante. Sua esquisitice provavelmente deixa observadores atentos desconfortáveis, somando +1 à dificuldade de interações sociais amistosas com humanos, com Cainitas na Humanidade e com outros de sensibilidade mortal.]==],
				},
				["Uncanny (1)"] = {
					pt = [==[Book of Secrets, pág. 86


Uncanny (1)


Por mais discreto que tente ser, você continua notavelmente memorável para quem cruza com você. É o oposto exato de "arcano", e por isso este Defeito foi originalmente descrito como Antecedente adverso do Traço de mesmo nome; em vez de atravessar a vida quase invisível, você se destaca como uma Marca HIT num churrasco Verbena.

Por que exatamente você é memorável? É um brilho desumano por trás dos olhos? Um tom inquietante na voz? Um miasma metafísico que paira em volta, apesar da sua aparência aparentemente mundana? A grama cresce ou morre na sua sombra? Talvez os cães se encolham ao sentir sua aproximação. Pode haver um zumbido grave na sua presença, como um coro de moscas, ou um crepitar desconcertante de eletricidade que irradia da sua pele, perturbando sistemas elétricos de formas pequenas mas perceptíveis. Seja lá o que faça as pessoas se lembrarem de você, essa faceta da sua presença é um lembrete constante de que você não é como os outros.

Mais uma vez, o valor em pontos deste Defeito depende do quanto ele interfere na sua vida:

(1 ponto) Você se destaca numa multidão.

(2 pontos) É bem difícil esconder suas esquisitices.

(3 pontos) As pessoas se lembram de você muito depois de você ter ido embora.

(4 pontos) Você dá arrepios nas pessoas só por existir.

(5 pontos) Você assusta as pessoas só por existir.

Por natureza, este Defeito representa uma impressão inconfundível. Cada ponto nele acrescenta um dado à parada de quem estiver tentando notá-lo, reconhecê-lo ou furar suas tentativas de furtividade ou disfarce. (Você não achou mesmo que aquelas almas penadas gemendo iam calar a boca só porque você estava tentando passar pelos guardas, achou?) Você pode, porém, tentar encobrir sua presença estranha com uma rolagem de Inteligência + Manha, supondo que tenha algum meio de fazê-lo – é mais fácil esconder olhos vermelhos brilhantes com óculos escuros que fazer aquelas almas penadas sumirem por alguns minutos! A dificuldade dessas tentativas costuma ser 5 + o valor do seu Defeito Estranho; se, por exemplo, a esperta bioconstruto Victoria Carliotti tem dois pontos em Estranho por causa da pele perfeita demais, dos músculos ondulantes e dos olhos impossivelmente verdes, sua dificuldade de disfarce seria 7. Dito isso, este Defeito não aumenta a dificuldade de rolagens sociais e pode, conforme o que você esteja tentando fazer, até reduzi-la (opção do Narrador).

Apesar da natureza potencialmente grotesca deste Defeito, sua estranheza não precisa necessariamente significar que seus traços físicos sejam assustadores. Uma pessoa desumanamente linda ou perturbadoramente comum pode ser Estranha à sua maneira. Este Defeito é ótimo companheiro de diversas Qualidades e Defeitos Físicos – Traço Encantador, Hiperflexível, Medonho e assim por diante – e combina muito bem com Antecedentes como Lenda, Vida Passada ou Totem. (Veja as entradas correspondentes.)

Embora o Defeito Ecos possa manifestar fenômenos estranhos parecidos, este aqui representa uma distinção constante e reconhecível. Ainda que provavelmente encarne certos elementos das suas práticas metafísicas, ele não está preso à sua Ressonância nem às suas atividades – é parte inata de quem você é. Sua estranheza pode representar traços físicos (físico avantajado, pele metálica, olhos que refletem a eternidade e assim por diante); esquisitices metafísicas (uma aura sobrenatural, vozes desencarnadas ecoando, um raio de frio ao seu redor etc.); ou companhias bizarras (um desfile de gatinhos de asas cor-de-rosa, borboletas fumegantes, espíritos de coiote uivando ou bichos igualmente inexplicáveis). Basicamente, qualquer torção localizada no rabo da normalidade pode ser considerada sinal da sua natureza Estranha. Por "estranho", aliás, não queremos dizer necessariamente "sobrenatural". A imobilidade antinatural de um Terno Preto, a pele impecável de um Vitorioso, o carisma predatório de um "mágico" do Sindicato – são todos exemplos de tecnologia Iluminada estranhamente inquietante.]==],
				},
				["Uncanny (2)"] = {
