(5 pontos) Você assusta as pessoas só por existir.

Por natureza, este Defeito representa uma impressão inconfundível. Cada ponto nele acrescenta um dado à parada de quem estiver tentando notá-lo, reconhecê-lo ou furar suas tentativas de furtividade ou disfarce. (Você não achou mesmo que aquelas almas penadas gemendo iam calar a boca só porque você estava tentando passar pelos guardas, achou?) Você pode, porém, tentar encobrir sua presença estranha com uma rolagem de Inteligência + Manha, supondo que tenha algum meio de fazê-lo – é mais fácil esconder olhos vermelhos brilhantes com óculos escuros que fazer aquelas almas penadas sumirem por alguns minutos! A dificuldade dessas tentativas costuma ser 5 + o valor do seu Defeito Estranho; se, por exemplo, a esperta bioconstruto Victoria Carliotti tem dois pontos em Estranho por causa da pele perfeita demais, dos músculos ondulantes e dos olhos impossivelmente verdes, sua dificuldade de disfarce seria 7. Dito isso, este Defeito não aumenta a dificuldade de rolagens sociais e pode, conforme o que você esteja tentando fazer, até reduzi-la (opção do Narrador).

Apesar da natureza potencialmente grotesca deste Defeito, sua estranheza não precisa necessariamente significar que seus traços físicos sejam assustadores. Uma pessoa desumanamente linda ou perturbadoramente comum pode ser Estranha à sua maneira. Este Defeito é ótimo companheiro de diversas Qualidades e Defeitos Físicos – Traço Encantador, Hiperflexível, Medonho e assim por diante – e combina muito bem com Antecedentes como Lenda, Vida Passada ou Totem. (Veja as entradas correspondentes.)

Embora o Defeito Ecos possa manifestar fenômenos estranhos parecidos, este aqui representa uma distinção constante e reconhecível. Ainda que provavelmente encarne certos elementos das suas práticas metafísicas, ele não está preso à sua Ressonância nem às suas atividades – é parte inata de quem você é. Sua estranheza pode representar traços físicos (físico avantajado, pele metálica, olhos que refletem a eternidade e assim por diante); esquisitices metafísicas (uma aura sobrenatural, vozes desencarnadas ecoando, um raio de frio ao seu redor etc.); ou companhias bizarras (um desfile de gatinhos de asas cor-de-rosa, borboletas fumegantes, espíritos de coiote uivando ou bichos igualmente inexplicáveis). Basicamente, qualquer torção localizada no rabo da normalidade pode ser considerada sinal da sua natureza Estranha. Por "estranho", aliás, não queremos dizer necessariamente "sobrenatural". A imobilidade antinatural de um Terno Preto, a pele impecável de um Vitorioso, o carisma predatório de um "mágico" do Sindicato – são todos exemplos de tecnologia Iluminada estranhamente inquietante.]==],
				},
				["Uncanny (4)"] = {
					pt = [==[Book of Secrets, pág. 86


Uncanny (4)


Por mais discreto que tente ser, você continua notavelmente memorável para quem cruza com você. É o oposto exato de "arcano", e por isso este Defeito foi originalmente descrito como Antecedente adverso do Traço de mesmo nome; em vez de atravessar a vida quase invisível, você se destaca como uma Marca HIT num churrasco Verbena.

Por que exatamente você é memorável? É um brilho desumano por trás dos olhos? Um tom inquietante na voz? Um miasma metafísico que paira em volta, apesar da sua aparência aparentemente mundana? A grama cresce ou morre na sua sombra? Talvez os cães se encolham ao sentir sua aproximação. Pode haver um zumbido grave na sua presença, como um coro de moscas, ou um crepitar desconcertante de eletricidade que irradia da sua pele, perturbando sistemas elétricos de formas pequenas mas perceptíveis. Seja lá o que faça as pessoas se lembrarem de você, essa faceta da sua presença é um lembrete constante de que você não é como os outros.

Mais uma vez, o valor em pontos deste Defeito depende do quanto ele interfere na sua vida:

(1 ponto) Você se destaca numa multidão.

(2 pontos) É bem difícil esconder suas esquisitices.

(3 pontos) As pessoas se lembram de você muito depois de você ter ido embora.

(4 pontos) Você dá arrepios nas pessoas só por existir.

(5 pontos) Você assusta as pessoas só por existir.

Por natureza, este Defeito representa uma impressão inconfundível. Cada ponto nele acrescenta um dado à parada de quem estiver tentando notá-lo, reconhecê-lo ou furar suas tentativas de furtividade ou disfarce. (Você não achou mesmo que aquelas almas penadas gemendo iam calar a boca só porque você estava tentando passar pelos guardas, achou?) Você pode, porém, tentar encobrir sua presença estranha com uma rolagem de Inteligência + Manha, supondo que tenha algum meio de fazê-lo – é mais fácil esconder olhos vermelhos brilhantes com óculos escuros que fazer aquelas almas penadas sumirem por alguns minutos! A dificuldade dessas tentativas costuma ser 5 + o valor do seu Defeito Estranho; se, por exemplo, a esperta bioconstruto Victoria Carliotti tem dois pontos em Estranho por causa da pele perfeita demais, dos músculos ondulantes e dos olhos impossivelmente verdes, sua dificuldade de disfarce seria 7. Dito isso, este Defeito não aumenta a dificuldade de rolagens sociais e pode, conforme o que você esteja tentando fazer, até reduzi-la (opção do Narrador).

Apesar da natureza potencialmente grotesca deste Defeito, sua estranheza não precisa necessariamente significar que seus traços físicos sejam assustadores. Uma pessoa desumanamente linda ou perturbadoramente comum pode ser Estranha à sua maneira. Este Defeito é ótimo companheiro de diversas Qualidades e Defeitos Físicos – Traço Encantador, Hiperflexível, Medonho e assim por diante – e combina muito bem com Antecedentes como Lenda, Vida Passada ou Totem. (Veja as entradas correspondentes.)

Embora o Defeito Ecos possa manifestar fenômenos estranhos parecidos, este aqui representa uma distinção constante e reconhecível. Ainda que provavelmente encarne certos elementos das suas práticas metafísicas, ele não está preso à sua Ressonância nem às suas atividades – é parte inata de quem você é. Sua estranheza pode representar traços físicos (físico avantajado, pele metálica, olhos que refletem a eternidade e assim por diante); esquisitices metafísicas (uma aura sobrenatural, vozes desencarnadas ecoando, um raio de frio ao seu redor etc.); ou companhias bizarras (um desfile de gatinhos de asas cor-de-rosa, borboletas fumegantes, espíritos de coiote uivando ou bichos igualmente inexplicáveis). Basicamente, qualquer torção localizada no rabo da normalidade pode ser considerada sinal da sua natureza Estranha. Por "estranho", aliás, não queremos dizer necessariamente "sobrenatural". A imobilidade antinatural de um Terno Preto, a pele impecável de um Vitorioso, o carisma predatório de um "mágico" do Sindicato – são todos exemplos de tecnologia Iluminada estranhamente inquietante.]==],
				},
