				},
				["Unclean (2)"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 421


Unclean (2)


Seja um traço remanescente da sua vida mortal, seja um efeito colateral infeliz do seu Abraço, sua pele está marcada de tal forma que a maioria dos observadores casuais supõe que você é leproso (ou que ao menos carrega algum tipo de peste). Você pode ter a entrada barrada em grandes cidades, ser expulso da maioria dos estabelecimentos ou ser alvo de tentativas equivocadas de cura ou caridade. Com 3 pontos, você de fato tem lepra (ou outra doença contagiosa e visível). Nosferatu que adquirem este Defeito recebem apenas 1 ponto por ele e sofrem seus efeitos completos (3 pontos).]==],
				},
				["Unclean (3)"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 421


Unclean (3)


Seja um traço remanescente da sua vida mortal, seja um efeito colateral infeliz do seu Abraço, sua pele está marcada de tal forma que a maioria dos observadores casuais supõe que você é leproso (ou que ao menos carrega algum tipo de peste). Você pode ter a entrada barrada em grandes cidades, ser expulso da maioria dos estabelecimentos ou ser alvo de tentativas equivocadas de cura ou caridade. Com 3 pontos, você de fato tem lepra (ou outra doença contagiosa e visível). Nosferatu que adquirem este Defeito recebem apenas 1 ponto por ele e sofrem seus efeitos completos (3 pontos).]==],
				},
				["Uncommon Vitae Preference"] = {
					pt = [==[Lore of the Clans, pág. 261


Uncommon Vitae Preference


Sua fonte preferida de vitae é rara até para os padrões do seu Clã, algo como "só veteranos da Guerra da Coreia", "só juízes federais" ou "só virgens acima dos 40". A dificuldade de todas as rolagens de caça da sua personagem aumenta em +2, até o máximo de 9.]==],
				},
				["Uncontrollable Night Sight"] = {
					pt = [==[Lore of the Clans, pág. 123


Uncontrollable Night Sight


Sua visão noturna é boa, mas você não consegue desligá-la. Embora enxergue com facilidade nas sombras mais fundas, qualquer luz é quase cegante para você. Você sofre penalidades tanto maiores quanto mais iluminado for o ambiente, na proporção inversa das penalidades padrão para escuridão. Até ficar de pé numa sala bem iluminada é desconfortável para você.]==],
				},
				["Unconvinced"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 485


Unconvinced


Você não vê necessidade nas ideologias centrais da sua Seita ou do seu Clã, e disse isso publicamente. Sua posição o tornou suspeito aos olhos dos seus superiores, e pode ter atraído também a atenção dos seus inimigos.]==],
				},
				["Unholy Stain"] = {
					pt = [==[Dark Ages Tome of Secrets, pág. 108


Unholy Stain


Sua alma está manchada de sacrilégio. Alguns nascem ou são Abraçados assim; a maioria ganha a mancha com juramentos perversos e atos torpes. Ao interagir com qualquer mortal, suas dificuldades Sociais aumentam em um, pois as pessoas se sentem antinaturalmente desconfortáveis na sua presença. Além disso, pessoas de fé se sentem compelidas à hostilidade quando estão perto de você. A postura inicial delas é sempre agressiva, e basta pouco para provocá-las à violência. Mortais com Fé Verdadeira o reconhecem à primeira vista, e muitas vezes atacam.]==],
				},
				["Unlucky (1)"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 427


Unlucky (1)


Você é espetacularmente azarado. O desastre segue seus passos. Você é magneticamente atraído pelo infortúnio. Com 1 ponto, chove sempre que você esquece o casaco. Com 3 pontos, é raro você se recuperar de um fracasso com elegância. Com 5 pontos, quase tudo o que você tenta acaba em catástrofe. Um número de vezes por dia igual aos pontos que você tem neste Defeito, o Narrador pode obrigá-lo a rolar de novo uma rolagem bem-sucedida e ficar com o segundo resultado. Sortudo e Azarado não são mutuamente exclusivos mas, para simplificar, a mesma rolagem não pode ser modificada pelos dois ao mesmo tempo. Ou seja: se uma rerrolagem de Sortudo foi usada, o Narrador não pode obrigá-lo a rolar de novo a rerrolagem.]==],
				},
				["Unlucky (2)"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 427


Unlucky (2)


Você é espetacularmente azarado. O desastre segue seus passos. Você é magneticamente atraído pelo infortúnio. Com 1 ponto, chove sempre que você esquece o casaco. Com 3 pontos, é raro você se recuperar de um fracasso com elegância. Com 5 pontos, quase tudo o que você tenta acaba em catástrofe. Um número de vezes por dia igual aos pontos que você tem neste Defeito, o Narrador pode obrigá-lo a rolar de novo uma rolagem bem-sucedida e ficar com o segundo resultado. Sortudo e Azarado não são mutuamente exclusivos mas, para simplificar, a mesma rolagem não pode ser modificada pelos dois ao mesmo tempo. Ou seja: se uma rerrolagem de Sortudo foi usada, o Narrador não pode obrigá-lo a rolar de novo a rerrolagem.]==],
				},
				["Unlucky (3)"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 427


Unlucky (3)


Você é espetacularmente azarado. O desastre segue seus passos. Você é magneticamente atraído pelo infortúnio. Com 1 ponto, chove sempre que você esquece o casaco. Com 3 pontos, é raro você se recuperar de um fracasso com elegância. Com 5 pontos, quase tudo o que você tenta acaba em catástrofe. Um número de vezes por dia igual aos pontos que você tem neste Defeito, o Narrador pode obrigá-lo a rolar de novo uma rolagem bem-sucedida e ficar com o segundo resultado. Sortudo e Azarado não são mutuamente exclusivos mas, para simplificar, a mesma rolagem não pode ser modificada pelos dois ao mesmo tempo. Ou seja: se uma rerrolagem de Sortudo foi usada, o Narrador não pode obrigá-lo a rolar de novo a rerrolagem.]==],
				},
				["Unlucky (4)"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 427


Unlucky (4)


Você é espetacularmente azarado. O desastre segue seus passos. Você é magneticamente atraído pelo infortúnio. Com 1 ponto, chove sempre que você esquece o casaco. Com 3 pontos, é raro você se recuperar de um fracasso com elegância. Com 5 pontos, quase tudo o que você tenta acaba em catástrofe. Um número de vezes por dia igual aos pontos que você tem neste Defeito, o Narrador pode obrigá-lo a rolar de novo uma rolagem bem-sucedida e ficar com o segundo resultado. Sortudo e Azarado não são mutuamente exclusivos mas, para simplificar, a mesma rolagem não pode ser modificada pelos dois ao mesmo tempo. Ou seja: se uma rerrolagem de Sortudo foi usada, o Narrador não pode obrigá-lo a rolar de novo a rerrolagem.]==],
				},
				["Unlucky (5)"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 427


Unlucky (5)


Você é espetacularmente azarado. O desastre segue seus passos. Você é magneticamente atraído pelo infortúnio. Com 1 ponto, chove sempre que você esquece o casaco. Com 3 pontos, é raro você se recuperar de um fracasso com elegância. Com 5 pontos, quase tudo o que você tenta acaba em catástrofe. Um número de vezes por dia igual aos pontos que você tem neste Defeito, o Narrador pode obrigá-lo a rolar de novo uma rolagem bem-sucedida e ficar com o segundo resultado. Sortudo e Azarado não são mutuamente exclusivos mas, para simplificar, a mesma rolagem não pode ser modificada pelos dois ao mesmo tempo. Ou seja: se uma rerrolagem de Sortudo foi usada, o Narrador não pode obrigá-lo a rolar de novo a rerrolagem.]==],
				},
				["Unproven"] = {
					pt = [==[Lore of the Clans, pág. 123


Unproven


De algum modo, você não conseguiu provar que é digno do nome Lasombra. Talvez seu senhor não o tenha testado o bastante, ou talvez a oportunidade de provar seu valor não tenha aparecido. Seja qual for a razão, você não é de fato considerado parte do Clã. Todo trato social com outros Lasombra sofre penalidade de -3 dados. Você também não pode ser escolhido para julgar nas Cortes de Sangue.]==],
				},
				["Unsanctioned Embrace"] = {
					pt = [==[Lore of the Bloodlines, pág. 4


Unsanctioned Embrace


Lázaro decretou que nenhum Precursor deveria Abraçar, mas seu senhor não deu ouvidos. Você é irremediavelmente verde e indigno da vitae que corre nas suas veias. Até realizar atos à altura da nobreza do seu sangue, sua existência é evitada como mau agouro. Aumente em dois as dificuldades de todas as ações Sociais que envolvam sua linhagem.]==],
				},
				["Uppity"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 492


Uppity


Você tem orgulho do seu novo status na Seita — tanto orgulho que abriu a boca demais com outros Cainitas e fez alguns inimigos. Vampiros mais sábios riem de você e creditam sua grosseria à juventude, mas outros o acham arrogante e ofensivo. Esses inimigos vão agir para constrangê-lo ou prejudicá-lo. Além disso, você sofre +2 de dificuldade em todas as rolagens Sociais contra qualquer vampiro que tenha afastado com sua tagarelice — e talvez você nem saiba quem são.

A critério do Narrador, você também pode ser obrigado a fazer uma rolagem de Força de Vontade (dificuldade 6) para manter a boca fechada sempre que surgir oportunidade de se gabar da sua matilha, do seu Clã ou do seu status.]==],
				},
				["Vanilla"] = {
					pt = [==[Book of Secrets, pág. 48


Vanilla


Meus deuses, como você é inocente! Num mundo cheio de magia sexual e jogos de poder, você é o cordeirinho que se afastou demais de casa. As piadas passam por cima de você, as pistas lhe escapam, e referências a qualquer coisa mais crua que um filme da Disney vão direto para o alto da sua cabeça. Talvez você tenha crescido num lugar isolado, com pais superprotetores; ou talvez esteja em negação sobre o que vê ao redor, porque a vida não pode ser tão distorcida assim… ou pode? De todo modo, agarre-se firme à sua inocência. Uma vez perdida, ela não volta nunca mais!]==],
				},
				["Vassal of the Clan"] = {
					pt = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, pág. 179


Vassal of the Clan


Por predisposição natural ou por maldição, você carrega um laço de sangue permanente de um ponto com os de uma Geração abaixo, de dois pontos com os de duas Gerações abaixo e de três pontos com os de três ou mais Gerações abaixo da sua dentro do seu próprio Clã. Esses laços se sobrepõem a qualquer outro laço de sangue que você venha a adquirir em jogo. Isso pode ser um grande risco para membros da Mão, já que o sangue impõe lealdades a vampiros potencialmente perigosos ou, pior, a ideologias heréticas.]==],
				},
				["Vengeful"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 486


Vengeful


Você tem contas a acertar, contraídas ainda em vida ou depois do Abraço. Você é obcecado por se vingar de um indivíduo ou grupo, e essa é sua prioridade absoluta em qualquer situação em que encontre o objeto da sua vingança. Você pode resistir temporariamente à sua necessidade de vingança gastando um ponto de Força de Vontade.]==],
				},
				["Venomous Bite"] = {
					pt = [==[Lore of the Clans, pág. 67


Venomous Bite


Você desenvolveu glândulas de veneno no céu da boca. O veneno é uma neurotoxina virulenta, fatal para mortais, embora Cainitas e outras criaturas sobrenaturais não sejam afetados. Você, claro, é imune. O problema é que você não tem controle nenhum sobre essas glândulas. Ao morder, você sempre injeta o veneno, o que em geral mata as vítimas humanas. Você precisa aprender a se alimentar de outras formas, talvez tirando o sangue de que precisa com uma seringa ou uma lâmina, se não quiser matar toda vez que se alimentar.]==],
				},
				["Victim of the Masquerade"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 486


Victim of the Masquerade


A máquina de propaganda da Camarilla fez bom demais o trabalho dela em você. Mesmo depois do Abraço, você se recusou a acreditar que era um vampiro. Continua convencido de que há alguma explicação lógica para a sua condição, e passa todo o tempo que pode procurando por ela. Você também tem dificuldade em se alimentar, e pode insistir em tentar comer comida comum. Nenhum desses hábitos faz de você companhia lá muito agradável para outros Cainitas. Este Defeito precisa ser interpretado o tempo todo, e em geral é adquirido por vampiros da Camarilla.]==],
				},
				["Vitae Sink"] = {
					pt = [==[Ghouls & Revenants, pág. 139


Vitae Sink


Por alguma razão, seu carniçal ou revenante metaboliza a vitae mais rápido que os outros. Você precisa ser alimentado a cada duas semanas, e não uma vez por mês, ou corre o risco de perder todos os Traços sobrenaturais e reverter ao seu estado natural. Poucos carniçais com este Defeito duram além do tempo natural de vida, a menos que seus domitores sejam especialmente devotados a eles. Nesse ritmo acelerado, porém, é provável que alimentações sejam perdidas, e é por isso que este Defeito é mortal para carniçais independentes.

Revenantes que sofrem de Sorvedouro de Vitae repõem sua vitae natural na metade da velocidade normal.

Usado por: a maioria dos carniçais e revenantes]==],
				},
				["Vulgar"] = {
					pt = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, pág. 178


Vulgar


Tato é um conceito estrangeiro para você, e sua fama é a de ser áspero e desagradável em geral. Rolagens que envolvam boas maneiras ou situações delicadas sofrem +1 de dificuldade.]==],
				},
				["Vulnerability (1)"] = {
					pt = [==[Book of Secrets, pág. 86


Vulnerability (1)


Alguma substância perigosa pode selar a sua ruína. Por causa de uma fraqueza paranormal – uma maldição, um Defeito de Paradoxo, um capricho de crença ou de lenda cultural –, você sofre dano extraordinário daquele material maligno. Talvez você resseque à luz do sol, fuja do cheiro de rosas ou derreta quando meninas insuportáveis do interior jogam água na sua cara. Essa substância em geral não é fatal para a maioria (Desperta ou não), mas é morte em potencial para você.

Sua vulnerabilidade à substância em questão tem dois níveis possíveis: Enfraquecimento, que causa um nível de vitalidade agravado por turno de contato com ela; e Perigo mortal, que causa três níveis agravados por turno de contato.

O valor deste Defeito se baseia em dois fatores: o quanto a substância fatal é comum e o quanto ela o afeta.

(2 pontos) Você pode ser mortalmente ferido pelo contato com algo quase impossível de obter (o som da flauta de Pã, uma lasca da Vera Cruz), ou enfraquecido por uma substância raríssima (um pedaço de rocha lunar, o dente de um leão idoso).

(3 pontos) Ferimento mortal por uma substância raríssima, ou fraqueza causada por algo relativamente escasso e não obviamente nocivo (açafrão, terra de sepultura, penas de corvo).

(4 pontos) Ferimento mortal por algo relativamente escasso, ou fraqueza causada por uma substância comum (água de chuva, prata, o choro de um bebê).

(5 pontos) Uma substância comum lhe causa ferimento mortal.

(+1 ponto) Você morre instantaneamente ao contato com a substância.

(+1 ponto) A mera presença da substância significa morte instantânea para você.

(-1 ponto) A substância precisa primeiro causar dano por um ferimento comum (uma facada, veneno ingerido, uma bala de prata) antes de poder feri-lo.

O dano deste Defeito não pode ser absorvido, a menos que você use algum tipo de armadura apropriada que impeça a exposição à substância. (Sendo dano agravado, ele normalmente já não deveria ser absorvido, mas magos têm meios de contornar essas trivialidades.) Sua história deve trazer a razão dessa vulnerabilidade potencialmente fatal, e ela também deve estar amarrada ao seu foco mágico – um magnata Macho Alfa dificilmente vai arder ao contato com água benta, embora possa ser divertido espalhar um pouco dela por Wall Street só para ter certeza! (Isso certamente explicaria algumas coisas.)]==],
				},
