				},
				["Vulnerability to Silver"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 482


Vulnerability to Silver


Para você, a prata é tão dolorosa e mortal quanto os raios do sol. Você sofre ferimentos agravados de qualquer arma de prata (balas, facas etc.), e o simples toque de objetos de prata o incomoda.]==],
				},
				["Ward"] = {
					pt = [==[Book of Secrets, pág. 66


Ward


Magos raramente atravessam a vida sozinhos. E, quando certos companheiros – amantes, filhos, parceiros, pais, amigos próximos, até empregadores – dependem de você, essa falta de solidão pode virar um passivo. Este Defeito representa uma personagem, ou um grupo delas, que exige atenção constante da sua parte. Sua vida é um perigo para elas, e as necessidades delas muitas vezes trazem perigo para você também. Tutelados costumam se meter em encrenca, precisar de resgate e fuçar aspectos da sua vida que você preferia que deixassem em paz. É o amor que o prende ao seu tutelado? O dever? Um juramento? Obrigações familiares? Um trabalho, como guarda-costas, professor ou médico? Seja qual for a razão, cada tutelado é parte essencial da sua vida. A vida dele é a sua prioridade.

Embora personagens Tuteladas possam ter uma ou outra habilidade útil, elas são gente não Desperta, e não magos, Gente da Noite, familiares ou outras entidades poderosas. Dito isso, você pode adquirir o Defeito Tutelado para representar um vínculo especial com um Lacaio, um membro do seu Culto ou um dos seus Espiões. Qualidades como Família Solidária ou Amor Verdadeiro (e Defeitos como Problemas de Família) combinam bem com este Traço. Tutelados também não precisam ser humanos – seu cão, seu gato, seu cavalo… um animal que dependa de você também pode ser um tutelado. Você pode adquirir este Defeito mais de uma vez, para representar vários dependentes. Pois é, há razões para os magos evitarem famílias grandes!

Obviamente, cada tutelado é um personagem do Narrador, com todas as agendas e complicações que isso acarreta. Essa pessoa pode não contar como testemunha Adormecida no que toca à sua magia… mas, se você a manteve no escuro quanto à sua vida e à sua natureza verdadeiras, ela ainda pode contar como testemunha ao menos na primeira experiência com esse tipo de "realidade".]==],
				},
				["Weak Blood"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 428


Weak Blood


Alguma coisa diminuiu seu vigor sobrenatural e reduziu suas capacidades como vampiro. Onde outros comandam sem esforço os dons de Lilith, você luta. Nenhuma Disciplina que você conheça pode passar de 4. Custa o dobro do normal em pontos de sangue controlar qualquer capacidade vampírica. Você precisa dar a alguém seis goles do seu sangue débil para que essa pessoa vire sua serva, e não tem potência para criar um carniçal nem gerar um filho. Este efeito também cobre as desvantagens do Defeito Não Pode Abraçar (p. 427), de modo que os dois são mutuamente exclusivos.]==],
				},
				["Weak-Willed"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 486


Weak-Willed


Você é altamente suscetível à Dominação e à intimidação alheia; tentativas de Dominação o afetam automaticamente, a menos que quem use a Disciplina seja de Geração mais alta, e suas dificuldades para resistir a habilidades Sociais como Intimidação ou Liderança, assim como a magias ou feitiços que alteram a mente, aumentam em dois. Seu Traço de Força de Vontade nunca pode passar de 4.]==],
				},
				["Whimsy"] = {
					pt = [==[Book of Secrets, pág. 48


Whimsy


Você fica bobo sob estresse. É uma tática de fuga e, embora esse comportamento possa ser adorável em doses pequenas, sua veia caprichosa acaba ficando meio irritante com o tempo, especialmente para quem tem de lidar com você sacando fantoches de mão no meio de uma discussão ou jogando uvas no decote da sua colega de coven enquanto ela tenta ter uma conversa séria com você. Em situações especialmente tensas, você pode precisar de uma rolagem de Força de Vontade (dificuldade 6) para não fazer palhaçada. Ora, você não consegue evitar, certo, se está só tentando aliviar o clima? Nossa, por que a magia tem de ser tão séria assim…?]==],
				},
				["Witch-Hunted"] = {
					pt = [==[Book of Secrets, pág. 68


Witch-Hunted


As Massas querem você morto. Você foi exposto pelo que é e pelo que pode fazer, e por isso vários grupos não Despertos decidiram eliminá-lo como a abominação em que você se transformou. Esses caçadores podem ser autoridades policiais, grupos religiosos, seitas fanáticas, turbas furiosas, caçadores imbuídos, peões da Gente da Noite… sejam quem forem, essas pessoas representam ameaça séria à sua existência, com poder para acabar com você e determinação para tanto. Suas Artes sozinhas não conseguem detê-los, e um confronto doloroso (ou três) é, infelizmente, inevitável.]==],
				},
				["Acute Sense"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 479


Acute Sense


Um dos seus sentidos é excepcionalmente aguçado, seja a visão, a audição, o olfato, o tato ou o paladar. As dificuldades de todas as tarefas que envolvam esse sentido em particular são reduzidas em dois. Esta Qualidade pode ser combinada com a Disciplina Auspícios para produzir uma acuidade sensorial sobre-humana.]==],
				},
				["Acute Senses (1)"] = {
					pt = [==[Book of Secrets, pág. 35


Acute Senses (1)


Veja Mage 20, pp. 642-643.]==],
				},
				["Acute Senses (3)"] = {
					pt = [==[Book of Secrets, pág. 35


Acute Senses (3)


Veja Mage 20, pp. 642-643.]==],
				},
				["Addictive Blood"] = {
					pt = [==[Lore of the Clans, pág. 67


Addictive Blood


Você não apenas trafica narcóticos; pelas bênçãos do Deus Sombrio, você é a droga perfeita. Seu sangue é especialmente delicioso para os outros, Cainitas ou rebanho. Quem provar o seu sangue precisa, em qualquer cena seguinte em que o encontrar, beber de novo ou gastar um ponto de Força de Vontade para evitar as pontadas da fissura. Essa fissura soma +2 de dificuldade a qualquer rolagem Mental ou Social. Setitas com esta Qualidade acham muito mais fácil criar um laço de sangue com um adversário, pois, uma vez provada a vitae maculada, ele fará quase qualquer coisa para bebê-la de novo.]==],
				},
				["Additional Discipline"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 494


Additional Discipline


Você pode adquirir uma Disciplina adicional (a critério do Narrador) como se fosse uma Disciplina de Clã. Todos os custos para aprendê-la são pagos como se ela fosse nativa do seu Clã. Uma personagem não pode adquirir esta Qualidade mais de uma vez, e vampiros Caitiff não podem adquiri-la.]==],
				},
				["Advanced Tech (1)"] = {
					pt = [==[Lore of the Bloodlines, pág. 99


Advanced Tech (1)


Você tem um dispositivo (ou possivelmente alguns) de projeto avançado. Embora os Brujah Verdadeiros não sejam especialmente bons em inovação, são bons em fazer melhorias. Assim, esse dispositivo não tem funções especiais indisponíveis aos seus contemporâneos, mas funciona bem melhor. Ele reduz pela metade a chance de falha mecânica (como um travamento), e todos os usos são feitos com -1 na dificuldade. O Narrador deve decidir o custo desta Qualidade conforme a quantidade de itens que a personagem tem e o quanto eles são poderosos.]==],
				},
				["Advanced Tech (2)"] = {
