				},
				["Alcohol /Drug Tolerance (1)"] = {
					pt = [==[Book of Secrets, pág. 35


Alcohol /Drug Tolerance (1)


Você bebe todo mundo debaixo da mesa, ou de outro modo aguenta a festa até o último cair. Em termos de sistema, esta Qualidade permite uma rolagem de Vigor (dificuldade 7) para se livrar dos efeitos da intoxicação – talento útil para Extáticos festeiros e Ternos Pretos de couro grosso!

Na forma de um ponto, esta Qualidade só funciona para drogas "naturais" (bebida, maconha, cocaína etc.), não para concocções sintetizadas em laboratório (LSD, metanfetamina, krokodil etc.). Por dois pontos, porém, ela neutraliza os efeitos psicoativos de qualquer droga, a menos que aquela droga tenha sido criada como veículo de um Efeito mágico baseado em Esferas. (Ou seja, digamos, uma pílula que entrega um Efeito de Vida 3/Mente 3 a quem a toma, ao contrário de uma pílula "comum" que um mago usa como parte dos instrumentos de foco Drogas e Venenos ou Beberagens, Poções e afins, conforme detalhado em Mage 20, pp. 588-600.) Nesse último caso, a personagem precisa usar contramagia; esta Qualidade não ajuda contra tais drogas. Substâncias "Despertas", porém (conforme Mage 20, p. 443), são tratadas como "concocções sintetizadas" mesmo que sejam, em todos os outros aspectos, "naturais".

Para uma resistência mais ampla a toxinas, veja Resistência a Venenos, abaixo.]==],
				},
				["Alcohol /Drug Tolerance (2)"] = {
					pt = [==[Book of Secrets, pág. 35


Alcohol /Drug Tolerance (2)


Você bebe todo mundo debaixo da mesa, ou de outro modo aguenta a festa até o último cair. Em termos de sistema, esta Qualidade permite uma rolagem de Vigor (dificuldade 7) para se livrar dos efeitos da intoxicação – talento útil para Extáticos festeiros e Ternos Pretos de couro grosso!

Na forma de um ponto, esta Qualidade só funciona para drogas "naturais" (bebida, maconha, cocaína etc.), não para concocções sintetizadas em laboratório (LSD, metanfetamina, krokodil etc.). Por dois pontos, porém, ela neutraliza os efeitos psicoativos de qualquer droga, a menos que aquela droga tenha sido criada como veículo de um Efeito mágico baseado em Esferas. (Ou seja, digamos, uma pílula que entrega um Efeito de Vida 3/Mente 3 a quem a toma, ao contrário de uma pílula "comum" que um mago usa como parte dos instrumentos de foco Drogas e Venenos ou Beberagens, Poções e afins, conforme detalhado em Mage 20, pp. 588-600.) Nesse último caso, a personagem precisa usar contramagia; esta Qualidade não ajuda contra tais drogas. Substâncias "Despertas", porém (conforme Mage 20, p. 443), são tratadas como "concocções sintetizadas" mesmo que sejam, em todos os outros aspectos, "naturais".

Para uma resistência mais ampla a toxinas, veja Resistência a Venenos, abaixo.]==],
				},
				["Alien Perfection"] = {
					pt = [==[Lore of the Bloodlines, pág. 59


Alien Perfection


Você possui uma beleza perturbadora em sua perfeição. As pessoas ficam maravilhadas diante da sua forma impecável, enquanto uma náusea inexplicável sobe sem que percebam. A dificuldade de qualquer rolagem de Aparência é reduzida em três. Uma rolagem de Vigor é exigida de quem passar mais de uma cena na sua presença, se for a primeira vez que o encontram. Uma falha os afasta de você com uma sensação de doença sacudindo o corpo.]==],
				},
				["Ambidextrous"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 480


Ambidextrous


Você tem alto grau de destreza com a mão não dominante e consegue realizar tarefas com a mão "errada" sem penalidade. As regras de ações múltiplas continuam valendo, mas você não sofre penalidade de dificuldade ao usar duas armas ou ao ser forçado a usar a mão não dominante.]==],
				},
				["Animal Magnetism"] = {
					pt = [==[Book of Secrets, pág. 54


Animal Magnetism


Embora talvez não envolva beleza convencional, você possui um tipo primal de atratividade. Suas rolagens sociais subtraem 2 da dificuldade quando você tenta encantar, seduzir ou de outro modo impressionar alguém apelando à natureza carnal dessa pessoa. Esse benefício normalmente não vale para ameaças ou tentativas de intimidação, embora aplicações espertas de puro apelo sexual possam ser bastante perturbadoras, o que pode render ameaças bem eficazes…]==],
				},
				["Antitoxin Blood"] = {
					pt = [==[Lore of the Clans, pág. 181


Antitoxin Blood


Embora vampiros costumem ser imunes a drogas e venenos mortais, existem venenos sobrenaturais capazes de afetar a fisiologia Cainita. Um Ravnos com esta Qualidade é imune a todas as formas de droga e veneno, inclusive às peçonhas e toxinas de criaturas sobrenaturais ou criadas por poderes sobrenaturais.]==],
				},
				["Apostate (Modern)"] = {
					pt = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, pág. 178


Apostate (Modern)


Desde sua origem, os Baali Nergali subvertem membros de outros Clãs para as próprias fileiras. Conhecidos como Apóstatas, os iniciados são primeiro drenados por completo por um senhor de ninho Baali, que então extrai o coração ainda batendo de uma vítima mortal, o enche com o próprio sangue e o enterra numa poça de vísceras dentro de um Poço de Sacrifício. O iniciado nada por entre os corpos desmembrados e os restos viscosos para achar e consumir o coração. Assim, os Nergali não fazem vítimas daqueles que Abraçam; os candidatos precisam conquistar aquilo pela força de vontade.

Apóstatas trocam uma Disciplina de Clã por Daimoinon, mas em troca ganham a fraqueza de Clã Baali somada à sua fraqueza de Clã original. Eles ainda passam com relativa facilidade por membros dos Clãs de origem, mas qualquer filho que Abracem é indistinguível de um Baali comum. Além disso, esse filho não compartilha nenhuma das Disciplinas ou fraquezas de Clã do antigo Clã do senhor, salvo as Disciplinas inatas dos Baali. Apóstatas não perdem níveis na Disciplina que escolhem trocar por Daimoinon, mas níveis futuros nela são comprados a custo de fora de Clã. Baali não podem adquirir esta Qualidade.]==],
				},
				["Arcane (1)"] = {
					pt = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, pág. 177


Arcane (1)


Alguns vampiros têm uma estranha capacidade de escapar da atenção, que se manifesta como uma aura de esquecimento. Quem tenta se lembrar do vampiro sente algo como um jamais-vu. A capacidade pode ser desenvolvida de propósito, ou o Cainita pode simplesmente ser comum demais para chamar atenção. Embora não se pareça com Ofuscação, Arcano não ajuda em situações de combate — o vampiro não some literalmente. Contudo, quem estiver procurando por ele pode muito bem falhar, já que ninguém se lembra dele nem consegue dar uma descrição confiável.

Cada ponto adquirido subtrai um dado de qualquer parada usada para localizar ativamente o vampiro ou recordá-lo. Quem tem esta Qualidade pode escolher "desligar" Arcano, se quiser. Sendo um traço passivo, ele não ajuda em rolagens de Furtividade nem em outras tentativas explícitas de se esconder. Se você tiver qualquer ponto em Status ou Fama, Arcano deixa de funcionar enquanto você os possuir.]==],
				},
				["Arcane (2)"] = {
					pt = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, pág. 177


Arcane (2)


Alguns vampiros têm uma estranha capacidade de escapar da atenção, que se manifesta como uma aura de esquecimento. Quem tenta se lembrar do vampiro sente algo como um jamais-vu. A capacidade pode ser desenvolvida de propósito, ou o Cainita pode simplesmente ser comum demais para chamar atenção. Embora não se pareça com Ofuscação, Arcano não ajuda em situações de combate — o vampiro não some literalmente. Contudo, quem estiver procurando por ele pode muito bem falhar, já que ninguém se lembra dele nem consegue dar uma descrição confiável.

