				},
				["Arcane (5)"] = {
					pt = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, pág. 177


Arcane (5)


Alguns vampiros têm uma estranha capacidade de escapar da atenção, que se manifesta como uma aura de esquecimento. Quem tenta se lembrar do vampiro sente algo como um jamais-vu. A capacidade pode ser desenvolvida de propósito, ou o Cainita pode simplesmente ser comum demais para chamar atenção. Embora não se pareça com Ofuscação, Arcano não ajuda em situações de combate — o vampiro não some literalmente. Contudo, quem estiver procurando por ele pode muito bem falhar, já que ninguém se lembra dele nem consegue dar uma descrição confiável.

