				},
				["Artistically Gifted"] = {
					pt = [==[Book of Secrets, pág. 43


Artistically Gifted


As Musas fazem sua vontade por meio de você, ou pelo menos é o que parece. Sempre que empregar seu talento artístico (ou seja, o Talento Arte, em Mage 20, p. 275), reduza a dificuldade dessas rolagens em -2. Como em outras Qualidades do gênero, esta não reduz a dificuldade das rolagens de conjuração mágica, mas pode reduzir a dificuldade de rolagens de Atributo + Habilidade envolvidas em atos mágicos. (Para mais detalhes, veja Habilidades que Ampliam a Magia, Mage 20, p. 533.)]==],
				},
				["Aura of Command"] = {
					pt = [==[Lore of the Clans, pág. 122


Aura of Command


Seja porque você é bom em berrar ordens, seja porque tem simplesmente um tom autoritário, as pessoas tendem a fazer o que você manda. Você não é tanto um líder nato quanto um comandante nato. Ao usar a perícia Liderança para fazer os outros lhe obedecerem, a dificuldade é reduzida em dois.]==],
				},
				["Avatar Companion"] = {
					pt = [==[Book of Secrets, pág. 79


Avatar Companion


De vida em vida, você divide um pedaço do seu Avatar com um companheiro que o segue pelas encarnações e se lembra dos detalhes melhor que você. Embora não seja tão poderoso quanto você, e não tenha a destreza metafísica das Qualidades Alma Gêmea ou Avatar Estilhaçado (acima), esse companheiro sabe muita coisa sobre o seu eu reencarnado… bem mais que você. Esse personagem leal (nem sempre agradável) literalmente o acompanha pela vida inteira, em geral encerrando a própria vida quando a sua termina; enquanto isso, ele oferece percepções, conselhos, informações sobre vidas anteriores e qualquer outra ajuda que possa dar. Como a Qualidade Anjo da Guarda, o Companheiro de Avatar é basicamente um empurrão ambulante do seu Narrador, sujeito aos caprichos dele mas agindo em favor dos seus interesses… na maior parte do tempo, pelo menos.

A menos que seja comprado junto do Antecedente Aliados, seu companheiro não tem nada de especial; pode ser uma pessoa ou um animal, mas não um vampiro, um metamorfo ou outra entidade da Gente da Noite. Ele também pode ser um Tutelado, o objeto de um Amor Verdadeiro ou talvez a encarnação de um Avatar Manifesto. Trate-o mal o bastante e ele pode virar um Inimigo. (Veja as entradas correspondentes.) Como em todo Traço baseado em personagem, esse companheiro tem personalidade, desejos e assim por diante. Ele pode ser leal, mas não é suicida, e dificilmente ficará contente se o mago decidir abusar dessa lealdade!]==],
				},
				["Backup Identity"] = {
					pt = [==[The Hunters Hunted II, pág. 133


Backup Identity


A maioria dos agentes monta uma ou duas identidades de fachada, completas com histórico e documentos de apoio. Você foi além e tem uma identidade de fachada que sua agência desconhece. Ela tem documentação completa, incluindo registro civil e passaporte, conta bancária e até um pequeno apartamento no nome dela. Ao contrário da maioria das fachadas, nada liga você a essa identidade reserva, o que a torna muito útil quando você precisa trabalhar por fora e como carta de fuga quando as coisas apertam.

Esta Qualidade fornece apenas a documentação e a garantia de que as agências de inteligência não conhecem seu álter ego. Você ainda precisa do Antecedente Identidade Alternativa se quiser desempenhar o papel de forma convincente.]==],
				},
				["Bardic Gift"] = {
					pt = [==[Book of Secrets, pág. 69


Bardic Gift


Abençoado com uma inspiração fora do comum, você cria obras profundamente evocativas. A verdade ecoa nas suas palavras, arde na sua tela, ressoa no canto, fala em silêncio na dança. Embora a técnica artística seja, claro, importante, este dom vai mais fundo que a mera técnica. A arte é sua paixão, seu espírito, sua Verdade. E essa Verdade se manifesta em qualquer arte que você siga, até e inclusive as Artes Mágicas.

Ao fazer uma rolagem com o Talento Arte, reduza a dificuldade em -2. Mesmo quando a tentativa fica aquém das suas expectativas (ou seja, quando você falha na rolagem), suas criações carregam um brilho inconfundível de genialidade e uma expressão sobrenatural de Verdade. Embora você não seja obrigado (como jogador) a usar a arte como parte do seu foco mágico, é bem provável que a sua abordagem da magia traga elementos de pintura, dança, música e outras manifestações de expressão artística.]==],
				},
				["Benevolent Domitor"] = {
					pt = [==[Ghouls & Revenants, pág. 129


Benevolent Domitor


Por razões que você desconhece, seu domitor gosta de você. Talvez seu serviço tenha sido exemplar, ou talvez você simplesmente lembre a seu mestre um amor do passado. Dada a natureza alienígena da mente de um vampiro, você pode nunca ter certeza, mas não reclama dos benefícios que ganhou com os sentimentos dele por você.

Você se sente seguro sob os cuidados do seu mestre e não teme passar noite após noite cumprindo suas obrigações. Seu domitor o trata com certa compaixão fingida e não põe sua vida em risco à toa. Ao contrário da relação entre outros mestres e seus carniçais, esta Qualidade não representa uma fase passageira. Você já provou seu valor ao seu mestre. Assim, a relação de vocês se parece com a amizade entre um ótimo chefe e seu funcionário.

Embora esta Qualidade determine como seu domitor o trata, ela não garante que você jamais se indisponha com ele. Você pode, a critério do Narrador, perder o direito de mantê-la, se seus atos com o tempo justificarem essa decisão.

Pré-requisito: Antecedente Domitor. Usado por: carniçais da Camarilla, alguns carniçais da Sabá]==],
				},
				["Berserker (Mage)"] = {
					pt = [==[Book of Secrets, pág. 46


Berserker (Mage)


Veja Mage 20, p. 644, e o Defeito Atavismo de Estresse.]==],
				},
				["Berserker (Vampire)"] = {
					pt = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, pág. 177


Berserker (Vampire)


Você tem a capacidade de entrar voluntariamente num estado de fúria berserk por uma cena. Enquanto está nesse estado, você ignora as penalidades de ferimento e reduz em -3 a dificuldade de todas as rolagens de combate, exceto esquivas. Você também não pode realizar ações complexas além de combater, esquivar ou correr. Social]==],
				},
				["Bigger Boys Came"] = {
					pt = [==[Lore of the Clans, pág. 121


Bigger Boys Came


Quando alguém usa seus contatos em proveito próprio, você pode tentar usar os seus para passar por cima. Talvez consiga que um editor engavete a matéria de um repórter, ou que um chefe de gangue impeça seus capangas de derrubar um rival. Para isso, você precisa fazer uma rolagem de Manipulação + Contatos (dificuldade 8). Se obtiver mais sucessos que o valor de Contatos do seu oponente, os contatos dele não respondem ao chamado.]==],
				},
				["Bioluminescence"] = {
					pt = [==[Lore of the Clans, pág. 238


Bioluminescence


Talvez por perícia biológica, talvez por destravar algo primordial dentro de si, você acessou os segredos da bioluminescência. Usando a Vicissitude, você pode conceder a si mesmo (por Semblante Maleável) ou aos outros (por Moldar Carne — ambos conforme V20, p. 241) a capacidade de emitir um brilho suave. Com controle muscular e prática, você domina a cor e o padrão da luz. Isso pode acender um brilho suave no escuro, criar exibições belíssimas ou até funcionar como forma primal de comunicação. Alguns Demônios concedem bioluminescência a seus carniçais ou filhos, desenvolvendo com seus servos e ninhadas uma linguagem sem palavras, inquietante em suas nuances. Apenas personagens com ao menos um ponto de Vicissitude podem comprar esta Qualidade.]==],
				},
				["Blasphemous Pact"] = {
					pt = [==[Dark Ages Tome of Secrets, pág. 108


Blasphemous Pact


Num passado recente ou há muito tempo, você firmou conscientemente um pacto com um ser de maldade absoluta. Fosse ele um demônio de imenso poder, um ceifador querendo reclamar sua alma ou algum monstro maior em busca de conhecimento em troca da sua bênção torpe, o pacto lhe rendeu um presente. Esse presente permite conter, até certo ponto, a Maldição de Caim. Talvez ele lhe permita andar de dia sob abrigo. Talvez você consiga comer carne crua, ainda escorrendo sangue. Talvez o dom lhe permita procriar. A natureza sombria do pacto significa que tudo isso tem um preço. A entidade com quem você se associou tomará, numa noite qualquer, tudo o que você tem, e o levará à ruína. Destruirá todas as suas relações, toda a sua reputação e todo o bem que você conquistar. Reclamará sua alma e, provavelmente, a alma de quem está perto de você. Converse com o Narrador sobre a natureza do seu presente. Ele decidirá o preço que você terá de pagar.]==],
				},
				["Blessed by St. Gustav"] = {
					pt = [==[Lore of the Clans, pág. 261


Blessed by St. Gustav


Muitos Ventrue antitribu trocam sua afinidade tradicional com Presença por aptidão em Auspícios, por meio do ignobilis ritus conhecido como a Prece a São Gustav. Pela sua piedade e devoção à causa da Sabá, você foi especialmente abençoado e tem afinidade com as duas Disciplinas.

Sistema: esta Qualidade é idêntica à Qualidade Disciplina Adicional, de V20, p. 494, exceto que só pode ser usada para acrescentar Auspícios como quarta Disciplina de Clã. Apenas Ventrue antitribu podem adquiri-la.]==],
				},
				["Blood Flaw Immunity"] = {
					pt = [==[Ghouls & Revenants, pág. 137


Blood Flaw Immunity


Você descobriu que é resistente às fraquezas de Clã ou linhagem presentes no sangue que bebe. Sua domitora pode ser uma Nosferatu de Geração baixa, que vive nos esgotos porque sua aparência é medonha, e ainda assim a sua aparência não muda. Se membros dos Clãs Tremere ou Tzimisce souberem da sua Imunidade a Fraquezas de Sangue, você pode virar alvo de estudos. Afinal, se a biologia de um carniçal é tal que ele não sofre tanto quanto seu domitor, certamente existe uma "cura" para as fraquezas presentes no sangue de cada Clã ou linhagem.

Esta Qualidade deixa de valer se seu carniçal ou revenante for Abraçado.

Usado por: todos os carniçais e revenantes]==],
				},
				["Blooded by the Code"] = {
					pt = [==[Dark Ages Companion, pág. 100


Blooded by the Code


Iniciada por um verdadeiro Guerreiro Salubri, e não por um mero membro da linhagem, a jovem Ciclope possui um poder sobrenatural muito além do que teria de outra forma. Ela pode comprar e usar o poder de Disciplina Canção do Sangue a custo normal (40 pontos de experiência), independentemente da Geração. Nenhum outro poder da Disciplina Valeren pode ser comprado, a menos que a Salubri se qualifique para ele por outros meios. Além disso, seu Status conta como dois pontos mais alto ao interagir com outros Salubri.]==],
				},
				["Blush of Health"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 480


Blush of Health


Você parece mais saudável e corado que os outros vampiros, o que lhe permite se misturar à sociedade humana com muito mais facilidade. Você mantém a cor de um mortal vivo, e sua pele é apenas ligeiramente fria ao toque.]==],
				},
				["Boon (1)"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 488


Boon (1)


Alguém lhe deve um favor. O vampiro em dívida com você pode ser o mais reles neonato da cidade ou a própria Príncipe; tudo depende de quantos pontos a Qualidade custa. Você tem direito apenas àquele único favor (a menos que adquira a Qualidade várias vezes), então usá-lo bem é da maior importância. Dependendo do status e de outros fatores, o vampiro que lhe deve o favor pode ter ressentimento da dívida e fazer questão de "quitá-la" cedo — chegando ao ponto de criar situações das quais precisará "resgatá-lo", limpando assim a conta.]==],
				},
				["Boon (2)"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 488


Boon (2)


Alguém lhe deve um favor. O vampiro em dívida com você pode ser o mais reles neonato da cidade ou a própria Príncipe; tudo depende de quantos pontos a Qualidade custa. Você tem direito apenas àquele único favor (a menos que adquira a Qualidade várias vezes), então usá-lo bem é da maior importância. Dependendo do status e de outros fatores, o vampiro que lhe deve o favor pode ter ressentimento da dívida e fazer questão de "quitá-la" cedo — chegando ao ponto de criar situações das quais precisará "resgatá-lo", limpando assim a conta.]==],
				},
