Boon (3)


Alguém lhe deve um favor. O vampiro em dívida com você pode ser o mais reles neonato da cidade ou a própria Príncipe; tudo depende de quantos pontos a Qualidade custa. Você tem direito apenas àquele único favor (a menos que adquira a Qualidade várias vezes), então usá-lo bem é da maior importância. Dependendo do status e de outros fatores, o vampiro que lhe deve o favor pode ter ressentimento da dívida e fazer questão de "quitá-la" cedo — chegando ao ponto de criar situações das quais precisará "resgatá-lo", limpando assim a conta.]==],
				},
				["Boon (4)"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 488


Boon (4)


Alguém lhe deve um favor. O vampiro em dívida com você pode ser o mais reles neonato da cidade ou a própria Príncipe; tudo depende de quantos pontos a Qualidade custa. Você tem direito apenas àquele único favor (a menos que adquira a Qualidade várias vezes), então usá-lo bem é da maior importância. Dependendo do status e de outros fatores, o vampiro que lhe deve o favor pode ter ressentimento da dívida e fazer questão de "quitá-la" cedo — chegando ao ponto de criar situações das quais precisará "resgatá-lo", limpando assim a conta.]==],
				},
				["Boon (5)"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 488


Boon (5)


Alguém lhe deve um favor. O vampiro em dívida com você pode ser o mais reles neonato da cidade ou a própria Príncipe; tudo depende de quantos pontos a Qualidade custa. Você tem direito apenas àquele único favor (a menos que adquira a Qualidade várias vezes), então usá-lo bem é da maior importância. Dependendo do status e de outros fatores, o vampiro que lhe deve o favor pode ter ressentimento da dívida e fazer questão de "quitá-la" cedo — chegando ao ponto de criar situações das quais precisará "resgatá-lo", limpando assim a conta.]==],
				},
				["Boon (6)"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 488


Boon (6)


Alguém lhe deve um favor. O vampiro em dívida com você pode ser o mais reles neonato da cidade ou a própria Príncipe; tudo depende de quantos pontos a Qualidade custa. Você tem direito apenas àquele único favor (a menos que adquira a Qualidade várias vezes), então usá-lo bem é da maior importância. Dependendo do status e de outros fatores, o vampiro que lhe deve o favor pode ter ressentimento da dívida e fazer questão de "quitá-la" cedo — chegando ao ponto de criar situações das quais precisará "resgatá-lo", limpando assim a conta.]==],
				},
				["Brahmin"] = {
					pt = [==[Lore of the Clans, pág. 182


Brahmin


Como membro do jati Brâmane, você é sacerdote, artista, professor ou outro pilar da sociedade. Talvez guarde o saber do Clã, talvez atue como conselheiro de outros Ravnos em busca de sabedoria. Uma vez por sessão, se falhar numa rolagem de Acadêmicos ou Expressão, você pode rolá-la de novo imediatamente.

Você não precisa comprar esta Qualidade para ser membro do jati Brâmane, mas só membros do jati Brâmane podem tê-la.]==],
				},
				["Broken Bond"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 489


Broken Bond


Você já esteve preso por um laço de sangue, mas se soltou da coleira em segredo, e está livre para agir como quiser mais uma vez. Seu regente não faz ideia de que você não está de fato vinculado e continua a tratá-lo como se estivesse. A critério do Narrador, a experiência de ter sido vinculado uma vez pode torná-lo imune a jamais ser escravizado de novo. Vampiros da Sabá não podem adquirir esta Qualidade.]==],
				},
				["Bruiser"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 480


Bruiser


Sua aparência é suficientemente de capanga para inspirar medo (ou pelo menos desconforto) em quem o vê. Embora você não seja necessariamente feio, irradia uma ameaça silenciosa, a ponto de as pessoas atravessarem a rua para não passar perto de você. Todas as rolagens de Intimidação contra quem não tenha demonstrado superioridade física sobre você recebem -1 de dificuldade.]==],
				},
				["Bullyboy"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 488


Bullyboy


Você faz parte do esquadrão de brutamontes que o Xerife ou o Bispo local aciona quando precisa de músculo. Por isso, você participa de ações que os outros perdem por completo, marca pontos com quem está no poder e vez ou outra tem a chance de agir fora da lei. Até onde você pode ir depende das circunstâncias e do quanto o vampiro a quem você se reporta gosta de você.]==],
				},
				["Burning Aura"] = {
					pt = [==[Book of Secrets, pág. 68


Burning Aura


Para quem consegue percebê-la, sua aura arde com brilho e clareza impressionantes. Até quem não enxerga essa coroa luminosa de energia percebe que você é "diferente". Entidades capazes de ler sua aura reagem de acordo; algumas o tratarão com respeito incomum, outras o verão como uma bela refeição. A natureza da sua aura não pode ser escondida com facilidade (+2 na dificuldade de qualquer tentativa) e, embora isso seja uma desvantagem terrível para, digamos, um Nephandus, pessoas que valorizam a integridade franca podem reduzir suas dificuldades em 2 ao tentar causar uma impressão condizente com essa aura vívida, diante de personagens capazes de percebê-la.

Supondo que você use estes Traços opcionais, sua Ressonância e sua Sinergia ganham, cada uma, um vívido acréscimo de um ponto por esta Qualidade – veja o Capítulo Três, pp. 133-134. Para cores e tons de aura, veja Mage 20, p. 507.]==],
				},
				["Call of the Sea"] = {
					pt = [==[Lore of the Clans, pág. 122


Call of the Sea


Há algo no mar que faz você se sentir em casa. Você está em sintonia com as marés e o ritmo do oceano. Quando estiver num barco no mar ou num rio, você acrescenta um dado a todas as suas paradas de dados, exceto às de Disciplinas.]==],
				},
				["Calm Heart"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 485


Calm Heart


Você é naturalmente calmo e não perde a cabeça com facilidade. Recebe dois dados extras ao tentar resistir a um frenesi. Brujah não podem adquirir esta Qualidade.]==],
				},
				["merit|Cannibal"] = {
					pt = [==[Lore of the Clans, pág. 106


Cannibal


A maioria dos vampiros não consegue comer comida e, mesmo os que conseguem forçá-la goela abaixo, não tiram sustento dela. Como eles, você continua sem estômago para a porcaria que a maioria dos mortais come. Carne humana, por outro lado, lhe dá enorme prazer. Ela pode ser assada, frita ou até crua, e você ataca sem cerimônia — e ainda tira sustento dela. Até outros vampiros olham torto para os Cainitas que devoram a própria presa, embora os Dunsirn aplaudam seu respeito pela tradição.

Além dos pontos de sangue que todo humano pode fornecer, você pode canibalizar um mortal e obter ainda mais. Um humano médio rende até sete porções de carne (uma por nível de vitalidade). Cada porção lhe fornece um ponto de sangue.]==],
				},
				["Cast-Iron Stomach"] = {
					pt = [==[Book of Secrets, pág. 36


Cast-Iron Stomach


Você come mais ou menos qualquer coisa sem ter ânsia. Insetos se contorcendo, gosma sintética, uma carcaça recém-estripada com as vísceras ainda penduradas… ora, é tudo comida, então mande ver! Qualquer coisa que você consiga fisicamente devorar e digerir está liberada. Esta Qualidade não o protege de forma alguma dos efeitos dessas substâncias (carne podre ainda pode envenená-lo), mas você segura no estômago uma refeição que faria a pessoa comum vomitar só pela proximidade… um dom especialmente útil se você tiver o Defeito sobrenatural Fome Bizarra (veja p. 87).]==],
				},
				["Catlike Balance"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 480


Catlike Balance


Você tem um senso de equilíbrio inatamente perfeito. Personagens com esta Qualidade reduzem em dois as dificuldades de todas as rolagens ligadas a equilíbrio (por exemplo, Destreza + Esportes para andar por uma saliência estreita).]==],
				},
				["Celestial Affinity"] = {
					pt = [==[Book of Secrets, pág. 70


Celestial Affinity


Você se dá especialmente bem com certo tipo de entidade espiritual. Conforme a sua prática, pode se entender bem com espíritos da natureza, Cortesãos da Alta Umbra, entidades da Teia Digital, os Mortos Inquietos, os Loa, seres angelicais ou demoníacos e assim por diante.

Ao lidar com entidades de uma única categoria escolhida, você reduz em -2 a dificuldade das suas rolagens de convocação e negociação. (Veja a seção sobre Convocação, Vínculo, Barganha e Proteção em How Do You DO That?, pp. 90-95.) Esse bônus não vale para tentativas de vincular ou barrar tais seres, pois se baseia em boa vontade, não em força. Vale, porém, para as rolagens de Arete ao lançar o Efeito de convocação (dentro dos limites normais de modificador, como sempre), porque as entidades em questão ficam mais inclinadas a aparecer quando você as chama.

Por três pontos adicionais por categoria, você pode acrescentar outra categoria de espíritos, supondo que sua prática favoreça afinidade com eles. (Um "caça-fantasmas" da DPC dos Engenheiros do Vazio, por exemplo, não poderia comprar Afinidade com fantasmas, embora um necromante certamente pudesse.) Se você abusar dessa boa vontade, como se pode imaginar, tanto o bônus quanto a Qualidade somem – e podem acabar substituídos por um Defeito como Inimigo Imortal (p. 93), se o seu mago se comportar de forma especialmente tola.]==],
				},
				["Celestial Attunement"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 422


Celestial Attunement


Você sabe por instinto que horas do dia são e consegue estimar com precisão o horário do nascer e do pôr do sol, com alguns minutos de margem. Com um momento de concentração, também consegue estimar a posição das estrelas, mesmo sem a ajuda de uma carta celeste.]==],
				},
				["Chorus Trained (3)"] = {
					pt = [==[Lore of the Bloodlines, pág. 3


Chorus Trained (3)


A personagem aprendeu a usar a Fuga para se sintonizar com suas irmãs e trabalhar em conjunto com muito mais eficiência. Por 3 pontos, esta Qualidade lhe dá 2 dados extras em qualquer parada de Melpominee ao usar o poder junto de outra personagem que também a tenha. Por 5 pontos, os 2 dados de bônus podem ser somados a qualquer ação realizada em parceria com quem tenha esta Qualidade, como fazer arte ou até lutar lado a lado.]==],
				},
				["Chorus Trained (5)"] = {
					pt = [==[Lore of the Bloodlines, pág. 3


Chorus Trained (5)


A personagem aprendeu a usar a Fuga para se sintonizar com suas irmãs e trabalhar em conjunto com muito mais eficiência. Por 3 pontos, esta Qualidade lhe dá 2 dados extras em qualquer parada de Melpominee ao usar o poder junto de outra personagem que também a tenha. Por 5 pontos, os 2 dados de bônus podem ser somados a qualquer ação realizada em parceria com quem tenha esta Qualidade, como fazer arte ou até lutar lado a lado.]==],
				},
				["Circumspect Avatar"] = {
					pt = [==[Book of Secrets, pág. 69


Circumspect Avatar


Você nunca viu seu Avatar e provavelmente duvida que tal coisa exista. Claro, você tem uma sombra, e um reflexo, e talvez um cachorrinho que o segue desde a infância e não parece mais velho, mesmo devendo ter morrido de velhice anos atrás — mas um Avatar? Que nada, isso é papo de hippie da Nova Era! Você ainda não encontrou nada disso, não sai por aí em "buscas", ou seja lá como chamam, e obtém suas percepções metafísicas do mesmo jeito que qualquer pessoa normal: por meio dos acontecimentos cotidianos do mundo cotidiano.

Basicamente, esta Qualidade concede um Avatar "silencioso" – um que, por alguma razão, não persegue nem guia sua personagem, apenas deixa pistas, deixas e indícios que a maga decifra ou não por conta própria. Buscas e Epifanias acontecem no plano físico, em geral como enigmas e dilemas ligados a questões que a maga precisa resolver para avançar ao próximo nível de compreensão. Nessas situações, o Avatar pode até aparecer (possivelmente até se manifestar – veja a Qualidade Avatar Manifesto, p. 71), mas apenas como alguma pessoa, criatura ou coisa aparentemente mundana, nunca como entidade obviamente paranormal. Você pode, por exemplo, receber uma ligação da sua mãe que o joga num humor introspectivo que, por sua vez, o leva a decifrar um enigma importante do seu passado; a mãe, claro, nega ter ligado. Hum. Então de quem terá sido aquela ligação? Ou será que você apenas a imaginou?]==],
				},
				["Clan Apostate"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 425


Clan Apostate


Tendo passado pelo Rito de Apostasia Baali, você agora pertence a uma ninhada. Troque uma Disciplina de clã por Daimoinon, mas ganhe também a fraqueza de clã Baali além da sua fraqueza de clã original. Você ainda passa por membro do seu antigo clã com relativa facilidade, e qualquer um que você Abrace também pertencerá ao seu clã de origem. Você não perde níveis na Disciplina que escolheu trocar por Daimoinon, mas níveis futuros nela são comprados a custo de fora de clã.]==],
				},
				["Clan Friendship"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 489


Clan Friendship


Um Clã em particular (que não o seu) tem uma simpatia especial por você. Você pode ter feito um favor ao Clã inteiro em algum momento, ou talvez seja apenas uma voz alta em apoio aos objetivos deles. Seja como for, você tem -2 de dificuldade em todas as rolagens Sociais amistosas envolvendo membros daquele Clã. Claro que a reação que sua relação aconchegante com outro Clã provavelmente vai provocar nos líderes do seu próprio Clã é uma lata de minhocas totalmente diferente.]==],
				},
				["Clear Sighted (Hunter)"] = {
					pt = [==[The Hunters Hunted II, pág. 141


Clear Sighted (Hunter)


Você enxerga através de todos os níveis de Ofuscação, Quimerismo e outras Disciplinas ou poderes sobrenaturais aparentados dos Cainitas, com uma rolagem de Percepção + Prontidão contra o nível do poder adversário + 3.]==],
				},
				["Clear Sighted (Mage)"] = {
					pt = [==[Book of Secrets, pág. 75


Clear Sighted (Mage)


Mesmo sem usar suas Artes, você tem um dom sobrenatural de ver as coisas como elas são, e não como parecem ser. Ilusões, disfarces, magias de ocultação e outras formas de embuste raramente enganam seus olhos.

Em termos de jogo, você pode fazer uma rolagem de Percepção + Prontidão para enxergar através de poderes metafísicos de engano: Disciplinas vampíricas, cantos feéricos, Dons de metamorfos, ilusões baseadas em Esferas e outros poderes que se apoiem em enganar a percepção de quem vê. Essa rolagem só funciona contra poderes que enganam a percepção do alvo, e não contra qualquer outra forma de Dom, Disciplina, canto e assim por diante. (Ofuscação vampírica, por exemplo, mas não Presença ou Dominação.)

A dificuldade dessa rolagem costuma ser 5 + o Nível de Esfera mais alto ou outro nível envolvido no poder; uma ilusão de Forças 2/Primórdio 2, então, seria dificuldade 7, enquanto a Máscara de Mil Faces de um vampiro (Ofuscação 3) seria dificuldade 8. Se a personagem normalmente teria direito a uma rolagem para enxergar através da ilusão (como mostrado em How Do You DO That?, pp. 129-132), então ela subtrai -3 da dificuldade ao tentar.

Sua visão clara também reduz sua dificuldade em -3 quando você tenta enxergar através de um disfarce, de uma magia ou dispositivo de ocultação, ou de outras tentativas de esconder a verdade de um observador. Ela não permite, porém, enxergar no escuro, notar personagens furtivos ou invisíveis, nem perceber de outro modo algo que você não conseguiria ver sem esta Qualidade; combiná-la com a Qualidade física Sentidos Aguçados, contudo, pode fazer de você uma personagem formidavelmente perceptiva.]==],
				},
				["Clear-Sighted"] = {
					pt = [==[The Hunters Hunted II, pág. 44


Clear-Sighted


Sua personagem não se deixa enganar facilmente por ilusões. Diante de uma ilusão sobrenatural, como as criadas por Ofuscação, Quimerismo e afins, você pode fazer uma rolagem de Percepção + Prontidão (dificuldade igual ao nível do poder adversário + 3) para que ela enxergue através do efeito.]==],
				},
				["Cloak of the Seasons"] = {
					pt = [==[Book of Secrets, pág. 70


Cloak of the Seasons


O tempo adverso não o incomoda. Independentemente da roupa que use, ou da falta dela, você é essencialmente imune aos efeitos da exposição a climas rigorosos, como descrito em Mage 20, p. 435. Você ainda precisa comer, beber e respirar – esta Qualidade não o salva de morrer de fome ou sufocado – e obstáculos climáticos (neblina, ventos fortes, montes de neve, gelo etc.) o atrapalham tanto quanto atrapalham qualquer um. Fora ataques diretos dos elementos, porém, você permanece intocado por extremos de temperatura e clima. Nem sempre estará confortável, mas sobreviverá.]==],
				},
				["Code of Honor"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 484


Code of Honor


Você tem um código pessoal de ética ao qual adere. As especificidades desse código devem ser acertadas com o Narrador antes do jogo, e a personagem precisa segui-lo à risca. Personagens com esta Qualidade ganham dois dados adicionais em todas as rolagens de Força de Vontade ou Virtude ao agir de acordo com o código (por exemplo, defendendo os indefesos) ou ao tentar evitar situações que possam forçá-las a violá-lo.]==],
				},
				["Cold Read"] = {
					pt = [==[Lore of the Clans, pág. 142


Cold Read


Sempre que conhece alguém pela primeira vez, você pode gastar um número de pontos de Força de Vontade igual à sua Percepção. Para cada ponto gasto, pode fazer ao Narrador uma pergunta sobre aquela personagem. O Narrador precisa responder com sinceridade ou devolver o ponto de Força de Vontade para não responder.]==],
				},
				["Coldly Logical"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 484


Coldly Logical


Embora alguns possam chamá-lo de "peixe frio", você tem talento para separar o relato dos fatos do colorido emocional ou histérico. Você pode ou não ser emotivo, mas enxerga com clareza quando os outros estão embaçando os fatos com sentimentos (-1 de dificuldade em todas as rolagens cabíveis).]==],
				},
				["Common Sense"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 484


Common Sense


Você tem uma boa dose de sabedoria prática do dia a dia. Sempre que estiver prestes a agir de forma contrária ao bom senso, o Narrador pode fazer sugestões ou dar avisos sobre as implicações daquele ato. É uma Qualidade muito útil para jogadores iniciantes que não conhecem bem o jogo.]==],
				},
				["Computer Aptitude"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 484


Computer Aptitude


Você conhece e tem talento para o uso de equipamentos de informática. Outros Cainitas podem não entender computadores, mas para você eles são intuitivos. Todas as rolagens que envolvam computadores têm -2 de dificuldade para você.]==],
				},
				["Concentration"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 484


Concentration


Você tem a capacidade de focar a mente e bloquear qualquer distração ou incômodo. Personagens com esta Qualidade não sofrem penalidade alguma vinda de circunstâncias que distraiam (por exemplo, ruídos altos, luzes estroboscópicas ou estar pendurado de cabeça para baixo).]==],
				},
				["Confidence"] = {
					pt = [==[Book of Secrets, pág. 55


Confidence


Você exala uma aura de autoridade inabalável. Nada parece abalá-lo. As pessoas se curvam a você por padrão, e você não espera menos. Mesmo quando está inventando tudo na hora, ou mentindo descaradamente sobre seus sentimentos ou intenções, sua autoconfiança inspira um grau incomum de confiança. Frieza é o seu nome do meio, e os poucos que tentam passá-lo para trás têm imensa dificuldade em consegui-lo.

Quando os dados começam a rolar, subtraia -2 da dificuldade de todas as rolagens sociais baseadas em impressionar os outros com suas capacidades. Os demais jogadores, porém – o Narrador incluído –, somam +2 à dificuldade das rolagens sociais de personagens que tentem abalar sua confiança ou quebrar sua calma.]==],
				},
				["Connoisseur"] = {
					pt = [==[Lore of the Clans, pág. 261


Connoisseur


Seu estudo da Disciplina Auspícios, somado ao seu paladar refinado, lhe permite uma empatia e uma conexão fora do comum com a vítima, dando-lhe percepções poderosas sobre o caráter de quem quer que você prove o sangue.

Sistema: a personagem prova o sangue de outro (arriscando potencialmente um laço de sangue), e o jogador rola Percepção + Empatia (dificuldade 6 para mortais ou 8 para Cainitas). Se o sangue veio de um mortal, cada sucesso permite descobrir um dos seguintes: a Natureza dele, o Comportamento, quaisquer Perturbações que possua, se está vinculado pelo sangue e se carrega alguma doença transmitida pelo sangue. Se a vitae veio de um vampiro, ele pode descobrir tudo isso mais qualquer coisa acessível pelo primeiro nível do Caminho do Sangue (veja V20, p. 213). O Ventrue pode provar o sangue de um mortal fora da sua restrição alimentar por tempo suficiente para usar esta capacidade, mas precisa cuspi-lo logo em seguida.

Vampiros sem Auspícios •• não podem adquirir esta Qualidade.]==],
				},
				["Consanguineous Resistance"] = {
					pt = [==[Lore of the Clans, pág. 106


Consanguineous Resistance


Sua personagem não pode ser vinculada pelo sangue por ninguém que compartilhe da sua linhagem mortal. Ou seja: se você nasceu na família Giovanni, não pode ser vinculado por outro nascido Giovanni, embora ainda possa ser vinculado por, digamos, um Pisanob do Clã Giovanni, ou por Cainitas de qualquer outro Clã. Do mesmo modo, um Dunsirn com Resistência Consanguínea não poderia ser vinculado por outros nascidos na família mortal Dunsirn, mas poderia ser vinculado por um Milliner do Clã Giovanni.

Os Giovanni desconfiam profundamente de quem se sabe manifestar essa esquisitice. Embora essa aberração do sangue não tenha sido documentada, alguns Giovanni espertos têm uma ideia aproximada do que ela é e do que faz. Em geral, ela é associada a jovens rebeldes e atrevidos que precisam ser postos no lugar. Isso não é tão injusto quanto parece: quando uma resistência ao laço fica realmente evidente, é provável que seja porque alguma punição não está funcionando. Uma personagem descoberta com este traço provavelmente ganha, no mínimo, a hostilidade do seu senhor.]==],
				},
				["Controllable Night Sight"] = {
					pt = [==[Lore of the Clans, pág. 122


Controllable Night Sight


Sua visão noturna é extraordinariamente boa, mesmo para um vampiro. As sombras mais fundas são para você como olhar para uma sala bem iluminada. Contudo, sob luz normal ou forte, você precisa voltar à visão menos sensível, ou a luz mais fraca o cega rapidamente. Enquanto sua visão noturna está ativa, você não sofre penalidade alguma pelo escuro e enxerga perfeitamente. Se usá-la em ambientes bem iluminados, sofre penalidade na proporção inversa das penalidades usuais para escuridão.]==],
				},
				["Court Favorite (1)"] = {
					pt = [==[Lore of the Clans, pág. 121


Court Favorite (1)


Embora as Cortes de Sangue costumem ser difíceis de influenciar, você ficou muito bom em mover a balança. Uma mistura de experiência e sensibilidade política lhe permite saber exatamente como empurrar a decisão na sua direção, ou talvez na do seu cliente. Qualquer rolagem que venha a afetar a decisão numa Corte de Sangue recebe um bônus ou penalidade (o que for a seu favor) em dados igual ao nível que você tem nesta Qualidade.]==],
				},
				["Court Favorite (2)"] = {
					pt = [==[Lore of the Clans, pág. 121


Court Favorite (2)


Embora as Cortes de Sangue costumem ser difíceis de influenciar, você ficou muito bom em mover a balança. Uma mistura de experiência e sensibilidade política lhe permite saber exatamente como empurrar a decisão na sua direção, ou talvez na do seu cliente. Qualquer rolagem que venha a afetar a decisão numa Corte de Sangue recebe um bônus ou penalidade (o que for a seu favor) em dados igual ao nível que você tem nesta Qualidade.]==],
				},
				["Court Favorite (3)"] = {
					pt = [==[Lore of the Clans, pág. 121


Court Favorite (3)


Embora as Cortes de Sangue costumem ser difíceis de influenciar, você ficou muito bom em mover a balança. Uma mistura de experiência e sensibilidade política lhe permite saber exatamente como empurrar a decisão na sua direção, ou talvez na do seu cliente. Qualquer rolagem que venha a afetar a decisão numa Corte de Sangue recebe um bônus ou penalidade (o que for a seu favor) em dados igual ao nível que você tem nesta Qualidade.]==],
				},
				["Court Favorite (4)"] = {
					pt = [==[Lore of the Clans, pág. 121


Court Favorite (4)


Embora as Cortes de Sangue costumem ser difíceis de influenciar, você ficou muito bom em mover a balança. Uma mistura de experiência e sensibilidade política lhe permite saber exatamente como empurrar a decisão na sua direção, ou talvez na do seu cliente. Qualquer rolagem que venha a afetar a decisão numa Corte de Sangue recebe um bônus ou penalidade (o que for a seu favor) em dados igual ao nível que você tem nesta Qualidade.]==],
				},
				["Court Favorite (5)"] = {
					pt = [==[Lore of the Clans, pág. 121


Court Favorite (5)


Embora as Cortes de Sangue costumem ser difíceis de influenciar, você ficou muito bom em mover a balança. Uma mistura de experiência e sensibilidade política lhe permite saber exatamente como empurrar a decisão na sua direção, ou talvez na do seu cliente. Qualquer rolagem que venha a afetar a decisão numa Corte de Sangue recebe um bônus ou penalidade (o que for a seu favor) em dados igual ao nível que você tem nesta Qualidade.]==],
				},
				["Critters"] = {
					pt = [==[Lore of the Clans, pág. 182


Critters


Você é excelente com animais — tanto que eles vivem procurando sua amizade. Aonde quer que vá, os bichos ficam felizes em vê-lo e, na maioria das vezes, felizes em ajudá-lo quando você pede. Você recebe um dado de bônus em rolagens Sociais para afetar animais pequenos. Além disso, companheiros animais que convivem com você o veem como uma espécie de bicho de estimação e vez ou outra lhe trazem pequenas coisas úteis. Uma vez por sessão, os animais lhe trazem uma informação útil ou um pequeno objeto relevante para os acontecimentos. Esse objeto pode, de vez em quando, alimentar o vício particular daquele Ravnos, já que os bichos logo percebem o que agrada ao amigo.]==],
				},
				["Cultural Chameleon"] = {
					pt = [==[The Hunters Hunted II, pág. 141


Cultural Chameleon


Você capta depressa as deixas sociais, os costumes locais, as expressões, os modos de vestir e outras miudezas próprias de um lugar. Se conseguir dar conta delas (trocar de roupa, falar o idioma etc.), qualquer um que tente perceber que você não é de lá sofre penalidade de dois dados. De todo modo, você recebe dois dados extras em qualquer ação para identificar quem não pertence a determinado lugar.]==],
				},
				["Danger Sense"] = {
					pt = [==[Book of Secrets, pág. 70


Danger Sense


Um estado elevado de atenção permite que você sinta o perigo se aproximando. Esse dom pode nascer de uma percepção primal, de condicionamento intenso, de vozes de espíritos que o avisam do perigo, de sensores nanotecnológicos ou de outros métodos de consciência refinada. Seja qual for a origem desta Qualidade, seu Narrador precisa fazer uma rolagem secreta de Percepção + Prontidão por você quando alguma ameaça de outro modo oculta se aproximar da sua personagem.

A dificuldade dessa rolagem depende da iminência do perigo; um perigo distante e abstrato (como uma trama para matá-lo) é bem mais difícil de sentir que um desastre em curso (como a bala de um franco-atirador), e por isso teria dificuldade maior (digamos, 10 para a trama, 6 para a bala). Um sucesso simples lhe diz que algo está errado, enquanto muitos sucessos podem localizar a natureza e a posição da ameaça.

Seu Narrador, claro, não é obrigado a lhe dar detalhes objetivos sobre a ameaça. Ele pode ser tão vago quanto "um arrepio percorre seu couro cabeludo", talvez com uma pista da direção e da natureza da fonte ("um súbito estalo metálico ecoa atrás de você, à direita. O que você faz?").]==],
				},
				["Daredevil"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 480


Daredevil


Você é bom em correr riscos, e melhor ainda em sobreviver a eles. Ao tentar ações fora de combate excepcionalmente arriscadas (como pular de um carro em movimento para outro), personagens com esta Qualidade somam três dados às rolagens e anulam um dado de falha crítica que possa resultar delas. Em geral, essas ações precisam ter ao menos dificuldade 8 e o potencial de causar pelo menos três níveis de vitalidade de dano em caso de fracasso.]==],
				},
				["Dark Triad"] = {
					pt = [==[Book of Secrets, pág. 58


Dark Triad


Veja Mage 20, p. 643.]==],
				},
				["Darksight"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 425


Darksight


Sua personagem enxerga na escuridão do jeito que os outros enxergam na luz. Mesmo na ausência completa de luz, ela vê perfeitamente e não sofre penalidade alguma pelo escuro. Além disso, ela capta vislumbres do outro mundo: vê fantasmas como se fossem materiais, mas apenas enquanto está no escuro. Mais luz que a de uma vela anula esta capacidade.]==],
				},
				["Dead Zone"] = {
					pt = [==[The Hunters Hunted II, pág. 151


Dead Zone


Sua exposição rotineira à morte torna difícil para os fantasmas perceberem que você existe. Você é considerado como tendo um ponto de Ofuscação (que funciona também nas terras dos mortos) contra espectros, aparições e seres do gênero.]==],
				},
				["Death Grip"] = {
					pt = [==[Lore of the Bloodlines, pág. 91


Death Grip


Graças à sua ligação com a morte, você tem uma percepção aguçada que poucos Cainitas possuem. Em contato com um cadáver, você faz uma rolagem de Raciocínio + Prontidão (dificuldade 7). Com um sucesso, sabe por intuição como aquele corpo morreu. Numa falha, você sofre uma versão ilusória do ferimento, que suga um ponto de Força de Vontade. Numa falha crítica, seu corpo espelha o ferimento e se machuca da mesma forma, causando dano letal igual ao golpe final.]==],
				},
				["Deathwalker"] = {
					pt = [==[Book of Secrets, pág. 74


Deathwalker


O Submundo lhe dá as boas-vindas. Enquanto a maioria dos viajantes da Umbra está mais ou menos barrada das Terras das Sombras e da Baixa Umbra, a menos que possua magias especiais (ou já tenha morrido), você consegue dar um passo lateral rumo às Terras Mortas com uma simples aplicação de Espírito 3. Ao fazê-lo, sua aura assume o tom pálido da morte, e você se torna essencialmente indistinguível de um fantasma, a menos que alguma entidade entendida tenha sucesso numa rolagem de Percepção + Ocultismo (dificuldade 7) para vê-lo pelo que realmente é. Se a Tempestade de Avatares ainda estiver em curso na sua crônica, você pode atravessar para a Baixa Umbra sem sofrer os efeitos dela.

Esse tipo de "dom" costuma deixar marcas macabras nos mortais que favorece. Por isso, esta Qualidade combina bem com os Defeitos Ecos, Estranho e Marcas Primais. Graças aos laços inatos com as Terras Mortas, os Caminhantes da Morte, via de regra, veem os Outros Mundos pelo Vidare Mortem, sofrem Quietudes de Morbidez e tendem a ter uma visão bastante fatalista da vida.]==],
				},
				["Debt of Gratitude (1)"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 423


Debt of Gratitude (1)


Ainda que admita isso a contragosto, um ancião está em dívida com você. Com 1 ponto, ele lhe deve um favor. Acerte com o Narrador que tipo de favor é esse e o que você fez para merecê-lo. Com 3 pontos, o ancião endividado lhe deve a própria não-vida. Um episódio desses é extraordinariamente incomum, então ele provavelmente detesta estar em dívida com você. Combine com o Narrador como (e por que) isso aconteceu.]==],
				},
				["Debt of Gratitude (3)"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 423


Debt of Gratitude (3)


Ainda que admita isso a contragosto, um ancião está em dívida com você. Com 1 ponto, ele lhe deve um favor. Acerte com o Narrador que tipo de favor é esse e o que você fez para merecê-lo. Com 3 pontos, o ancião endividado lhe deve a própria não-vida. Um episódio desses é extraordinariamente incomum, então ele provavelmente detesta estar em dívida com você. Combine com o Narrador como (e por que) isso aconteceu.]==],
				},
				["Deceptive Aura"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 493


Deceptive Aura


Sua aura é antinaturalmente clara e colorida para um vampiro. Você é lido como mortal em todas as tentativas de leitura da sua aura.]==],
				},
				["Deceptive Eating"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 420


Deceptive Eating


Por alguma sorte, você consegue consumir e apreciar a culinária mortal, o que acrescenta mais uma camada ao seu disfarce de mortalidade. Quando cabível, o Narrador pode determinar dificuldade menor ou penalidades reduzidas nas rolagens para convencer os outros de que você é humano. Você não consegue digerir a comida comum nem tirar nutrição dela, porém, e cedo ou tarde precisa achar hora e lugar para pôr tudo para fora.]==],
				},
				["Demonic Patron"] = {
					pt = [==[Dark Ages Tome of Secrets, pág. 108


Demonic Patron


Seus atos atraíram a atenção de uma entidade demoníaca. Talvez você a tenha procurado de propósito como meio de ganhar poder, ou talvez ela tenha se enfiado na sua existência e agora não larga mais. A entidade virou sua padroeira, oferecendo orientação quando procurada e ajuda contra seus inimigos. Numa noite qualquer ela se voltará contra você e exigirá algo. E você não poderá recusar o pedido. Até lá, sua padroeira conta como três pontos em Mentor e dois pontos em Aliados.]==],
				},
				["Detached"] = {
					pt = [==[The Hunters Hunted II, pág. 42


Detached


Seu caçador tem a rara capacidade de ver suas habilidades psíquicas como algo separado da existência física, e consegue manter essa distância mesmo em condições adversas. Penalidades de ferimento não afetam o uso de Númina Psíquicos até que sua personagem chegue a Incapacitado. Estando Incapacitado, você pode gastar um ponto de Força de Vontade para usar um poder de Númina Psíquico com metade da parada de dados normal (arredondando para baixo). Essa ação só pode ser feita uma vez por cena, e depois dela a personagem desmaia — então escolha bem os esforços derradeiros. Nota: esta Qualidade só pode ser usada em conjunto com Númina Psíquicos.]==],
				},
				["Discerning Palate"] = {
					pt = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, pág. 177


Discerning Palate


Seu paladar naturalmente seletivo lhe permite discernir traços específicos de uma amostra de sangue. Com apenas um gole, você determina potência, frescor, espécie ou se a amostra está contaminada, além de tentar identificar a Geração, a idade e até o Clã de outros vampires. Se provar mesmo que uma única gota, role Percepção + Prontidão (dificuldade 8).

Um sucesso permite identificar a potência e o frescor relativos do sangue, uma espécie cujo sangue você já tenha provado e saiba reconhecer, a Geração de outro vampiro até dois degraus da sua, se o sangue tem menos ou mais de cem anos, e se é do seu próprio Clã.

Dois sucessos identificam se o sangue está contaminado por doença ou veneno, a Geração de vampiros até quatro degraus da sua, a idade aproximada dentro de cinquenta anos (se tiver menos de trezentos anos) e qualquer Clã cujo sangue você já tenha provado.

Com três ou mais sucessos, você identifica contaminantes específicos que já tenha provado antes, Gerações até seis degraus da sua, a safra do sangue dentro de vinte e cinco anos (se tiver menos de seiscentos anos) e qualquer Clã, bem como a família de vampiros cujo sangue você já provou.]==],
				},
				["Disciple of Lazarus / Japheth"] = {
					pt = [==[Lore of the Bloodlines, pág. 48


Disciple of Lazarus / Japheth


Você fala pelos poderosos da sua linhagem e ostenta a máscara mortuária branca e limpa de um Precursor respeitado, perdido em um dos expurgos históricos que seu povo sofreu. A maioria dos Precursores do Ódio ouve o que você diz e toma suas palavras como verdade. Esta Qualidade acrescenta dois dados a qualquer rolagem Social em que você invoque o nome de Lázaro ou de Jafé.]==],
				},
				["Distracting Aura"] = {
					pt = [==[Lore of the Clans, pág. 142


Distracting Aura


Ler uma aura com Auspícios exige que o observador se concentre em padrões e cores recorrentes para detectar o estado emocional do alvo. Por causa do estado singular da sua psique, sua aura é ainda mais difícil de ler que a maioria. Todos os usos de Percepção da Aura sofrem +2 de dificuldade contra você.]==],
				},
				["Dracon's Temperament"] = {
					pt = [==[Lore of the Clans, pág. 238


Dracon's Temperament


Você encarna o ideal de Azi Dahaka por dentro e por fora, em níveis viscerais e abstratos. Sua psique flui com a natureza mutável da mudança. Como o proteico Dragão, você é um turbilhão de temperamentos. Isto não é personalidade múltipla. Você é uma identidade só, vista através do prisma de Naturezas em constante transformação. Nenhuma âncora prende o seu senso de si. Você pode ser qualquer você.

No começo de cada história, você pode escolher um Arquétipo de Personalidade para funcionar como sua Natureza, e passa o resto da história percebendo o mundo por aquela perspectiva. Você também recupera Força de Vontade de acordo com a nova Natureza e pode ser afetado por outros efeitos ou poderes de Disciplina conforme ela.]==],
				},
				["Drug Resistance"] = {
					pt = [==[Lore of the Clans, pág. 67


Drug Resistance


A religião Setita é cheia de vícios, tanto para comprometer inimigos quanto para iluminar iniciados. Cultistas tendem a criar tolerância às substâncias que tomam diretamente (se humanos ou carniçais) ou pelo sangue da presa (se Cainitas). Você é excepcionalmente resistente a álcool, narcóticos e substâncias viciantes semelhantes. Pode fingir estar muito mais alterado do que está para levar vantagem sobre um adversário. Todas as rolagens para resistir aos efeitos dessas substâncias têm -2 de dificuldade.]==],
				},
				["Dual Affiliation"] = {
					pt = [==[Book of Secrets, pág. 79


Dual Affiliation


Você foi iniciado e treinado em dois grupos Despertos diferentes. Talvez fosse uma Verbena que gravitou para os Adeptos Virtuais, ou um Homem de Preto que buscou refúgio entre os Templários. Seja qual for a sua história e sejam quais forem suas filiações, você conhece intimamente os dois grupos, tem ligações (não necessariamente amigos) nos dois e pode usar e compreender as práticas, ferramentas e crenças (em resumo, o foco) de qualquer um deles.

Em regras, seu mago desfruta dos benefícios das duas filiações. Se ele é um ex-Tecnocrata que passou para o lado místico, ainda pode usar tecnomagia enquanto transcende os banimentos tecnocratas usuais quanto a Arete e foco. Ao elevar uma Esfera, sua personagem usa a taxa de Esfera de Afinidade para uma Esfera por grupo. Seus antigos companheiros provavelmente não o veem com bons olhos, a menos que o "treinamento cruzado" tenha ocorrido entre grupos amistosos, como um Falador de Sonhos que virou Extático ou um Hermético que entrou para os Filhos do Conhecimento.

Para mais detalhes sobre o assunto, veja o FAQ do Foco no Capítulo Três, p. 174.]==],
				},
				["Dynamic Personality"] = {
					pt = [==[Lore of the Clans, pág. 48


Dynamic Personality


Seu carisma natural atrai os mortais como fãs atrás de um astro do rock. Por isso, é mais fácil para você adquirir certos Antecedentes ligados a mortais.

Sistema: além de quaisquer Antecedentes adquiridos na criação do personagem ou pela interpretação, você pode comprar novos Antecedentes com pontos de experiência ao fim de cada história. Os Antecedentes disponíveis são Aliados, Contatos, Rebanho e Lacaios, e cada ponto novo custa o valor atual em pontos de experiência.]==],
				},
				["Early Riser"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 480


Early Riser


Ninguém sabe explicar, mas você parece ter a capacidade de funcionar com menos descanso que os outros vampiros. Você é sempre o primeiro a se erguer e o último a se deitar, mesmo tendo ficado acordado até o amanhecer. Sua Humanidade ou seu Caminho conta como 10 para determinar a hora em que você se ergue a cada noite. Vampiros com esta Qualidade não podem adquirir o Defeito Sono Pesado.]==],
				},
				["Eat Food"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 480


Eat Food


Você é capaz de comer alimentos e até de apreciar o sabor deles. Embora não consiga tirar nutrição alguma de comida comum, essa capacidade lhe será muito útil para fingir ser humano. Claro que você não digere o que come, e em algum momento da noite terá de pôr tudo para fora.]==],
				},
				["Ecclesial Rank (1)"] = {
					pt = [==[The Hunters Hunted II, pág. 123


Ecclesial Rank (1)


Embora sua condição de Inquisidor seja segredo fora da Sociedade de Leopoldo, você é também membro oficial da hierarquia católica romana. Esta Qualidade determina sua posição, e cada ponto amplia o alcance do seu serviço e da sua influência. A versão de um ponto lhe dá a patente de padre, à frente de uma paróquia (e de seus diáconos e leigos). A de dois pontos lhe dá a de Bispo, à frente de uma diocese formada por muitas paróquias (e seus padres). A de três pontos lhe dá a de Arcebispo, à frente de várias dioceses (e seus bispos).]==],
				},
				["Ecclesial Rank (2)"] = {
					pt = [==[The Hunters Hunted II, pág. 123


Ecclesial Rank (2)


Embora sua condição de Inquisidor seja segredo fora da Sociedade de Leopoldo, você é também membro oficial da hierarquia católica romana. Esta Qualidade determina sua posição, e cada ponto amplia o alcance do seu serviço e da sua influência. A versão de um ponto lhe dá a patente de padre, à frente de uma paróquia (e de seus diáconos e leigos). A de dois pontos lhe dá a de Bispo, à frente de uma diocese formada por muitas paróquias (e seus padres). A de três pontos lhe dá a de Arcebispo, à frente de várias dioceses (e seus bispos).]==],
				},
				["Ecclesial Rank (3)"] = {
					pt = [==[The Hunters Hunted II, pág. 123


Ecclesial Rank (3)


Embora sua condição de Inquisidor seja segredo fora da Sociedade de Leopoldo, você é também membro oficial da hierarquia católica romana. Esta Qualidade determina sua posição, e cada ponto amplia o alcance do seu serviço e da sua influência. A versão de um ponto lhe dá a patente de padre, à frente de uma paróquia (e de seus diáconos e leigos). A de dois pontos lhe dá a de Bispo, à frente de uma diocese formada por muitas paróquias (e seus padres). A de três pontos lhe dá a de Arcebispo, à frente de várias dioceses (e seus bispos).]==],
				},
				["Ecstatic"] = {
					pt = [==[The Hunters Hunted II, pág. 124


Ecstatic


Você é propenso a acessos de êxtase religioso — estigmas, glossolalia (falar em línguas), visões e transes. É uma Qualidade de benefício duvidoso. Enquanto alguns desconfiam de você como histérico religioso, você é muito bem visto por outros da fé como alguém "tocado por Deus". Some um dado a qualquer parada de dados Social ao interagir com a Sociedade (e possivelmente com outros de crenças espirituais semelhantes).]==],
				},
				["Ecumenist"] = {
					pt = [==[The Hunters Hunted II, pág. 124


Ecumenist


O Espírito Santo "sopra onde quer". Você entende isso. Vê os reflexos fractais do seu Deus em outras religiões e se mantém humilde ao saber o quão pouco do divino você pode conhecer. Onde outros precisam brandir os símbolos sagrados da própria tradição ao usar a Fé Verdadeira, você enxerga a centelha superna no âmago de crenças que não são a sua, e consegue usar os ícones religiosos e o solo sagrado delas ao enfrentar o sobrenatural. Do mesmo modo, na sua presença um grupo de pessoas de religiões diferentes pode somar sua Fé Verdadeira para um efeito maior. Essa soma coletiva exige apenas uma pessoa com esta Qualidade. Você pode ser a ponte que une todas as fés como irmãos e irmãs na longa noite escura da alma.]==],
				},
				["Efficient Digestion"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 480


Efficient Digestion


Você consegue tirar do sangue mais nutrição que o normal. Ao se alimentar, você ganha um ponto adicional na reserva de sangue a cada dois pontos consumidos. Isso não lhe permite ultrapassar o máximo da sua reserva.]==],
				},
				["Eidetic Memory"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 484


Eidetic Memory


Você se lembra, em detalhes perfeitos, do que vê e ouve. Documentos, fotografias, conversas etc. podem ser memorizados com pouca concentração. Em condições estressantes, com muitas distrações, você precisa fazer uma rolagem de Percepção + Prontidão (dificuldade 6) para reunir concentração suficiente e absorver o que seus sentidos captam.]==],
				},
				["Elysium Regular"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 487


Elysium Regular


Você passa um tempo incomum no Elísio. Você vê e é visto a tal ponto que todos os figurões do Elísio ao menos sabem quem você é. Esse tempo prolongado também lhe dá mais oportunidades de conviver com as Harpias e outros Cainitas daquele porte — e eles saberão seu nome quando você se aproximar. Esta Qualidade em geral é adquirida por vampiros que respeitam e frequentam o Elísio regularmente.]==],
				},
				["Embedded Agent"] = {
					pt = [==[The Hunters Hunted II, pág. 133


Embedded Agent


Você é um membro aceito da sua agência de inteligência, apesar de qualquer projeto paralelo esquisito em que trabalhe. Pode ser um agente do FBI de ficha impecável que faz bico para a DAE, ou um analista da NSA que por acaso passa algumas semanas por trimestre monitorando relatórios de caoscópio. Como convive mais com agentes "normais", eles o aceitam como um dos seus. Some um dado de bônus a qualquer rolagem de Empatia, Liderança ou Investigação ao lidar com outros membros da sua agência. Você também é a última pessoa que alguém apontaria como "caçador de monstros", o que o mantém fora do radar de criaturas sobrenaturais que de outro modo seriam bem informadas.]==],
				},
				["Embraced without the Cup"] = {
					pt = [==[Lore of the Clans, pág. 218


Embraced without the Cup


Por alguma razão, você não bebeu o sangue dos anciões quando foi admitido no Clã Tremere. Mais perigoso ainda: pode ser que ele não tenha surtido efeito em você. Por isso, você não está vinculado ao Clã como a maioria dos Tremere. Se isso for descoberto, normalmente será corrigido, mas quase dá para acreditar que houve algum propósito nesse lapso, já que os Tremere não cometem erros. Talvez o Clã tenha uma tarefa especial em mente para você, em que precise agir contra o próprio Clã para manter um disfarce…]==],
				},
				["Enchanting Feature"] = {
					pt = [==[Book of Secrets, pág. 37


Enchanting Feature


Abençoado com olhos magníficos, cabelo sedoso, bíceps poderosos, uma graça sobrenatural, abdômen definido, um sorriso deslumbrante ou outra característica física de destaque, você encanta as pessoas com a perfeição bruta desse traço. Ele não precisa ser visualmente evidente: talvez você tenha um cheiro bom, uma voz sedutora, um andar de apelo animalesco ou outro atributo físico igualmente notável. (Tenham bom gosto aqui, pessoal.)

Esta Qualidade substitui Qualidades Físicas relacionadas, como Olhar Encantador, Voz Suave, Gracioso e outros atributos parecidos. Em termos de história, esse Traço Encantador vira parte marcante da descrição da sua personagem. Em termos de sistema, você reduz a dificuldade em -2 quando ela usa aquela característica como parte de algum feito social.

Se o seu mago empregar o Traço Encantador como parte do foco mágico (veja as entradas de Instrumentos Contato Visual, Dança e Movimento, Provações e Esforços, Sexo e Sensualidade, Dominação Social, e Voz e Vocalizações no Capítulo Dez de Mage 20), você pode contá-lo como instrumento personalizado único/especializado (conforme Mage 20, pp. 503 e 588). Do lado bom, isso permite reduzir certas dificuldades de conjuração em -2 quando a característica é especificamente usada para lançar um Efeito. Do lado nem tão bom, isso pode render ao seu mago olhos arrancados, rosto desfigurado, cordas vocais cortadas ou… bem, você entendeu… se um inimigo particularmente cruel considerar aquele traço "o foco do poder dele".]==],
				},
				["Enchanting Voice"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 480


Enchanting Voice


Há algo na sua voz que os outros não conseguem ignorar. Quando você ordena, eles se encolhem. Quando você seduz, eles derretem. Trovejando, acalmando, persuadindo ou simplesmente conversando, sua voz comanda atenção. As dificuldades de todas as rolagens que envolvam usar a voz para persuadir, encantar ou comandar são reduzidas em dois.]==],
				},
				["Entrepreneur"] = {
					pt = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, pág. 178


Entrepreneur


Ganhar dinheiro é natural para você, e você sabe o que é preciso para ter sucesso. Todas as rolagens que envolvam obter dinheiro por meio de negócios têm a dificuldade reduzida em 2.]==],
				},
				["Expert Driver"] = {
					pt = [==[Book of Secrets, pág. 44


Expert Driver


Você nasceu para dirigir como um demônio, aonde quer que a estrada leve. Todas as suas dificuldades em rolagens de direção são reduzidas em -2.]==],
				},
				["Extra Sharp"] = {
					pt = [==[Lore of the Bloodlines, pág. 70


Extra Sharp


Todos os Nagaraja já têm presas afiadas para cortar a carne com facilidade. Uma personagem com esta Qualidade, porém, tem fileiras adicionais de presas, como as de um tubarão, cada uma pronta para causar o máximo de dor possível. Em vez de causar 1 nível de dano letal inabsorvível por mordida, ela causa 2. Alguns Nagaraja gostam desse dom, porque faz as vítimas pararem de se contorcer bem mais rápido. Outros temem que ele crie uma ligação com a mordida dolorosa dos Giovanni, e podem ver Nagaraja com esta Qualidade quase como estranhos.]==],
				},
				["Eyes of Shadow (1)"] = {
					pt = [==[Lore of the Clans, pág. 121


Eyes of Shadow (1)


Há algo nos seus olhos que faz você parecer sombrio e perigoso. Manter contato visual com você é como encarar o Abismo. Pode não ser óbvio o porquê, mas qualquer um com quem você fale sente um arrepio ao cruzar o seu olhar. A dificuldade de qualquer rolagem de Intimidação é reduzida pelo número de pontos nesta Qualidade (até um mínimo de 2).]==],
				},
				["Eyes of Shadow (2)"] = {
					pt = [==[Lore of the Clans, pág. 121


Eyes of Shadow (2)


Há algo nos seus olhos que faz você parecer sombrio e perigoso. Manter contato visual com você é como encarar o Abismo. Pode não ser óbvio o porquê, mas qualquer um com quem você fale sente um arrepio ao cruzar o seu olhar. A dificuldade de qualquer rolagem de Intimidação é reduzida pelo número de pontos nesta Qualidade (até um mínimo de 2).]==],
				},
				["Eyes of Shadow (3)"] = {
					pt = [==[Lore of the Clans, pág. 121


Eyes of Shadow (3)


Há algo nos seus olhos que faz você parecer sombrio e perigoso. Manter contato visual com você é como encarar o Abismo. Pode não ser óbvio o porquê, mas qualquer um com quem você fale sente um arrepio ao cruzar o seu olhar. A dificuldade de qualquer rolagem de Intimidação é reduzida pelo número de pontos nesta Qualidade (até um mínimo de 2).]==],
				},
				["Eyes of Shadow (4)"] = {
					pt = [==[Lore of the Clans, pág. 121


Eyes of Shadow (4)


Há algo nos seus olhos que faz você parecer sombrio e perigoso. Manter contato visual com você é como encarar o Abismo. Pode não ser óbvio o porquê, mas qualquer um com quem você fale sente um arrepio ao cruzar o seu olhar. A dificuldade de qualquer rolagem de Intimidação é reduzida pelo número de pontos nesta Qualidade (até um mínimo de 2).]==],
				},
				["Fae Blood"] = {
					pt = [==[Book of Secrets, pág. 74


Fae Blood


Suas veias pulsam com o sangue enigmático dos fae. Embora não seja um changeling completo, você possui um laço distante com o Sonhar por causa dessa herança estranha. Nos termos de Changeling: The Dreaming, você é kinain: um humano mortal aparentado com eles. Sua Banalidade é baixa (não mais que 4, e muitas vezes menos), e você permanece permanentemente encantado, no sentido de que percebe o mundo changeling e é afetado por ele. Como membro por natureza dessa irmandade encantada, você também tende a ser arrastado para as intrigas esquisitas deles, e sabe um tanto desconfortável sobre o mundo oculto em que vivem.

Como na Qualidade Afinidade Feérica, esta é proibida a tecnomantes de todo tipo. A Banalidade deles é alta demais para sustentar este dom do sangue.]==],
				},
				["Faerie Affinity"] = {
					pt = [==[Book of Secrets, pág. 69


Faerie Affinity


Os seres fae gostam de você. Atraídos por um apelo indizível, eles o procuram e dividem com você segredos que poucos mortais sequer compreendem. Em termos de sistema, você reduz em -2 a dificuldade das suas rolagens sociais ao lidar com changelings e entidades aparentadas; em troca, os changelings reduzem em -2 a dificuldade quando tentam – por qualquer método – obter Glamour de você, ou encantá-lo para trazê-lo ao reino efêmero deles. Em termos de história, os Fae tendem a favorecê-lo em relação a outros mortais, mesmo quando os temperamentos de vocês parecem incompatíveis. Um Nocker ranzinza, por exemplo, normalmente não tem paciência para frivolidade… mas, no seu caso, seu Cultista bobo, ele abre essa exceção!

Tecnomantes, sendo considerados "banais" aos olhos dos Fae, não podem comprar esta Qualidade. Mesmo que não pertençam à União Tecnocrata, a presença desses magos é veneno metafísico para os Sonhadores. (Veja Changeling: The Dreaming para detalhes sobre os efeitos de Glamour e Banalidade sobre os changelings.)]==],
				},
				["False Reflection"] = {
					pt = [==[Lore of the Clans, pág. 161


False Reflection


Mesmo usando a Ofuscação, os Nosferatu ainda aparecem em sua forma verdadeira quando captados por máquinas, como câmeras ou circuitos de vigilância. Com esta capacidade, o Nosferatu pode estender seu poder a imagens e mídias gravadas. Contudo, como na Máscara de Mil Faces, a imagem original não muda de fato; as pessoas é que a veem do jeito que o Nosferatu quer. Infelizmente, computadores não se enganam tão fácil: se a imagem for usada em software de reconhecimento facial, por exemplo, a máquina verá o rosto real do Nosferatu e não achará correspondência. É melhor o Nosferatu tomar cuidado com o uso deste poder, pois ele pode se dissipar com o tempo. Algumas fotos de arquivo deram um belo susto em bibliotecários, anos depois de guardadas.]==],
				},
				["Family Support (1)"] = {
					pt = [==[Book of Secrets, pág. 53


Family Support (1)


Sua família sabe da sua vida Desperta – e, na maior parte, aprova. Você pode pertencer a uma "tradição de família" ancestral (uma linhagem de práticas mágicas/ocultas), a um clã simpático à Nova Era, a uma família religiosa apropriada (ou seja, parentes que seguem o mesmo credo que você), a uma dinastia rica que banca suas escolhas de vida e assim por diante. Essa família pode ser sua proverbial "família de origem" (parentes de sangue), uma "família escolhida" adotiva (gente sem parentesco genético que funciona como família agora) ou as duas. De um jeito ou de outro, sua família está do seu lado. Esta Qualidade não se estende a ajuda econômica pesada, a menos que você compre também os Antecedentes cabíveis (Recursos, Lacaios e assim por diante). Ainda assim, é bom ter um lugar a que chamar de lar, e alguém a quem recorrer quando precisa.

Quanto mais influente a sua família e mais apoio ela lhe dá, mais esta Qualidade custa:

(1 ponto) Você tem uma família "típica" para a sua cultura, e o apoio dela é sobretudo emocional, embora você consiga uns trocados, um favor e um lugar para dormir quando precisa.

(2 pontos) Sua família tem status, dinheiro e influência. Embora espere que você se vire sozinho na maior parte do tempo, ainda dá para conseguir ajuda quando é necessário.

(3 pontos) Herdeiro de riqueza, poder e privilégio, você pode recorrer a favores e influência quando preciso. Seu clã puxa cordas em seu nome mesmo sem você pedir, e as pessoas o tratam com deferência por causa da sua origem.

Como pode atestar quem nasceu num clã rico e disfuncional, é possível ter Apoio Familiar e Problemas de Família (o Defeito descrito abaixo) ao mesmo tempo. Seu pai rico pode ser um babaca abusivo, seu tio querido pode ser possessivo de forma assustadora, e o apoio da mamãe vem com mais cordinhas que uma convenção de marionetistas. Os dois Traços juntos também podem representar uma personagem cuja família de origem é um desastre, mas cuja família escolhida a apoia.

Para fins de magia coincidente, uma família representada por esta Qualidade não conta como testemunha Adormecida quando o mago querido lança Efeitos. Esse benefício normalmente não se estende aos seus companheiros, a menos que eles usem o mesmo tipo de foco que você, pratiquem magia que caiba na visão de mundo da sua família, ou comprem esta Qualidade para representar terem sido "adotados" pela família como amigo de infância, cônjuge ou parte querida do clã.]==],
				},
