				},
				["Fatalist"] = {
					pt = [==[Lore of the Bloodlines, pág. 5


Fatalist


O estudo do tempo levou a personagem a acreditar que o que está feito está simplesmente feito. O destino é um caminho fixo e, portanto, somos todos escravos do nosso próprio futuro. Assim, nada pode ser realmente culpa nossa, pois nada está inteiramente sob nosso controle. Fica então bem mais fácil se desculpar dos próprios excessos. A personagem subtrai 2 da dificuldade de todas as rolagens de degeneração contra perda de Humanidade ou de Caminho de Iluminação.]==],
				},
				["Favor (1)"] = {
					pt = [==[Book of Secrets, pág. 54


Favor (1)


Também conhecida como Dádiva, esta Qualidade significa que alguém lhe deve, e muito. Você coçou as costas dessa pessoa e, no devido tempo, vai cobrar que cocem as suas. Talvez você tenha ajudado um mago de nível Mestre… ou socorrido um príncipe vampiro… ou feito um favor a um Adormecido rico, a um espírito, a uma fada ou a um membro graduado das Raças Metamorfas. Seja quem for, essa parte é mais poderosa que você e consegue fazer, em seu nome, coisas que você não conseguiria sozinho.

O valor desta Qualidade depende do tamanho do favor. Atos menores de benevolência custam um ponto, dádivas consideráveis valem dois, e uma dívida de vida vale três. Você pode comprar vários Favores, seja de uma mesma parte, seja de várias pessoas que lhe devem. O Narrador pode conceder esta Qualidade no lugar de pontos de experiência se sua personagem tiver ajudado um personagem coadjuvante e pedido, merecido ou exigido um Favor em troca. Uma vez prestado o favor, porém, a Qualidade se esgota. Ajuda duradoura seria contada como um Antecedente do tipo Mentor ou Patrono, ou como um dos aliados descritos na seção de Qualidades Sobrenaturais.]==],
				},
				["Favor (2)"] = {
					pt = [==[Book of Secrets, pág. 54


Favor (2)


Também conhecida como Dádiva, esta Qualidade significa que alguém lhe deve, e muito. Você coçou as costas dessa pessoa e, no devido tempo, vai cobrar que cocem as suas. Talvez você tenha ajudado um mago de nível Mestre… ou socorrido um príncipe vampiro… ou feito um favor a um Adormecido rico, a um espírito, a uma fada ou a um membro graduado das Raças Metamorfas. Seja quem for, essa parte é mais poderosa que você e consegue fazer, em seu nome, coisas que você não conseguiria sozinho.

