				},
				["Fist of God"] = {
					pt = [==[The Hunters Hunted II, pág. 124


Fist of God


Alguns o chamam de "Martelo das Bruxas", pois suas mãos nuas causam ferimentos graves aos filhos da noite antiga. Todo o seu dano de Briga é considerado agravado contra sobrenaturais. Acerte com o Narrador uma boa razão para esse efeito raro e para o modo como ele se desenvolveu. Apenas mortais com Humanidade sete ou mais podem comprar (ou manter) esta Qualidade.]==],
				},
				["Force of Spirit"] = {
					pt = [==[M20 Sorcerer, pág. 107


Force of Spirit


A luz da sua alma é evidente para quem está ao redor. Você pode brilhar fisicamente, parecer divinamente belo, ou talvez sua voz ressoe com a música das esferas. Você pode gastar pontos de Quintessência para reduzir a dificuldade de uma rolagem social, um por um. Nenhuma dificuldade pode ficar abaixo de dois, e nenhuma pode ser reduzida em mais de três. Você precisa ser capaz de armazenar Quintessência no próprio padrão para se qualificar a esta Qualidade.]==],
				},
				["Former Ghoul"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 487


Former Ghoul


Você foi apresentado ao Sangue muito antes de ser feito Cainita. Sua longa experiência como carniçal lhe dá compreensão e desenvoltura na sociedade vampírica. Você tem -1 de dificuldade em todas as rolagens Sociais na presença de outros neonatos (em especial os que não foram educados por seus senhores), e -1 de dificuldade em todas as rolagens ligadas a conhecimento vampírico.]==],
				},
				["Foul Blood"] = {
					pt = [==[Lore of the Clans, pág. 160


Foul Blood


Seu sangue é repugnante; na verdade, tem gosto tão nojento que exige uma rolagem de Força de Vontade (dificuldade 6) só para não engasgar e vomitar depois de prová-lo. Se alguém for tolo o bastante para tentar diablerie em você, precisará de três sucessos em rolagens de Força de Vontade (dificuldade 9) para levar aquilo até o fim. O sangue é tão nojento que ninguém consegue segurá-lo tempo suficiente para virar carniçal, tampouco.]==],
				},
				["Friend of the Underground"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 489


Friend of the Underground


Embora você não seja Nosferatu, conhece bem os esgotos, túneis, dutos, linhas de metrô e outras passagens subterrâneas da sua cidade. Os Nosferatu locais (e quaisquer outras criaturas que morem na lama) podem até não gostar de você, mas não estão inclinados a matá-lo à primeira vista quando o veem no território deles. Você tem -1 de dificuldade em qualquer rolagem que envolva o mundo subterrâneo (esgueirar-se de um ponto a outro por baixo, achar rotas para subsolos e assim por diante). Nosferatu não podem comprar esta Qualidade.]==],
				},
				["Friendly Face"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 480


Friendly Face


Você tem um rosto que lembra alguém a todo mundo, a ponto de estranhos ficarem bem-dispostos com você por causa disso. O efeito não some nem quando você explica o "engano", o que lhe dá -1 de dificuldade em todas as rolagens Sociais cabíveis (vale para Sedução, não vale para Intimidação, por exemplo) quando há um estranho envolvido. Esta Qualidade só funciona no primeiro encontro.]==],
				},
				["Fugue Instinct"] = {
					pt = [==[Lore of the Bloodlines, pág. 26


Fugue Instinct


Você consegue ouvir avisos e obter percepções ao escutar a Fuga mais fundo. Para isso, precisa abrir mão de uma das suas ações e escutar direito a Fuga interior. Durante esse tempo, você pode se defender, mas não realiza ações ativas. Se o fizer, ganha uma percepção para a ação seguinte, que lhe concede +2 dados na parada que usar.]==],
				},
				["Ghoul"] = {
					pt = [==[Book of Secrets, pág. 75


Ghoul


O sangue dos Cainitas fez de você algo mais que humano. Por vontade própria ou não, você bebeu do sangue de um vampiro e, embora provavelmente já não esteja vinculado pelo sangue ao serviço dela (a menos que esteja), a vitalidade antinatural daquela criatura virou sua. O problema é que você precisa de mais vitae para sustentar suas capacidades sobrenaturais… e, como muitos magos descobriram, esse sangue é extremamente viciante.

Uma personagem carniçal envelhece muito devagar, ganha um sucesso automático em qualquer rolagem baseada em Força e causa um dado extra de dano em todos os ataques corpo a corpo não mágicos. Se sua crônica usa as regras de Vampiro: A Máscara, ela também tem uma reserva de sangue, um ponto em Potência e a possibilidade de comprar e usar Fortitude, Potência e uma capacidade do clã do vampiro que a iniciou.

Essa é a parte boa; as ruins envolvem o desejo constante por mais vitae, a perda desses bônus sobrenaturais depois de cerca de um mês sem sangue de vampiro, vários pontos em Ressonância (ou o Defeito Ecos, detalhado em Mage 20, pp. 646-647) que refletem a natureza corrupta dos mortos-vivos, e os inconvenientes óbvios de andar com vampiros só para poder beber o sangue deles.]==],
				},
				["Green Thumb"] = {
					pt = [==[Book of Secrets, pág. 69


Green Thumb


As plantas florescem ao seu toque. Embora não desabrochem e cresçam ao contato (um efeito escancaradamente paranormal que fazia parte da forma original desta Qualidade), elas recebem um belo impulso de saúde quando você trabalha com elas. Reduza em -2 a dificuldade de todas as rolagens que não sejam de Arete, e em -1 a das rolagens de Arete, ao lidar com plantas, árvores e outras formas de vegetação – algas, mofo, fungos, limo marinho e afins. Em termos de história, sua aura pulsa com vitalidade verde, a matéria vegetal cresce rápida e robusta na sua presença, e sua Ressonância e Sinergia refletem uma ligação poderosa com o mundo verde. Qualidade comum entre Verbena, Bata'a e outros místicos primais, ela também pode representar um tino estranho para biomassa vegetal que certos tecnomantes possuem.]==],
				},
				["Groomed for Embrace"] = {
					pt = [==[Ghouls & Revenants, pág. 129


Groomed for Embrace


Sua personagem foi julgada digna do Abraço e está sendo preparada para essa eventualidade por meio de treinamento cuidadoso e dirigido pelo seu futuro senhor. Embora esta Qualidade não garanta quando você será Abraçado, sua personagem sabe que virará vampira e conhece a identidade do seu futuro senhor.

Os benefícios de ser Preparado para o Abraço têm a ver com seu papel atual como carniçal e com sua futura posição como vampiro dentro de um Clã ou linhagem específica. Assim, seu lugar entre os carniçais da casa da sua domitora sobe ao de aprendiz valioso, em vez de servo descartável. Alguns Clãs, como os Tremere ou os Tzimisce, podem acompanhar seu progresso pelo estudo acadêmico do saber, das Disciplinas ou dos rituais taumatúrgicos. Você pode não conseguir usar a Vicissitude, por exemplo, mas talvez tenha permissão de auxiliar sua domitora na mesa de laboratório dela. Outros vampiros podem ser mais cautelosos e prepará-lo para ser avaliado pelo príncipe local antes de irem adiante.

Há alguns inconvenientes que sua personagem pode encontrar ao longo da crônica. Como você alcançou o sonho de muitos carniçais, pode ser alvo de acessos de ciúme raivoso ou de agressões por parte de outros carniçais. Sua domitora pode até saber disso e ter estimulado esses sentimentos para testar se você é digno de virar vampiro.

Além disso, se o fato vier à tona, você pode atrair atenção indesejada dos inimigos do seu futuro senhor. Como é bem provável que ele também seja sua domitora, você pode ser sequestrado, espionado ou pressionado por informações sobre o refúgio, os bens e os planos dela. Muitos vampiros, porém, não revelam que seus carniçais e revenantes estão sendo Preparados para o Abraço, e mantêm as intenções em segredo.

Se decidir comprar a Qualidade Preparado para o Abraço, você pode comprar Domitor Benevolente por um ponto, desde que tenha o Antecedente Domitor exigido. Nesse caso, você está sinalizando ao Narrador que sua domitora se comprometeu a ser sua futura senhora. Você também pode, a critério do Narrador, aprender um ponto numa terceira Disciplina conhecida do seu futuro senhor, ou seguir um Caminho depois de abandonar sua Humanidade.

Usado por: carniçais da Camarilla e da Sabá, além de alguns revenantes. Carniçais independentes podem ser Abraçados, mas não seriam Preparados para o Abraço, por sua condição de párias entre os carniçais.]==],
				},
				["Guardian Angel"] = {
					pt = [==[Book of Secrets, pág. 78


Guardian Angel


Uma entidade poderosa está velando por você, oferecendo conselhos, ajuda e proteção ocasional quando a coisa fica feia. Essa ajuda está além do seu controle (talvez até além da sua compreensão) e, embora este "anjo" certamente tenha defendido os seus interesses até agora, pode haver um preço terrível preso a tudo isso. Você acha que seu anjo é dos bons mas, sério – você já leu as lendas sobre anjos? Doçura e luz não estão entre as características mais citadas deles.

Do ponto de vista da Qualidade, este Traço às vezes gera situações bastante irônicas – um anjo de verdade, por exemplo, velando por um mago Infernalista, ou um espírito da natureza protegendo um Tecnocrata convicto. A parte prestativa pode estar esperando que o mago "veja a luz", honrando um voto antigo feito aos ancestrais dele, conduzindo o protegido a um Caminho novo e inesperado, ou talvez preparando-o para uma revelação final que pode ser pior que aquilo de que o anjo o vem afastando.

Do ponto de vista do Narrador, recomendamos explorar a natureza misteriosa e potencialmente assustadora deste "anjo" da guarda. Os anjos das lendas costumam ser notoriamente sangrentos no trabalho e conseguem apavorar mortais mesmo quando as intenções são tecnicamente justas. Como Narrador, determine quem está ajudando o mago, e por quê; essa informação, claro, pode ser só sua, e cabe aos jogadores especular. Sempre que o anjo se manifestar, explore a estranheza implacável dessas entidades, envolvendo suas aparições em simbolismo inquietante e fenômenos elementais (ventos, fogos, terremotos e assim por diante). (Para sugestões, veja Mage 20, pp. 356-359 e 363-367.)

Por outro lado, o anjo pode ser uma pessoa ou um animal aparentemente comum que simplesmente desencadeia o inferno em nome do mago. Os espíritos animais, servos e elementais descritos no Apêndice I de Mage 20 representam a ponta mais comportada do espectro de anjos da guarda; seres mais estranhos podem incluir massas protoplasmáticas, energias cintilantes, bestas medonhas e coisas inomináveis a serviço de poderes que é melhor nem sonhar. Mesmo que o anjo seja exatamente isso – um mensageiro do Deus bíblico –, esses mensageiros podem ser bem apavorantes. Veja Ezequiel 1-10, Gênesis 3, Apocalipse 4 e outras manifestações de tirar o fôlego. Se os Poderosos por trás deste anjo da guarda forem mais do tipo deuses pagãos ou horrores cósmicos, esta Qualidade sobrenatural pode soltar coisas bem assustadoras…]==],
				},
				["Half-Life"] = {
					pt = [==[Lore of the Bloodlines, pág. 4


Half-Life


Você é mais que um vampiro; é um espectro em forma vampírica. Sua consciência das realidades da morte permite gastar metade do custo normal em pontos de experiência para elevar Caminhos de Necromancia depois do primeiro ponto, e permite transitar entre as Terras das Sombras e as Terras da Pele gastando um ponto de Força de Vontade. Você não pode ser controlado como um espírito comum pelo uso de Necromancia mas, se outros vampiros descobrirem o que você é, pode esperar ser caçado sem piedade. Você sofre as mesmas fraquezas e tem as mesmas forças de um vampiro mas, se for observado com um poder como Percepção da Aura (V20, p. 135), sua aura aparece como uma dupla exposição, com uma forma humanoide translúcida e trêmula entrando e saindo da sua.]==],
				},
				["Hands of Daedalus"] = {
					pt = [==[Book of Secrets, pág. 71


Hands of Daedalus


Você tem um dom inato para construir máquinas e tecnologia. Esses aparelhos parecem ganhar vida nas suas mãos, encaixando-se com facilidade e funcionando com precisão incrível depois que você trabalha neles. Embora o dom não se estenda aos meandros do software, você pode trabalhar em hardware (supondo que saiba o que está fazendo) com a mesma naturalidade com que regula um Ford 58.

Em termos de sistema, qualquer rolagem que você faça para construir, consertar, inventar ou de outro modo modificar tecnologias mecânicas tem -2 de dificuldade quando você tem a chance de pôr essas Mãos de Dédalo para trabalhar. Instrumentos mágicos de base tecnológica (veja as entradas de Mage 20 sobre Armaduras, Dispositivos e Máquinas e outras tecnologias de hardware) e práticas (veja Artesanato e Hipertecnologia na seção Foco e as Artes, Capítulo Dez de Mage 20) funcionam, nas suas mãos, como Instrumentos Personalizados (Mage 20, pp. 503 e 587-588) depois que você tem a chance de se familiarizar com eles… e de deixá-los se familiarizar com você.]==],
				},
				["Harmless"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 487


Harmless


Todo mundo na cidade conhece você, e sabe que você não é ameaça aos planos deles. Embora esse tipo de avaliação possa parecer ofensivo, é também o que o mantém vivo. Ninguém o considera digno do tempo deles, e essa opinião baixa o mantém em segurança. Se você começar a agir de um jeito que demonstre não ser mais inofensivo, a reação dos outros provavelmente vai mudar.]==],
				},
				["Haven Affinity"] = {
					pt = [==[Lore of the Clans, pág. 238


Haven Affinity


Você é a terra. A terra é você. O solo natal o chama. Você dá a ele, e ele dá a você. Sua ligação com a terra do seu refúgio principal lhe concede um dado extra em todas as paradas quando você age ali. Ela funciona também como farol místico, permitindo localizá-lo com uma rolagem normal de Percepção + Sobrevivência (dificuldade 6), +1 de dificuldade quando um estado ou país o separa dele; +2 se você estiver do outro lado do mundo. Isso vale apenas para o seu refúgio principal.]==],
				},
				["Healing Touch"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 493


Healing Touch


Normalmente, vampiros só conseguem selar os ferimentos que causam ao se alimentar lambendo-os. Com um simples toque, você obtém o mesmo efeito, fechando as perfurações deixadas pela bebida do sangue.]==],
				},
				["Heart of Needles"] = {
					pt = [==[Lore of the Clans, pág. 182


Heart of Needles


Suas capacidades naturais com ilusões o deixaram particularmente blasé e difícil de impressionar. Como algo poderia ser tão perfeito quanto a sua própria imaginação? Por isso, seu coração é mais duro que a média, e você tem resistência significativa ao controle emocional. Todos os poderes e desafios Sociais que tentem manipulá-lo emocionalmente sofrem +2 de dificuldade.]==],
				},
				["Heavy Hands"] = {
					pt = [==[Lore of the Bloodlines, pág. 37


Heavy Hands


Um dos efeitos de virar vampiro são as mudanças estranhas que acontecem no corpo. As alterações evidentes nas suas mãos as deixaram mais duras, mais rígidas e mais insensíveis à dor. Todas as dificuldades de rolagens de dano com ataques desarmados caem em 1.]==],
				},
				["Heretical Sympathizer"] = {
					pt = [==[Dark Ages Tome of Secrets, pág. 4


Heretical Sympathizer


Você é o protetor de uma Bruxa de Equidna, ou possui um tesouro do conhecimento delas. Fazendo isso por altruísmo ou por interesse próprio, você tem a ganhar o apoio permanente do culto e a desconfiança duradoura da Ortodoxia. Dependendo da situação que o levou a adquirir este traço, você pode conseguir cortejar o lado oposto entregando sua Górgona tutelada e ganhando o aval dos Seguidores de Set egípcios.]==],
				},
				["Hidden Diablerie"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 493


Hidden Diablerie


Os reveladores riscos negros da diablerie não se manifestam na sua aura.]==],
				},
				["Hideaway /Safehouse (2)"] = {
					pt = [==[Book of Secrets, pág. 55


Hideaway /Safehouse (2)


Quando você precisa de um tempo só seu, existe um lugar aonde ir que ninguém conhece além de você. É pequeno, sim, e remoto o bastante para que amigos e inimigos não o achem lá. É provável que seja um apartamento secreto, uma cabana distante, um trailer, ou literalmente uma caverna, um bosque ou um ponto de acampamento aonde você foge do estresse da sua vida comum. Pode até ser um Reino de bolso, acessível apenas a você e a quem você escolher, se for tolo o bastante para confiar esse esconderijo a alguém. A menos que você entregue a localização, ou acabe rastreado até lá por um perseguidor dedicado, esse refúgio é sua saída de emergência pessoal. Use-o com sabedoria e tome cuidado ao ir e vir!

Ao contrário da Qualidade Propriedade (veja abaixo) ou dos Antecedentes Capela, Nodo e Santuário, esse buraco discreto não é amplo, elaborado nem mágico por natureza. Dito isso, ele está escondido da maioria das formas casuais de detecção. Você pode combinar esta Qualidade com Propriedade, Nodo ou Santuário, embora esses Traços precisem ser comprados além do seu Esconderijo, e a existência deles precise permanecer secreta dos outros personagens. Capelas são sociais por padrão e, portanto, não podem virar Esconderijo. O lugar está abastecido com o que você precisaria para umas duas semanas de estadia, e pode, claro, ser abastecido para períodos maiores se você levar mais suprimentos. Embora você possa ser rastreado até lá por magia ou outros métodos, seu retiro não está ligado a você por nenhum canal oficial pesquisável: contas, contrato de aluguel, correspondência, serviços de internet etc.

Uma vez por história – se acontecerem coisas que possam levar outras pessoas até o esconderijo, se você fizer algo que possa revelar a localização, ou se alguém dedicar tempo e esforço a rastreá-lo –, o Narrador pode rolar dois dados contra dificuldade 6. (Sim, essa rolagem é feita em segredo, então você não sabe o resultado.) Se ela obtiver ao menos um sucesso, seu segredo continua guardado; uma falha significa que alguém pegou uma pista, mas não o seu paradeiro exato; quatro falhas sucessivas revelam a localização, e uma falha crítica a expõe imediatamente. Enquanto você continuar apagando seus rastros, porém, o lugar continua sendo só seu.

Por quatro pontos, esta Qualidade também pode ser comprada com o nome Casa Segura. Nesse caso, é um refúgio protegido com instalações e proteções melhores que as de um Esconderijo comum. O estoque dá conta de umas doze pessoas por cerca de dois meses, e a Qualidade inclui uma pequena equipe dedicada (em regras, dois pontos em Lacaios ou quatro em Reforços) para manter o local. Ao contrário do Esconderijo, essa área aguenta um assalto de pequeno porte e traz até três escritórios/áreas de trabalho, paredes reforçadas, vidro à prova de balas e uma sala de pânico tipo cofre. A casa segura inclui também um sistema blindado de comunicações (-2 nas tentativas de invadir ou rastrear) e um sistema simples mas eficaz de alarme e câmeras (de novo, -2 nas tentativas de subversão). A desvantagem é que a Qualidade não é propriedade sua: pertence aos seus superiores e pode lhe ser tirada se você se indispuser com quem paga a conta. Em geral, uma Tecnocrata em boa situação com seus superiores consegue a Qualidade Casa Segura (ou é premiada com uma, por serviço especialmente bom), mas outros magos também podem obter instalação semelhante.

Por seis pontos, seu refúgio pode ser Casa Segura e Esconderijo ao mesmo tempo; nesse caso, a propriedade é inteiramente sua. Aproveite sua Batcaverna, Sr. Wayne!]==],
				},
				["Hideaway /Safehouse (4)"] = {
					pt = [==[Book of Secrets, pág. 55


Hideaway /Safehouse (4)


Quando você precisa de um tempo só seu, existe um lugar aonde ir que ninguém conhece além de você. É pequeno, sim, e remoto o bastante para que amigos e inimigos não o achem lá. É provável que seja um apartamento secreto, uma cabana distante, um trailer, ou literalmente uma caverna, um bosque ou um ponto de acampamento aonde você foge do estresse da sua vida comum. Pode até ser um Reino de bolso, acessível apenas a você e a quem você escolher, se for tolo o bastante para confiar esse esconderijo a alguém. A menos que você entregue a localização, ou acabe rastreado até lá por um perseguidor dedicado, esse refúgio é sua saída de emergência pessoal. Use-o com sabedoria e tome cuidado ao ir e vir!

