Uma vez por história – se acontecerem coisas que possam levar outras pessoas até o esconderijo, se você fizer algo que possa revelar a localização, ou se alguém dedicar tempo e esforço a rastreá-lo –, o Narrador pode rolar dois dados contra dificuldade 6. (Sim, essa rolagem é feita em segredo, então você não sabe o resultado.) Se ela obtiver ao menos um sucesso, seu segredo continua guardado; uma falha significa que alguém pegou uma pista, mas não o seu paradeiro exato; quatro falhas sucessivas revelam a localização, e uma falha crítica a expõe imediatamente. Enquanto você continuar apagando seus rastros, porém, o lugar continua sendo só seu.

Por quatro pontos, esta Qualidade também pode ser comprada com o nome Casa Segura. Nesse caso, é um refúgio protegido com instalações e proteções melhores que as de um Esconderijo comum. O estoque dá conta de umas doze pessoas por cerca de dois meses, e a Qualidade inclui uma pequena equipe dedicada (em regras, dois pontos em Lacaios ou quatro em Reforços) para manter o local. Ao contrário do Esconderijo, essa área aguenta um assalto de pequeno porte e traz até três escritórios/áreas de trabalho, paredes reforçadas, vidro à prova de balas e uma sala de pânico tipo cofre. A casa segura inclui também um sistema blindado de comunicações (-2 nas tentativas de invadir ou rastrear) e um sistema simples mas eficaz de alarme e câmeras (de novo, -2 nas tentativas de subversão). A desvantagem é que a Qualidade não é propriedade sua: pertence aos seus superiores e pode lhe ser tirada se você se indispuser com quem paga a conta. Em geral, uma Tecnocrata em boa situação com seus superiores consegue a Qualidade Casa Segura (ou é premiada com uma, por serviço especialmente bom), mas outros magos também podem obter instalação semelhante.

Por seis pontos, seu refúgio pode ser Casa Segura e Esconderijo ao mesmo tempo; nesse caso, a propriedade é inteiramente sua. Aproveite sua Batcaverna, Sr. Wayne!]==],
				},
				["Hideaway /Safehouse (6)"] = {
					pt = [==[Book of Secrets, pág. 55


Hideaway /Safehouse (6)


Quando você precisa de um tempo só seu, existe um lugar aonde ir que ninguém conhece além de você. É pequeno, sim, e remoto o bastante para que amigos e inimigos não o achem lá. É provável que seja um apartamento secreto, uma cabana distante, um trailer, ou literalmente uma caverna, um bosque ou um ponto de acampamento aonde você foge do estresse da sua vida comum. Pode até ser um Reino de bolso, acessível apenas a você e a quem você escolher, se for tolo o bastante para confiar esse esconderijo a alguém. A menos que você entregue a localização, ou acabe rastreado até lá por um perseguidor dedicado, esse refúgio é sua saída de emergência pessoal. Use-o com sabedoria e tome cuidado ao ir e vir!

Ao contrário da Qualidade Propriedade (veja abaixo) ou dos Antecedentes Capela, Nodo e Santuário, esse buraco discreto não é amplo, elaborado nem mágico por natureza. Dito isso, ele está escondido da maioria das formas casuais de detecção. Você pode combinar esta Qualidade com Propriedade, Nodo ou Santuário, embora esses Traços precisem ser comprados além do seu Esconderijo, e a existência deles precise permanecer secreta dos outros personagens. Capelas são sociais por padrão e, portanto, não podem virar Esconderijo. O lugar está abastecido com o que você precisaria para umas duas semanas de estadia, e pode, claro, ser abastecido para períodos maiores se você levar mais suprimentos. Embora você possa ser rastreado até lá por magia ou outros métodos, seu retiro não está ligado a você por nenhum canal oficial pesquisável: contas, contrato de aluguel, correspondência, serviços de internet etc.

Uma vez por história – se acontecerem coisas que possam levar outras pessoas até o esconderijo, se você fizer algo que possa revelar a localização, ou se alguém dedicar tempo e esforço a rastreá-lo –, o Narrador pode rolar dois dados contra dificuldade 6. (Sim, essa rolagem é feita em segredo, então você não sabe o resultado.) Se ela obtiver ao menos um sucesso, seu segredo continua guardado; uma falha significa que alguém pegou uma pista, mas não o seu paradeiro exato; quatro falhas sucessivas revelam a localização, e uma falha crítica a expõe imediatamente. Enquanto você continuar apagando seus rastros, porém, o lugar continua sendo só seu.

Por quatro pontos, esta Qualidade também pode ser comprada com o nome Casa Segura. Nesse caso, é um refúgio protegido com instalações e proteções melhores que as de um Esconderijo comum. O estoque dá conta de umas doze pessoas por cerca de dois meses, e a Qualidade inclui uma pequena equipe dedicada (em regras, dois pontos em Lacaios ou quatro em Reforços) para manter o local. Ao contrário do Esconderijo, essa área aguenta um assalto de pequeno porte e traz até três escritórios/áreas de trabalho, paredes reforçadas, vidro à prova de balas e uma sala de pânico tipo cofre. A casa segura inclui também um sistema blindado de comunicações (-2 nas tentativas de invadir ou rastrear) e um sistema simples mas eficaz de alarme e câmeras (de novo, -2 nas tentativas de subversão). A desvantagem é que a Qualidade não é propriedade sua: pertence aos seus superiores e pode lhe ser tirada se você se indispuser com quem paga a conta. Em geral, uma Tecnocrata em boa situação com seus superiores consegue a Qualidade Casa Segura (ou é premiada com uma, por serviço especialmente bom), mas outros magos também podem obter instalação semelhante.

Por seis pontos, seu refúgio pode ser Casa Segura e Esconderijo ao mesmo tempo; nesse caso, a propriedade é inteiramente sua. Aproveite sua Batcaverna, Sr. Wayne!]==],
				},
				["Hive-Minded (1)"] = {
					pt = [==[Lore of the Clans, pág. 86


Hive-Minded (1)


Seu Animalismo funciona com insetos e outros bichos rastejantes, além dos animais. Se você escolher a versão de dois pontos desta qualidade, suas formas de Proteanismo podem assumir a forma de um enxame de insetos em vez de uma criatura só (embora o enxame precise ter tamanho e equivalência mecânica de um lobo ou de um morcego, conforme o caso).]==],
				},
				["Hive-Minded (2)"] = {
					pt = [==[Lore of the Clans, pág. 86


Hive-Minded (2)


Seu Animalismo funciona com insetos e outros bichos rastejantes, além dos animais. Se você escolher a versão de dois pontos desta qualidade, suas formas de Proteanismo podem assumir a forma de um enxame de insetos em vez de uma criatura só (embora o enxame precise ter tamanho e equivalência mecânica de um lobo ou de um morcego, conforme o caso).]==],
				},
				["Holy Aura"] = {
					pt = [==[The Hunters Hunted II, pág. 124


Holy Aura


Não importa a cor: sua aura arde como um farol brilhante de devoção religiosa. Até mortais que não enxergam auras se sentem atraídos pela sua presença. Subtraia um da dificuldade de todas as rolagens de interação social. Alguns sobrenaturais verão isso como algo positivo; outros, especialmente os Cainitas, provavelmente serão hostis a você. Muitos vão acreditar que você tem grande poder (independentemente da verdade).]==],
				},
				["Huge Size"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 480


Huge Size


Você é anormalmente grande, com pelo menos 2,08 m e 135 kg. Além de torná-lo extremamente notável em público, essa massa extra lhe concede um nível de vitalidade Escoriado adicional. Personagens com esta Qualidade também podem ganhar bônus para empurrar objetos, arrombar portas trancadas, evitar ser derrubado etc.]==],
				},
				["Hyperflexible"] = {
					pt = [==[Book of Secrets, pág. 36


Hyperflexible


Você é o que se costuma chamar, de forma equivocada, de "desossado" (como na velha Qualidade de mesmo nome). Na verdade, suas articulações são extremamente flexíveis, talvez por treino intenso, por ampliação mágica ou pela condição médica conhecida como Síndrome de Ehlers-Danlos (SED – veja acima, e também o Defeito Impedimento, abaixo). Seja qual for a razão, você se estica e se dobra de formas que a maioria não consegue.

Em termos de jogo, esta Qualidade concede -2 de dificuldade em rolagens que envolvam flexibilidade física – tentativas de escapar, contorções etc. Sua personagem também consegue realizar feitos impressionantes de hiperflexibilidade, como os vistos no Cirque du Soleil, na dança butô e em posturas extremas de ioga.]==],
				},
				["Hyperfocus"] = {
					pt = [==[Book of Secrets, pág. 45


Hyperfocus


Com tempo e ausência de distrações, você consegue concentrar a mente a um grau fora do comum. Para cada hora de concentração sem distrações numa tarefa mundana (não numa rolagem de conjuração mágica), você pode somar um dado à sua parada em cada rolagem feita durante uma ação estendida (como descrito em Mage 20, p. 389). Esse bônus tem limite de três dados no total. Assim, se Nix tem Hiperfoco e passa duas horas numa tarefa, o jogador soma dois dados extras à parada de Nix; três horas dão três dados, mas quatro horas continuam dando três. Esses dois ou três dados, porém, são usados toda vez que o jogador de Nix rola para completar aquela ação estendida.

Como dito acima, esta Qualidade não ajuda em rolagens de conjuração mágica. Por causa do tempo necessário de concentração – e da ausência de distrações –, o Hiperfoco também não ajuda em combate, embora uma personagem estrategista possa hiperfocar no planejamento de uma batalha, mas não em travá-la depois que o combate começa. Na mesma linha, um mago pode usar o Hiperfoco para auxiliar nos elementos mundanos de um ritual – veja Rituais e Habilidades Mundanas, Mage 20, p. 541.

O hiperfoco extremo costuma (embora não exclusivamente) ser associado a pessoas do espectro autista, ainda que algumas autoridades afirmem que a perseveração (veja o Defeito Trava Mental) é uma forma mais precisa de olhar para esse tipo intenso de concentração. Com ou sem autismo, esta Qualidade é útil para Herméticos, tecnomantes, xamãs e outros magos cujas práticas dependem de dedicação extrema a certas tarefas.]==],
				},
				["Hypersensitivity"] = {
					pt = [==[Book of Secrets, pág. 38


Hypersensitivity


Extraordinariamente aberto às sensações físicas, você possui uma profundidade de sensibilidade que a maioria das pessoas nem consegue conceber. Um simples gole de vinho lhe revela a safra; um sopro de fumaça denuncia a qualidade (ou a falta dela) e a origem do tabaco queimado; um toque leve pode invocar êxtases orgásmicos.

Em termos de história, você "cai" com facilidade dentro de uma sensação prazerosa, saboreando-a muito além da sensibilidade humana comum. Em termos de sistema, você reduz a dificuldade em -2 ao tentar usar uma rolagem de Percepção + Prontidão para identificar detalhes de uma sensação. Supondo que você use instrumentos como Trabalho Corporal, Drogas, Energia, Contato Visual, Comida e Bebida ou Sexo e Sensualidade (e você provavelmente usa a maioria deles, se não todos), consegue extrair mais dessas sensações, o que lhe permite empregar tais instrumentos mais rápido e, talvez (opção do Narrador), lhe dá -2 na dificuldade das rolagens de Habilidade associadas. Os limites normais de modificador continuam valendo.

Por outro lado, sensações dolorosas e superestimulação podem disparar agonias paralisantes e pânico intenso. Sempre que você experimentar uma sensação dolorosa sem consentimento (ou seja, ser açoitado contra a vontade, submetido a música alta que não queria ouvir, ou ferido por algo que não queria que o ferisse), precisa fazer uma rolagem de Força de Vontade para não ser "puxado para o fundo" e ficar atordoado pela dor por um turno ou dois. (Veja Atordoamento em Mage 20, p. 417.) A dificuldade depende da intensidade da dor – de 4 para um incômodo pequeno a 10 para uma agonia de gritar. Como qualquer Cultista pode lhe dizer, o êxtase é mesmo uma via de mão dupla!

Embora esta Qualidade combine bem com Sentidos Aguçados, ela não pode ser adquirida por uma personagem que também seja Insensível à Dor (detalhada abaixo).]==],
				},
				["Impressive Restraint"] = {
					pt = [==[Lore of the Clans, pág. 200


Impressive Restraint


Quando você não se alimentou, estar perto de mortais pode ser uma tortura. O martelar do sangue nas veias deles não o tenta nem de perto tanto quanto tentaria outros Cainitas. Quando a oportunidade aparece, a dificuldade de todas as rolagens de Autocontrole para resistir à fome recebe -2. Personagens em Caminhos de Iluminação que exijam Instinto não podem adquirir esta Qualidade.]==],
				},
				["Incantation"] = {
					pt = [==[Dark Ages Tome of Secrets, pág. 4


Incantation


Sua personagem aprende um único Encantamento. Esta Qualidade pode ser comprada várias vezes durante o jogo, cada vez para um Encantamento novo. O custo é de seis pontos de experiência.]==],
				},
				["Indelible (1)"] = {
					pt = [==[Lore of the Clans, pág. 200


Indelible (1)


Enquanto o corpo dos outros vampiros volta a cada noite ao estado em que estava no Abraço, quaisquer modificações corporais que você adquira depois do Abraço permanecem como estão até que você gaste ativamente um ponto de Força de Vontade para devolver o corpo ao seu estado de tabula rasa. Esta Qualidade vale desde mudanças simples, como pintar ou cortar o cabelo, até modificações complicadas, como tatuagens, piercings ou mesmo pequenos implantes.

Se a Qualidade permitir apenas alterações cosméticas, vale 1 ponto. Se permitir alterações mais utilitárias, como implantes de RFID que acionam certos dispositivos eletrônicos, vale 2 pontos.]==],
				},
				["Indelible (2)"] = {
					pt = [==[Lore of the Clans, pág. 200


Indelible (2)


Enquanto o corpo dos outros vampiros volta a cada noite ao estado em que estava no Abraço, quaisquer modificações corporais que você adquira depois do Abraço permanecem como estão até que você gaste ativamente um ponto de Força de Vontade para devolver o corpo ao seu estado de tabula rasa. Esta Qualidade vale desde mudanças simples, como pintar ou cortar o cabelo, até modificações complicadas, como tatuagens, piercings ou mesmo pequenos implantes.

Se a Qualidade permitir apenas alterações cosméticas, vale 1 ponto. Se permitir alterações mais utilitárias, como implantes de RFID que acionam certos dispositivos eletrônicos, vale 2 pontos.]==],
				},
				["Inner Knight"] = {
					pt = [==[Book of Secrets, pág. 77


Inner Knight


No fundo do seu coração, você é um herói. Enquanto seus companheiros trabalham pelos próprios fins egoístas, você encarna um propósito mais alto. Esse propósito o guia de formas estranhas que, às vezes, parecem movidas por uma força maior que você – uma força nobre, naturalmente, mas que transcende até a sua Iluminação pessoal. Em sonhos, você se vê como Guerreiro da Razão, Campeão da Verdade. Um paladino. Um gênio. Um cavaleiro de tudo o que vale a pena defender.

Pensada mais para operativos Tecnocratas e tecnomantes céticos que para magos que aceitam a reencarnação como verdade metafísica, esta Qualidade lhe concede dons especiais quando parece que toda esperança se perdeu. Esses dons permitem: acessar Traços que você não possui, como no Antecedente Sonho (com valor 5), mas sem entrar em transe; somar cinco pontos temporários ao seu Traço de Força de Vontade, para usar durante aquela crise de "esperança perdida"; e talvez recordar coisas de uma vida anterior que a personagem não teria como saber – um idioma que ela não fala, uma rota de fuga num lugar onde nunca esteve, uma pessoa que nunca conheceu e assim por diante.

Esses impulsos duram apenas pela cena em curso, mas trazem uma explosão de energia vitalizante e a sensação de que o herói interior veio de novo salvar o dia.

Não é o tipo de coisa sobre a qual se fala, claro, ainda mais se você for agente da União Tecnocrata. Os benefícios, porém, não podem ser negados, mesmo que a fonte deles seja claramente… bem, improvável, na melhor das hipóteses. E, embora esta Qualidade tenha sido criada originalmente para o suplemento Guide to the Technocracy, qualquer mago com senso de propósito maior pode adquiri-la. Só lembre que a maior diferença entre um cavaleiro e um assassino é o lado da espada em que você está na hora.]==],
				},
				["Inner Strength"] = {
					pt = [==[Book of Secrets, pág. 45


Inner Strength


Diante da adversidade, você vence. Em termos de sistema, esta Qualidade reduz em -2 a dificuldade das rolagens de Força de Vontade quando você luta contra probabilidades aparentemente esmagadoras.]==],
				},
				["Innocent"] = {
					pt = [==[The Hunters Hunted II, pág. 142


Innocent


Você é sempre visto da forma mais positiva possível, a menos que existam provas em contrário. Se fizer algo errado e o ato não for facilmente atribuído a você, é bem provável que a culpa recaia sobre outra pessoa. Isso não significa que você seja "um inocente" — significa apenas que todo mundo acha que é.]==],
				},
				["Inoffensive to Animals"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 493


Inoffensive to Animals


Com raras exceções, os animais em geral detestam os Cainitas. Uns fogem, outros atacam, mas todos não gostam de estar perto de um vampiro. Você não tem esse problema. Os animais podem não gostar da sua companhia, mas não fogem ativamente de você.]==],
				},
				["Insensate to Pain"] = {
					pt = [==[Book of Secrets, pág. 38


Insensate to Pain


Nada dói até matar você. Certo, provavelmente dói, mas não o bastante para atrasá-lo. As penalidades de ferimento não afetam sua personagem de forma alguma; até morrer, ela costuma funcionar com as paradas de dados intactas. Esta Qualidade não muda de forma alguma o modo como ela recebe dano – para isso, veja a Qualidade abaixo –, mas muda radicalmente o modo como esse dano afeta a capacidade dela de fazer as coisas.

Há, claro, um lado ruim nisso tudo: a dor nos avisa que não estamos funcionando direito e que provavelmente é melhor parar enquanto dá tempo. Assim, você também vai acabar se queimando sem querer, tentando andar com as pernas quebradas e só notando cortes quando o sangue já atravessa a camisa. Embora a dor não o atrase, ossos e órgãos despedaçados atrasam. Ferimentos que causem limitação física considerável (pernas esmagadas, crânio quebrado, olhos arrancados etc.) se sobrepõem à sua imunidade usual às penalidades de dados por ferimento, e você pode causar mais dano letal a si mesmo (opção do Narrador) se continuar depois que o corpo tenta lhe dizer para parar.]==],
				},
				["Instrument of God"] = {
					pt = [==[Lore of the Clans, pág. 123


Instrument of God


Sua autoconfiança não vem da crença nas próprias capacidades, mas de um mandato direto do Senhor. Você tem um propósito divino e Ele age por meio de você, ainda que seus objetivos possam parecer tudo menos santos. Seja pela força da sua vontade, seja por uma ligação real com o divino, você ganha três dados adicionais para resistir aos poderes da Fé Verdadeira usados contra você, inclusive para absorver dano de capacidades de Fé Verdadeira.]==],
				},
				["Inter-Agency Liaison"] = {
					pt = [==[The Hunters Hunted II, pág. 133


Inter-Agency Liaison


Você trabalha para duas agências ao mesmo tempo. Ou é oficial de ligação entre elas — a Segurança Interna é um disfarce prático para a CIA ou a NSA enfiarem o nariz no FBI, e vice-versa — ou seus atuais empregadores não sabem para quem você realmente trabalha. De todo modo, você pode recorrer à inteligência e aos recursos das duas agências quando precisa. Você precisa comprar o Antecedente Patente para cada agência separadamente, e sua Patente na agência "de origem" precisa ser igual ou maior que a da agência nova.]==],
				},
				["Introspection"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 484


Introspection


Você tem uma percepção aguçada das segundas intenções de todos os seus atos. Por esse exercício noturno, você também tem uma percepção incrível dos motivos ocultos por trás dos atos alheios. Some dois dados à sua parada de Percepção quando precisar agir contra alguém com a mesma Natureza ou Comportamento que você.]==],
				},
				["Iron Will"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 485


Iron Will


Quando você está determinado e decidido, nada o afasta dos seus objetivos. Personagens usando Dementação, Dominação ou qualquer outra magia, feitiço ou caminho de Taumaturgia que altere a mente contra a sua personagem sofrem +3 de dificuldade.

Níveis de ancião de poderes como Dementação e Dominação podem superar até essa resistência. Contra poderes de Nível Seis, gastar um ponto de Força de Vontade pela Vontade de Ferro aumenta a dificuldade da rolagem de Disciplina em apenas dois. Contra poderes de Nível Sete, o aumento é de apenas um. Poderes de Nível Oito ou acima não podem ser resistidos com Vontade de Ferro.

Esta Qualidade não afeta Presença nem outros poderes que lidem com emoções. Personagens com Força de Vontade abaixo de 8 não podem adquiri-la.]==],
				},
				["Jack-of-All-Trades"] = {
					pt = [==[Book of Secrets, pág. 45


Jack-of-All-Trades


Você sabe um pouco de muita coisa. Ao tentar uma rolagem usando uma Perícia (não um Talento) que sua personagem não possui, você não sofre a penalidade usual. (Veja Perícias, Mage 20, p. 279.) Se estiver tentando usar um Conhecimento que ela não possui, ainda pode rolar, mas com +2 na dificuldade normal. (Veja Conhecimentos, Mage 20, p. 283.)

Como os Talentos representam dons inatos afiados pela prática, esta Qualidade não dá acesso a Talentos que sua personagem não possui.]==],
				},
				["Judge's Wisdom"] = {
					pt = [==[Book of Secrets, pág. 46


Judge's Wisdom


Por uma autodisciplina firme, você dominou suas emoções até uma perfeição vulcana. Nenhum ataque baseado em paixão abala seu julgamento, e os golpes baixos dos demônios que torcem corações têm pouco domínio sobre você. Em regras, você permanece imune a Efeitos de Mente ou Vida que influenciem emoções (conforme detalhado em How Do You DO That?, pp. 60 e 120-122) e consegue ignorar a Disciplina vampírica Presença, a menos que o sugador de sangue tenha ao menos seis pontos nela. Poderes emocionais de metamorfos, fadas e outras criaturas do gênero não conseguem afetá-lo, embora você ainda possa ser possuído, controlado mentalmente, encantado e de outro modo dobrado ou quebrado, desde que o ataque não dependa de arrancar uma resposta emocional do seu comando sereno e perfeito.]==],
				},
				["Kashaph"] = {
					pt = [==[Rites of Blood, pág. 100


Kashaph


O termo kashaph tem sentido ambíguo, derivado de uma raiz hebraica para "murmurar", e sugere feitiçaria e encantamentos falados. A palavra é usada no Antigo Testamento para condenar os praticantes de bruxaria. O verdadeiro kashaph está extinto há muito tempo — exceto entre os Inconnu. O kashaph é uma língua encantada e não pode ser "decodificada" pela linguística ou pela criptografia modernas. Os Inconnu a usam para se comunicar em segredo e também como método de reconhecimento mútuo.

Novos membros dos Inconnu não aprendem kashaph por meios normais. Ela não pode ser estudada nem aprendida como uma língua convencional. Em vez disso, os membros são iniciados na sociedade por um ritual elaborado durante o qual a língua kashaph é inscrita na alma deles. Uma vez "aprendida" assim, a língua pode ser falada, mas não escrita (não existe forma escrita, e os sons não podem ser capturados com precisão por rabiscos fonéticos), e apenas outra pessoa com esta qualidade tem capacidade de compreender o que é dito em kashaph.]==],
				},
				["Keys to the Library (1)"] = {
					pt = [==[Lore of the Clans, pág. 218


Keys to the Library (1)


Você ocupa uma das posições mais cobiçadas da capela: bibliotecário. É seu dever catalogar e manter o saber mágico guardado ali. Isso significa que você tem acesso completo a ele e decide quem pode ou não vê-lo. Um vasto conjunto de rituais e conhecimento taumatúrgico reside ali, o que torna simples aprender muitos dos segredos da magia. Por mais restritiva que seja sua capela, você tem acesso irrestrito à biblioteca para pesquisa. O custo desta qualidade é igual ao valor de Biblioteca da capela (veja pp. 221-222).]==],
				},
				["Keys to the Library (2)"] = {
					pt = [==[Lore of the Clans, pág. 218


