				},
				["Patron (4)"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 423


Patron (4)


Você tem a sorte de contar com um personagem de certa riqueza e poder disposto a patrocinar seus empreendimentos. Presume-se que seu Patrono goste de você e esteja disposto a oferecer bens materiais para avançar o objetivo que vocês combinaram, desde que você não abuse do favor. A escala desta Qualidade diz respeito tanto ao poder do Patrono quanto à proximidade dele com você. Um Patrono de 1 ponto pode ser um vampiro distante mas poderoso, ou um mortal rico e entusiasmado com fundos irregulares. Um de 3 pontos pode ser um príncipe ou uma rainha mortal, ou um vampiro de certa posição mais disposto a financiá-lo ou defendê-lo com regularidade, enquanto um de 5 pontos é quase certamente sobrenatural e tem vastos recursos à disposição. Nada disso é de graça, porém, e de tempos em tempos (com frequência diretamente proporcional aos pontos investidos nesta Qualidade) seu Patrono pedirá algo a você. Em geral é imprudente dizer não.]==],
				},
				["Patron (5)"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 423


Patron (5)


Você tem a sorte de contar com um personagem de certa riqueza e poder disposto a patrocinar seus empreendimentos. Presume-se que seu Patrono goste de você e esteja disposto a oferecer bens materiais para avançar o objetivo que vocês combinaram, desde que você não abuse do favor. A escala desta Qualidade diz respeito tanto ao poder do Patrono quanto à proximidade dele com você. Um Patrono de 1 ponto pode ser um vampiro distante mas poderoso, ou um mortal rico e entusiasmado com fundos irregulares. Um de 3 pontos pode ser um príncipe ou uma rainha mortal, ou um vampiro de certa posição mais disposto a financiá-lo ou defendê-lo com regularidade, enquanto um de 5 pontos é quase certamente sobrenatural e tem vastos recursos à disposição. Nada disso é de graça, porém, e de tempos em tempos (com frequência diretamente proporcional aos pontos investidos nesta Qualidade) seu Patrono pedirá algo a você. Em geral é imprudente dizer não.]==],
				},
				["Peacemaker"] = {
					pt = [==[Anarchs Unbound, pág. 102


Peacemaker


Você tem fama de ter juízo e de manter a palavra dada, custe o que custar. Por isso, seus aliados e companheiros de seita pedem que você medeie as disputas deles, mesmo com outras seitas. Esta Qualidade permite à sua personagem usar a reputação como alavanca para manter a paz em situações tensas. Reduza em 2 a dificuldade de todas as rolagens sociais para manter a paz ou mediar honestamente entre facções (mesmo de outras seitas).]==],
				},
				["Perfect Liar"] = {
					pt = [==[Book of Secrets, pág. 56


Perfect Liar


Ah, meus deuses, como você mente bem! As inverdades escorregam da sua língua como água em folha de videira, e até quem o conhece bem tende a cair quando você começa a falar. Você também não tem os "sinais" habituais que denunciam um mentiroso: seus sinais vitais permanecem estáveis, seus olhos não tremem e sua voz nunca falha. A menos que alguém esteja literalmente lendo sua mente (usando magia da Esfera da Mente ou outro poder paranormal), você continua parecendo dizer a verdade; e, mesmo então, quem lê sua mente pode supor que você ao menos acredita estar dizendo a verdade!

Em termos de história, as pessoas em geral acreditam no que você diz quando você mente sobre coisas pequenas e casuais que não sejam imediata e obviamente falsas. Nos dados, reduza a dificuldade em -2 quando estiver mentindo sobre algo importante. De novo: esta Qualidade não altera auras nem muda os pensamentos na sua cabeça, embora quem não puder monitorar ativamente sua alma tenda a lhe dar o benefício da dúvida. (Otários…)]==],
				},
				["Personal Masquerade"] = {
					pt = [==[Lore of the Clans, pág. 269


Personal Masquerade


Por charme, manipulação ou pura sorte, você conseguiu convencer outros vampiros de que é membro de um dos Clãs. Em qualquer interação social com vampiros ignorantes da sua verdadeira natureza, a penalidade usual por ser Caitiff é ignorada. Contudo, você precisa vigiar constantemente sua farsa. Se alguém perceber que você o vem fazendo de bobo, a vingança será rápida. Quanto mais alto você sobe na política Cainita, mais provável isso fica. O Defeito Fraqueza de Clã pode até ser uma bênção para sustentar sua Máscara. Os outros, porém, precisam ser muito mais cuidadosos.]==],
				},
				["Physically Impressive"] = {
					pt = [==[Book of Secrets, pág. 37


Physically Impressive


Você é um desgraçado imponente, não tanto grande quanto aparentemente perigoso, seja qual for o seu humor no momento. Isso pode ser tão evidente quanto cicatrizes ou um físico intimidador, ou tão intangível quanto o proverbial "ar de ameaça". Em termos de sistema, esta Qualidade soma dois dados a todas as rolagens de Traços Sociais que envolvam intimidar alguém; em termos de história, as pessoas o acham perturbador – e possivelmente atraente de um jeito perigoso – mesmo quando você não está tentando impressionar.]==],
				},
				["Piscine"] = {
					pt = [==[Lore of the Clans, pág. 161


Piscine


A água é um ambiente bem mais confortável para você, seja o mar, seja o efluente de esgoto. Rolagens que envolvam nadar ou se mover debaixo d'água têm a dificuldade reduzida em 1.]==],
				},
				["Pitiable"] = {
					pt = [==[Book of Secrets, pág. 54


Pitiable


Ah, coitadinho! As pessoas querem ajudá-lo, e você as deixa ajudar. Embora esta Qualidade reduza em -2 a dificuldade das suas rolagens sociais quando você tenta fazer alguém cuidar de você, ela soma +2 à dificuldade das rolagens que tentam intimidar as pessoas ou de outro modo fazê-las levá-lo a sério.]==],
				},
				["Poison Resistance"] = {
					pt = [==[Book of Secrets, pág. 37


Poison Resistance


As toxinas podem deixá-lo doente, mas provavelmente não vão matá-lo. Embora venenos mágicos possam ser exceção à regra, seu corpo sacode de si os piores efeitos de venenos naturais e sintetizados.

Quando atacado por essas substâncias, some dois dados à rolagem de Vigor da sua personagem ao resistir aos efeitos; um sucesso reduz a intensidade de toxinas potentes e elimina por completo os efeitos mais letais das mais fracas. Claro, ela pode se sentir meio tonta e ficar seriamente doente mas, mesmo que a rolagem falhe, provavelmente não morrerá.

Embora funcione contra bactérias tóxicas, esta Qualidade não protege contra doenças transmitidas por vírus, condições genéticas e afins. Para detalhes, veja Drogas, Venenos e Doenças em Mage 20, pp. 441-444 e 456. E, como intoxicantes também são toxinas, ela ajuda a sobreviver a overdoses de bebida ou drogas – veja Tolerância a Álcool/Drogas, acima.]==],
				},
				["Poisonous Blood"] = {
					pt = [==[The Hunters Hunted II, pág. 44


Poisonous Blood


Por circunstâncias misteriosas, o sangue da sua personagem é venenoso para vampiros. Se um vampiro beber dele, cada ponto de sangue ingerido lhe causa um nível de vitalidade de dano contundente. Vampiros naturalmente têm rancor de mortais que se sabe possuírem essa bênção, e podem muito bem buscar a destruição deles. Os Narradores são encorajados a ter uma explicação para essa aberração nas suas crônicas, embora o jogador (e provavelmente a personagem) possa não ter acesso imediato a ela. Alguns exemplos são proteção sagrada de um poder superior, um ritual raro de proteção ou mesmo uma anormalidade genética.]==],
				},
				["Poker Face"] = {
					pt = [==[Book of Secrets, pág. 38


Poker Face


Nada o abala. Nada. O surgimento de uma coisa anciã e titânica das profundezas do espaço talvez mereça um tremor preocupado do canto da boca, mas é basicamente isso. Ah, isso não significa que você não sinta nada – isso é o Defeito Mental Frieza, abaixo. Sua expressão impassível, seus olhos vazios e seu tom monocórdico, porém, não revelam nada dos seus pensamentos ou intenções… o que, para quem está do outro lado, pode ser bem desconcertante; reduza em -2 a dificuldade de rolagens de intimidação, manha e resistência à intimidação, somando +2 às dificuldades de quem tentar tirá-lo do sério ou entrar sob a sua pele, inclusive tentativas de ler, seduzir, torturar ou de outro modo furar essa cara de paisagem.]==],
				},
				["Postulant of Echidna"] = {
					pt = [==[Dark Ages Tome of Secrets, pág. 4


Postulant of Echidna


Você recebe a tutela de uma das Bruxas de Equidna. Esta Qualidade permite adquirir a Feitiçaria Setita como Disciplina de Clã no lugar de uma das suas. Se estiver fora da Ortodoxia Setita, você pode acabar caçado para integração ou destruição por outros do seu sangue. A maioria dos Postulantes de Equidna tem vários pontos no Antecedente Mentor para representar a tutora Górgona, embora a ausência de um Mentor possa sugerir que a Bruxa encontrou a destruição. Esta Qualidade é predominantemente Setita, mas correm boatos de Bruxas de Equidna passando conhecimento a vampiros de outros clãs.]==],
				},
				["Powerful Ally (5)"] = {
					pt = [==[Book of Secrets, pág. 77


Powerful Ally (5)


Você tem amigos seriamente durões – um senhor vampiro, um nobre feérico, uma matilha de lobisomens, cortesãos Umbrood ou outras entidades igualmente magníficas. Em quase tudo, esta é a Qualidade Companheiro Sobrenatural, mas num nível de poder muito mais alto… um nível que pode estar além da capacidade de magos abaixo do posto de Mestre. E, embora o Narrador determine quem são seus amigos, o que podem fazer e o que querem da relação com você, o valor desta Qualidade depende do benefício relativo que trazem:

(5 pontos) Um camarada de poder e influência consideráveis dentro da comunidade dele – um Príncipe da Cidade, um ancião Garou e assim por diante.

(6 pontos) Um pequeno grupo de Companheiros Sobrenaturais (uns cinco), ou um representante especialmente poderoso da sua espécie.

(7 pontos) Um grupo maior de Companheiros (uns doze), ou dois ou três amigos poderosos.

(8 pontos) Mais de uma dúzia de Companheiros, um punhado de amigos poderosos, ou um aliado de poder quase divino.

De novo: o Narrador decide quem são esses aliados, por que se interessam pela sua boa vontade e qual pode ser o preço da ajuda deles. Nada é de graça, afinal, ainda mais quando seres assim estão envolvidos! Para um nível equivalente de inimigos, veja o Defeito Inimigo Imortal, p. 93.]==],
				},
				["Powerful Ally (6)"] = {
					pt = [==[Book of Secrets, pág. 77


Powerful Ally (6)


Você tem amigos seriamente durões – um senhor vampiro, um nobre feérico, uma matilha de lobisomens, cortesãos Umbrood ou outras entidades igualmente magníficas. Em quase tudo, esta é a Qualidade Companheiro Sobrenatural, mas num nível de poder muito mais alto… um nível que pode estar além da capacidade de magos abaixo do posto de Mestre. E, embora o Narrador determine quem são seus amigos, o que podem fazer e o que querem da relação com você, o valor desta Qualidade depende do benefício relativo que trazem:

