				},
				["Powerful Ally (8)"] = {
					pt = [==[Book of Secrets, pág. 77


Powerful Ally (8)


Você tem amigos seriamente durões – um senhor vampiro, um nobre feérico, uma matilha de lobisomens, cortesãos Umbrood ou outras entidades igualmente magníficas. Em quase tudo, esta é a Qualidade Companheiro Sobrenatural, mas num nível de poder muito mais alto… um nível que pode estar além da capacidade de magos abaixo do posto de Mestre. E, embora o Narrador determine quem são seus amigos, o que podem fazer e o que querem da relação com você, o valor desta Qualidade depende do benefício relativo que trazem:

