De novo: o Narrador decide quem são esses aliados, por que se interessam pela sua boa vontade e qual pode ser o preço da ajuda deles. Nada é de graça, afinal, ainda mais quando seres assim estão envolvidos! Para um nível equivalente de inimigos, veja o Defeito Inimigo Imortal, p. 93.]==],
				},
				["Precocious"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 485


Precocious


Você aprende rápido. O tempo para você adquirir determinada Habilidade (ou Habilidades, a critério do Narrador) cai pela metade, assim como o custo em experiência.]==],
				},
				["Prestige"] = {
					pt = [==[Book of Secrets, pág. 56


Prestige


Também conhecida como Reputação, esta Qualidade o revela como pessoa honrada dentro da sua Tradição, Convenção, Ofício ou outro tipo de seita. Entre seus pares, você soma três dados extras a todas as rolagens sociais usadas para influenciar gente daquele grupo. Em termos de história, aliados do seu grupo tendem a gostar de você, e rivais ou inimigos tendem a… não.

Ao escolher esta Qualidade, defina a origem desse prestígio. Talvez você o tenha conquistado por feitos anteriores ao início da crônica, ou ganhado a Qualidade no lugar de pontos de experiência. Ela pode representar uma linhagem honrada à qual você pertence, ou refletir um mentor glorioso cuja fama respinga em você. De todo modo, esperam grandes coisas de você e em geral lhe dão deferência, desde que você esteja à altura da reputação de que desfruta.

Para o avesso desta Qualidade, veja o Defeito Social Infâmia, pp. 62-63.]==],
				},
				["Prestigious Mentor"] = {
					pt = [==[Book of Secrets, pág. 54


Prestigious Mentor


Seu Mentor (como no Antecedente de mesmo nome) tem uma reputação que beneficia você também. Ao fazer rolagens sociais em que invoca seu professor influente, reduza a dificuldade em -2. Claro que algumas pessoas ficarão bem menos impressionadas; em rolagens que envolvam rivais ou inimigos do seu mentor, some +2 à dificuldade, a menos que ele os apavore… caso em que é bom você conseguir estar à altura do medo que o nome dele desperta!]==],
				},
				["Prestigious Sire"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 488


Prestigious Sire


Seu senhor tem ou teve grande status na Seita ou no Clã dela, e isso lhe rendeu certo prestígio. Embora ela talvez já não tenha trato algum com você, o simples fato da sua ascendência o marcou para sempre. Esse prestígio pode ajudá-lo muito no trato com outros vampiros, ou pode gerar inveja e desprezo.]==],
				},
				["Primogen/Bishop Friendship"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 489


Primogen/Bishop Friendship


Os vampiros que governam a cidade valorizam você e suas opiniões. Você é chamado para opinar em decisões, e suas recomendações têm grande peso. Sua posição pode não ser oficial, mas nem por isso é menos poderosa.]==],
				},
				["Prized Collection (1)"] = {
					pt = [==[Lore of the Bloodlines, pág. 59


Prized Collection (1)


Os Kiasyd apreciam coleções de livros, discos, safras de sangue e outros itens colecionáveis entre os Cainitas. Você possui uma coleção que pode não valer muito (1 pt.) ou valer bastante para o comprador certo (2 pts.). O importante é que ela é ponto de interesse para qualquer Kiasyd de passagem ou especialista da área, e essas pessoas tendem a tratá-lo bem só para conseguir acesso a ela.]==],
				},
				["Prized Collection (2)"] = {
					pt = [==[Lore of the Bloodlines, pág. 59


Prized Collection (2)


Os Kiasyd apreciam coleções de livros, discos, safras de sangue e outros itens colecionáveis entre os Cainitas. Você possui uma coleção que pode não valer muito (1 pt.) ou valer bastante para o comprador certo (2 pts.). O importante é que ela é ponto de interesse para qualquer Kiasyd de passagem ou especialista da área, e essas pessoas tendem a tratá-lo bem só para conseguir acesso a ela.]==],
				},
				["Prized Patch"] = {
					pt = [==[Anarchs Unbound, pág. 102


Prized Patch


Você pertence a uma gangue Anarquista de reputação violenta, eficaz ou de outro modo impressionante. A história do bando pode remontar a cem anos antes do seu nascimento mas, enquanto você for membro e vestir as cores da sua turma, os outros Anarquistas tendem naturalmente a respeitá-lo. Alguns podem até executar tarefas menores para você de vez em quando, para cair nas graças dos demais. Quando sua filiação é conhecida, reduza em 2 a dificuldade de todas as rolagens de Manipulação com outros Anarquistas, a menos que aquele Anarquista tenha animosidade histórica com a sua gangue.]==],
				},
				["Profane Trappings"] = {
					pt = [==[Dark Ages Tome of Secrets, pág. 108


Profane Trappings


Você conspurca tudo em que toca. Seja por intenção, seja por infeliz acaso, seu Domínio, seus Lacaios, seu Rebanho e seus pertences estão todos maculados pelo profano. Embora isso polua o que o cerca com uma aura constante de náusea e desconforto, também torna mais fácil realizar atos infernais na presença deles. Ao adquirir esta Qualidade, quaisquer Disciplinas que você use são consideradas infernais; a critério do Narrador, usar suas Disciplinas em terras que você possui, em servos a seu serviço ou com objetos seus reduz a dificuldade da rolagem em -2.]==],
				},
				["Promethean Clay"] = {
					pt = [==[Lore of the Clans, pág. 238


Promethean Clay


Sua carne ondula e se molda à sua vontade sobrenatural quase antes de você invocar conscientemente a mudança. A dificuldade para usar qualquer poder de Vicissitude em si mesmo é dois pontos menor que o normal, e você pode ativar poderes de Vicissitude de forma reflexa, com a parada de dados cheia, enquanto realiza outras ações. Poderes que exijam vários turnos para ativar continuam exigindo a duração usual. A mudança simplesmente acontece, sem direção consciente. Como benefício final, você não precisa esculpir fisicamente nada para usar os três primeiros níveis de Vicissitude em si mesmo, pois sua carne ondula e se estende até a forma desejada. Apenas personagens com ao menos um ponto de Vicissitude podem comprar esta Qualidade.]==],
				},
				["Property (2)"] = {
					pt = [==[Book of Secrets, pág. 56


Property (2)


Você tem um imóvel de tamanho razoável que, embora não seja mágico, é certamente útil: uma casa senhorial, uma fazenda, uma boate, uma livraria, um restaurante, um bosque e assim por diante. Quanto maior e mais próspera a propriedade, mais pontos esta Qualidade custa. Conhecida em outros lugares como as Qualidades Boate e Mansão, ela exige um valor mínimo no Antecedente Recursos, como indicado abaixo.

(2 pontos) Uma propriedade relativamente pequena, de uns 280 metros quadrados, com talvez – se for um negócio – um fiapo de renda que supera de pouco as despesas. Exemplos: uma boa casa, uma loja de quadrinhos, uma cafeteria, uma cobertura etc. Recursos mínimos: 3.

(3 pontos) Um lugar bem bacana, com funcionários dedicados, todas as instalações necessárias (esgoto, coleta de lixo, conexão de internet etc.) e – se for um negócio – renda que contribui para o seu Antecedente Recursos. Exemplos: uma boate, uma mansão, uma pequena fazenda, uma estação de rádio, uma loja grande e assim por diante. Recursos mínimos: 4.

(4 pontos) Um local considerável, com empregados qualificados (ainda que mundanos) e ligado a um ou dois hectares de terra. Exemplos: um pequeno edifício de escritórios, uma casa de família, uma arena, uma escola, uma fazenda média, um vinhedo, um pequeno laboratório, uma biblioteca e afins. Neste nível, também pode representar várias Propriedades menores, de dois pontos. Recursos mínimos: 5.

(5 pontos) Um patrimônio impressionante, com equipe extensa e boa quantidade de terreno. Exemplos: um complexo de escritórios, um estádio, uma faculdade, um grande laboratório, um centro comercial, um arquivo e assim por diante. Este nível também pode refletir várias Propriedades de dois ou três pontos. Recursos mínimos: 6.

Embora esta Qualidade, por si só, não seja mágica nem equipada com hipertecnologia, sua Propriedade pode servir de base de operações para os Antecedentes Aliados, Reforços, Capela, Culto, Biblioteca, Nodo, Recursos, Lacaios, Santuário e até Espiões. (Baristas ouvem cada coisa…) A menos que você tenha um gerente dedicado, ela também exige certo tempo e atenção, e rapidamente cai em ruína e/ou falência se você a abandonar por uma semana ou mais enquanto sai por aí em aventuras. A Propriedade também tende a atrair interesse de gente mundana e não tão mundana, especialmente se houver rivalidade em curso com negócios concorrentes, inimigos de família, um arqui-inimigo e por aí vai. A polícia não vê com bons olhos coisas malucas acontecendo no seu imóvel, e o custo do seguro pode ser assassino se (leia-se: quando) o lugar for destruído por entidades extradimensionais, Marcas HIT ou Guerreiros da Ascensão furiosos.

A menos que façam parte dos Antecedentes Aliados, Reforços, Culto ou Lacaios, os empregados da sua Propriedade contam como testemunhas Adormecidas no que toca a feitos mágicos dentro e ao redor dela.]==],
				},
