				},
				["Prophetic Dreams"] = {
					pt = [==[Lore of the Clans, pág. 142


Prophetic Dreams


Você tem sonhos durante o sono diurno. Sonhos dos quais se lembra. Às vezes, eles até se realizam. Gastando um ponto de Força de Vontade ao se erguer à noite, você pode pedir que o Narrador dê à sua personagem um sonho lúcido com prenúncios de acontecimentos, personagens e situações por vir.]==],
				},
				["Psychic Awareness"] = {
					pt = [==[M20 Sorcerer, pág. 106


Psychic Awareness


Mesmo sem ter poderes psíquicos próprios, você consegue sentir a presença de energias psíquicas recentes numa área próxima (raio de uns 3 metros) com uma rolagem de Percepção + Ocultismo (dificuldade 8). Quanta informação você colhe e o nível de detalhe dependem dos sucessos. Um único sucesso pode apenas confirmar que houve um talento psíquico ali há pouco, enquanto cinco ou mais podem permitir captar a sensação remanescente de um psíquico talentoso que passou por ali, sua força, seu humor e seus planos naquele momento.]==],
				},
				["Psychic Leech"] = {
					pt = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, pág. 179


Psychic Leech


Ao custo de um ponto de Força de Vontade, você pode se alimentar da Força de Vontade das suas vítimas a distância. A Força de Vontade consumida fortalece a potência do seu próprio sangue, transformando-a em sangue temporário que se dissipa ao fim da noite. Esses pontos de sangue temporários podem ser gastos como pontos normais, mas não podem ser perdidos por dano ou drenagem, não afetam as rolagens de fome para frenesi e não podem ser usados para criar ou sustentar laços de sangue ou carniçais. Para ativar esta capacidade, o alvo precisa ter ao menos um ponto do seu sangue no organismo e estar em contato visual com você.]==],
				},
				["Quartermaster"] = {
					pt = [==[Lore of the Clans, pág. 219


Quartermaster


Você é um dos Cainitas responsáveis por manter e organizar os suprimentos mundanos da capela. Você pode retirar qualquer coisa dos estoques dela, conforme o valor de Estoques da capela. Embora tenha de devolver ou repor o que pegar emprestado, você tem acesso a toda a gama de equipamentos apropriada ao tamanho da capela. Isso pode ir de armas de assalto e explosivos a equipamento médico e científico avançado.]==],
				},
				["Ravnos Jati"] = {
					pt = [==[Dark Ages Companion, pág. 101


Ravnos Jati


Você pertence a um jati Ravnos amplamente reconhecido, o que lhe dá certa medida de status junto aos membros do seu Clã. Sempre que interagir com outro Vagabundo, trate seu Status como um nível mais alto; se ele também for do seu jati, trate seu Antecedente como dois níveis mais alto e seus Aliados, Contatos ou Mentor como um nível mais alto no que toca ao seu jati. Uma vez por sessão, se estiver numa cidade com população Ravnos significativa, você encontra sem problemas um membro do seu jati, que provavelmente o ajudará sem fazer perguntas. Uma vez por capítulo, um membro do seu jati o procura para pedir ajuda numa tarefa problemática e perigosa.]==],
				},
				["Regal Bearing"] = {
					pt = [==[Book of Secrets, pág. 54


Regal Bearing


O carisma aristocrático é seu direito de nascença. Embora talvez você não venha de fato de uma família nobre, sua presença irradia dignidade. Postura, traços, tom de voz, aura de domínio – você tem tudo. As pessoas lhe dão deferência por reflexo; subtraia 2 da dificuldade das suas rolagens de Traços Sociais sempre que estiver tentando causar impressão e, embora certas pessoas queiram baixar sua bola por princípio, a maioria tende a respeitá-lo, mesmo sem necessariamente gostar de você.]==],
				},
				["Rep"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 488


Rep


Sua fama ultrapassou os limites da sua Seita. Todo mundo sabe quem você é, o que você fez e o que dizem que você fez (o que pode não ser a mesma coisa). A publicidade pode ser boa ou ruim; o que importa é que todos conhecem seu nome. Se as pessoas fora do seu círculo social imediato sabem o bastante para ligar seu rosto ao seu nome já é outra história.]==],
				},
				["Research Grant"] = {
					pt = [==[The Hunters Hunted II, pág. 141


Research Grant


Você tem uma bolsa de pesquisa prestigiosa de alguma universidade ou centro de pesquisa. Isso o livra do fardo de precisar de um emprego regular. A bolsa fornece um estipêndio mínimo (de US$ 1.500 a US$ 2.000 por mês na maioria dos casos), além de credenciais que dão acesso a bibliotecas e centros de pesquisa exclusivos pelo mundo.]==],
				},
				["Revenant Disciplines"] = {
					pt = [==[Lore of the Clans, pág. 238


Revenant Disciplines


O sangue da sua família revenante corre fundo, mais fundo que o Abraço. As Disciplinas que eram inatas em você como carniçal continuaram inatas como Cainita. Na criação do personagem, escolha a família de carniçais de onde você vem (V20, pp. 503-506). Em vez do conjunto padrão dos Tzimisce — Animalismo, Auspícios e Vicissitude —, você usa as três Disciplinas da sua família para a distribuição inicial (embora possa comprar outras Disciplinas com pontos livres, normalmente). Você troca todo o conjunto de Disciplinas de Clã Tzimisce pelo conjunto da família revenante, para fins de custo de experiência dentro do Clã.]==],
				},
				["Rising Star"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 489


Rising Star


Você é um dos nomes em ascensão da cidade, uma estrela em alta na sua Seita. Todos querem conhecê-lo e ser seus amigos, enquanto os que estão no poder o preparam para posições de maior responsabilidade. Você tem -1 de dificuldade em todas as rolagens Sociais contra vampiros da sua Seita que não estejam ativamente atrapalhando sua subida.]==],
				},
				["Rugged Bad Looks"] = {
					pt = [==[Lore of the Clans, pág. 161


Rugged Bad Looks


Embora ainda seja medonho, você não é tão feio quanto a maioria dos Nosferatu. Sua Aparência continua sendo 0, mas você pode passar por humano na luz certa. Ainda é boa ideia se cobrir e ficar nas sombras, mas a sua visão (ou mesmo o seu cheiro) não faz alguém pensar de imediato que você é uma aberração ou vítima de trauma. Dito isso, você ainda é feio o bastante para arrepiar a maioria das pessoas.]==],
				},
				["Sabbat Survivor"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 488


Sabbat Survivor


Você sobreviveu a pelo menos um ataque ou tentativa de recrutamento da Sabá. Sua experiência o ajuda a antecipar situações em que possa ser posto em perigo por eles de novo. Você tem -1 de dificuldade em todas as rolagens de Percepção em assuntos ligados à Sabá. Esta Qualidade em geral é adquirida por grupos em conflito com a Sabá, e entra em jogo com mais frequência como meio de evitar emboscadas.]==],
				},
				["Sanction"] = {
					pt = [==[The Hunters Hunted II, pág. 133


Sanction


Sua agência lhe deu autorização limitada para usar força letal contra alvos específicos e nomeados. Eles o responsabilizarão por qualquer morte adicional e não hesitarão em revogar a autorização se você for desleixado demais. Esse tipo de permissão é extremamente raro — a CIA autoriza algumas mortes em território estrangeiro, e um grupo obscuro do alto escalão do FBI a usa para eliminar potenciais terroristas domésticos. Enquanto você fizer o que mandam, sua agência fornece armas e equipamento (dentro do razoável) e apaga seus rastros quando o trabalho termina. Apesar do que se imagina, isso não é uma "licença para matar" — assassinar continua sendo crime, mesmo com o aval de uma agência de inteligência, e você pode ser processado por homicídio se for pego.]==],
				},
				["Sanctioned Witch"] = {
					pt = [==[The Hunters Hunted II, pág. 123


Sanctioned Witch


Você é conhecido como "Bruxa de Judas", tendo recebido o Santuário da Disciplina Arcani das mãos da própria Inquisidora-Geral. Você não pode ser punido nem detido por estudo do oculto ou uso de Númina (embora a autorização possa ser revogada por má conduta). Uma tatuagem do Selo de Salomão, na palma da mão esquerda, atesta suas credenciais. Isso não significa que todos na Sociedade confiem na sua perícia, já que muitos desprezam as artes mágicas.]==],
				},
				["Sanctity"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 488


Sanctity


Esta Qualidade às vezes é chamada de efeito auréola: todos o consideram puro e inocente, ainda que não necessariamente ingênuo. Você tem uma qualidade de santo, difícil de apontar mas impossível de negar. Confiam em você, mesmo que você não seja confiável. A critério do Narrador, você tende a receber punições mais brandas por transgressões, e a maioria gosta de você.]==],
				},
				["Sanctuary"] = {
					pt = [==[The Hunters Hunted II, pág. 44


Sanctuary


Sua personagem tem um esconderijo que é um verdadeiro santuário. Criaturas sobrenaturais precisam de sucesso num teste de Força de Vontade (dificuldade 9) para entrar na casa dela sem convite. Isso pode se dever a alguma ocorrência mística estranha, a sorte, a um ritual esquecido, ou talvez a casa esteja sobre solo consagrado. Esta Qualidade precisa ser atribuída a uma única edificação onde a personagem tenha residência permanente. Bons exemplos de santuário são uma casa, um pequeno prédio de apartamentos ou uma igreja.]==],
				},
				["Sanguine Incongruity"] = {
					pt = [==[Lore of the Clans, pág. 106


Sanguine Incongruity


Giovanni com este atavismo são raríssimos. Cainitas que o possuem não carregam a fraqueza tradicional do Clã Giovanni, a chamada Maldição de Lâmia; o Beijo deles não causa mais dano que a própria perda de sangue. Esses vampiros, porém, adquirem uma palidez peculiar no Abraço — parecem cadáveres, e nenhuma quantidade de sangue ingerido consegue corar seus traços (como os outros vampiros conseguem). Na verdade, quem tem esta Qualidade se parece mais com os ancestrais Cappadocianos do Clã, e tem um ar ligeiramente perturbador. Por isso, todas as rolagens que envolvam um atributo Social (Carisma, Manipulação ou Aparência) sofrem +1 de dificuldade.

Giovanni com esta Qualidade recebem larga distância, já que o Clã tende a ser bastante supersticioso a respeito. Personagens com a Qualidade Incongruência Sanguínea não podem possuir também a Qualidade Mortuario.]==],
				},
				["Scent of the Other"] = {
					pt = [==[Lore of the Bloodlines, pág. 80


Scent of the Other


"Você não parece um sugador de almas…" Por alguma razão, seu terceiro olho se fecha por completo quando você quer escondê-lo, e seu sangue e sua aura não entregam seu Clã. Você pode ser tomado por Caitiff, ou por membro de outro Clã. De todo modo, caçadores Tremere ou de outros Salubri perdem sua trilha, a menos que você faça algo que o revele de novo.]==],
				},
				["Scholar of Enemies"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 489


Scholar of Enemies


Você dedicou tempo a estudar e se especializar num inimigo específico da sua Seita. Você conhece ao menos parte dos costumes, estratégias, capacidades e objetivos de longo prazo daquele grupo, e sabe usar bem esse conhecimento. Esta Qualidade vale -2 de dificuldade em todas as rolagens fora de combate que digam respeito especificamente ao objeto da sua especialização. Por outro lado, você sofre +1 de dificuldade ao lidar com outros inimigos, simplesmente por estar tão concentrado no seu campo.]==],
				},
				["Scholar of Others"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 489


Scholar of Others


Esta Qualidade funciona de forma idêntica a Estudioso dos Inimigos, exceto que se aplica a um grupo que não é necessariamente hostil à sua Seita.]==],
				},
				["Science Laboratory"] = {
					pt = [==[The Hunters Hunted II, pág. 43


Science Laboratory


Sua personagem tem acesso a um laboratório completamente equipado, com aparelhos científicos funcionais e material de pesquisa. Quando tem acesso a ele, ela pode realizar experimentos, fazer testes e coletar dados, e você pode reduzir em 2 a dificuldade das rolagens cabíveis de Investigação ou Ciência, ou em 1 a dificuldade de outras rolagens apropriadas (a critério do Narrador) enquanto ela usa o equipamento.]==],
				},
				["Scientific Mystic /Techgnosi"] = {
					pt = [==[Book of Secrets, pág. 45


Scientific Mystic /Techgnosi


Certos tecnomantes heterodoxos entendem que "misticismo" é apenas outra forma de ciência, cujos princípios podem ser compreendidos por uma mente devidamente Iluminada. Embora você siga uma prática tecnológica e use instrumentos de base tecnológica, pode empregar instrumentos tradicionalmente tidos como "mágicos" depois de ter a oportunidade de estudá-los e encaixá-los no seu paradigma científico.

A Qualidade Místico Científico permite a um tecnomante dedicado – isto é, membro da Sociedade de Éter, dos Adeptos Virtuais, um "órfão" de base tecnológica ou talvez até um Tecnocrata renegado como os Díspares de Navalon – estudar princípios metafísicos com magos de paradigma místico sem custo extra em pontos, desde que ele tenha a prática de foco Ciência Estranha. (Para detalhes, veja Um Mago Que Usa um Tipo de Foco Pode Aprender Magia com um Mago de Outro Tipo?, Capítulo Três, p. 174, e a entrada Ciência Estranha em Mage 20, p. 584.) Esse tecnomante também pode escolher ferramentas tradicionalmente "místicas" como até metade dos instrumentos exigidos (conforme detalhado em Arete, Foco e Instrumentos, Mage 20, p. 329) e pode descartar esses instrumentos como místico, e não como tecnomante (de novo, veja Mage 20, p. 329). Basicamente, isso significa que sua abordagem da ciência Iluminada é flexível o bastante para abraçar caminhos bizarros nas suas buscas metafísicas. Outros cientistas podem considerar tais coisas impossíveis, mas você sabe que "possibilidade" é o que você faz dela.

Do outro lado dessa moeda metafísica, a Qualidade Tecnognose permite a um místico dedicado fazer exatamente as mesmas coisas, mas com instrumentos tecnológicos e sem custo extra para estudar magia com colegas tecnomantes, sejam quais forem suas práticas. (Veja a entrada do Capítulo Três citada acima.) Sim, sua alma pertence aos Mistérios, mas você reconheceu que a tecnologia também tem lugar neles.]==],
				},
				["Secret Code Language"] = {
					pt = [==[Book of Secrets, pág. 57


Secret Code Language


A linguagem em si é uma série de códigos; quem foi iniciado nela (ou seja, quem aprendeu o idioma) é considerado membro daquela sociedade. Algumas línguas, porém, são mais exclusivas e secretas que outras. Esta Qualidade representa seu conhecimento de um código específico, conhecido apenas pelas "pessoas certas".

Magos são reservados por natureza, e por isso a sociedade deles é cheia de códigos secretos. Mesmo os Adormecidos, porém, têm suas linguagens iniciáticas: jargão militar, a Linguagem das Flores, vários sinais de mão, cifras e senhas usadas por gente que precisa se comunicar de formas que ninguém fora do grupo entenda… exceto, talvez, quem aprendeu esses códigos por alguma fonte "não autorizada".

Como na Qualidade Idioma (p. 44), esta concede conhecimento de um modo específico de comunicação, que pode não ser verbal de forma alguma. Ele pode envolver sinais de mão, posturas corporais, obras de arte, bandeiras, simbolismo, números e assim por diante. Para observadores não iniciados, essa linguagem parece algaravia (palavra que, aliás, remete aos escritos cifrados do alquimista Abu Musa Jabir ibn Hayyan); em muitos casos, um método codificado de comunicação parece completamente mundano, a menos que você saiba o que procurar, como na arte cifrada de O Código Da Vinci.

Uma ressalva vital: a personagem precisa ter uma razão muito boa, dentro do jogo, para saber o que sabe. Aprender uma Língua Codificada exige alguma base de história: treinamento militar de elite, leitura de mentes, tempo de convivência com o grupo em questão etc. Felizmente, línguas de código tendem a ser utilitárias, revelando o essencial de forma geral. ("Estou com fome", "Mate-o", "Esta área é proibida" etc.) Ainda assim, os códigos podem ter sutilezas nada evidentes; um único gesto ou uma sílaba acentuada pode marcar a diferença entre "nocauteie-o e siga rápido" e "torture-o até o último suspiro, não importa quanto tempo leve".]==],
				},
				["Secret Society Member"] = {
					pt = [==[Lore of the Clans, pág. 218


Secret Society Member


Você encontrou e ingressou numa das muitas sociedades secretas do Clã Tremere. Sua personagem precisa ser apta a entrar, como ter Necromancia para entrar na Aliança. Você pode escolher uma das sociedades listadas aqui ou criar a sua. Na maioria dos casos, sua filiação deve ser mantida em segredo, mas a lealdade a ela não é considerada crime. Embora a sociedade espere que você defenda seus preceitos e sua agenda, também se pode contar com ela para lhe dar respaldo e ajudá-lo a crescer em poder dentro da pirâmide.]==],
				},
				["Secret Stash (2)"] = {
					pt = [==[Lore of the Clans, pág. 122


Secret Stash (2)


Você tem vários recursos, agentes adormecidos ou seguidores guardados para um dia de chuva. Para cada nível desta Qualidade, você tem um ponto de Antecedente não atribuído "no estoque" (2 lhe dá um ponto, 3 lhe dá dois, e assim por diante). A qualquer momento, você pode gastar quantos quiser para aumentar seu nível em Aliados, Contatos, Rebanho, Influência, Mentor, Recursos ou Lacaios. Uma vez gastos, os pontos ficam atribuídos em definitivo mas, até lá, não podem ser afetados por nada. Isso permite ao vampiro criar um recurso novo num instante, sem gastar pontos de experiência nem esperar um intervalo entre histórias. Ele não está de fato ganhando níveis novos: está revelando níveis que sempre teve.]==],
				},
				["Secret Stash (3)"] = {
					pt = [==[Lore of the Clans, pág. 122


Secret Stash (3)


Você tem vários recursos, agentes adormecidos ou seguidores guardados para um dia de chuva. Para cada nível desta Qualidade, você tem um ponto de Antecedente não atribuído "no estoque" (2 lhe dá um ponto, 3 lhe dá dois, e assim por diante). A qualquer momento, você pode gastar quantos quiser para aumentar seu nível em Aliados, Contatos, Rebanho, Influência, Mentor, Recursos ou Lacaios. Uma vez gastos, os pontos ficam atribuídos em definitivo mas, até lá, não podem ser afetados por nada. Isso permite ao vampiro criar um recurso novo num instante, sem gastar pontos de experiência nem esperar um intervalo entre histórias. Ele não está de fato ganhando níveis novos: está revelando níveis que sempre teve.]==],
				},
				["Secret Stash (4)"] = {
					pt = [==[Lore of the Clans, pág. 122


Secret Stash (4)


Você tem vários recursos, agentes adormecidos ou seguidores guardados para um dia de chuva. Para cada nível desta Qualidade, você tem um ponto de Antecedente não atribuído "no estoque" (2 lhe dá um ponto, 3 lhe dá dois, e assim por diante). A qualquer momento, você pode gastar quantos quiser para aumentar seu nível em Aliados, Contatos, Rebanho, Influência, Mentor, Recursos ou Lacaios. Uma vez gastos, os pontos ficam atribuídos em definitivo mas, até lá, não podem ser afetados por nada. Isso permite ao vampiro criar um recurso novo num instante, sem gastar pontos de experiência nem esperar um intervalo entre histórias. Ele não está de fato ganhando níveis novos: está revelando níveis que sempre teve.]==],
				},
				["Secret Stash (5)"] = {
					pt = [==[Lore of the Clans, pág. 122


Secret Stash (5)


Você tem vários recursos, agentes adormecidos ou seguidores guardados para um dia de chuva. Para cada nível desta Qualidade, você tem um ponto de Antecedente não atribuído "no estoque" (2 lhe dá um ponto, 3 lhe dá dois, e assim por diante). A qualquer momento, você pode gastar quantos quiser para aumentar seu nível em Aliados, Contatos, Rebanho, Influência, Mentor, Recursos ou Lacaios. Uma vez gastos, os pontos ficam atribuídos em definitivo mas, até lá, não podem ser afetados por nada. Isso permite ao vampiro criar um recurso novo num instante, sem gastar pontos de experiência nem esperar um intervalo entre histórias. Ele não está de fato ganhando níveis novos: está revelando níveis que sempre teve.]==],
				},
				["Sectarian Ally"] = {
					pt = [==[Lore of the Clans, pág. 26


Sectarian Ally


Você tem um amigo próximo em uma das seitas Cainitas. Talvez seja um guerreiro em contato com um dos antitribu, um vizir que divide interesses comerciais com alguns Ventrue da Camarilla, ou um feiticeiro que se corresponde com um dos raros magos de sangue do Movimento Anarquista. Seu aliado pode ajudá-lo a navegar as correntes da seita dele, mas pode querer algo em troca de vez em quando.]==],
				},
				["Self-Confident"] = {
					pt = [==[Book of Secrets, pág. 46


Self-Confident


Magos são confiantes; você é ainda mais. Ao gastar Força de Vontade para obter um sucesso automático, você nem precisa perder aquele ponto, a menos que:

1) o sucesso obtido pela Força de Vontade seja o único sucesso daquela ação; ou

2) a dificuldade da ação seja 5 ou menos.

Esta Qualidade só entra em jogo em circunstâncias desafiadoras, e tarefas com dificuldade 5 ou menos são fáceis demais para exigir a autoconfiança da sua personagem.]==],
				},
				["Sense Influence"] = {
					pt = [==[The Hunters Hunted II, pág. 151


Sense Influence


Por treino e convivência com outros caçadores experientes, você pode comprar a Perícia Prontidão. Além disso, consegue perceber que alguém está sob influência sobrenatural ou presença fantasmagórica com uma rolagem de Percepção + Prontidão, dificuldade 8.]==],
				},
				["Setite Initiate"] = {
					pt = [==[Lore of the Clans, pág. 67


Setite Initiate


Você foi Abraçado num Clã que não os Seguidores de Set. Contudo, aceitou a religião Setita, passou pelo processo de avaliação e pelos ritos, e foi formalmente iniciado no culto. Você tem acesso a Serpentis e à Feitiçaria de Sangue Setita (embora pague custo de fora de Clã para aprendê-las). Pode até estudar um dos Caminhos de Iluminação deles.

É importante notar que "Setitas" de outros Clãs ou linhagens não são tratados como cidadãos de segunda classe. Você deixou de ser um trouxa a quem enrolar. Uma vez dentro, você é irmão de fé, distinção bem mais importante que a de sangue. Um forasteiro que aceita o Deus Sombrio é motivo de alegria, mesmo para o ancião mais conservador. Há até rumores de seres sobrenaturais não Cainitas entrando para o culto.]==],
				},
				["Shapechanger Kin"] = {
					pt = [==[Book of Secrets, pág. 74


Shapechanger Kin


Por um capricho distante mas perceptível de linhagem, você compartilha um toque do Sangue Mutável. Em bom português: você é aparentado com uma das raças metamorfas — lobisomens, gatos-garou, corvos-garou e assim por diante. Este dom não lhe concede os poderes nem a Gnose deles, mas você provavelmente conhece alguns segredos (em regras, um Conhecimento de saber) sobre seus parentes. Você permanece imune ao Delírio de medo primal que afeta a maioria das pessoas na presença de um metamorfo (não que magos sofram dele, de todo modo); consegue viajar pelos Outros Mundos por mais tempo que a maioria dos mortais, sem sofrer os efeitos colaterais de Desconexão e Aclimatação dessas viagens (detalhados em Mage 20, pp. 482-483); e possivelmente desfruta de alguma boa vontade da sua família feral, desde que não tenha feito nada para irritá-la. Os inimigos deles, porém, são seus inimigos, o que faz desta uma Qualidade de gume extremamente duplo.]==],
				},
				["Shattered Avatar"] = {
					pt = [==[Book of Secrets, pág. 77


Shattered Avatar


Seu Avatar foi partido em pedaços por algum trauma de vida passada. Por isso, a parte que está dentro de você está incompleta… mas essa situação pode ser corrigida. Se e quando localizar os pedaços que faltam, você pode tornar esse espírito interior mais forte. Em termos de jogo, esta Qualidade permite aumentar seu Antecedente Avatar depois da criação do personagem – algo que, normalmente, não pode ser feito. (Veja Mage 20, p. 336.)

Como em Almas Gêmeas, acima, esta Qualidade oferece muitos ganchos dramáticos. Os pedaços perdidos do seu Avatar podem estar encarnados em outras pessoas; presos em prisões espirituais (Reinos de Paradoxo, infernos demoníacos, armadilhas de alma, gemas encantadas e assim por diante); embutidos numa árvore de um jardim guardado por cinco dragões, e por aí vai. A busca pelos fragmentos da sua alma pode ser parte épica da sua crônica, com enigmas, reviravoltas, traições e batalhas em que sua alma é literalmente o prêmio. Esse tipo de coisa pode ser difícil de conciliar com suas crenças se, por exemplo, você for Tecnocrata. Ainda assim, até reunir os pedaços que faltam, haverá uma parte essencial de você que se sente incompleta.

O Narrador deve determinar exatamente o que estilhaçou seu Avatar e o que você precisa fazer para reunir os pedaços num espírito só. Se ele vai ou não compartilhar essa informação com você é escolha dele – pode ser algo que você descubra ao longo do jogo. A cada peça recuperada, você soma um ponto ao seu Antecedente Avatar, a menos que aquele Avatar estivesse encarnado em outro mago; nesse caso, o valor de Avatar dele é somado ao seu se você conseguir matá-lo… e, se ele o matar primeiro, seu Avatar é somado ao dele. (Aparentemente, só pode haver um.)

Não importa quantos pedaços estejam envolvidos, porém: o Antecedente Avatar tem teto de 5 pontos. Embora esta Qualidade permita elevar o valor do Traço, ela não permite ultrapassar esse limite.]==],
				},
				["Sight Beyond Sight"] = {
					pt = [==[Lore of the Bloodlines, pág. 80


Sight Beyond Sight


Seu terceiro olho ocasionalmente tem visões e fura ilusões. Quando ele está aberto (pelo uso de Auspícios ou Obeah), você vez ou outra atravessa Ofuscação ou Quimerismo. Alguns Salubri do passado enxergaram através de semblantes feéricos ou vislumbraram as terras mortas dos fantasmas. Você não tem controle sobre o que o olho vê, embora ele às vezes se abra involuntariamente em resposta aos fenômenos acima.]==],
				},
				["Simply Waiting"] = {
					pt = [==[Lore of the Bloodlines, pág. 16


Simply Waiting


O Baali conhece seu lugar na ordem do universo, e sabe onde está em relação a outros vampiros ou aos da própria linhagem. Sabe também que o fim do mundo está chegando, e mais cedo que tarde. Ele parece apático diante do mundo ao redor mas, na verdade, está simplesmente resignado ao próprio destino e não se abala quando tentam desviá-lo do seu caminho. Todas as rolagens Sociais contra ele sofrem +2 de dificuldade, pois o Baali conhece o verdadeiro fim de tudo.]==],
				},
				["Skald"] = {
					pt = [==[Lore of the Clans, pág. 87


Skald


Sempre que fizer uma rolagem de Ocultismo para saber algum fato da história vampírica, você pode somar um dado à parada. Além disso, você tem memória excepcional para histórias orais e aprende rápido quando se trata de memorizar grandes volumes de informação decorada. Não é memória eidética de verdade, mas a capacidade de memorizar eddas poéticas, códigos ou mensagens complexas com apenas algumas horas de estudo.]==],
				},
				["Skin of Porcelain"] = {
					pt = [==[Lore of the Bloodlines, pág. 60


Skin of Porcelain


Por beberagens ingeridas ou por um acaso do seu Abraço, sua pele tem uma camada semelhante à cerâmica. Para que isso tenha algum efeito além de parecer estranho, é exigida uma rolagem de Vigor (dificuldade 8). Um sucesso permite converter até três pontos de dano agravado causado por fogo em dano letal, antes das tentativas de absorção. O endurecimento se dissipa pelo resto da história em curso.]==],
				},
				["Sleep Unseen"] = {
					pt = [==[Lore of the Clans, pág. 161


Sleep Unseen


O poder da Ofuscação em geral exige ao menos um pouco de concentração. Você, porém, consegue travá-lo ligado, o que lhe permite dormir sem deixar de estar escondido. Isso exige o gasto de um ponto de sangue, mas dura por todo o descanso do dia. Quem tem Auspícios ainda pode tentar detectá-lo, mas os mortais não perceberão seu santuário. É um truque útil para Cainitas que gostam de viajar.]==],
				},
				["Slimy"] = {
					pt = [==[Lore of the Clans, pág. 161


Slimy


Você secreta uma gosma, tão nojenta quanto parece. Ela cobre todo o seu corpo e encharca suas roupas. Isso o deixa escorregadio e difícil de segurar, exigindo dois sucessos a mais para que adversários o agarrem. A umidade também o torna um pouco resistente ao fogo, reduzindo em 1 a dificuldade para absorver dano de fogo.]==],
				},
				["Slowed Degeneration"] = {
					pt = [==[Lore of the Clans, pág. 200


Slowed Degeneration


Sua Humanidade é forte e resiste melhor aos assaltos da Besta. Você ganha dois dados adicionais em qualquer rolagem de Consciência. Esse grau de resiliência moral permite a um vampiro bem-comportado perder Humanidade num ritmo muito mais lento que o normal. Apenas vampiros que seguem a Humanidade podem adquirir esta Qualidade, e ela é perdida para sempre caso o vampiro adote outro Caminho de Iluminação.]==],
				},
				["Soapbox"] = {
					pt = [==[Anarchs Unbound, pág. 4


Soapbox


Você tem algum tipo de tribuna própria (um fanzine, um blog seguro, um podcast conhecido ou uma conta de rede social com muitos seguidores) que permite ao seu Anarquista expressar uma opinião e vê-la se espalhar. A Qualidade Tribuna representa um mecanismo social de difusão capaz de influenciar Cainitas fora do círculo ou da classe social habitual da sua personagem. Reduza em 2 a dificuldade das rolagens de Expressão e Manha ao lidar com vampiros que acompanham a Tribuna.]==],
				},
				["Socially Networked"] = {
					pt = [==[Book of Secrets, pág. 57


Socially Networked


Bem conectado na internet (como na Qualidade de mesmo nome dos Adeptos Virtuais), você desfruta de um perfil on-line de destaque – um site, ao menos um blog, mais seguidores no Twitter e amigos no Facebook do que você poderia conhecer no mundo de carne, e assim por diante. Quando você publica, as pessoas leem, compartilham e levam a sério. Isso pode ou não se traduzir em gente que você conhece na Teia Digital (e, sinceramente – você ia querer isso?), mas você exerce influência global pela rede mundial. Como resultado, tem um tipo de influência e de recursos que a maioria nem imagina: financiadores coletivos, informação instantânea, lugares para dormir no mundo inteiro quando quiser… os detalhes dependem do tipo de presença que você mantém e das pessoas que atrai, mas vão além de qualquer coisa que você conseguiria sem a internet.

Claro que você também pode estragar tudo em escala planetária se não tomar cuidado – toda essa atenção pode se voltar contra você se publicar a coisa errada na hora errada – e certos odiadores o desprezam por princípio. Considerando que a internet é uma frente central nas guerras de realidade do século XXI, porém, esse tipo de rede pode dar uma vantagem enorme ao seu lado.]==],
				},
				["Spark of Life"] = {
					pt = [==[Book of Secrets, pág. 78


Spark of Life


Abençoado com grande vitalidade, você cura ferimentos com velocidade e facilidade heroicas. Seus próprios ferimentos de dano letal se curam como se fossem dano contundente (veja a tabela de Cura de Dano em Mage 20, p. 406), e o dano agravado se cura como se estivesse um nível acima do que está. (Dano de nível Muito Ferido, por exemplo, curaria na velocidade do nível Ferido.) Dano contundente, seja qual for a extensão, se cura em uma hora.

Se estiver tentando curar outra pessoa, você subtrai -2 da dificuldade da rolagem, mesmo que ela envolva lançar um Efeito de cura da Esfera da Vida. (O modificador máximo usual de +3 e a dificuldade mínima de 3 continuam valendo – veja Mage 20, p. 503.) Enquanto mantiver contato físico com a pessoa ferida, ela usa a sua taxa de cura como se fosse dela. Seu toque também alivia dores pequenas – espasmos musculares, dores de cabeça e afins – em um ou dois minutos.

Além dos poderes de cura, essa onda de energia vital simplesmente faz bem. Sua aura brilha com vitalidade intensa, e sua Ressonância reflete a forte ligação com a força vital primal. No inevitável lado ruim, vampiros acham seu sangue delicioso – duas vezes mais potente que a vitae humana normal (valendo o dobro dos pontos de sangue usuais, para jogadores de Vampiro: A Máscara) – e indescritivelmente revigorante.]==],
				},
				["Spawning Pool (1)"] = {
					pt = [==[Lore of the Clans, pág. 161


Spawning Pool (1)


Você tem seu próprio poço de procriação (ou talvez faça doações pesadas ao poço principal do Clã). Criar um poço desses leva tempo e exige infusões regulares de sangue: ao menos seis pontos por semana durante um ano.

Esta Qualidade concede seu nível como bônus de dados ao uso de Animalismo pelo Nosferatu na cidade natal, mas apenas com animais considerados pragas, como ratos e baratas. Basicamente, o bônus só vale para criaturas que possam concebivelmente beber com regularidade do sangue maculado.

Uma vez estabelecido, o poço exige o dobro do seu nível em pontos de sangue toda semana. Sem manutenção adequada, o nível dele cai em um. Ele pode ser reconstruído mantendo-o no novo nível e acrescentando quatro pontos de sangue extras por semana durante seis meses.

Esta Qualidade não pode ser elevada acima do nível inicial, pois ela também representa a conveniência da localização e a variedade de criaturas que possam encontrá-lo.]==],
				},
				["Spawning Pool (2)"] = {
					pt = [==[Lore of the Clans, pág. 161


Spawning Pool (2)


Você tem seu próprio poço de procriação (ou talvez faça doações pesadas ao poço principal do Clã). Criar um poço desses leva tempo e exige infusões regulares de sangue: ao menos seis pontos por semana durante um ano.

Esta Qualidade concede seu nível como bônus de dados ao uso de Animalismo pelo Nosferatu na cidade natal, mas apenas com animais considerados pragas, como ratos e baratas. Basicamente, o bônus só vale para criaturas que possam concebivelmente beber com regularidade do sangue maculado.

Uma vez estabelecido, o poço exige o dobro do seu nível em pontos de sangue toda semana. Sem manutenção adequada, o nível dele cai em um. Ele pode ser reconstruído mantendo-o no novo nível e acrescentando quatro pontos de sangue extras por semana durante seis meses.

Esta Qualidade não pode ser elevada acima do nível inicial, pois ela também representa a conveniência da localização e a variedade de criaturas que possam encontrá-lo.]==],
				},
				["Spawning Pool (3)"] = {
					pt = [==[Lore of the Clans, pág. 161


Spawning Pool (3)


Você tem seu próprio poço de procriação (ou talvez faça doações pesadas ao poço principal do Clã). Criar um poço desses leva tempo e exige infusões regulares de sangue: ao menos seis pontos por semana durante um ano.

Esta Qualidade concede seu nível como bônus de dados ao uso de Animalismo pelo Nosferatu na cidade natal, mas apenas com animais considerados pragas, como ratos e baratas. Basicamente, o bônus só vale para criaturas que possam concebivelmente beber com regularidade do sangue maculado.

Uma vez estabelecido, o poço exige o dobro do seu nível em pontos de sangue toda semana. Sem manutenção adequada, o nível dele cai em um. Ele pode ser reconstruído mantendo-o no novo nível e acrescentando quatro pontos de sangue extras por semana durante seis meses.

Esta Qualidade não pode ser elevada acima do nível inicial, pois ela também representa a conveniência da localização e a variedade de criaturas que possam encontrá-lo.]==],
				},
				["Sphere Natural"] = {
					pt = [==[Book of Secrets, pág. 79


Sphere Natural


Para um único elemento da magia – a Esfera da sua escolha –, você tem uma proficiência inata. Os poderes daquela Esfera vêm a você com mais facilidade que o normal, e você avança mais rápido naquele campo que nas outras Esferas. Em termos de sistema, você paga 70% do custo usual em experiência, arredondando para cima, ao avançar naquela Esfera. Naturalmente, o avanço custa ainda menos quando você eleva sua Esfera de Afinidade.

Custo (Esfera comum / Esfera de Afinidade): Esfera nova 7 pts · nível 2: 6/5 · nível 3: 11/10 · nível 4: 17/15 · nível 5: 23/20.

A versão de Mage 20 desta Qualidade custa mais que a das edições anteriores porque o custo de melhorar Esferas com experiência caiu e, portanto, os benefícios envolvidos aumentaram. Você só pode escolher esta Qualidade uma vez, para uma única Esfera, e ela deve ter alguma ligação intrínseca com o conceito, o passado e o foco mágico do seu mago. Afinal, esta é uma Arte que lhe vem naturalmente, e essa predisposição deve transparecer em muitos aspectos da personalidade da sua personagem.]==],
				},
				["Spirit Mentor"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 493


Spirit Mentor


Você tem um companheiro e guia fantasmagórico. A identidade e os poderes exatos desse espírito ficam a cargo do Narrador, mas ele pode ser chamado em situações difíceis para ajuda e orientação.]==],
				},
				["Stillness of Death"] = {
					pt = [==[Lore of the Bloodlines, pág. 37


Stillness of Death


Gárgulas costumam se esconder como estátuas. A dificuldade de qualquer busca para encontrá-lo aumenta em 2 quando você fica perfeitamente imóvel.]==],
				},
				["Stitcher"] = {
					pt = [==[Lore of the Bloodlines, pág. 5


Stitcher


Ser despedaçado não é grande coisa. Quando partes do seu corpo são cortadas ou removidas por dano, você pode fazer uma rolagem de Destreza + Medicina (dificuldade 7) para costurar a parte de volta no lugar certo. Com sucesso, o custo de curar aquele ferimento cai em um ponto de sangue.]==],
				},
				["Stormwarden"] = {
					pt = [==[M20 Victorian Age, pág. 122


Stormwarden


Dada a época em que estas histórias se passam, esta Qualidade é um conceito irrelevante.]==],
				},
				["Stormwarden /Quantum Voyager (3)"] = {
					pt = [==[Book of Secrets, pág. 74


Stormwarden /Quantum Voyager (3)


Veja Mage 20, p. 643.]==],
				},
				["Stormwarden /Quantum Voyager (5)"] = {
					pt = [==[Book of Secrets, pág. 74


Stormwarden /Quantum Voyager (5)


Veja Mage 20, p. 643.]==],
				},
				["Strength of Psyche"] = {
					pt = [==[M20 Sorcerer, pág. 107


Strength of Psyche


Você desenvolveu o talento de recorrer a energias arcanas para turbinar a mente. Consegue aguçar os sentidos, acelerar o pensamento e ligar os pontos entre pistas desconexas. Você pode gastar pontos de Quintessência para reduzir a dificuldade de qualquer parada de dados de ação mental. A dificuldade não pode cair abaixo de dois, nem ser reduzida em mais de três. Você precisa ser capaz de armazenar Quintessência no próprio padrão para se qualificar a esta Qualidade.]==],
				},
				["Sturdy"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 420


Sturdy


Treino, privações ou capacidade natural endureceram seu corpo contra a dor e o dano. Embora você não seja necessariamente um brutamontes, quem já o viu em ação sabe que você aguenta mais dano que a média. Você ganha um nível de vitalidade Escoriado adicional, e o Narrador pode conceder bônus cabíveis quando sua resistência inata entrar em jogo.]==],
				},
				["Style Sleeper"] = {
					pt = [==[M20 Sorcerer, pág. 107


Style Sleeper


Sua personagem sabe que a magia é real e a pratica, mas esses outros pretensos magos são claramente falsos. Sempre que você vê magia que se encaixa no seu Paradigma, tudo corre como deveria; mas, quando testemunha magia fora daquele estilo, você é tratado como Adormecido. Isto não é um Defeito porque atrapalha mais a magia dos seus adversários que a sua. Pode haver consequências indesejadas quando outro feiticeiro de Paradigma diferente tenta curá-lo, mas sua descrença anula a magia dele.]==],
				},
				["Styx Baptism"] = {
					pt = [==[Lore of the Bloodlines, pág. 48


Styx Baptism


Você jurou fidelidade aos Precursores do Ódio e prometeu trabalhar contra as maquinações de Ashur, apesar de não ter sido Abraçado na linhagem. Você foi escoltado até as Terras das Sombras, onde foi batizado de cabeça nas águas revoltas do Estige. A carne da sua cabeça se desprendeu com o contato ao longo do mês seguinte, deixando apenas manchas apodrecidas ou osso exposto, o que reduziu sua Aparência a 0 permanentemente. Agora você é tido em alta conta pelos Lazarenos, e ganha uma das Disciplinas da linhagem como Disciplina de Clã no lugar de uma das suas.]==],
				},
				["Subculture Insider"] = {
					pt = [==[Book of Secrets, pág. 58


Subculture Insider


Você conhece por dentro um ambiente social que a maioria das pessoas nunca visita, muito menos compreende. Lá eles o conhecem e, por isso, mesmo quando você ainda não encontrou determinada pessoa (humana ou não) naquele meio, ela o considera alguém de dentro. Graças a essa familiaridade, você também navega certos elementos do ambiente físico do lugar – os aparatos de segurança, os "apertos de mão secretos", os cantos escondidos que só quem é de dentro conhece e que um forasteiro jamais pensaria em procurar, e outros obstáculos que uma subcultura ergue para garantir que só a gente "certa" circule. Ao se mover pela subcultura que escolheu, subtraia -2 das dificuldades das rolagens que concedam acesso social ou físico ao território estabelecido dela.

A subcultura em questão pode ser qualquer ambiente social exclusivo que inclua também o entorno físico usado por aquele grupo: clubes de campo, cartéis de droga, a rede internacional de mercenários, o submundo global da espionagem, executivos do alto escalão financeiro, a comunidade fetichista, comunidades de população em situação de rua, comunidades rurais fechadas, redes do hip-hop, a jet set, a cultura dos festivais rave, fãs de fantasia, a comunidade de músicos de estrada, líderes financeiros mundiais, viajantes ciganos e assim por diante. Embora possa incluir magos e outra Gente da Noite, a comunidade precisa ser essencialmente "mortal" na maioria dos seus membros. Você pode comprar esta Qualidade várias vezes, para representar participação em várias comunidades. Essa condição de membro, porém, leva tempo para ser conquistada e muita atenção para ser mantida. Se você negligenciar sua comunidade, logo verá aquelas portas familiares batendo na sua cara.]==],
				},
				["Sugar Daddy"] = {
					pt = [==[Anarchs Unbound, pág. 102


Sugar Daddy


Você tem uma relação pessoal com um membro graduado de outra seita. Pode invocar o nome do seu Padrinho para reduzir em 2 a dificuldade de rolagens de Manipulação com membros daquela seita ao tentar aparar arestas ou obter favores menores. Claro que o Padrinho pode esperar tratamento semelhante em troca, e dificilmente verá com bons olhos qualquer comportamento que manche o status dele.]==],
				},
				["Supernatural Companion"] = {
					pt = [==[Book of Secrets, pág. 74


Supernatural Companion


Você tem um amigo entre a Gente da Noite: um vampiro, um changeling, um metamorfo, um fantasma ou outra entidade que existe fora das Massas Adormecidas. Esse amigo não é tão confiável quanto um personagem do Antecedente Aliados, mas pode ajudá-lo quando necessário. Essa porta abre para os dois lados, claro; seu companheiro também vai chamá-lo de tempos em tempos, e nem sempre nas ocasiões mais convenientes!

As pessoas (e a Gente da Noite) provavelmente torcem o nariz para essa amizade. Lobisomens, por exemplo, não vão com a cara de magos ladrões de Septos! Isso vale ainda mais se você for um Tecnocrata de fraldas com um daqueles malditos Desviantes da Realidade, ou um mago das Tradições que anda com um demônio chupador de sangue. Sim, a amizade vale o incômodo, mas às vezes dá um belo trabalho. Seja quem ou o que for esse amigo, o Narrador cria e controla a personagem em questão… com todas as prioridades estranhas, necessidades conflitantes e agendas secretas que isso sugere.]==],
				},
				["The Company of Saints and Heroes"] = {
					pt = [==[Vampire: The Dark Ages 20th Anniversary Edition, pág. 423


The Company of Saints and Heroes


Experiências de vida (e possivelmente de não-vida) o aproximaram de augustas figuras religiosas, entidades políticas e heróis lendários. Eles realmente o conhecem e pensam bem de você, mas vocês não são necessariamente próximos. Use o Antecedente Aliados para representar uma relação mais estreita. Esta Qualidade permite que você invoque sua conexão famosa e reduza em um a dificuldade das rolagens Sociais aplicáveis.]==],
				},
				["The Flow of Ki"] = {
					pt = [==[M20 Sorcerer, pág. 106


The Flow of Ki


Você compreende o fluxo natural de energia através do corpo humano, ensinado por meio de uma forma de artes marciais. Essa energia é representada como Quintessência, mas pode receber vários nomes: chi, ki e outros, dependendo do seu estilo de artes marciais. Você pode gastar Quintessência das suas reservas internas para reduzir a dificuldade de qualquer parada de dados de ações físicas. Você não pode baixar a dificuldade abaixo de dois, nem reduzi-la em mais de três. Você precisa ser capaz de armazenar Quintessência no seu próprio padrão para se qualificar para esta Qualidade.]==],
				},
				["The High Price"] = {
					pt = [==[Lore of the Bloodlines, pág. 16


The High Price


O fardo de adquirir verdade ou poder sempre cobra um preço alto. Ninguém sabe disso melhor que estes Baali, que sacrificam uma parte da própria alma em busca da grandeza. Seu corpo físico é atormentado por fraqueza e dor, limitando qualquer Atributo Físico a quatro pontos e custando 1 ponto de Força de Vontade toda noite ao despertar. Em troca desse tributo, o Baali recebe +2 dados em qualquer teste relacionado a Disciplinas.]==],
				},
				["Thousand Meter Killer"] = {
					pt = [==[Lore of the Clans, pág. 26


Thousand Meter Killer


Você provou ser digno de ingressar no Clube dos Mil Metros graças à sua habilidade notável com o rifle de precisão. A dificuldade de todas as rolagens associadas a tiros de precisão é reduzida em -1. Você também dobra o alcance normal ao usar um rifle de precisão como arma.]==],
				},
				["Thugs"] = {
					pt = [==[The Hunters Hunted II, pág. 151


Thugs


Ao comprar o Antecedente Aliados, você está adquirindo membros linha-dura do submundo, e não membros comuns da sociedade respeitável. Seus Aliados podem ser membros de gangue, mafiosos ou integrantes do seu sindicato do crime organizado. Diferentemente dos Aliados normais, esses indivíduos estão dispostos a arrumar briga com outros mortais, assassinar inocentes, intimidar moradores locais, isolar temporariamente uma área da cidade ou até cometer crimes em seu nome.]==],
				},
				["Ties"] = {
					pt = [==[Book of Secrets, pág. 58


Ties


Veja Mage 20, pp. 643-644.]==],
				},
				["Time Sense"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 484


Time Sense


Você tem um senso inato de tempo e é capaz de estimar com precisão a passagem do tempo sem usar relógio ou qualquer outro dispositivo mecânico.]==],
				},
				["Too Tough to Die"] = {
					pt = [==[Book of Secrets, pág. 39


Too Tough to Die


Veja Mage 20, p. 644.]==],
				},
				["Totemic Change"] = {
					pt = [==[Lore of the Clans, pág. 87


Totemic Change


Suas formas de Metamorfose são flexíveis; você pode escolher uma forma animal diferente a cada vez que muda de forma. A forma escolhida em cada ocasião precisa seguir todas as convenções e regras das formas animais padrão de Metamorfose (veja a p. 91); você simplesmente pode optar por aparecer como um animal diferente sempre que assume a Forma da Besta.]==],
				},
				["Tough Hide"] = {
					pt = [==[Lore of the Clans, pág. 161


Tough Hide


Sua pele é muito mais resistente que o normal, possivelmente como a de um rinoceronte ou de um lagarto. Esse couro o protege contra a maior parte do dano, concedendo um dado extra ao fazer uma rolagem de absorção. Contudo, esse bônus não se aplica contra fogo e luz solar.]==],
				},
				["Tracker's Mark"] = {
					pt = [==[Dark Ages Companion, pág. 100


Tracker's Mark


Bem sintonizado com a alma de sua presa, o terceiro olho da Salubri enxerga a influência do oponente no mundo, e não apenas os rastros físicos que ele deixou: ao rastrear (V20 Dark Ages, página 337), a jogadora da Salubri rola com -2 de dificuldade. Sinais efêmeros de uma presa são considerados evidência válida a ser seguida, mesmo que uma Salubri normalmente não consiga detectá-los; por exemplo, se um Brujah irado perturbou a paz de um mercado, a Guerreira pode discernir a presença dele nos comerciantes ainda irritados horas depois, dando o salto intuitivo de relacionar o evento à passagem de sua presa.]==],
				},
				["True Celerity"] = {
					pt = [==[Lore of the Bloodlines, pág. 99


True Celerity


Os Brujah Verdadeiros têm uma relação estranha com a Celeridade. Ela costuma vir com facilidade para eles, mas alguns se recusam a aprendê-la, por ter se tornado um símbolo dos Brujah traidores. Ainda assim, muitos a consideram uma habilidade útil para se passar por Brujah dentro da Camarilla ou do Sabá, e por isso alguns Brujah Verdadeiros desenvolveram uma forma ligeiramente diferente da Disciplina.

Um personagem com esta Qualidade tem a capacidade de aprender a Celeridade Verdadeira. Embora funcione exatamente como a Celeridade, a sensação é bem diferente: em vez de o personagem se mover depressa, ele desacelera o tempo ao seu redor. Esta Qualidade não concede ponto nenhum de Disciplina ao personagem, mas permite que ela seja comprada com experiência como se a Celeridade fosse uma Disciplina de Clã. Embora este poder funcione igual à Celeridade, ele não pode ser ensinado a ninguém que não tenha algum nível da Disciplina Temporis.]==],
				},
				["True Faith"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 494


True Faith


Você tem uma fé profunda em Deus, ou em qualquer outro nome que escolha dar ao Todo-Poderoso, e amor por Ele. Você começa o jogo com um ponto de Fé Verdadeira (veja o quadro na p. 372); esse Traço acrescenta um dado por ponto a todas as rolagens de Força de Vontade e de Virtude. Você precisa ter Humanidade 9 ou mais para escolher esta Qualidade e, se perder um único ponto, todos os seus pontos de Fé são perdidos e só podem ser recuperados quando a Humanidade perdida for recuperada. Indivíduos com Fé Verdadeira são capazes de realizar atos mágicos semelhantes a milagres, mas a natureza exata desses atos fica a cargo do Narrador.]==],
				},
				["True Love"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 493


True Love


Você descobriu, talvez tarde demais, um amor verdadeiro. Ele ou ela é mortal, mas é o centro da sua existência e o inspira a seguir em frente num mundo de trevas e desespero. Sempre que você sofre, o pensamento do seu amor verdadeiro lhe dá forças para perseverar. Esta Qualidade concede um sucesso automático em todas as rolagens de Força de Vontade, que só pode ser anulado por um dado de falha crítica. Isso pode ser um grande presente, mas também um estorvo, pois seu amor verdadeiro pode precisar de proteção e, ocasionalmente, de resgate.]==],
				},
				["Tunnel Rat (1)"] = {
					pt = [==[Lore of the Clans, pág. 161


Tunnel Rat (1)


Você é notavelmente hábil em se deslocar pelos túneis subterrâneos que chama de lar. Ao tentar se orientar, escapar ou rastrear por esgotos e lugares subterrâneos que conhece, você ganha um dado adicional para cada ponto que tiver nesta Qualidade.]==],
				},
				["Tunnel Rat (2)"] = {
					pt = [==[Lore of the Clans, pág. 161


Tunnel Rat (2)


Você é notavelmente hábil em se deslocar pelos túneis subterrâneos que chama de lar. Ao tentar se orientar, escapar ou rastrear por esgotos e lugares subterrâneos que conhece, você ganha um dado adicional para cada ponto que tiver nesta Qualidade.]==],
				},
				["Tunnel Rat (3)"] = {
					pt = [==[Lore of the Clans, pág. 161


Tunnel Rat (3)


Você é notavelmente hábil em se deslocar pelos túneis subterrâneos que chama de lar. Ao tentar se orientar, escapar ou rastrear por esgotos e lugares subterrâneos que conhece, você ganha um dado adicional para cada ponto que tiver nesta Qualidade.]==],
				},
				["Tunnel Rat (4)"] = {
					pt = [==[Lore of the Clans, pág. 161


Tunnel Rat (4)


Você é notavelmente hábil em se deslocar pelos túneis subterrâneos que chama de lar. Ao tentar se orientar, escapar ou rastrear por esgotos e lugares subterrâneos que conhece, você ganha um dado adicional para cada ponto que tiver nesta Qualidade.]==],
				},
				["Tunnel Rat (5)"] = {
					pt = [==[Lore of the Clans, pág. 161


Tunnel Rat (5)


Você é notavelmente hábil em se deslocar pelos túneis subterrâneos que chama de lar. Ao tentar se orientar, escapar ou rastrear por esgotos e lugares subterrâneos que conhece, você ganha um dado adicional para cada ponto que tiver nesta Qualidade.]==],
				},
				["Twin Link (4)"] = {
					pt = [==[M20 Sorcerer, pág. 107


Twin Link (4)


Seu personagem psíquico compartilha uma conexão psíquica permanente com outra pessoa. Isso duplica o benefício do efeito Sinergia de Nível Dois. Os psíquicos ligados ganham +2 no valor de Empatia para determinar os sentimentos da outra parte. Como Qualidade de 6 pontos, os personagens vinculados podem comprar o poder Sinergia, além dos outros poderes psíquicos que possuam, a um custo menor: 7 pontos livres por ponto, 3 pontos de experiência por ponto para aumentar. Esse poder Sinergia só funciona com o parceiro vinculado.]==],
				},
				["Twin Link (6)"] = {
					pt = [==[M20 Sorcerer, pág. 107


Twin Link (6)


Seu personagem psíquico compartilha uma conexão psíquica permanente com outra pessoa. Isso duplica o benefício do efeito Sinergia de Nível Dois. Os psíquicos ligados ganham +2 no valor de Empatia para determinar os sentimentos da outra parte. Como Qualidade de 6 pontos, os personagens vinculados podem comprar o poder Sinergia, além dos outros poderes psíquicos que possuam, a um custo menor: 7 pontos livres por ponto, 3 pontos de experiência por ponto para aumentar. Esse poder Sinergia só funciona com o parceiro vinculado.]==],
				},
				["Twin Souls"] = {
					pt = [==[Book of Secrets, pág. 75


Twin Souls


Para você, o termo alma gêmea é literalmente verdadeiro. Seu Avatar tem um gêmeo que se encarnou em outro corpo mortal. Essa outra pessoa (tipicamente um ser humano, mas potencialmente um animal) compartilha sua Natureza e sua Essência, e possivelmente também seu Comportamento. Ainda assim, seu "gêmeo" pode ser uma pessoa muito diferente: outro gênero, outra etnia, outra cultura e, de novo, possivelmente até um animal "superior" como um lobo, um urso, um falcão, um bisão e assim por diante. Essa pessoa pode viver do outro lado do mundo e talvez nem saiba que você existe. Se dois gêmeos de alma se encontram pessoalmente, porém, ambos sentem uma conexão inconfundível um com o outro. Essa conexão, contudo, não se traduz necessariamente em boa vontade: irmãos de sangue frequentemente se estranham, e almas gêmeas também podem se estranhar.

Se esse gêmeo também for um mago (muitos Avatares gêmeos ainda não Despertaram), então os dois magos têm o mesmo valor de Avatar. Vocês podem compartilhar Quintessência e conjurar magias juntos se estiverem em contato físico (ou, na Umbra, em contato efêmero). Nesse caso, o personagem com o maior valor de Arete e as maiores Esferas é aquele cujos Traços são usados para conjurar esses Efeitos. Os dois magos, quando estão ao alcance do braço, também ganham uma quantidade de pontos de Quintessência bônus igual ao seu valor de Avatar; se Ryan Summers e sua gêmea Sylvia Jane têm três pontos em Avatar, cada um ganha três pontos adicionais de Quintessência quando estão perto o bastante para se tocar. Para detalhes sobre conjuração colaborativa, veja Agindo em Conjunto em Mage 20, pp. 542-543. Almas compartilhadas, porém, também compartilham igualmente qualquer Paradoxo acumulado por suas magias, e cada gêmeo recebe separadamente a quantidade integral de Paradoxo. Se Ryan ou Sylvia conjura um Efeito que rende 10 pontos de Paradoxo, então tanto Ryan quanto Sylvia recebem 10 pontos de Paradoxo cada um.

Sendo seu gêmeo um mago ou não, você pode usar magia para acompanhá-lo depois de tê-lo encontrado. Um único ponto de Correspondência permite saber onde sua alma gêmea está, um único ponto em Vida permite saber seu estado de saúde atual, e um único ponto em Mente permite que vocês compartilhem pensamentos. A morte de um gêmeo, contudo, é um evento devastador: se seu gêmeo morrer, você precisa fazer uma rolagem de Força de Vontade (dificuldade 8) ou sofrer o choque psíquico das Coisas Que o Homem Não Deveria Saber. Até que o Avatar desse gêmeo reencarne (o que pode não acontecer dentro da sua própria vida) e seja encontrado pessoalmente outra vez, você não pode usar os poderes compartilhados de que um dia desfrutou.

Como acontece com outros Traços baseados em personagens, seu gêmeo não é uma Qualidade ambulante, e sim um personagem por direito próprio. Os dois gêmeos poderiam ser interpretados por jogadores diferentes do mesmo grupo, e provavelmente não deveriam ser interpretados pelo mesmo jogador. A busca por uma alma gêmea, uma disputa amarga entre almas gêmeas, duas almas gêmeas em facções opostas da Guerra da Ascensão: histórias assim podem servir de base para eventos e temas decisivos na sua crônica. Esta Qualidade combina bem com o Antecedente Aliados, com a Qualidade Amor Verdadeiro e com os Defeitos Inimigo, Dormindo com o Inimigo e Protegido. Por causa da natureza já Desperta do Povo da Noite, porém, um gêmeo de alma não pode ser um vampiro, um metamorfo, um changeling ou outra entidade paranormal.]==],
				},
				["Umbral Affinity"] = {
					pt = [==[Book of Secrets, pág. 75


Umbral Affinity


Veja Mage 20, p. 644.]==],
				},
				["Unaging"] = {
					pt = [==[Book of Secrets, pág. 69


Unaging


Os anos parecem passar por você sem tocá-lo. O tempo avança, mas você permanece essencialmente com a mesma idade física que tinha quando esta Qualidade interrompeu seu processo de envelhecimento. Talvez você tenha descoberto a Fonte da Juventude, tenha se atualizado para uma estabilidade perpétua, tenha assumido uma relação estranha com o fluxo do tempo ou tenha fechado um pacto insólito que preservou sua idade atual. E assim, embora continue a acumular as cicatrizes, a experiência e a perspectiva da idade, seu corpo mantém um estado constante de desenvolvimento cronológico. Note que isso não é o mesmo que imortalidade: ferimentos e doenças podem matá-lo com a mesma certeza com que matariam qualquer outra pessoa. A decrepitude da velhice, contudo, não é algo com que você vá precisar se preocupar.]==],
				},
				["Unbondable"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 494


Unbondable


Você é imune ao Laço de Sangue. Tremere não podem escolher esta Qualidade.]==],
				},
				["Unmarked Antitribu (2)"] = {
					pt = [==[Lore of the Clans, pág. 219


Unmarked Antitribu (2)


Embora você faça parte do Sabá e seja um traidor da Casa e Clã Tremere, de algum modo você permanece sem a marca da maldição antitribu. Você não é facilmente reconhecido como um Tremere renegado, e a magia que queimou tantos dos seus irmãos não consegue tomá-lo por alvo. Além disso, outros membros do Sabá não conseguem julgá-lo à primeira vista. Os da linhagem Telyavelic podem comprar esta Qualidade por 2 pontos, enquanto os demais Tremere pagam 5 pontos.]==],
				},
				["Unmarked Antitribu (5)"] = {
					pt = [==[Lore of the Clans, pág. 219


Unmarked Antitribu (5)


Embora você faça parte do Sabá e seja um traidor da Casa e Clã Tremere, de algum modo você permanece sem a marca da maldição antitribu. Você não é facilmente reconhecido como um Tremere renegado, e a magia que queimou tantos dos seus irmãos não consegue tomá-lo por alvo. Além disso, outros membros do Sabá não conseguem julgá-lo à primeira vista. Os da linhagem Telyavelic podem comprar esta Qualidade por 2 pontos, enquanto os demais Tremere pagam 5 pontos.]==],
				},
				["Unobtrusive"] = {
					pt = [==[Book of Secrets, pág. 54


Unobtrusive


Você consegue passar despercebido na maioria das situações sociais. Isso tem menos a ver com o inexplicável Antecedente Arcano (embora possa complementá-lo) do que com o simples fato de você parecer banal. A menos que faça algum alarde, as pessoas simplesmente não se lembram de você. Você é… ahn, aquele cara… ou aquela moça… ou, bom, droga, eu nem lembro direito que tipo de pessoa você é, na verdade. E em certas linhas de trabalho ou modos de vida, esse é um talento muito útil de se ter.

Embora não o torne de forma alguma invisível ou irrastreável, esta Qualidade permite que você se misture à paisagem e escape da memória alheia. As pessoas precisam fazer uma rolagem de Percepção (dificuldade 6) para recordar seus traços ou seu nome. Em contrapartida, você soma +2 à dificuldade de qualquer rolagem social que precise fazer, porque as pessoas simplesmente não o notam na maioria das circunstâncias. Por motivos óbvios, você não pode escolher nenhuma Qualidade, Defeito ou Antecedente socialmente marcante — Traços assim o tornariam memorável — nem ter traços físicos ou roupas especialmente marcantes. É claro que "marcante" depende de quem você é e de onde você está; o proverbial terno de flanela cinza, por exemplo, chama atenção em lugares como o Burning Man! Na maioria das circunstâncias, porém, você se mistura à paisagem aonde quer que vá.]==],
				},
				["Useful Knowledge"] = {
					pt = [==[Vampire: The Masquerade 20th Anniversary Edition, pág. 484


Useful Knowledge


Você tem conhecimento especializado em um campo específico que torna sua conversa intrigante para um Cainita mais velho. Enquanto o seu conhecimento prender a atenção do outro vampiro, ele tem interesse próprio em manter você por perto. Por outro lado, assim que ele tiver extraído de você cada fiapo de informação que você possui, esse patrocínio pode desaparecer de repente. (Nota: esta Qualidade deve ser interpretada como um Mentor de 1 ponto com um interesse específico. Contudo, diferentemente de um Mentor, Conhecimento Útil não implica uma relação permanente.)]==],
				},
				["Vaishya"] = {
					pt = [==[Lore of the Clans, pág. 182


Vaishya


Os jati Vaishya têm a incumbência de manejar influência, manter os rebanhos humanos e cuidar das finanças. Costumam ser vistos como comerciantes e mercadores, mas, para os Ravnos, também são uma parte crítica da manutenção da Máscara que esconde os vampiros dos caçadores mortais. Uma vez por sessão, você pode recorrer a um dos seus Antecedentes como se tivesse um ponto a mais nele (até o máximo normal de 5).

Você não precisa comprar esta Qualidade para ser membro do jati Vaishya, mas somente membros do jati Vaishya podem ter esta Qualidade.]==],
				},
				["Vicissitude Modifications (1)"] = {
					pt = [==[Ghouls & Revenants, pág. 134


Vicissitude Modifications (1)


Você é um carniçal ou um revenant cujo corpo foi hediondamente modificado pelo uso da Disciplina Vicissitude. Você mesmo pode não ter talento nessa área, mas sua carne e seus ossos foram remodelados em um pesadelo projetado para ser útil na guerra. Assim, embora suas Modificações possam lhe render um benefício mecânico, você é considerado um monstro ainda que, tecnicamente, continue mortal.

As alterações feitas no seu corpo são permanentes, a menos que sejam remodeladas por novos usos de Vicissitude. Embora suas Modificações de Vicissitude possam ser perigosas, seu corpo ainda sofre dano normalmente. Apesar da sua aparência horrenda, você continua sendo carne e osso.

Modificações de Vicissitude exige que você adquira o Defeito Monstruoso, que está na página 482 de V20. Independentemente de quantas alterações você escolha, sua Aparência é 0. A critério do Narrador, você também pode ser obrigado a adquirir um Defeito Mental, uma penalidade em rolagens Sociais ou uma Perturbação por causa dos horrores que está vivendo.

De modo geral, esta Qualidade só pode ser usada por personagens que estejam Vinculados a um vampiro ou Clã que disponha de Vicissitude, ou que sejam patrocinados por ele. Revenants modificados dessa forma costumam ser submetidos ao Laço de Sangue para garantir sua lealdade.

Visão Circular (1pt.): um dos seus olhos foi movido para a nuca, concedendo a você a capacidade de enxergar num ângulo mais amplo. Você pode ganhar um bônus em Percepção, especialmente quando alguém tenta se aproximar de você furtivamente. Além disso, sua percepção de profundidade é ruim em qualquer ângulo, e você sofre uma penalidade de dois dados em qualquer rolagem que envolva estimar distância, inclusive o uso de armas de projétil. Presas (1pt.): seus dentes foram alongados e afiados; seu sorriso pode lembrar o de um tigre ou de um tubarão, ou pode não se parecer com nada que exista na natureza. Você pode atacar usando Mordida, que está na página 276 de V20. Por causa da sua aparência monstruosa, você perde dois dados em paradas que envolvam seu Atributo Manipulação, a menos que esteja tentando intimidar ou assustar o alvo. Estômago de Ferro (2pts.): você é capaz de digerir qualquer material orgânico que consiga partir, mastigar e engolir. Em rolagens de Vigor, você ganha +2 quando precisa resistir a venenos ingeridos ou a outros tipos de doença de origem estomacal. Essa modificação digestiva costuma vir acompanhada de Presas. Esporões (2pts.): esporões ósseos afiados e pontiagudos projetam-se dos seus antebraços, da sua coluna ou das suas panturrilhas. Você pode golpear com os Esporões causando For + 2 de dano. Contudo, Esporões são difíceis de esconder e podem limitar sua mobilidade em algumas situações. Carapaça (3pts.): você é coberto por placas ósseas ou espinhosas que o protegem de ataques. Você pode somar dois dados de absorção à sua parada ao se defender de um dano. Patágio (4pts.): seus ossos foram tornados ocos e abas de pele estranha foram enxertadas nos seus braços e pulsos para formar membranas. Embora não consiga voar, você pode usar essas asas de morcego para planar de uma posição mais alta até outra, ou até o chão. Subtraia um dado de todas as paradas de absorção para resistir a golpes de punhos e armas de concussão, ou a qualquer outra forma de dano por impacto que possa danificar seus ossos.

Carniçais e revenants nunca podem curar uma Modificação de Vicissitude danificada, nem mesmo com o Sangue. Nesse aspecto, ambos são tão indefesos quanto seus equivalentes não modificados. Contudo, se um carniçal ou revenant possuir níveis suficientes em Vicissitude, esse personagem pode curar a si mesmo ou remover a Modificação de Vicissitude por completo. Para isso, o personagem precisa ter um nível de Vicissitude superior ao do vampiro que infligiu a mutilação em primeiro lugar.

Usado por: por causa da complexidade desta Qualidade, consulte seu Narrador antes de gastar pontos em Modificações de Vicissitude.]==],
				},
