Usado por: por causa da complexidade desta Qualidade, consulte seu Narrador antes de gastar pontos em Modificações de Vicissitude.]==],
				},
				["Virulent Strike"] = {
					pt = [==[Ghouls & Revenants, pág. 138


Virulent Strike


Por meio de estranha feitiçaria taumatúrgica, de rituais desconhecidos ou mesmo de uma esquisitice da sua fisiologia, seu sangue foi imbuído do poder do sobrenatural. Você pode causar dano agravado em criaturas sobrenaturais ao golpeá-las, mordê-las ou dilacerá-las com esporões de osso. Isso é considerado dano de Briga padrão contra mortais, e normalmente deve se aplicar a apenas uma forma de ataque (mordida, garras de osso etc.).

Você deve trabalhar junto com o Narrador para encontrar uma explicação para esta Qualidade, e o Narrador pode proibi-la por completo, se assim preferir.

Usado por: todos os carniçais e revenants.]==],
				},
				["Vitae Mutation"] = {
					pt = [==[Lore of the Bloodlines, pág. 60


Vitae Mutation


Você bebeu a essência líquida de entidades tão estranhas quanto poderosas. Seja a vitae de Matusaléns, o sangue fervente de lupinos ou sonhos de fadas engarrafados, o volume e a combinação das misturas que você consumiu o alteraram para sempre. A cada noite é exigida uma rolagem de Força de Vontade (dificuldade 7) para que você manifeste um único ponto de Auspícios, Quimerismo ou Demência. Esse ponto pode ser somado a um valor já existente na Disciplina, mas desaparece na noite seguinte.]==],
				},
				["Warrior's Heart"] = {
					pt = [==[Lore of the Bloodlines, pág. 80


Warrior's Heart


Há aço no coração plácido da linhagem Salubri, e a ressurreição de Adonai fez o seu próprio coração palpitar ainda que levemente. Como os Curandeiros de outrora, você pode aprender os poderes de Valeren dos antitribu ao custo de valor atual x6; se conhecer os dois primeiros pontos de Obeah e de Valeren, você ganha um bônus de 2 dados ao usar os dois primeiros pontos dessas Disciplinas. Contudo, seu coração de guerreiro sofre do Preceito de Samiel, a bem delineada inquietação que afeta muitos Salubri: para cada semana que você passa no mesmo lugar, você perde um ponto de Força de Vontade, à medida que sua alma se agita sem ação. Os antitribu podem ter uma Qualidade semelhante que lhes permite aprender Obeah ao custo de sempre ajudar alguém necessitado, a critério do Narrador.]==],
				},
				["Well-Rounded"] = {
					pt = [==[M20 Victorian Age, pág. 119


Well-Rounded


Você foi treinado ou educado especialmente bem em um campo generalista. Você consegue aplicar conceitos básicos até mesmo a usos distantes do seu treinamento. Com o tempo, a aplicação dessas habilidades básicas permite uma flexibilidade admirável na sua área de especialidade.]==],
				},
				["Without a Trace"] = {
					pt = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, pág. 179


Without a Trace


Quando você está no ermo, a terra preenche suas pegadas. Você não deixa rastro perceptível nenhum, nem mesmo cheiro. Tentativas normais de rastreamento falham automaticamente. Tentativas sobrenaturais são feitas com +2 de dificuldade.]==],
				},
				["Wolverine's Palate"] = {
					pt = [==[Lore of the Bloodlines, pág. 70


Wolverine's Palate


Embora muitos não saibam disso, o temido carcaju é uma das poucas criaturas do mundo capazes de devorar a presa por inteiro, seja ela maior ou menor que ele. A Nagaraja com esta Qualidade tem a capacidade de comer osso com a mesma facilidade com que come carne, drenando ainda mais essência espiritual da vítima e convertendo-a em pontos de sangue. Com uma mordida, ela corta carne e osso e engole tudo de uma vez sem efeito adverso nenhum. Isso também significa que ela pode obter até 5 pontos de sangue adicionais de um corpo ao consumir os ossos.]==],
				},
				-- <<< MERIT_DESC_END
};
